const POEMS_DATA = [{"poem_id": "1", "title": "七绝·有思", "genre": "七绝", "date": "2019.09.02", "body": "人间有味是清欢，\n几案书香不羡仙。\n享受孤独方为道，\n浮生寡欲尽晴天。 ​​​", "image_files": []}, {"poem_id": "2", "title": "七绝·秋水晨钓", "genre": "七绝", "date": "2019.09.06", "body": "晨风摇柳水云边，\n旭日红霞映碧天。\n临岸听蝉垂钓早，\n清心养气且悠闲。 ​​​", "image_files": []}, {"poem_id": "3", "title": "长相思·秋晓", "genre": "长相思", "date": "2019.09.07", "body": "晨光明，晓风轻，\n自在白云卷碧空，\n高天万里晴。\n鸟儿鸣，果儿红，\n一夜深眠思绪清，\n平安寄此生。 ​​​", "image_files": []}, {"poem_id": "4", "title": "浣溪沙·白露有寄", "genre": "浣溪沙", "date": "2019.09.08", "body": "白露滴阶黄菊开，\n青云碧水映高台。\n中秋不日又将来。\n岁月无声年过半，\n苍生有愿可舒怀？\n路途艰险莫徘徊。 ​​​", "image_files": []}, {"poem_id": "5", "title": "七绝·缅怀主席", "genre": "七绝", "date": "2019.09.09", "body": "江水乱流山不动，\n顶峰灯塔照舟行。\n四十三载何曾灭，\n雾散云开万里明。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "6", "title": "鹧鸪天·谢恩师", "genre": "鹧鸪天", "date": "2019.09.10", "body": "别却恩师四秩年，\n同窗偶聚总相谈。\n课堂音貌依稀记，\n人事言行仔细传。\n今俱老，愿心欢。\n不能谋面盼身安。\n当初年少得君教，\n尘世浮生天地宽。 ​​​", "image_files": []}, {"poem_id": "7", "title": "浣溪沙·银滩行", "genre": "浣溪沙", "date": "2019.09.12", "body": "千里驱车到乳山，\n雨珠一路打窗前。\n临家有事电频传。\n白露秋霜飞野草，\n中秋梧叶隐寒蝉。\n明天新月万家圆。 ​​​", "image_files": []}, {"poem_id": "8", "title": "五律·银滩秋景", "genre": "五律", "date": "2019.09.13", "body": "软风吹不燥，\n拂面润心田。\n临海凭栏眺，\n倚山戏水玩。\n渔舟欢唱晚，\n燕雀舞云天。\n远客闲思荡，\n抬头望纸鸢。 ​​​", "image_files": []}, {"poem_id": "9", "title": "苏幕遮·银滩中秋寄怀", "genre": "苏幕遮", "date": "2019.09.13", "body": "海风吹，云朵卷。\n水漾渔舟，\n虾蟹仓仓满。\n厚道船家盈笑脸。\n人悦鱼收，\n无悔归来晚。\n恰中秋，心绪远。\n月映银滩，\n怎肯金樽浅。\n把酒怀乡一盏盏。\n遥望婵娟，\n无限情思远。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "10", "title": "七绝·自然美", "genre": "七绝", "date": "2019.09.15", "body": "黄绿赤橙染碧天，\n谁人法力大无边。\n等闲信手丹青画，\n胜却粉颜几万千。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "11", "title": "贺新郎·银滩感怀", "genre": "贺新郎", "date": "2019.09.16", "body": "雨过云天碧。\n望银滩，\n青青草木，\n软风和煦。\n鹰燕凌空随心意，\n自在东西来去。\n舟荡漾，\n渔家笑立。\n烟水波涛拍岸绿，\n更红枫秋色宜人地。\n盈海景，\n溢朝气。\n天南地北人相聚。\n看晨昏，\n悠悠共乐，\n浑然成趣。\n忘却昔时烦恼事，\n欢语频连妙句。\n凭日夜，\n无忧少虑。\n斑鬓花颜争献艺，\n胜夕阳辉映霞光璧。\n身于此，\n藐仙帝。", "image_files": ["01.jpg", "02.jpg", "03.jpg", "04.jpg"]}, {"poem_id": "12", "title": "七律·银滩随想", "genre": "七律", "date": "2019.09.17", "body": "海天空阔细风扬，\n多趣花筝巧自翔。\n风荡线牵翻转舞，\n云开翼摆闪金光。\n七八列阵九天外，\n三两成行一水长。\n银线由心松紧去，\n思绪随风散海疆。 ​​​", "image_files": []}, {"poem_id": "13", "title": "破阵子·铭记九一八", "genre": "破阵子", "date": "2019.09.20", "body": "难忘当年今日\n倭贼半夜炮轰\n霎那间烟光四起\n淫火遍烧北大营\n可怜我众生\n十四春秋惨烈\n万千罪恶分明\n抵赖模糊强盗事\n妄想乾坤向后行\n语出世界惊 ​​​", "image_files": []}, {"poem_id": "14", "title": "江城子·寄同窗", "genre": "江城子", "date": "2019.09.21", "body": "京城别后信茫茫，\n念春光，鬓飞霜。\n遥望神州，鸿雁俱翱翔。\n展翅九霄风雨翥，\n雄姿丽，气轩昂。\n山河万里自流芳，\n伴高阳，映疏窗，\n影越楼台，庭树散幽香。\n数度春秋传锦字，\n情谊远，韵悠长。 ​​​", "image_files": []}, {"poem_id": "15", "title": "渔家傲·庆丰收", "genre": "渔家傲", "date": "2019.09.23", "body": "丽日金秋云淡淡，\n喜人五谷盈场院，\n锣鼓喧天歌遍遍。\n清风伴，\n黄叶飘飖频点赞。\n辛苦农家千百万，\n冰霜泥雪从无怨，\n双手赢得身境换。\n双颊灿，\n神州百姓心光艳。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "16", "title": "渔家傲·庆丰收", "genre": "渔家傲", "date": "2019.09.24", "body": "丽日金秋云淡淡，\n喜人五谷盈场院，\n锣鼓喧天歌遍遍。\n清风伴，\n黄叶飘飖频点赞。\n辛苦农家千百万，\n冰霜泥雪从无怨，\n双手赢得身境换。\n双颊灿，\n神州百姓心光艳。 ​​​", "image_files": []}, {"poem_id": "17", "title": "浣溪沙·题同学忆父", "genre": "浣溪沙", "date": "2019.09.25", "body": "自古人生父子恩，\n言传身教善留根。\n阴阳别后更情深。\n中岁前觉无所谓，\n晚年后望泪湿襟。\n再忙莫忘孝双亲。 ​​​", "image_files": []}, {"poem_id": "18", "title": "浣溪沙·闲钓", "genre": "浣溪沙", "date": "2019.09.26", "body": "秋日闲来理钓钩，\n湖边垂线绪思收。\n白云飞鸟各悠悠。\n别却高楼天地阔，\n亲合芳野气神柔。\n起杆空也不烦忧。 ​​​", "image_files": []}, {"poem_id": "19", "title": "七律·银滩随想", "genre": "七律", "date": "2019.09.27", "body": "海天空阔细风扬，\n多趣花筝巧自翔。\n风荡线牵翻转舞，\n云开翼摆闪金光。\n七八列阵九天外，\n三两成行一水长。\n银线由心松紧去，\n思绪随风散海疆。 ​​​", "image_files": []}, {"poem_id": "20", "title": "七律·银滩随想2", "genre": "七律", "date": "2019.09.27", "body": "庭院幽深木叶青，\n轻风徐荡鸟虫鸣。\n闲翻诗画添情趣，\n忙弈棋牌聚老翁。\n河北河南才见面，\n楼前楼后总同行。\n秦腔越调协同曲，\n尽展情怀唱山东。 ​​​", "image_files": []}, {"poem_id": "21", "title": "水调歌头·祖国颂", "genre": "水调歌头", "date": "2019.10.01", "body": "秋日云天碧，\n山水好风光。\n神州国庆民奋，\n旗展舞飞扬。\n塞北江南红遍，\n莺燕蝉蛩欢唱，\n喜气满城乡。\n草树迎人笑，\n街角溢花香。\n惊回首，\n情不尽，\n韵悠长。\n桥连港澳，\n丝路横跨亚欧邦。\n天眼巡回宇宙，\n北斗指明航向，\n江海映高阳。\n华夏齐心力，\n世纪铸辉煌。 ​​​", "image_files": []}, {"poem_id": "22", "title": "蝶恋花·缅怀英烈", "genre": "蝶恋花", "date": "2019.10.01", "body": "静默无言人肃立，\n纪念碑前，\n俱为忠魂泣。\n浴血牺牲家万里，\n神州代代心铭记。\n今日山河千千异，\n矗立东方，\n国盛云天碧。\n带路连通欧亚体，\n子孙不负君前志。 ​​​", "image_files": []}, {"poem_id": "23", "title": "清平乐·国庆有感", "genre": "清平乐", "date": "2019.10.01", "body": "激怀壮志，\n红叶金秋季。\n千载古都新彩丽，\n亿万工农吐气。\n军姿威武昂扬，\n铁流滚滚飞光，\n闪闪银鹰耀眼，\n山河万寿无疆。 ​​​", "image_files": []}, {"poem_id": "24", "title": "清平乐·慰英灵", "genre": "清平乐", "date": "2019.10.02", "body": "三车并进，\n些许心生闷。\n此举为何谁可问？\n晓寓深情眼润。\n空车满载英魂，\n邀来回望三军。\n盛世如您所愿，\n银鹰铁甲成林。 ​​​", "image_files": []}, {"poem_id": "25", "title": "苏幕遮·银滩夜色", "genre": "苏幕遮", "date": "2019.10.04", "body": "月黄昏，华彩放。\n远客乡邻，\n携手身心畅。\n笑聚欢谈闲地上，\n乐曲飞扬，\n歌舞翻新样。\n水兵操，男女靓。\n独舞蹁跹，\n戏曲连环唱。\n管瑟琴笙音悠荡。\n夜半声消，\n好梦凭人酿。 ​​​", "image_files": []}, {"poem_id": "26", "title": "鹧鸪天·又聚银滩", "genre": "鹧鸪天", "date": "2019.10.04", "body": "午聚檀香情谊深，\n九龙玉液满金樽。\n五家老少同欢笑，\n和面烧鱼煮海珍。\n红扇贝，紫蟹新，\n茴香韭菜饺馋人，\n客居他处时常乐，\n故友频逢别样亲。 ​​​", "image_files": []}, {"poem_id": "27", "title": "渔家傲·贺岳母生日", "genre": "渔家傲", "date": "2019.10.06", "body": "四世同堂福寿宴，\n耄耋鹤发微红面，\n慈目安神盈笑脸。\n齐祝愿，\n南山不老松苍健。\n母女情深金不换，\n一家老少胸中惦。\n历尽沧桑却无怨。\n心绪淡，\n福如东海千邻羡。 ​​​", "image_files": []}, {"poem_id": "28", "title": "采桑子·银滩重阳有寄", "genre": "采桑子", "date": "2019.10.07", "body": "海边胜似高山阔，\n碧水云天，\n思绪无边，\n惟念家乡父母安。\n临堤梧叶迎风去，\n岁月无言，\n秋日余年，\n潇洒人生跬步前。 ​​​", "image_files": []}, {"poem_id": "29", "title": "蝶恋花·寒露抒怀", "genre": "蝶恋花", "date": "2019.10.08", "body": "国庆豪情心正荡，\n喜悦难消，\n谁不回头望。\n方阵铿锵兵甲壮，\n东风烈烈催巨浪。\n思绪随风收岗上，\n亿万神奇，\n再为九州创。\n日日旋升光彩放，\n赤龙腾起东方亮。 ​​​", "image_files": []}, {"poem_id": "30", "title": "清平乐·重阳寄友", "genre": "清平乐", "date": "2019.10.09", "body": "真情久久，\n彼此心中有。\n年少校园前或后，\n同事多年左右。\n闲来共处银滩，\n无由把酒言欢。\n兴起诗词歌赋，\n云开踏海登山。 ​​​", "image_files": []}, {"poem_id": "31", "title": "江城子·妻游仙人桥", "genre": "江城子", "date": "2019.10.11", "body": "濛濛丝雨有无间，\n洞桥边，海天蓝。\n水面无风，\n鸟语润心田。\n闺蜜远来留倩影，\n轻挽手，似从前。\n细声慢步碎石湾，\n肺腑言，恁悠闲。\n昔日同窗，\n转眼四十年。\n南北两人缘分厚，\n各置业，共银滩。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "32", "title": "临江仙·问无锡", "genre": "临江仙", "date": "2019.10.13", "body": "近日古城名又震，\n缘由竟是桥翻。\n可怜母女再无言。\n出门歇片刻，\n家路永难还。\n悲剧真的防不了？\n个中疑问连连。\n曾经网上有书篇，\n任凭车载重，\n早晚那一天。 ​​​", "image_files": []}, {"poem_id": "33", "title": "七绝·秋晓", "genre": "七绝", "date": "2019.10.14", "body": "白云戏水舞金秋，\n鸥鹭翱翔日色流。\n晨雾随风千里去，\n霎时散尽梦中愁。 https://video.weibo.com/show?fid=1034:4427210426152453 ​​​", "image_files": []}, {"poem_id": "34", "title": "七绝·秋晓", "genre": "七绝", "date": "2019.10.14", "body": "白云戏水舞金秋，\n鸥鹭翱翔日色流。\n晨雾随风千里去，\n霎时散尽梦中愁。 ​​​", "image_files": []}, {"poem_id": "35", "title": "浣溪沙·银滩潮汐湖", "genre": "浣溪沙", "date": "2019.10.15", "body": "草木红黄水岸边，\n高阳斜照碧云天，\n桥亭栈道曲连环。\n秋色层叠人漫步，\n微风偶荡鸟飞还。\n晚霞辉映暖心田。 ​​​", "image_files": []}, {"poem_id": "36", "title": "如梦令·银滩", "genre": "如梦令", "date": "2019.10.16", "body": "夜色流光溢彩，\n炫舞飙歌人帅，\n无虑释深情，\n万众激昂欢快。\n豪迈，豪迈。\n魅力银滩常在。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg", "04.jpg", "05.jpg", "06.jpg"]}, {"poem_id": "37", "title": "清平乐·银滩渔村", "genre": "清平乐", "date": "2019.10.17", "body": "杜家海岛，\n村小人稀少。\n红瓦青石房俱老，\n窄巷闲聊翁媪。\n三边水绕青山，\n苍峰袅袅云烟。\n青壮弄舟踏浪，\n鹰飞鱼跳人欢。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg", "04.jpg", "05.jpg", "06.jpg"]}, {"poem_id": "38", "title": "渔家傲·游多福山", "genre": "渔家傲", "date": "2019.10.18", "body": "十月多褔山灿烂，\n黄花红叶坡上漫，\n曲径丛幽天一线。\n轻挥汗，\n飞身跃顶天池见。\n香客游人盈笑脸，\n玉皇庙顶俯身瞰，\n楼立银滩清水岸。\n高声唤，\n红旗飘洒英雄汉。\n七律        多福山\n晨曦四射耀福山，\n岭翠坡葱气色仙。\n半米方池盈玉液，\n一祠圆顶绕云烟。\n石阶千磴寿星老，\n曲径九折一线天。\n玉庙碧霞烟火处，\n万千福禄降人间。\n七绝 碧霞元君祠\n凌空横卧碧霞宫，\n紫气东来万里风。\n护佑家国逢盛世，\n悠悠千载惠苍生。\n七绝     霄龙禅寺\n清幽寺院笼云烟，\n白虎青龙左右边。\n宝塔护国顶天立，\n斩妖除孽保平安。", "image_files": ["01.jpg", "02.jpg", "03.jpg", "04.jpg", "05.jpg", "06.jpg", "07.jpg", "08.jpg", "09.jpg"]}, {"poem_id": "39", "title": "七律·逛南泓码头", "genre": "七律", "date": "2019.10.19", "body": "黄昏渔港渐人欢，\n陆续归来满载船。\n杆顶红旗风劲舞，\n栏边老汉笑开颜。\n八方来客齐询价，\n数个鱼仓一瞬完。\n拎蟹兜虾车散去，\n夕晖暮色又安然。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg", "04.jpg", "05.jpg", "06.jpg"]}, {"poem_id": "40", "title": "贺新郎·寄同窗返校", "genre": "贺新郎", "date": "2019.10.20", "body": "闻道将相聚。\n喜难言，\n频思夜日，\n有心归去。\n无奈今朝难凑巧，\n千里随风遥寄。\n秋色爽，\n师生合璧。\n携手开怀言旧事，\n更金樽笑语连欢句。\n情未老，\n溢豪气。\n已然四秩春秋逝。\n忆当年，\n风霜寒暑，\n苦读成趣。\n今日京城重聚首，\n忘却昔时烦事。\n凭日夜，\n无忧少虑。\n海阔长空心意远，\n恰夕阳辉映云天碧。\n山水处，\n任君去。", "image_files": []}, {"poem_id": "41", "title": "贺新郎·大学情", "genre": "贺新郎", "date": "2019.10.20", "body": "闻道将相聚。\n喜难言，\n频思夜日，\n有心归去。\n无奈今朝难凑巧，\n千里随风遥寄。\n秋色爽，\n师生合璧。\n携手开怀言旧事，\n更金樽笑语连欢句。\n情未老，\n溢豪气。\n已然四秩春秋逝。\n忆当年，\n风霜寒暑，\n苦读成趣。\n今日京城重聚首，\n忘却昔时烦事。\n凭日夜，\n无忧少虑。\n海阔长空心意远，\n恰夕阳辉映云天碧。\n山水处，\n任君去。", "image_files": []}, {"poem_id": "42", "title": "七绝·自乐", "genre": "七绝", "date": "2019.10.22", "body": "飘洒芦花染晚秋，\n不须谁赏自欢悠。\n为人行事若如此，\n心里清安无乱愁。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "43", "title": "浣溪沙·潮汐湖夜景", "genre": "浣溪沙", "date": "2019.10.23", "body": "夜色朦胧露丽容，\n楼光桥影漾湖明。\n玩童戏耍趣犹浓。\n华彩倚栏环水岸，\n流辉映字耀星空。\n迷离仙境梦中行。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg", "04.jpg", "05.jpg", "06.jpg"]}, {"poem_id": "44", "title": "浣溪沙·潮汐湖夜景", "genre": "浣溪沙", "date": "2019.10.23", "body": "夜色朦胧露丽容，\n楼光桥影漾湖明。\n玩童戏耍趣犹浓。\n华彩倚栏环水岸，\n流辉映字耀星空。\n迷离仙境梦中行。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg", "04.jpg", "05.jpg", "06.jpg"]}, {"poem_id": "45", "title": "如梦令·盼", "genre": "如梦令", "date": "2019.10.24", "body": "往日喧哗无现，\n树静场清人散。\n远客返家乡，\n能否明年还见？\n期盼，期盼。\n日后天随人愿！ ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg", "04.jpg", "05.jpg", "06.jpg"]}, {"poem_id": "46", "title": "行香子·健身乐", "genre": "行香子", "date": "2019.10.27", "body": "树下川前，跑步登山。\n斗寒暑，晓暮风烟。\n浑身轻巧，步履翩翩。\n自睡得香，吃得好，顽得欢。\n鸟啭心闲，岭翠神安。\n交新友，故友难偏。\n偶然远去，常聚尊前。\n对几声歌，几杯酒，几人酣。 ​​​", "image_files": []}, {"poem_id": "47", "title": "五绝·银滩夜望", "genre": "五绝", "date": "2019.10.29", "body": "临岸数寒星，\n轻闻海浪声。\n归心思故土，\n最忆是乡情。 ​​​", "image_files": []}, {"poem_id": "48", "title": "十六字令·井冈山", "genre": "十六字令", "date": "2019.10.30", "body": "山，\n青翠茫茫袅袅烟。\n人居此，\n不愿做神仙。\n山，\n百里方圆峻岭连。\n黄洋界，\n一炮退敌千。\n山，\n回望当年尽杜鹃。\n忆先烈，\n血色映红天。 ​​​", "image_files": []}, {"poem_id": "49", "title": "七绝·题庄子岭", "genre": "七绝", "date": "2019.10.31", "body": "蓝天红叶映岭川，\n溪水游人峡谷间。\n秋意正浓山色美，\n鸟姿风韵润心田。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg", "04.jpg", "05.jpg", "06.jpg"]}, {"poem_id": "50", "title": "减字木兰花·秋雨闲赋", "genre": "减字木兰花", "date": "2019.11.01", "body": "云飘雨落\n窗外清风亲远客\n节气宜人\n望海休闲最销魂\n琴音楼上\n顿挫悠扬思绪畅\n诗画品读\n缕缕书香浸玉壶 ​​​", "image_files": []}, {"poem_id": "51", "title": "一剪梅·欢聚", "genre": "一剪梅", "date": "2019.11.03", "body": "千里归来秋月明，\n往日三家，\n今又重逢。\n养元道里气氛浓，\n两盏三杯，\n情趣难平。\n畅饮开怀意绪清，\n论古谈今，\n诗赋乡情。\n月移花影粉墙东，\n酒肆人稀，\n夜色朦胧。 ​​​", "image_files": []}, {"poem_id": "52", "title": "七律·秋游", "genre": "七律", "date": "2019.11.04", "body": "红叶黄花炫丽秋，\n山间漫步乐悠悠。\n清清溪水欢腾过，\n淡淡飞云眼底收。\n柿子满枝随处望，\n游人稀少景边留。\n不闻喧闹心神静，\n鸟语花香自不愁。 ​​​", "image_files": []}, {"poem_id": "53", "title": "七律·神州美", "genre": "七律", "date": "2019.11.05", "body": "广袤山河万里长，\n涓涓溪水汇川江。\n浪涛滚滚东流去，\n云雾茫茫卷夕阳。\n塞北已然冰雪地，\n江南依旧稻花香。\n神州处处风光美，\n铭刻心中是故乡。 ​​​", "image_files": []}, {"poem_id": "54", "title": "卜算子·晨练", "genre": "卜算子", "date": "2019.11.06", "body": "街上月朦胧，\n露重声稀少。\n起舞闻鸡早养成，\n挥汗一清晓。\n遥望日东升，\n雾散云天皎。\n抖擞精神昂首回，\n秋色晨曦好。 ​​​", "image_files": []}, {"poem_id": "55", "title": "七绝·无题", "genre": "七绝", "date": "2019.11.07", "body": "雾里看花别样红，\n糊涂处世更高明。\n五分清醒五分醉，\n闲淡安然度半生。 ​​​", "image_files": []}, {"poem_id": "56", "title": "七绝·洒脱", "genre": "七绝", "date": "2019.11.07", "body": "雾里看花别样红，\n糊涂处世更高明。\n五分清醒五分醉，\n闲淡安然度半生。 ​​​", "image_files": []}, {"poem_id": "57", "title": "长相思·娘", "genre": "长相思", "date": "2019.11.08", "body": "菊花黄，\n梧叶黄，\n秋染山川五彩光。\n天凉果正香。\n思老娘，\n伴老娘，\n一日三餐絮短长。\n娘安心不慌。 ​​​", "image_files": []}, {"poem_id": "58", "title": "七绝·立冬所见", "genre": "七绝", "date": "2019.11.08", "body": "惺忪晓起已立冬，\n窗外轻寒未显冰。\n路边花草寻常见，\n红叶频摇笑北风。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg", "04.jpg", "05.jpg", "06.jpg"]}, {"poem_id": "59", "title": "七绝·念", "genre": "七绝", "date": "2019.11.09", "body": "携手红原山水间，\n匆匆别后念无边。\n心期来日还相聚，\n豪饮华山醉九天。 ​​​", "image_files": []}, {"poem_id": "60", "title": "青玉案·题同窗忆恩师", "genre": "青玉案", "date": "2019.11.10", "body": "读罢短文飞思绪，\n四十载，光阴逝。\n笑貌音容难忘记。\n治学严谨，\n待人周细，\n常道谆谆语。\n独撑农电高挥臂，\n沥血终生倾心力。\n学业品行传弟子。\n宛如秋叶，\n护根情续，\n岁月留佳迹。 ​​​", "image_files": []}, {"poem_id": "61", "title": "七绝·咏菊", "genre": "七绝", "date": "2019.11.11", "body": "深秋大地独娇艳，\n带露含香弄晓寒。\n彩嫩腰枝风伴舞，\n暖阳斜照韵斑斓。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg", "04.jpg", "05.jpg", "06.jpg"]}, {"poem_id": "62", "title": "七绝·咏菊", "genre": "七绝", "date": "2019.11.11", "body": "深秋大地独娇艳，\n带露含香弄晓寒。\n彩嫩腰枝风伴舞，\n暖阳斜照韵斑斓。 ​​​", "image_files": []}, {"poem_id": "63", "title": "长相思·遥望银滩", "genre": "长相思", "date": "2019.11.12", "body": "---观视频有寄\n天已凉，\n心不凉。\n暮色银滩管乐扬，\n银花夜未央。\n为人忙，\n为己忙。\n去到乳山梦里香，\n归来更思量。 ​​​", "image_files": []}, {"poem_id": "64", "title": "七律·闲咏", "genre": "七律", "date": "2019.11.13", "body": "立冬雨后尽寒风\n黄叶枯枝遍地横。\n玉露银霜晨尽染，\n层云斜日晚趋彤。\n宵吟苏轼西江月，\n日咏曹操短歌行。\n千古诗词催己奋，\n高歌把酒趣无穷。 ​​​", "image_files": []}, {"poem_id": "65", "title": "七律·冬咏", "genre": "七律", "date": "2019.11.13", "body": "立冬雨后尽寒风\n黄叶枯枝遍地横。\n玉露银霜晨尽染，\n层云斜日晚趋彤。\n宵吟苏轼西江月，\n日咏曹操短歌行。\n千古诗词催己奋，\n高歌把酒趣无穷。 ​​​", "image_files": []}, {"poem_id": "66", "title": "七绝·无题", "genre": "七绝", "date": "2019.11.14", "body": "世间名利无穷尽，\n诱惑今年胜去年。\n锦瑟时光须奋斗，\n桑榆岁月且悠闲。 ​​​", "image_files": []}, {"poem_id": "67", "title": "破阵子·农家喜事", "genre": "破阵子", "date": "2019.11.15", "body": "昨日回家巧遇，\n乡临嫁女酬宾。\n酒宴当街连数日，\n换盏推杯聚友亲，\n欢言贺新婚。\n冬季农闲事少，\n凭添喜气纷纷。\n满院彩旗人尽笑，\n远近亲朋情谊真。\n鼓锣鞭炮频。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "68", "title": "七绝·选择", "genre": "七绝", "date": "2019.11.16", "body": "人生之路万千条，\n行走凭思慎重挑。\n地里种瓜难获豆，\n仰天空叹只心焦。 ​​​", "image_files": []}, {"poem_id": "69", "title": "七绝·友聚", "genre": "七绝", "date": "2019.11.17", "body": "茶亦醉人难忘酒，\n丹青笔墨映书香。\n文词诗赋情千古，\n舞影歌声久荡肠。 ​​​", "image_files": []}, {"poem_id": "70", "title": "七绝·芦花二首", "genre": "七绝", "date": "2019.11.18", "body": "飘洒芦花染晚秋，\n不须谁赏自欢悠。\n为人行事皆如此，\n心里清安无乱愁。\n风摆苇丛飞浪花，\n芦塘深处有渔家。\n船头偶见金鱼跃，\n笑脸微微映晚霞。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "71", "title": "七绝·画中行", "genre": "七绝", "date": "2019.11.19", "body": "穿行云海越仙山，\n人似梦中入九天。\n不是神州国力盛，\n怎得踏岭若平原。 https://video.weibo.com/show?fid=1034:4440262550702321 ​​​", "image_files": []}, {"poem_id": "72", "title": "五律·秋望", "genre": "五律", "date": "2019.11.20", "body": "一夜秋风劲，\n千山木叶黄。\n菊花开正盛，\n柿子染红墙。\n云淡鸣飞鸟，\n水清流碧光。\n山头携酒卧，\n邀月举金觞。 ​​​", "image_files": []}, {"poem_id": "73", "title": "七律·闲咏", "genre": "七律", "date": "2019.11.21", "body": "半生苦累晚来闲，\n无愧于心心自安。\n戴月披星度寒暑，\n青丝斑鬓代朱颜。\n一张一驰道中道，\n花落花开年复年。\n惟有青春多努力，\n人间岁月不遭难。 ​​​", "image_files": []}, {"poem_id": "74", "title": "七绝·夜读", "genre": "七绝", "date": "2019.11.22", "body": "月升花影落书窗，\n灯映诗笺淡淡黄。\n品味先贤明理句，\n不觉花色却闻香。 ​​​", "image_files": []}, {"poem_id": "75", "title": "采桑子·感悟", "genre": "采桑子", "date": "2019.11.23", "body": "人间自古千般味，\n草舍层楼，\n争向层楼，\n心绪不平常犯愁。\n而今尝过千般味，\n闲事皆休，\n静乐无休，\n恬淡欣然度春秋。 ​​​", "image_files": []}, {"poem_id": "76", "title": "清平乐·与君欢酌", "genre": "清平乐", "date": "2019.11.24", "body": "多时不见，\n昨晚逢君面。\n笑口欢言金不换，\n玉液琼浆怕浅。\n遥思共忆当年，\n云光暮色窗前。\n心喜频端玉觯，\n悠然快意杯干。 ​​​", "image_files": []}, {"poem_id": "77", "title": "木兰花·远近", "genre": "木兰花", "date": "2019.11.25", "body": "有心则近无心远，\n即便天天能碰面。\n低头不语枉相识，\n微笑招呼初次见。\n虽然隔水犹思念，\n莫要对门缺顾眄 。\n人生在世友宜多，\n切勿急时才找盼。 ​​​", "image_files": []}, {"poem_id": "78", "title": "七绝·创新评审", "genre": "七绝", "date": "2019.11.27", "body": "同行高手聚锡州，\n各展神思语不休。\n电力精英齐奋进，\n凝神远望上高楼。\n七绝 夜行二泉路\n千里之行到无锡，\n恰逢骤冷雨丝丝。\n白天忙碌难得空，\n晚上凉风吹绪思。 ​​​", "image_files": []}, {"poem_id": "79", "title": "七绝·偷闲", "genre": "七绝", "date": "2019.11.28", "body": "黄昏小聚粤玲珑，\n烧脑之余起笑声。\n玉液笼包香气漫，\n身心疲倦尽随风。\n七绝    锡州冬晓\n三天未见太阳公，\n雨过晓来云彩明。\n漫步花园三五里，\n回身厅内论英雄。 ​​​", "image_files": []}, {"poem_id": "80", "title": "江城子·永无止境", "genre": "江城子", "date": "2019.11.29", "body": "…贺创新评审圆满结束\n创新论剑聚锡州，\n上层楼，竞风流。\n各路精英，\n言语不肯休，\n文字描说图画展，\n精彩处，博眼球。\n切磋技艺未存留，\n有刚柔，重交流。\n尽展绝招，\n携手度春秋。\n生产经营强管理，\n齐进步，俱丰收。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "81", "title": "破阵子·高手欢别", "genre": "破阵子", "date": "2019.11.30", "body": "乐曲萦空飞荡，\n创新颁奖情浓。\n光聚舞台眉眼笑，\n手捧金牌绪不平，\n大厅起掌声。\n南北精英互贺，\n相识欢意无穷。\n携手交谈增干劲，\n日后人生做友朋，\n攀登永不停。 ​​​", "image_files": []}, {"poem_id": "82", "title": "五律·别无锡", "genre": "五律", "date": "2019.12.01", "body": "初冬翠未衰，\n连日雨徘徊。\n傍晚增寒气，\n清晨云雾开。\n笑观龙虎竞，\n惬意释心怀。\n伫立锡州路，\n今别期再来。 ​​​", "image_files": []}, {"poem_id": "83", "title": "七绝·华为娇子", "genre": "七绝", "date": "2019.12.01", "body": "成仁取义中国范，\n优雅从容看晚舟。\n不畏风云千里浪，\n置身虎穴度春秋。\nhttps://mp.weixin.qq.com/s/U0q1mvD_gJttJgVzbJTB7Q ​​​", "image_files": []}, {"poem_id": "84", "title": "七绝·心安自乐", "genre": "七绝", "date": "2019.12.02", "body": "年与时驰人易老，\n夜凭事少梦无惊。\n醒来又是新天地，\n南北东西万里晴。 ​​​", "image_files": []}, {"poem_id": "85", "title": "七律·出师表读感", "genre": "七律", "date": "2019.12.03", "body": "忠贞不二肺腑言，\n字里行间老泪斑。\n先帝后君皆念顾，\n文臣武将摆堂前。\n宫中府内寻常事，\n陟罚利弊列其间。\n碧血丹心昭厚土，\n鞠躬尽瘁映苍天。 ​​​", "image_files": []}, {"poem_id": "86", "title": "七律·寒窑赋读感", "genre": "七律", "date": "2019.12.04", "body": "谁解千年醒世篇？\n祸福叵测瞬息间。\n颜渊命短非凶恶，\n楚霸艺高刎江边。\n君子失时宜守份，\n蛟龙未遇岂飞天。\n时来风雨皆同力。\n运去英雄共犯难。 ​​​", "image_files": []}, {"poem_id": "87", "title": "鹧鸪天·庆母八十大寿", "genre": "鹧鸪天", "date": "2019.12.05", "body": "冬日返乡不道寒，\n老娘伞寿聚桌前。\n稀疏银发慈眉目，\n忙碌农家月复年。\n人敬重，赖心安，\n轻言少语众邻欢。\n一生孝老疼晚辈，\n和睦家风代代传。 ​​​", "image_files": []}, {"poem_id": "88", "title": "七律·滕王阁序读感", "genre": "七律", "date": "2019.12.06", "body": "王杨卢骆第一人，\n八斗之才弱冠身。\n投笔抒怀明壮志，\n登楼作赋震佳宾。\n落霞孤鹜云空丽，\n海角天涯若比邻。\n仕路曲折遭意外，\n滕王阁上荡英魂。 ​​​", "image_files": []}, {"poem_id": "89", "title": "七绝·大雪", "genre": "七绝", "date": "2019.12.07", "body": "玉树琼枝万里飘，\n神工鬼斧胜雕刀。\n青青一色同天地，\n山野茫茫气势豪。 ​​​", "image_files": []}, {"poem_id": "90", "title": "蝶恋花·雾中冬练", "genre": "蝶恋花", "date": "2019.12.08", "body": "雾锁晨空浑不见，\n湿气扑身，\n双耳风中颤。\n漫跑修身金不换，\n春秋寒暑未曾断。\n脚下叶黄随声乱，\n偶遇行人，\n花罩遮颜面。\n蹬腿扩胸微透汗，\n弥天大雾何时散？ ​​​", "image_files": []}, {"poem_id": "91", "title": "七律·<师说>读感", "genre": "七律", "date": "2019.12.09", "body": "学而师道古来传，\n术业专攻日复年。\n一技之长宜敬重，\n三人行坐近师边。\n居前闻道无长少，\n之后习学态必端。\n不耻相师齐共进，\n人无贵贱艺当先。 ​​​", "image_files": []}, {"poem_id": "93", "title": "七律·醉翁亭记读感", "genre": "七律", "date": "2019.12.10", "body": "山水之间醉老翁，\n若非泉酿具神功？\n林梢岩穴云飞荡，\n木秀芳幽景色明。\n野簌香肴心喜悦，\n觥筹喧闹鸟悲惊。\n夕阳西下人还乐，\n客与仙翁乐不同。 ​​​", "image_files": []}, {"poem_id": "94", "title": "七律·戒子书读感", "genre": "七律", "date": "2019.12.11", "body": "修身明志度人生，\n勤俭养德家道平。\n宁静沉思山水远，\n澹泊冶性世间行。\n谁能险躁兴宏业，\n惟有才学可事成。\n戒子箴言千古句，\n一生垂范树家风。 ​​​", "image_files": []}, {"poem_id": "95", "title": "七律·爱莲说读感", "genre": "七律", "date": "2019.12.12", "body": "秋菊夏莲春牡丹，\n世人所爱不一般。\n晋陶篱下闻香菊，\n唐李口中夸牡丹。\n臣子随君追富贵，\n宋民独有喜清莲。\n大千世界花无意，\n却是凡人眼色偏。 ​​​", "image_files": []}, {"poem_id": "96", "title": "破阵子·12.13寄怀", "genre": "破阵子", "date": "2019.12.13", "body": "---悼南京大屠杀亡灵\n地破天惊惨案\n狼烟昏暗长空\n凄切悲魂今尚在\n岁岁敲击警世钟\n江河恨泪盈\n上下俯身共奋\n城乡倾力齐兴\n五岳三山容貌换\n万寨千村映彩虹\n神州腾巨龙。 ​​​", "image_files": []}, {"poem_id": "97", "title": "七律·岳阳楼记读感", "genre": "七律", "date": "2019.12.14", "body": "览文胜似踏江楼，\n遥想波涛滚滚流。\n阴雨霏霏星日隐，\n青云淡淡卷春秋。\n临风把酒心神旷，\n望月凝思进退忧。\n悲喜君民惟忘我，\n先忧后乐更何求！ ​​​", "image_files": []}, {"poem_id": "98", "title": "七律·五柳先生传读感", "genre": "七律", "date": "2019.12.15", "body": "垂垂苍柳草宅边，\n无虑得失静少言。\n嗜酒樽前期必醉，\n赋诗窗下总成欢。\n不汲富贵甘贫苦，\n喜著文章性雅然。\n日后若得如此过，\n轻忧寡欲享天年。 ​​​", "image_files": []}, {"poem_id": "99", "title": "五绝·晨咏", "genre": "五绝", "date": "2019.12.16", "body": "华夏千条路，\n神州万古情。\n人生行正道，\n为善贵心恒。 ​​​", "image_files": []}, {"poem_id": "100", "title": "七律·陋室铭读感", "genre": "七律", "date": "2019.12.17", "body": "身居简室胸怀阔，\n不近丝竹品亦高。\n鸿儒往来天下事，\n金经研阅万千条。\n沉浮官场心神淡，\n驰骋文坛气势豪。\n志向云亭草庐者，\n江湖飞荡任逍遥。 ​​​", "image_files": []}, {"poem_id": "101", "title": "浣溪沙·遥望乳山", "genre": "浣溪沙", "date": "2019.12.18", "body": "阳侧银滩倚秀山，\n夏凉冬暖醉人间。\n民风醇厚蟹鱼鲜。\n负氧盈空挥不尽，\n白云拂水海天蓝。\n休闲养老可心甜。 ​​​", "image_files": []}, {"poem_id": "102", "title": "七律·归去来兮读感", "genre": "七律", "date": "2019.12.19", "body": "辞官不作当宵去，\n归隐田园心不忧。\n三径将荒松菊在，\n一门虽破子仆留。\n乐琴书日闲星悦，\n善棹舟云卷水流。\n不道今人闻此后，\n钻营上位几时休？ ​​​", "image_files": []}, {"poem_id": "103", "title": "七律·惜缘", "genre": "七律", "date": "2019.12.20", "body": "茫茫人海能相遇，\n前世修得今日缘。\n逢聚珍惜如手足，\n别离思念盼平安。\n取长补短乾坤阔，\n细语轻言天地宽。\n处事为人多换位，\n浮生处处尽情欢。 ​​​", "image_files": []}, {"poem_id": "104", "title": "清平乐·贺澳门回归", "genre": "清平乐", "date": "2019.12.20", "body": "莲花宝地，\n廿载回归日。\n拥抱母亲逢盛世，\n诠释一国两制。\n昔时七子之身，\n今朝丽日飞云。\n临海鸟欢人笑，\n民情风景欣欣。 ​​​", "image_files": []}, {"poem_id": "105", "title": "浣溪沙·大寨小岗", "genre": "浣溪沙", "date": "2019.12.21", "body": "人道三农两面旗，\n前行路上各东西。\n请君回首看端倪。\n合作经营成大事，\n分家管理只求吃。\n种田模式引深思。 ​​​", "image_files": []}, {"poem_id": "106", "title": "七律·问天", "genre": "七律", "date": "2019.12.22", "body": "冬至时节鲜见冰，\n天寒日短感微风。\n河边树上摇残叶，\n墙角枝头吐嫩红。\n敢问天公何日雪，\n聊安百姓几多情。\n漫空银粟飘遥落，\n瑞兆春来庚子丰。\n七绝            冬至\n时从今日渐天长，\n大地微微初聚阳。\n寒气犹存春已近，\n更喜红梅满院香。 ​​​", "image_files": []}, {"poem_id": "107", "title": "七律·孔雀东南飞读感", "genre": "七律", "date": "2019.12.23", "body": "棒打鸳鸯失伴飞，\n别离无奈泪花催。\n弱妻含痛休家去，\n独子凝思耐苦悲。\n各被逼婚心有恨，\n竞相赴死愿无违。\n千年咏唱钟情女，\n何日安得此女归？ ​​​", "image_files": []}, {"poem_id": "108", "title": "七律·颜斶说齐王读感", "genre": "七律", "date": "2019.12.24", "body": "颜斶齐王各命前，\n短文趣事古来传。\n昔时有士昂胸首，\n今日无人陈谏言。\n礼贤下士寻常少，\n慕势贪权盈耳边。\n取巧投机终坏事，\n遭人唾弃更无颜。 ​​​", "image_files": []}, {"poem_id": "109", "title": "七律·沧浪亭记读感", "genre": "七律", "date": "2019.12.25", "body": "黜官野外得幽境，\n傍水临竹构小亭。\n风月柔和踞仰笑，\n山川澄翠绪思明。\n远离仕宦情怀淡，\n亲近林光忘辱荣。\n不与众驱别有趣，\n诗文花鸟悦人生。 ​​​", "image_files": []}, {"poem_id": "110", "title": "七律·有感", "genre": "七律", "date": "2019.12.25", "body": "静无喧闹过三天，\n屏网清晰任我观。\n惟有军人风雪立，\n岂因洋鬼送平安。\n居家当念边关苦，\n出外犹思华夏甘。\n隔夜主席诞辰日，\n请君默默记心间。 ​​​", "image_files": []}, {"poem_id": "111", "title": "满江红·缅怀毛主席", "genre": "满江红", "date": "2019.12.26", "body": "年少心高，铭壮志，\n湘江北去。\n望川岳，茫茫烟雨，\n秋收霹雳。\n瞰井冈风云漫卷，\n藐沉浮信旗高举。\n遵义城，倾力转乾坤，\n谁能比！\n击日寇，除蒋匪，\n城楼上，抒豪气！\n为人民作主，\n动天惊地。\n两弹一星横宇宙，\n五湖四海皆兄弟。\n弹指间，清气满神州，\n山河丽！ ​​​", "image_files": []}, {"poem_id": "112", "title": "七律·独领风骚", "genre": "七律", "date": "2019.12.26", "body": "五帝三皇日月年，\n唐诗汉赋韵连篇。\n文人骚客遥天梦，\n公子王侯欲作仙。\n毛氏笔锋绝万古，\n历朝墨色怎齐肩。\n运筹帷幄神州丽，\n伟略雄韬煜世间。 ​​​", "image_files": []}, {"poem_id": "113", "title": "七律·朱子家训读感", "genre": "七律", "date": "2019.12.27", "body": "晨昏琐事莫嫌烦，\n处世居家忌乱言。\n富贵贫穷诚恳待，\n祖宗后辈勿心偏。\n娶媳嫁女求人品，\n教子读书慎为官。\n恒久行之家业旺，\n简明古训利当前。 ​​​", "image_files": []}, {"poem_id": "114", "title": "七律·斥歪风斜气", "genre": "七律", "date": "2019.12.28", "body": "造假蒙人诚可恨，\n谎言虚数纸连篇。\n张冠李戴寻常事，\n太子换猫都想圆？\n无病呻吟装稚嫩，\n纵情胡闹扮疯癫。\n长空何日清风起？\n霾散天光万里传！ ​​​", "image_files": []}, {"poem_id": "115", "title": "浣溪沙·岁暮吟", "genre": "浣溪沙", "date": "2019.12.29", "body": "腊月初三转眼年，\n春红夏翠已飘然。\n莫失己亥雪花天。\n玉树冬梅别有味，\n银丝斑鬓暖心田。\n临屏咏赋喜流连。 ​​​", "image_files": []}, {"poem_id": "116", "title": "临江仙·深冬暮雾", "genre": "临江仙", "date": "2019.12.30", "body": "雾起黄昏阴暗早，\n潮湿冷气朦胧，\n身边过客俱匆匆。\n残枝垂败叶，\n河水静无冰。\n今岁一直天少雪，\n浮尘常聚高空，\n凭风吹散碧云晴。\n无风尘不去，\n灰色染苍穹。 ​​​", "image_files": []}, {"poem_id": "117", "title": "卜算子·致2019", "genre": "卜算子", "date": "2019.12.31", "body": "睁眼已然年尾，\n路上车流如水，\n奋力向前方，\n只为家国更美。\n无悔，无悔。\n梦想使人陶醉。 ​​​", "image_files": []}, {"poem_id": "118", "title": "菩萨蛮·年前午后", "genre": "菩萨蛮", "date": "2019.12.31", "body": "楼台午后高阳照，\n凭栏心逸云空俏。\n隔夜又新年，\n乘风再向前。\n神州山水处，\n溪岭穿行悟。\n饱览好风光，\n青葱花色香。 ​​​", "image_files": []}, {"poem_id": "119", "title": "行香子·元旦寄怀", "genre": "行香子", "date": "2020.01.01", "body": "岁月无声，今又新年。\n家国盛，华夏人欢。\n山青林翠，碧水云天。\n看花儿繁、鸟儿乐、海儿蓝。\n半生奋斗，近日悠闲。\n爱诗书，几案流连。\n来春心向，郊野田园。\n望世平和、家平妥、友平安。\n祝大家新年快乐！！！ ​​​", "image_files": []}, {"poem_id": "120", "title": "行香子·新年寄语银滩", "genre": "行香子", "date": "2020.01.01", "body": "不是家人，却似亲人。\n来相聚，粤调京音。\n楼前院后，日夜欢心。\n望海中浪、山中寺、空中云。\n春秋寒暑，红翠芳芬。\n白云卷，碧水青林。\n夏凉冬暖，健体安神。\n胜桃花源、梅花坞、杏花村。 ​​​", "image_files": []}, {"poem_id": "121", "title": "长相思·新年好", "genre": "长相思", "date": "2020.01.01", "body": "昨一年，\n今一年。\n抖擞精神更向前，\n晴空丽日天。\n月光绵，\n彩光绵。\n漫步街头喜流连，\n风轻心里甜。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "122", "title": "诉衷情·腊八", "genre": "诉衷情", "date": "2020.01.02", "body": "昨天元旦碧云光，\n今日腊粥香。\n晓星高挂人起，\n窗外细风扬。\n盛两碗，\n满屋芳，\n热中肠。\n心暖绪飞，\n期盼鼠年，\n业旺家康。 ​​​", "image_files": []}, {"poem_id": "123", "title": "七绝·腊八二首", "genre": "七绝", "date": "2020.01.02", "body": "元旦风轻年味浓，\n腊八炉火映晓星。\n色香温润来一碗，\n暖透身心逐梦行。\n夜熬枣米晓清香，\n暖意丝丝缓润肠。\n老伴对桌欢笑语，\n不觉日上小楼窗。 ​​​", "image_files": []}, {"poem_id": "124", "title": "七律·报任安书读感", "genre": "七律", "date": "2020.01.03", "body": "字里行间司马迁，\n耻羞悲愤苦辛酸。\n死生度外心无惧，\n史记为先宁体残。\n获罪因言千古恨，\n成名仗志永相传。\n当时贼子鸿毛去，\n君书君死重泰山。 ​​​", "image_files": []}, {"poem_id": "125", "title": "七律·新农村老父母", "genre": "七律", "date": "2020.01.04", "body": "家中父老不觉孤，\n手把微屏万里呼。\n孝子贤孙心顺气，\n儿来女往信和书。\n不道天涯山路远，\n只缘村落未曾出。\n耄耋老友门前唤，\n慢语欢言笑洒途。 ​​​", "image_files": []}, {"poem_id": "126", "title": "浣溪沙·阖家欢", "genre": "浣溪沙", "date": "2020.01.05", "body": "一路斜阳到帝京，\n黄昏相聚叙亲情。\n闲闻趣事笑谈中。\n儿子家庭新气象，\n外甥女婿更从容。\n微风夜色月朦胧。 ​​​", "image_files": []}, {"poem_id": "127", "title": "七律·遥望", "genre": "七律", "date": "2020.01.05", "body": "京城遥望石门雪，\n片片晶花漫舞天。\n玉树琼枝风里俏，\n腊梅飞鸟斗严寒。\n孩童小院开心闹，\n老者中堂喜上颜。\n期盼一冬有今日，\n飘来祥瑞兆丰年。 ​​​", "image_files": []}, {"poem_id": "128", "title": "五律·雪趣", "genre": "五律", "date": "2020.01.05", "body": "童娃堆雪妞，\n寒冷不言休。\n通体多白色，\n浑身酥软柔。\n红唇萦秀口，\n绿眼泛神谋。\n地上并肩站，\n风中一起游。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "129", "title": "五律·小寒晨练", "genre": "五律", "date": "2020.01.06", "body": "雪落浮尘去，\n拂晓气清新。\n慢跑微出汗，\n深吸醒脑神。\n轻风摇玉树，\n寒鸟隐琼林。\n偶见枝头蕊，\n无言报鼠春。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg", "04.jpg", "05.jpg", "06.jpg"]}, {"poem_id": "130", "title": "七律·谏太宗十思疏读感", "genre": "七律", "date": "2020.01.07", "body": "魏徵切症谏直言，\n无虑得失犯圣颜。\n易取江山难守住，\n详说社稷怎平安。\n处事竭诚无不克，\n纵情傲物事维艰。\n十思成就贞观世，\n一奏忠良万古传。 ​​​", "image_files": []}, {"poem_id": "131", "title": "点绛唇·冬日游园", "genre": "点绛唇", "date": "2020.01.07", "body": "午后清闲，\n醒来惬意街园转。\n东瞧西看，\n黄叶微风乱。\n残雪银山，\n王树冰湖岸。\n寒鸦啭，\n斜阳拂面，\n漫步心怀淡。 ​​​", "image_files": []}, {"poem_id": "132", "title": "清平乐·怀念周总理", "genre": "清平乐", "date": "2020.01.08", "body": "怎能忘记，\n元月单八日。\n泪洒长街天地泣，\n悲送人民总理。\n四十四载春秋，\n英魂激荡神州。\n华夏今非昔比，\n蛟龙誉满环球。\n七律\n周公无子又无私，\n沥血为民才智奇。\n少壮明心华夏起，\n终生践志未曾移。\n虚怀待事情思满，\n和气与人诚不失。\n表里如一堪典范，\n神州内外美名遗。", "image_files": []}, {"poem_id": "133", "title": "七绝·缅怀周总理", "genre": "七绝", "date": "2020.01.08", "body": "无子岂缺思念人\n山川湖海悼英魂\n挺拔俊逸参天树\n万古尘间几度闻 ​​​", "image_files": []}, {"poem_id": "134", "title": "七律·天坛大爷", "genre": "七律", "date": "2020.01.09", "body": "出手惊人艺不凡，\n单双杠上后空翻。\n飞身似燕头高起，\n弓体如蛙背照天。\n已是古稀人倒立，\n赢得青壮眼睁圆。\n年年岁岁风霜笑，\n日月无言鸟雀欢。 https://video.weibo.com/show?fid=1034:4458746198294551 ​​​", "image_files": []}, {"poem_id": "135", "title": "一剪梅·遥望感怀", "genre": "一剪梅", "date": "2020.01.10", "body": "星火桥横闻响笛，\n南北东西，日夜奔驰。\n茫茫车海客心急，\n老少相期，老板相逼。\n遥想当年恋此时，\n窗下吟诗，几案书词。\n人生逐梦恰今昔，\n青发司职，斑鬓悠息。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "136", "title": "七绝·望月", "genre": "七绝", "date": "2020.01.11", "body": "娟娟明月照神京，\n夜色清清望远空。\n回首无言冬又去，\n严寒过后尽春风。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "137", "title": "十六字令·冬", "genre": "十六字令", "date": "2020.01.12", "body": "一\n冬，\n白雪皑皑万里冰。\n春心动，\n千万物萌生。\n二\n冬，\n寒夜梅英舞细风。\n清香溢，\n归客悦心容。\n三\n冬，\n午后楼台避北风。\n高阳照，\n倦意暖融融。 ​​​", "image_files": []}, {"poem_id": "138", "title": "长相思·春归", "genre": "长相思", "date": "2020.01.13", "body": "寒相催，\n暖相催。\n不待多时春又回，\n乾坤万里晖。\n北风吹，\n东风吹。\n杨柳依依花絮飞，\n衡阳雁也归。 ​​​", "image_files": []}, {"poem_id": "139", "title": "七绝·蝴蝶兰", "genre": "七绝", "date": "2020.01.14", "body": "蝶衣片片欲翩跹，\n娇似娉婷妩媚颜。\n韵态宛如梅卧雪，\n清香淡淡自悠然。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "140", "title": "唐多令·致文朋诗友", "genre": "唐多令", "date": "2020.01.15", "body": "群里聚玩家，\n长词短调佳。\n触银屏，妙笔生花。\n平仄和谐音韵美，\n昏暮咏，映朝霞。\n齐诵酒棋茶，\n同吟草木鸦。\n寄情怀，慨叹频发。\n斑鬓红颜人气旺，\n绝律唱，赋诗答。 ​​​", "image_files": []}, {"poem_id": "141", "title": "十六字令·佛", "genre": "十六字令", "date": "2020.01.16", "body": "一\n佛，\n寡欲清心自快活。\n禅中悟，\n除却己身魔。\n二\n佛，\n宽大为怀行善德。\n寻心路，\n独自履山河。\n三\n佛，\n凡世尘间最重和。\n得人敬，\n遍地缘分多。 ​​​", "image_files": []}, {"poem_id": "142", "title": "踏莎行·小年寄怀", "genre": "踏莎行", "date": "2020.01.17", "body": "晓月西南，\n晨曦东泛，\n长空日月遥相见。\n灯笼高挂庆新春，\n火红年味心思念。\n常日团圆，\n而今别散，\n双方父母身边伴。\n阖家老少几头忙，\n人生欢乐金不换。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg", "04.jpg", "05.jpg", "06.jpg"]}, {"poem_id": "143", "title": "渔家傲·遥望", "genre": "渔家傲", "date": "2020.01.18", "body": "客地桥飞楼耸立，\n车流声远匆匆去。\n云淡风轻斜暖日，\n光芒刺，\n平阶垂幕晖横溢。\n岁月掩埋多少事，\n故乡老友凭栏忆，\n不道除夕能否聚。\n心铭记，\n少年哭笑无穷次。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "144", "title": "卜算子·岁暮街景", "genre": "卜算子", "date": "2020.01.19", "body": "岸上雪残存，\n河里冰融化。\n四九微微暖意回，\n鸟雀枝头踏。\n年味渐趋浓，\n遍处红灯挂。\n但见行人脚步急，\n包鼓兜斜挎。 ​​​", "image_files": []}, {"poem_id": "145", "title": "南乡子·大寒寄怀", "genre": "南乡子", "date": "2020.01.20", "body": "拂晓气清寒，\n残月当空镰细弯。\n风摆灯旗欢快舞，\n蹁跹，\n不日迎来子鼠年。\n回首亦安然，\n饱览诗书日月天。\n挚友高朋山海过，\n心甜，\n春暖花开又向前。 ​​​", "image_files": []}, {"poem_id": "146", "title": "如梦令·小酌", "genre": "如梦令", "date": "2020.01.21", "body": "老友樽前欢聚，\n深浅凭心随欲。\n陈酿溢清香，\n勾起馋虫难驭。\n情趣，情趣。\n盏往杯来谁拒。 ​​​", "image_files": []}, {"poem_id": "147", "title": "忆秦娥·年前寄怀", "genre": "忆秦娥", "date": "2020.01.22", "body": "年关近，\n回乡伴母心怀奋。\n心怀奋，\n不拘时日，\n促膝言论。\n半生漂外奔波紧，\n离多聚少心头恨。\n心头恨，\n从今不再，\n孝亲应分。 ​​​", "image_files": []}, {"poem_id": "148", "title": "虞美人·父母愿", "genre": "虞美人", "date": "2020.01.23", "body": "椿萱连日蒸煎煮，\n香气萦门户。\n炊烟袅袅舞云空，\n白发红颜欢喜溢言情。\n喃喃自语心头事，\n只待除夕日。\n鸡鸭鱼肉摆厅堂，\n犒赏儿孙晚辈整年忙。 ​​​", "image_files": []}, {"poem_id": "149", "title": "五绝·秘方", "genre": "五绝", "date": "2020.01.23", "body": "消息满天飞，\n不知能信谁。\n与其忙打问，\n岂若把家回。 ​​​", "image_files": []}, {"poem_id": "150", "title": "七律·辞旧迎新", "genre": "七律", "date": "2020.01.24", "body": "金猪辞岁除夕到，\n玉鼠迎春残雪消。\n喜鹊踏枝鸣树杪，\n归人入户喜眉梢。\n疫情难阻家乡愿，\n高铁成全父老邀。\n华夏一宵同守岁，\n神州万里乐如潮。\n祝亲朋好友身体健康！新年快乐！ ​​​", "image_files": []}, {"poem_id": "151", "title": "七律·新年敬医者", "genre": "七律", "date": "2020.01.25", "body": "逆行身影舞江城，\n别样除夕战疫情。\n昂首离家亏父母，\n低头诊病赛英雄。\n为人舍己堪豪迈，\n救死扶伤美誉升。\n大爱无疆广称赞，\n举国上下志成城。 ​​​", "image_files": []}, {"poem_id": "152", "title": "清平乐·出征", "genre": "清平乐", "date": "2020.01.25", "body": "鲜红指印，\n请战群情奋。\n恰是除夕春晚劲，\n将士江城挺进。\n人民利益崇高，\n舍家千里迢迢。\n携手铲除魔怪，\n徐风温暖同胞。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg", "04.jpg", "05.jpg", "06.jpg"]}, {"poem_id": "153", "title": "浣溪沙·初一有感", "genre": "浣溪沙", "date": "2020.01.26", "body": "恰遇新春闹肺炎，\n除夕心冷感天寒。\n城乡街市少人烟。\n别后相逢隔布罩，\n樽前空对怎言欢。\n平生难忘这一年。 ​​​", "image_files": []}, {"poem_id": "154", "title": "七律·闲咏", "genre": "七律", "date": "2020.01.26", "body": "庚子新年不是味，\n皆因疫起汉阳城。\n神州万众家藏匿，\n华夏千城路禁行。\n幸有白衣拼死战，\n更得将士踏征程。\n南山不老多贤智，\n再斩恶魔尘世清。 ​​​", "image_files": []}, {"poem_id": "155", "title": "浣溪沙·随吟", "genre": "浣溪沙", "date": "2020.01.27", "body": "晓起传来假日添，\n疫情严峻莫心欢。\n居家勿动自平安。\n坚信国家多举措，\n辩听网络少谣言。\n寒冬过后艳阳天。 ​​​", "image_files": []}, {"poem_id": "156", "title": "长相思·武汉", "genre": "长相思", "date": "2020.01.28", "body": "盼新年，\n过新年。\n不道除夕夜色寒，\n江城行路难。\n火神山，\n雷神山。\n三镇乡亲眼欲穿，\n降魔仗此间。 ​​​", "image_files": []}, {"poem_id": "157", "title": "虞美人·致武汉", "genre": "虞美人", "date": "2020.01.28", "body": "惊慌恐惧何时了？\n人祸知多少。\n可怜江汉起寒风，\n野味不堪回首病房中。\n华南市场今犹在，\n日后真能改？\n劝君牢记而今愁！\n痛改前非泪水莫白流！ ​​​", "image_files": []}, {"poem_id": "158", "title": "七绝·初五寄怀", "genre": "七绝", "date": "2020.01.29", "body": "破五心期破疫情，\n炮声阵阵刺长空。\n妖魔鬼怪随烟去，\n还我神州万里晴。 ​​​", "image_files": []}, {"poem_id": "159", "title": "五律·致敬", "genre": "五律", "date": "2020.01.30", "body": "着装席地睡，\n屈体映君心。\n忘却娇儿女，\n难思父母亲。\n醒来还战斗，\n挺立更精神，\n坚韧白衣者，\n泪湿无数人。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "160", "title": "五律·问责唐志红", "genre": "五律", "date": "2020.01.31", "body": "问三三不知，\n日日作何思。\n身在卫生委，\n神离防疫时。\n不谙疾痛苦，\n难对病人慈。\n当场免职去，\n黎民百姓期。 ​​​", "image_files": []}, {"poem_id": "161", "title": "鹧鸪天·夜问", "genre": "鹧鸪天", "date": "2020.02.01", "body": "闪闪银星耀远空，\n可知尘世起瘟情。\n白衣将士身心苦，\n病患黎民日夜疼。\n年假日，却封城，\n人烟稀少月宫惊。\n嫦娥俯瞰凡间事，\n雷火神山景色明。 ​​​", "image_files": []}, {"poem_id": "162", "title": "蝶恋花·庚子新春有感", "genre": "蝶恋花", "date": "2020.02.02", "body": "本是访亲邀友日，\n路上清清，难见人来去。\n街口追查盘问细，\n目光炯炯神情异。\n江汉病魔侵各地，\n形势非常，门户纷纷闭。\n百姓白衣同努力，\n乡村州府除瘟疫。 ​​​", "image_files": []}, {"poem_id": "163", "title": "鹧鸪天·闲咏", "genre": "鹧鸪天", "date": "2020.02.03", "body": "防疫居家茶灶边，\n茗香四溢懒得端。\n青云舒卷随天意，\n麻雀高飞任自欢。\n人坐卧，绪难闲，\n不知前线可平安。\n屏银日日风声紧，\n惟盼江城过险关。 ​​​", "image_files": []}, {"poem_id": "164", "title": "七律·立春有寄", "genre": "七律", "date": "2020.02.04", "body": "又逢春日再题诗，\n正是瘟神肆虐时。\n但愿东风吹晦气，\n惟期初雨洗霉枝。\n冰消雪化云烟暖，\n叶放花开韵色奇。\n万众山前携巨手，\n雄关迈步更心齐。 ​​​", "image_files": []}, {"poem_id": "165", "title": "青玉案·防疫迎春", "genre": "青玉案", "date": "2020.02.05", "body": "风吹庚子新春日，\n更期待，驱瘟疫。\n万寨千城门户闭，\n步移庭院，耳闻风泣，\n眼望云天碧。\n闲思飞绪江城事，\n欣喜白衣再发力，\n雷火神山添利器。\n众心凝聚，军民齐志，\n华夏巍然立。 ​​​", "image_files": []}, {"poem_id": "166", "title": "青玉案·致敬钟老", "genre": "青玉案", "date": "2020.02.06", "body": "南山不老松苍翠，\n斗风雨，迎尘秽。\n闻道龟蛇悲洒泪，\n纵行千里，百般抚慰，\n是以心操碎。\n瘟神肆虐如洪水，\n降住魔头苦难寐。\n心系江城终不悔，\n任眸湿润，于民无愧，\n洁雅如兰桂。 ​​​", "image_files": []}, {"poem_id": "167", "title": "七绝·悼李医生", "genre": "七绝", "date": "2020.02.07", "body": "魔来吹哨无人醒！\n反被追究惊夜梦。\n倘若当初稳稳神，\n挽回多少江城命？ ​​​", "image_files": []}, {"poem_id": "168", "title": "七绝·致武汉相关部门及其后", "genre": "七绝", "date": "2020.02.07", "body": "有脑缺思枉为人，\n未闻临阵哨鸣音。\n糊涂之举终生憾，\n毁誉江城罪对民。 ​​​", "image_files": []}, {"poem_id": "169", "title": "七律·悼文亮医生", "genre": "七律", "date": "2020.02.07", "body": "三十五岁正华年，\n初面瘟神释警言。\n无奈善行遭训戒，\n更逢昏吏扯虚篇。\n江城霎那悲难尽，\n华夏轰然雾满天。\n不幸今朝君又去，\n神州百姓痛心肝。 ​​​", "image_files": []}, {"poem_id": "170", "title": "西江月·庚子元夕", "genre": "西江月", "date": "2020.02.08", "body": "明月可知别苦？\n华人正叹离伤！\n瘟神肆虐遍城乡，\n一场攻坚硬仗。\n龙马花灯不见，\n汤圆珍野无香。\n满怀思念寄前方，\n何日江城解放？ ​​​", "image_files": []}, {"poem_id": "171", "title": "七律·再悼李医生", "genre": "七律", "date": "2020.02.08", "body": "他为苍生说过话，\n读来泪水潸然下。\n平凡言语蕴深情，\n宽阔胸怀天地纳。\n忍爱割慈似远行，\n思儿念母心头挂。\n愿君一路气盈身，\n魑魅瘟神都惧怕。\n转发：2月7日，李文亮医生的妻子付雪洁在社交平台发布声明称：不接受任何个人捐款，网上流传的关于她本人的求助信息均为不实信息。声明全文如下：\n本人付雪洁，襄阳人，是李文亮医生的妻子，本人声明我们不接受任何个人捐款。网上流传的本人求助信息均为不实信息。\n感谢社会各界对李文亮医生及对我们家人的关怀！\n同时我把我丈夫李文亮的《我走了》完成全稿！\n在我成为一粒尘埃之前，我又静静地怀想了一遍故乡的黑土白云。多想回到小时候啊，风是尽情飞舞的，雪是洁白无瑕的。\n活着真好，可我死了。我再也无法抚摸亲人的脸庞，再也无法带孩子去看东湖春晓，再也无法陪父母去看武大樱花，再也无法把风筝放到白云深处。\n我曾依稀梦见我尚未出世的孩子，他（她）一出生就眼含热泪，在人潮人海中把我寻找。对不起，孩子！我知道你只想要一个平凡父亲，而我却做了一个平民英雄。\n天快亮了，我要走了，带着一张保证书，那是我此生唯一的行囊。\n谢谢世间所有懂我怜我爱我的人，我知道你们都在黎明等候，等我越过山丘！可是，我太累了。\n此生，我不想重于泰山，也不怕轻于鸿毛。我唯一的心愿，就是希望冰雪消融之后，众生依然热爱大地，依然相信祖国。\n等到春雷滚滚，如果有人还想纪念我，请给我立一个小小的墓碑吧！不必伟岸，只须证明我曾来过这个世界，有名有姓，无知无畏。\n那么，我的墓志铭只需一句：\n他为苍生说过话。", "image_files": []}, {"poem_id": "172", "title": "鹧鸪天·元宵夜", "genre": "鹧鸪天", "date": "2020.02.09", "body": "月暗星疏各闭门，\n不闻街上闹灯音。\n元夕晚会无观众，\n惟见真情华夏人。\n凝斗志，力千钧，\n瘟神当道铸英魂。\n珞珈山下民同愿，\n万里神州分外亲。 ​​​", "image_files": []}, {"poem_id": "173", "title": "定风波·初春闲咏", "genre": "定风波", "date": "2020.02.10", "body": "多日阴霾转丽天，\n东风徐荡渐心宽。\n喜看疫情新患少，趋好。\n封城闭户众人安。\n小院轻寒莺鹊闹，微笑。\n庭前漫步自成欢。\n更待江城传喜报，尽早。\n神州又见百花繁。 ​​​", "image_files": []}, {"poem_id": "174", "title": "清平乐·闲思", "genre": "清平乐", "date": "2020.02.11", "body": "世间万物，\n千古悠悠处。\n切莫自私浑不顾，\n失道神仙难助。\n风云日月长空，\n山川雨雪辰星。\n花木飞禽走兽，\n与人相辅相成。 ​​​", "image_files": []}, {"poem_id": "175", "title": "苏幕遮·爱无疆", "genre": "苏幕遮", "date": "2020.02.12", "body": "月明圆，思不寐。\n遥寄江城，多少离人泪。\n父母望儿心欲碎，\n挚爱夫妻，千里空相对。\n难当头，心不愧。\n无数白衣，昼夜人憔悴。\n昂首逆行留弱背，\n他日相逢，切莫无情怼。 ​​​", "image_files": []}, {"poem_id": "176", "title": "沁园春·望", "genre": "沁园春", "date": "2020.02.13", "body": "庚子初春，霾雾萦浮，\n尘秽漫飘。\n瞰江城内外，瘟神荡荡，\n大河南北，民意滔滔。\n泪染龟蛇，疫侵黄鹤，\n山海齐心气势高。\n除夕夜，看白衣将士，\n分外妖娆。\n九州赤子多娇，\n引父老乡亲尽折腰。\n敬南山豪迈，几多神采，\n兰娟温雅，无限风骚。\n耋耄之年，倾心呐喊，\n挥臂弯弓射大雕。\n同奋力，斩妖魔鬼怪，\n喜看明朝。", "image_files": []}, {"poem_id": "177", "title": "如梦令·无奈独吟", "genre": "如梦令", "date": "2020.02.14", "body": "夜半雨丝飘落，\n晓起冷风吹彻。\n闻疫更心寒，\n羡野鸟儿飞过。\n神恻，神恻，\n魑魅几时能破。 ​​​", "image_files": []}, {"poem_id": "178", "title": "卜算子·春雪晓寄", "genre": "卜算子", "date": "2020.02.15", "body": "残月挂西南，\n风雪吹来冷。\n晓起凭栏远望天，\n四下悠悠静。\n依旧不开门，\n防疫千般重。\n回坐窗前览古书，\n思绪交先圣。 ​​​", "image_files": []}, {"poem_id": "179", "title": "七律·时事有感", "genre": "七律", "date": "2020.02.16", "body": "言行莫要惹民怨，\n善恶须知天在看。\n身正毋忧地影斜，\n脚歪自是沙痕乱。\n遭人唾弃岂无因，\n受众尊崇难自愿。\n平语近民仁爱心，\n神州大地苍生盼。 ​​​", "image_files": []}, {"poem_id": "180", "title": "渔家傲·春日随咏", "genre": "渔家傲", "date": "2020.02.17", "body": "春晓风寒残叶响，\n暖阳午后窗辉漾，\n伏案悠闲思绪畅。\n随手望，\n谁家词赋眼前亮。\n古者情怀多坦荡，\n苦吟笑对堪豪放，\n千载诗篇一宝藏。\n常向往，\n不时咏诵心神旷。 ​​​", "image_files": []}, {"poem_id": "181", "title": "七绝·题图", "genre": "七绝", "date": "2020.02.17", "body": "机静人闲湛蓝天，\n乱飞鸟雀任由欢。\n可知百姓心中苦，\n日日居家绪不安。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "182", "title": "清平乐·呼唤", "genre": "清平乐", "date": "2020.02.18", "body": "春风依旧，\n无奈山河瘦。\n厂院无人机欲锈，\n街市冷清难购。\n神州何日花开，\n莺飞燕舞萦杯。\n将士凯歌高奏，\n白衣抗疫归来。 ​​​", "image_files": []}, {"poem_id": "183", "title": "渔家傲·期待", "genre": "渔家傲", "date": "2020.02.19", "body": "残雪虽消寒未尽，\n突起瘟情，万户如临阵。\n堵路封城人不顺，\n凭添百姓无名恨。\n到底何因都在问，\n众口纷纭，拭目瞧踪信。\n期待青天雷暴震，\n闪光霹雳传真讯。 ​​​", "image_files": []}, {"poem_id": "184", "title": "七律·雨水日有寄", "genre": "七律", "date": "2020.02.20", "body": "紫气东来风色长，\n千城万寨把毒防。\n而今独对一株柳，\n他日同游万里江。\n华夏山川恒有道，\n龟蛇瘟疫奈何常。\n早春雨水欣然至，\n静待花繁絮卷扬。 ​​​", "image_files": []}, {"poem_id": "185", "title": "浪淘沙·晨望", "genre": "浪淘沙", "date": "2020.02.21", "body": "晓起雾茫茫，\n弥漫无疆。\n倚栏伫立感湿凉。\n防疫掩门何日了，\n苦荡回肠。\n烟霭笼村庄，\n难见鹰翔。\n凭心只盼大风狂。\n吹散阴霾尘秽去，\n晴照溪塘。 ​​​", "image_files": []}, {"poem_id": "186", "title": "蝶恋花·春望", "genre": "蝶恋花", "date": "2020.02.22", "body": "浩荡东风霾雾去，\n晴映山河，阡陌铺新绿。\n无奈掩门防肺疫，\n凭栏独自飞思绪。\n往日春来芳草地，\n车马游人，燕舞莺声细。\n花色纸鸢争俏丽，\n山阳斜照湖光碧。 ​​​", "image_files": []}, {"poem_id": "187", "title": "如梦令·悟", "genre": "如梦令", "date": "2020.02.23", "body": "莫道光阴虚掷，\n庚子春千年计。\n闭户佑神州，\n自有春风和煦。\n凝气、凝气，\n心静神闲明志。 ​​​", "image_files": []}, {"poem_id": "188", "title": "清平乐·龙之愿", "genre": "清平乐", "date": "2020.02.24", "body": "凭空腾起，\n辉映乾坤赤。\n横扫神州庚子疫，\n巷陌山川葱碧。\n行人整备衣装，\n雏莺乳燕争翔。\n花木飘红吐翠，\n湖光岭色呈祥。 ​​​", "image_files": []}, {"poem_id": "189", "title": "蝶恋花·春雨练功", "genre": "蝶恋花", "date": "2020.02.25", "body": "午后转阴飘细雨，\n啭鸟归飞，庭院独幽寂。\n四处无声寒又至，\n云空黯淡回屋去。\n舒体静心松站立，\n两臂轻垂，颔首眸微闭。\n气聚丹田凭运意，\n任督二脉如天地。 ​​​", "image_files": []}, {"poem_id": "190", "title": "满庭芳·独思闲问", "genre": "满庭芳", "date": "2020.02.26", "body": "晓色阴阴，早春清冷，院落空荡无声。\n树头残叶，岑寂舞斜风。\n多日关门谢客，屋檐下，偶有莺呜。\n遥相敬，神州遍地，抗疫众豪英。\n心情，多郁闷。宾朋不见，亲友难逢。\n任酒别金榼，人对虚庭。\n何至今朝如此？当初语：可控休惊。\n谁之过？江城失守，魑魅祸千城！", "image_files": []}, {"poem_id": "191", "title": "临江仙·闲吟", "genre": "临江仙", "date": "2020.02.27", "body": "防疫居家门户闭，\n清悠闲览诗书。\n王杨卢骆耀唐初，\n元白歌盛世，\n李杜竞哀哭。\n翠鸟金鱼皆意境，\n山川秀脑中图，\n欢涛怒水自心出。\n花香飘不断，\n叶落有还无。 ​​​", "image_files": []}, {"poem_id": "192", "title": "浣溪沙·情无尽", "genre": "浣溪沙", "date": "2020.02.28", "body": "防疫隔绝门户间，\n遥思汇聚手屏前，\n文言闪动报平安。\n见字如人心底近，\n闻声视面似身边。\n情温意暖克时艰。 ​​​", "image_files": []}, {"poem_id": "193", "title": "七绝·春晓风色", "genre": "七绝", "date": "2020.02.29", "body": "濛濛渐落纤纤雨，\n细细轻拂昨夜尘。\n远处红灯湿不舞，\n柔风欲暖吻行人。 ​​​", "image_files": []}, {"poem_id": "194", "title": "采桑子·问风", "genre": "采桑子", "date": "2020.03.01", "body": "闭门已耐三十日，\n意绪低迷，\n解禁心期，\n试问春风知不知。\n依然翻卷吹来去，\n摇曳残枝，\n昼夜如斯，\n催染愁颜鬓上丝。 ​​​", "image_files": []}, {"poem_id": "195", "title": "江城子·寄语武汉", "genre": "江城子", "date": "2020.03.02", "body": "东风春日绪难平，\n望江城，寄深情。\n鸿雁高飞，划破碧云空。\n凭借君行传口信：\n荆楚地，尽豪英。\n举国上下志成城，\n战瘟神，聚精兵。\n百姓三军，携手力无穷。\n毕竟酷寒冬已过，\n花正放，看新晴。 ​​​", "image_files": []}, {"poem_id": "196", "title": "玉楼春·疫火怒烧", "genre": "玉楼春", "date": "2020.03.03", "body": "神州之外狼烟起，\n烈焰已然烧美帝。\n先前咧嘴妄狂言，\n不道今朝能有此。\n天涯地角同一体，\n山海同晖千古世。\n人间相助万年安，\n舞爪张牙难度日。 ​​​", "image_files": []}, {"poem_id": "197", "title": "长相思·谁之过", "genre": "长相思", "date": "2020.03.04", "body": "风凄凄，\n路凄凄。\n庚子初春防疫急，\n千家万户离。\n草未萋，\n木未萋。\n怨恨由谁日夜思，\n宵寒月又西。 ​​​", "image_files": []}, {"poem_id": "198", "title": "浣溪沙·惊蛰有寄", "genre": "浣溪沙", "date": "2020.03.05", "body": "乍响春雷万物惊，\n蛰虫骇醒鸟飞鸣。\n东来紫气卷长空。\n驱赶瘟神霄汉外，\n赢得芳翠陌阡中。\n软风摇荡杏枝红。 ​​​", "image_files": []}, {"poem_id": "199", "title": "七绝·今日天安门", "genre": "七绝", "date": "2020.03.05", "body": "城楼高耸入蓝天，\n金柱银灯矗路边。\n倒影清晰天地阔，\n宛如仙境落人间。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "200", "title": "临江仙·股市风云", "genre": "临江仙", "date": "2020.03.06", "body": "冷暖沉浮欢并恨，\n惊魂日日年年。\n银屏红绿舞翩跹。\n霎时崖坠谷，\n转眼跃山巅。\n昨日收盘窃喜，\n今朝开市难言。\n心潮澎湃涨跌间。\n平生如胆小，\n切莫近跟前。 ​​​", "image_files": []}, {"poem_id": "201", "title": "天仙子·古韵屏辉", "genre": "天仙子", "date": "2020.03.07", "body": "书画文词屏上秀，\n南北知音千里凑，\n挥毫泼墨度春秋。\n寻故旧，\n邀新友，\n唱和赏读如醉酒。\n柳赵欧颜宣纸透，\n汉赋唐诗情韵厚，\n九州瑰宝煜双眸。\n童与叟，\n师徒手，\n共仿先贤神意走。 ​​​", "image_files": []}, {"poem_id": "202", "title": "忆王孙·节日寄妻", "genre": "忆王孙", "date": "2020.03.08", "body": "三八恰是月圆时，\n独望蟾宫意绪凄，\n古冶廉州两处思。\n恨别离，\n只盼瘟神滚向西。 ​​​", "image_files": []}, {"poem_id": "203", "title": "七绝·三八敬天使", "genre": "七绝", "date": "2020.03.08", "body": "白衣袅袅若羽轻，\n心暖江城满目情。\n驱散人间瘟疫雾，\n换回云汉九霄明。 ​​​", "image_files": []}, {"poem_id": "204", "title": "七绝·春晓风光", "genre": "七绝", "date": "2020.03.09", "body": "初阳冉冉耀东方，\n春水涟漪漾碧光。\n两岸纤纤垂细柳，\n惺忪娇眼泛蛾黄。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "205", "title": "清平乐·孤酌", "genre": "清平乐", "date": "2020.03.11", "body": "愁闲殢酒，\n独伴庭前柳。\n岂奈掩门难聚友，\n不道春来人瘦。\n枉然天外云光，\n欣欣风色隔墙。\n何日芳郊览翠？\n消除烦闷忧慌。 ​​​", "image_files": []}, {"poem_id": "206", "title": "卜算子·寂叹", "genre": "卜算子", "date": "2020.03.12", "body": "午静鸟清啼，\n窗下闲思乱。\n独处已然月有余，\n愁寂空长叹。\n细柳剪蛾黄，\n院外花香淡。\n心绪随风无限飞，\n遥望云空雁。 ​​​", "image_files": []}, {"poem_id": "207", "title": "采桑子·植树节寄语", "genre": "采桑子", "date": "2020.03.13", "body": "和风煦日难植绿，\n不似昔年，\n种树山前，\n翠柳青杨映碧天。\n心期往日槐梧壮，\n枝叶连连，\n遮蔽云烟，\n迢递花香漫世间。 ​​​", "image_files": []}, {"poem_id": "208", "title": "浣溪沙·方仓医院", "genre": "浣溪沙", "date": "2020.03.14", "body": "生命方舟拯救谁？\n江城百姓万千回。\n遮风避浪闪惊雷。\n霎那瘟魔袭武汉，\n瞬间将士斩蛇龟。\n白衣妙手送春晖。 ​​​", "image_files": []}, {"poem_id": "209", "title": "七绝·遣怀", "genre": "七绝", "date": "2020.03.15", "body": "人生梦想半成非，\n半世沉浮有喜悲。\n富贵终究身外物，\n幸福只在自心扉。 ​​​", "image_files": []}, {"poem_id": "210", "title": "天仙子·瘟神怒", "genre": "天仙子", "date": "2020.03.16", "body": "席卷西方兴巨浪，\n倒海翻江摧陆上，\n千山万壑起风狂。\n洪水涨，\n谁能挡，\n堤岸滩涂残叶广。\n前日讽嘲华夏妄，\n今夜自身无处躺，\n缺情少问遍鳞伤。\n空张望，\n胡乱撞，\n相互咬撕狠狈样。 ​​​", "image_files": []}, {"poem_id": "211", "title": "画堂春·春日寄妻", "genre": "画堂春", "date": "2020.03.17", "body": "闲庭独坐念亲人，\n斜阳西下销魂。\n廉州古冶却连心，\n两处愁春。\n相比江城百姓，\n顿觉万幸安神。\n从今往后重家身，\n平淡才真。 ​​​", "image_files": []}, {"poem_id": "212", "title": "浣溪沙·农家小院", "genre": "浣溪沙", "date": "2020.03.18", "body": "垂柳无言染蛾黄，\n新芽嫩草映花墙。\n清幽庭院洒春光。\n丽日明霞阶上暖。\n流莺脆响荡回肠。\n窗前闲坐绪飞扬  。 ​​​", "image_files": []}, {"poem_id": "213", "title": "蝶恋花·风夜咏", "genre": "蝶恋花", "date": "2020.03.19", "body": "楼外狂风声不住，\n击打疏窗，\n乱叶残枝舞。\n彻夜起伏停又蹙，\n梦中多少离人苦。\n日月轮回失晓暮，\n世道沉浮，\n且把春秋度。\n庚子年来常闭户，\n银丝染镜侵双目。 ​​​", "image_files": []}, {"poem_id": "214", "title": "蝶恋花·别武汉", "genre": "蝶恋花", "date": "2020.03.20", "body": "近日天河频洒泪，\n不舍白衣，\n敬送千滋味。\n各路英雄身已累，\n凯旋归去颜憔悴。\n多是除夕援鄂妹，\n两月拼搏，\n人苦心无愧。\n救死扶伤她最美，\n亲情堪比金翡翠。\n注：武汉天河机场 ​​​", "image_files": []}, {"poem_id": "215", "title": "蝶恋花·别江城", "genre": "蝶恋花", "date": "2020.03.20", "body": "近日天河频洒泪，\n不舍白衣，\n敬送千滋味。\n各路英雄身已累，\n凯旋归去颜憔悴。\n多是除夕援鄂妹，\n两月拼搏，\n人苦心无愧。\n救死扶伤她最美，\n亲情堪比金翡翠。\n注：武汉天河机场 ​​​", "image_files": []}, {"poem_id": "216", "title": "蝶恋花·天使逢春", "genre": "蝶恋花", "date": "2020.03.21", "body": "柳幕垂垂迎赤子，\n翠鸟声声，\n淡淡云空丽。\n花萼欣欣春满地，\n纵横阡陌蒸蒸意。\n千里凯旋人畅喜，\n战疫江城，\n屡屡传佳绩。\n燕赵家亲行重礼，\n英雄儿女心铭记。 ​​​", "image_files": []}, {"poem_id": "217", "title": "七绝·老子二十二章读感", "genre": "七绝", "date": "2020.03.22", "body": "直枉曲全天下道，\n得失多少莫强求。\n明彰有度功长远，\n世事无争更自由。 ​​​", "image_files": []}, {"poem_id": "218", "title": "相见欢·春洒晓院", "genre": "相见欢", "date": "2020.03.23", "body": "朝霞一抹穿庭，\n暖融融，\n树杪轻轻翠叶舞春风。\n花枝绽，\n禽鸟啭，\n小窗明。\n闲坐阶前遥望燕翔空。 ​​​", "image_files": []}, {"poem_id": "219", "title": "七律·春夜寄怀", "genre": "七律", "date": "2020.03.24", "body": "更深独坐静无言，\n惦念亲人难入眠。\n陈酒清香盈翠觯，\n孤灯暗色笼银笺。\n三杯玉液穿肠过，\n几句拙词落纸间。\n难禁遥思眸欲润，\n星空岑寂待明天。 ​​​", "image_files": []}, {"poem_id": "220", "title": "七绝·流氓", "genre": "七绝", "date": "2020.03.24", "body": "米帝全无羞耻布，\n高官信口黄毛助。\n自家瓢碗满尘灰，\n却怨他人纤手妇。 ​​​", "image_files": []}, {"poem_id": "221", "title": "七绝·老子十二章读感", "genre": "七绝", "date": "2020.03.25", "body": "五色令人双目盲，\n五音催断几回肠。\n贪食五味一时快，\n岂料赢得遍体伤。 ​​​", "image_files": []}, {"poem_id": "222", "title": "减字木兰花·晓雨寄杯", "genre": "减字木兰花", "date": "2020.03.26", "body": "清明将到，\n细雨纷纷悲绪绕。\n泪染衣襟，\n多少今人忆故人。\n一年一度，\n相念相思情不住。\n天上人间，\n未了尘缘梦里还。 ​​​", "image_files": []}, {"poem_id": "223", "title": "减字木兰花·防疫峰会", "genre": "减字木兰花", "date": "2020.03.27", "body": "寰球大佬，\n万里连屏属稀少。\n只为新毒，\n共讨良方把病除。\n神州上策，\n分享世间险滩过。\n日月齐辉，\n风雨同舟携手归。 ​​​", "image_files": []}, {"poem_id": "224", "title": "少年游·画像", "genre": "少年游", "date": "2020.03.28", "body": "自觉最是善独思，\n疑世俱无知。\n万民皆醉，\n高天欲倒，\n唯有吾独支。\n出言必语他人傻，\n满眼不相宜。\n东西任我，\n指南损北，\n谁敢不从余。 ​​​", "image_files": []}, {"poem_id": "225", "title": "采桑子·战疫初捷", "genre": "采桑子", "date": "2020.03.29", "body": "移除路卡春风畅，\n天碧云轻，\n万里新晴，\n翠鸟争翔遍处鸣。\n瘟情得控山河喜，\n草木葱茏，\n溪水叮咚，\n百姓欢欣享太平。 ​​​", "image_files": []}, {"poem_id": "226", "title": "减字木兰花·春宵", "genre": "减字木兰花", "date": "2020.03.30", "body": "夕阳如玉，\n日暮斜辉花弄趣。\n烟晕朦胧，\n阵阵清香小院浓。\n纤纤弯月，\n闪闪星光轻洒泻。\n凝伫飞思，\n千里家亲共此时。 ​​​", "image_files": []}, {"poem_id": "227", "title": "苏幕遮·神州内外", "genre": "苏幕遮", "date": "2020.03.31", "body": "夜风寒，\n心底颤。\n异域瘟情，\n患者七十万。\n昔日恶言酸武汉，\n忍看今朝，\n遍处家国乱。\n望神州，\n云水淡。\n战疫初捷，\n日暖山花漫。\n力尽所能情无限，\n放眼寰球，\n旗展五星艳。 ​​​", "image_files": []}, {"poem_id": "228", "title": "减字木兰花·晓寒", "genre": "减字木兰花", "date": "2020.04.01", "body": "冷风吹雨，\n倒灌春寒丝缕缕。\n老弱难支，\n夜醒昼眠不进食。\n阴云暗日，\n烟雾濛濛挥不去。\n期盼天晴，\n万里长空花色明。 ​​​", "image_files": []}, {"poem_id": "229", "title": "忆秦娥·贺父生日", "genre": "忆秦娥", "date": "2020.04.02", "body": "千长寿，\n儿孙祝愿重音奏，\n重音奏。\n神安体健，\n舒心夜昼。\n耄耋霜鬓人淳厚，\n风闲云淡常思旧，\n常思旧。\n一生仗义，\n尊崇盈袖。 ​​​", "image_files": []}, {"poem_id": "230", "title": "蝶恋花·春之病", "genre": "蝶恋花", "date": "2020.04.03", "body": "乍暖乍寒天未定，\n表壮实虚，\n一霎飞来病。\n胸闷头晕神不静，\n三三两两医院碰。\n滴液行针消肿痛，\n昼夜烦心，\n可悔常无动？\n人恙逢春难称兴，\n最当烟酒吃喝控！ ​​​", "image_files": []}, {"poem_id": "231", "title": "减字木兰花·国祭", "genre": "减字木兰花", "date": "2020.04.04", "body": "山河肃静，\n逝者英魂江海敬。\n抗疫辞亲，\n赢取神州万里春。\n名垂千古，\n酹酒凭觞浇热土。\n岁岁清明，\n泪洒川原草木惊。 ​​​", "image_files": []}, {"poem_id": "232", "title": "七律·悼抗疫英烈", "genre": "七律", "date": "2020.04.04", "body": "笛声刺耳入云空，\n旗落杆头祭逝灵。\n山海同悲天地泣，\n岭河齐怨暗尘风。\n英雄儿女辞身去，\n百姓黎民心底生。\n从此清明春雨日，\n神州万里泪盈盈。 ​​​", "image_files": []}, {"poem_id": "233", "title": "七律·时事有思", "genre": "七律", "date": "2020.04.05", "body": "崇洋教化几十年，\n尧舜儿孙总不安。\n域外遭欺呑苦泪，\n家中疑恨月无圆。\n黄毛蓝眼均称客，\n黑脸白牙也上天。\n生米已然半熟饭，\n便能咽下岂心甘？ ​​​", "image_files": []}, {"poem_id": "234", "title": "蝶恋花·闲人忧天", "genre": "蝶恋花", "date": "2020.04.06", "body": "无影青苗多草木，\n只为赔偿，\n乱毁良田处。\n累累伤痕袭眼目，\n陌阡无语情难诉。\n自古粮丰心不怵，\n若靠他人，\n恐断儿孙路。\n莫道九州千万户，\n将来食饮无着处。 ​​​", "image_files": []}, {"poem_id": "235", "title": "采桑子·春日掠影", "genre": "采桑子", "date": "2020.04.07", "body": "芳园闲步香风软，\n柳晕青青，\n草色绒绒，\n欢快悠悠乐曲声。\n倚栏倩侣轻轻语，\n意态娇秾，\n眉目传情，\n远处斜阳映小亭。 ​​​", "image_files": []}, {"poem_id": "236", "title": "忆秦娥·解甲归去", "genre": "忆秦娥", "date": "2020.04.08", "body": "东风劲，\n一宵吹绽花枝盛，\n花枝盛。\n沿堤细柳，\n鳞光摇动。\n九州怒把瘟神送，\n白衣执甲今朝胜，\n今朝胜。\n江城解放，\n万民礼敬。 ​​​", "image_files": []}, {"poem_id": "237", "title": "望江南·三首", "genre": "望江南", "date": "2020.04.09", "body": "多少事，\n庚子九州春。\n突起疫情袭武汉，\n霎时牵动亿人心，\n凝聚到如今。\n白衣将，\n日夜战瘟神。\n不顾身危同奋力，\n救扶病患胜亲人，\n赢取百花春。\n怀歹意，\n码字日发文。\n点火煽风凭臆断，\n斜眸歪嘴乱喷人，\n睁眼坏良心。 ​​​", "image_files": []}, {"poem_id": "238", "title": "七绝·老子第八章读感", "genre": "七绝", "date": "2020.04.10", "body": "上善有谁能似水，\n不争名利亦无忧。\n润滋万物葳蕤状，\n无虑山川遍处流。 ​​​", "image_files": []}, {"poem_id": "239", "title": "一剪梅·春风晓色", "genre": "一剪梅", "date": "2020.04.11", "body": "河岸柔风翠鸟鸣，\n花落花开，\n水碧天晴。\n春光满目郁葱茏，\n紫粉青黄，\n尽展芳容。\n晨练飞奔脚下轻，\n浊气排出，\n体爽神清。\n人生花甲绪思明，\n远事无忧，\n少虑心平。 ​​​", "image_files": []}, {"poem_id": "240", "title": "七绝·老子二十九章读感", "genre": "七绝", "date": "2020.04.12", "body": "天道恒常莫乱为，\n世间万物自行随。\n吹歔隳载由他去，\n自古圣人淡喜悲。 ​​​", "image_files": []}, {"poem_id": "241", "title": "蝶恋花·于无声处", "genre": "蝶恋花", "date": "2020.04.13", "body": "晓月无言荆楚静，\n远处樱花，\n寞寞遥相送。\n将士江城圆使命，\n凯旋不扰黎民梦。\n最是当代人可敬，\n历次灾来，\n上下齐听令。\n军纪严明思想硬，\n五洲四海谁能胜！ ​​​", "image_files": []}, {"poem_id": "242", "title": "七绝·春湖花岸", "genre": "七绝", "date": "2020.04.14", "body": "一\n碧水涟漪翠色深，\n繁花争艳喜游人。\n随风摇曳轻声语，\n何日再来同赏春。\n二\n柳烟袅袅影沉沉，\n湖水清清花色深。\n曲岸小桥欢语处，\n絮飞云卷戏游人。 ​​​", "image_files": []}, {"poem_id": "243", "title": "浪淘沙·牵手", "genre": "浪淘沙", "date": "2020.04.15", "body": "千里冀东行，\n一路春风，\n飞车旷野映晨星。\n冉冉红阳彤似火，\n树暖花明。\n别后苦伤情，\n离绪翻腾，\n相思相望却难逢。\n今日疫情得解放，\n携手从容。 ​​​", "image_files": []}, {"poem_id": "244", "title": "一剪梅·春雨有寄", "genre": "一剪梅", "date": "2020.04.16", "body": "夜半轻闻打叶声，\n细雨悄然，\n梦醒天明。\n芳菲满目脑神清，\n木翠花繁，\n紫粉黄红。\n晓色濛濛雨未停，\n伫立窗前，\n思绪飞萦。\n花开花谢任天公，\n往复循环，\n恰似人生。 ​​​", "image_files": []}, {"poem_id": "245", "title": "浣溪沙·闲庭漫步", "genre": "浣溪沙", "date": "2020.04.17", "body": "午后雨停接晚晴，\n清幽楼院少人声。\n微风阵阵起飞红。\n偶有黄犬窗外吠，\n时闻翠鸟树梢鸣。\n闲情漫步与妻同。 ​​​", "image_files": []}, {"poem_id": "246", "title": "浣溪沙·唐山南湖", "genre": "浣溪沙", "date": "2020.04.18", "body": "塌陷成湖水映天，\n废墟堆变万花山。\n莺飞蝶舞榭桥边。\n丹凤朝阳鸣盛世，\n姮嫦辞月慕凡间。\n春来此处醉八仙。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg", "04.jpg", "05.jpg", "06.jpg"]}, {"poem_id": "247", "title": "七绝·百花赞", "genre": "七绝", "date": "2020.04.19", "body": "平生开谢尽随天，\n雨打风吹默不言。\n无计得失难有恨，\n归根化土亦安然。 ​​​", "image_files": []}, {"poem_id": "248", "title": "踏莎行·黄昏寄语", "genre": "踏莎行", "date": "2020.04.20", "body": "翠色盈庭，\n幽香满径。\n暮春花影微风动。\n斜阳夕照暖人心，\n红英绿叶争相竞。\n脚下清溪，\n眸中秀景。\n昔时山岗荒芜境。\n几年楼筑地翻天，\n而今夜夜温馨梦。 ​​​", "image_files": []}, {"poem_id": "249", "title": "七绝·游园两首", "genre": "七绝", "date": "2020.04.21", "body": "一.\n疫情过后踏新晴，\n曲岸平湖碧水明。\n花盛人闲心绪好，\n小园寻觅旧行踪。\n二.\n湖水清清柳岸明，\n玉兰花绽笑云空。\n沉思忆起当年事，\n四秩光阴一瞬中。 ​​​", "image_files": []}, {"poem_id": "250", "title": "南歌子·春晓远望", "genre": "南歌子", "date": "2020.04.22", "body": "楼外青山远，\n晨风起细沙。\n枝头啼鸟唱春华，\n满眼芳菲、\n无限绪思发。\n花落飘零去，\n燕飞恋故家。\n人生有志闯天涯，\n阔岸高峰、\n极目望朝霞。 ​​​", "image_files": []}, {"poem_id": "251", "title": "减字木兰花·看西方", "genre": "减字木兰花", "date": "2020.04.23", "body": "万分心痛，\n宝贵时光轻放纵。\n大疫当前，\n到处甩锅胡乱言。\n谎称最懂，\n愚弄国人梦难醒。\n恸地悲天，\n无数冤魂怎个安。 ​​​", "image_files": []}, {"poem_id": "252", "title": "相见欢·暮春晓色", "genre": "相见欢", "date": "2020.04.24", "body": "晨曦一缕花明，\n暖融融，\n满院春晖、\n梦醒好心情。\n莺儿啭，\n丁香漫，\n晚樱浓。\n翠叶无言、\n轻舞趁东风。 ​​​", "image_files": []}, {"poem_id": "253", "title": "虞美人·春游曹妃甸", "genre": "虞美人", "date": "2020.04.25", "body": "曹妃湖畔蒹葭密，\n水净云天碧。\n传说渔女救唐王，\n千载悠悠、\n韵味愈芬芳。\n甸边连片高楼起，\n花木欣欣意。\n青桥跨海似飞虹，\n鸥鹭争翔、\n深港远洋行。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg", "04.jpg"]}, {"poem_id": "254", "title": "临江仙·夕照河岸", "genre": "临江仙", "date": "2020.04.26", "body": "碧水清波斜照影，\n无边岸柳垂绦。\n落花柔絮正飘飘。\n风轻摇翠叶，\n云淡燕飞高。\n漫步休闲人渐密，\n疫情恐惧烟消。\n轻松心绪自昭昭。\n时常闻笑语，\n偶有诵歌谣。 ​​​", "image_files": []}, {"poem_id": "255", "title": "七绝·老子第二章读感", "genre": "七绝", "date": "2020.04.27", "body": "雅俗美丑有无间，\n善恶相行伴地天。\n长短盈虚相对望，\n无为胜似乱添言。 ​​​", "image_files": []}, {"poem_id": "256", "title": "临江仙·月季礼赞", "genre": "临江仙", "date": "2020.04.28", "body": "篱下街边花色艳，\n风摇朵朵娇人。\n深红浅粉笑迎君。\n春归从不怨，\n夏日也清新。\n不与杏桃争众赏，\n无言自有芳心。\n秋姿秋色胜当春。\n一生情久远，\n不恋短时亲。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg", "04.jpg", "05.jpg", "06.jpg"]}, {"poem_id": "257", "title": "南乡子·时事有思", "genre": "南乡子", "date": "2020.04.29", "body": "放眼扫寰球，\n瘟疫横行万众愁。\n却有贼人闲找事，\n胡诌，\n乱搅时局嘴脸丢。\n叫嚣比人优，\n抵毁神州壮志酬。\n轻看国民频死去，\n无忧，\n只为私心语不休。 ​​​", "image_files": []}, {"poem_id": "258", "title": "苏幕遮·晖映春岸", "genre": "苏幕遮", "date": "2020.04.30", "body": "晓窗明，惊梦醒。\n啼鸟穿空，\n叶翠花香重。\n漫步河边心绪静。\n吐水金鱼，\n欢跃谁人懂。\n望长川，春浪涌。\n垂柳飘摇，\n月季迎风动。\n林下人声轻诵咏。\n百姓高歌，\n万物朝晖竞。 ​​​", "image_files": []}, {"poem_id": "259", "title": "鹧鸪天·忐忑", "genre": "鹧鸪天", "date": "2020.05.01", "body": "别样年光过五一，\n诚惶诚恐度假期。\n赏花与否心敲鼓，\n戏水可行人不知。\n君切记，勿轻敌，\n随身口罩莫分离。\n三山五岳寻常在，\n岂差今朝望顶池。 ​​​", "image_files": []}, {"poem_id": "260", "title": "七绝·老子三十七章读感", "genre": "七绝", "date": "2020.05.02", "body": "看似无为却有为，\n真心守道气相随。\n无名之朴催人奋，\n动静相辅正自归。 ​​​", "image_files": []}, {"poem_id": "261", "title": "满江红·暮春晓热", "genre": "满江红", "date": "2020.05.03", "body": "晓起潮湿，\n似欲雨、雾尘相伴。\n叶无声、繁花不语，\n苍烟悠远。\n快步河边飞腿炼，\n瞬间汗水衣衫满。\n气短虚、歇脚缓心神，\n桥头站。\n云空渺，无所念。\n不经意，高飞燕。\n俱翩跹振翅、山翻岭转。\n举目周边青草木，\n更闻树杪蝉音乱。\n望天地、万里少清风，\n神难淡。", "image_files": []}, {"poem_id": "262", "title": "鹧鸪天·五四寄怀", "genre": "鹧鸪天", "date": "2020.05.04", "body": "丝雨如尘晓色阴，\n楼台窗下细风频。\n潮湿退去心神爽，\n鸟雀前来语调亲。\n逢五四，忆青春，\n峥嵘岁月铸忠魂。\n今生无悔为华夏，\n来世炎黄好子孙。 ​​​", "image_files": []}, {"poem_id": "263", "title": "鹧鸪天·春暮寄妻", "genre": "鹧鸪天", "date": "2020.05.05", "body": "雨送亲人去帝京，\n银屏连线走停停。\n心期日暮黄昏到，\n不料凌晨午夜行。\n频堵塞，防疫情。\n入城查测不轻松。\n千辛万苦家门进，\n只为儿孙享太平。 ​​​", "image_files": []}, {"poem_id": "264", "title": "踏莎行·春暮寄怀", "genre": "踏莎行", "date": "2020.05.06", "body": "飞絮飘飘，\n落花袅袅。\n枝头叶壮莺声老。\n东风无力柳垂垂，\n斜阳冉冉当庭照。\n风雨春归，\n烟空云渺。\n芳菲渐去桐荫好。\n人生起落莫伤心，\n恰如春去春来早。 ​​​", "image_files": []}, {"poem_id": "265", "title": "南乡子·莫争斗", "genre": "南乡子", "date": "2020.05.07", "body": "夜雨细无声，\n润物轻轻一片情。\n叶翠花娇欢不语，\n祥宁，\n天地从来不抢功。\n人却为虚名，\n争斗难休遍体疼。\n纵使眼前财万贯，\n如风，\n一旦归西两手空。 ​​​", "image_files": []}, {"poem_id": "266", "title": "七绝·后浪别说", "genre": "七绝", "date": "2020.05.08", "body": "一.\n自居前辈语新人，\n后浪之说未入心。\n惟有真诚才是友，\n春风化雨自缤纷。\n二.\n江水连绵千里浪，\n难分前后莫强求。\n一同奔涌东流去，\n岂可超脱独自留！ ​​​", "image_files": []}, {"poem_id": "267", "title": "踏莎行·蓬特之流", "genre": "踏莎行", "date": "2020.05.09", "body": "信口雌黄，\n贼心若墨。\n无中生有飞污沫。\n是非颠倒却寻常，\n移花接木民惊愕。\n狼狈为奸，\n狗猪同卧。\n咬人吠日声名恶。\n搅得天下不能安，\n万年遗臭遭千唾。 ​​​", "image_files": []}, {"poem_id": "268", "title": "满江红·节日敬娘亲", "genre": "满江红", "date": "2020.05.10", "body": "回首当初，依稀记，\n时时牵手。\n拥怀里，寒冬亦暖，\n温馨腕肘。\n巧施针线缝衣裤，\n妙用食材香过肉。\n脚步捷、四季不得闲，\n人清瘦。\n如今日，银丝抖。\n双耳背，常怀旧。\n总开心悠乐，\n门庭慢走。\n一日三餐仍自理，\n念女挂儿凭夜昼。\n愿双亲、犹似泰山松，\n千长寿。", "image_files": []}, {"poem_id": "269", "title": "南歌子·备而无患", "genre": "南歌子", "date": "2020.05.11", "body": "五月天多变，\n晴空骤雨飘。\n行人无备总挨浇，\n苦痛难言、咳嗽又发烧。\n国际风云乱，\n反华怪调高。\n九州有备任他嚣，\n猎手神枪、岂让虎狼逃。 ​​​", "image_files": []}, {"poem_id": "270", "title": "一剪梅·少怨自安", "genre": "一剪梅", "date": "2020.05.12", "body": "春暮欢娱闹市东，\n溪水叮当，\n陌上青青。\n花繁鸟啭舞蝶蜂，\n翼展飞香，\n风起云惊。\n乱絮茫茫落又升，\n扑面遮眸，\n扰乱心情。\n一天好事半成空，\n切勿伤怀，\n莫怨天公。 ​​​", "image_files": []}, {"poem_id": "271", "title": "七绝·老子二十三章读感", "genre": "七绝", "date": "2020.05.13", "body": "骤雨急来难日久，\n惊风乍起只一朝。\n苍天尚且才如此，\n况于人乎有妙招？ ​​​", "image_files": []}, {"poem_id": "272", "title": "南乡子·晓园风色", "genre": "南乡子", "date": "2020.05.14", "body": "烟暖晓风柔，\n青翠街园人渐稠。\n歌舞太极随乐起，\n悠悠，\n散尽疫情庚子愁。\n鸟雀绕枝头，\n溪水潺潺碧色流。\n草里虫儿闲不住，\n啾啾，\n月季荷花曲径幽。 ​​​", "image_files": []}, {"poem_id": "273", "title": "南乡子·疫情飘过", "genre": "南乡子", "date": "2020.05.14", "body": "烟暖晓风柔，\n青翠街园人渐稠。\n歌舞太极随乐起，\n悠悠，\n散尽疫情庚子愁。\n鸟雀绕枝头，\n溪水潺潺碧色流。\n草里虫儿闲不住，\n啾啾，\n月季荷花曲径幽。 ​​​", "image_files": []}, {"poem_id": "274", "title": "苏幕遮·槐香清韵", "genre": "苏幕遮", "date": "2020.05.15", "body": "晚风轻，香气漫。\n辞树槐花，\n飘过深墙院。\n归鸟栖息蝉响软。\n夜色如银，\n枝影花阴散。\n漾清辉，弯月灿。\n幽景宜人，\n惬意心怀展。\n把酒问天星闪闪，\n意荡天河，\n静望飞思远。 ​​​", "image_files": []}, {"poem_id": "275", "title": "踏莎行·贺兄嫂山居", "genre": "踏莎行", "date": "2020.05.16", "body": "清晓急行，\n初阳高速。\n悠悠云雾山前驻。\n凭栏缓上半山中，\n潺潺溪水萦新户。\n挚友亲朋，\n群贤共路。\n樽前把酒情无数。\n扬眉弹指几十年，\n车轱山下轻轻诉。 ​​​", "image_files": []}, {"poem_id": "276", "title": "浣溪沙·元谷山庄", "genre": "浣溪沙", "date": "2020.05.17", "body": "栈道曲栏入碧天，\n潺潺溪水舞长川。\n闲情漫步翠无边。\n一路蜂蝶萦脚下，\n千年茶树卧山前。\n清幽行宿彩云间。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg", "04.jpg", "05.jpg", "06.jpg"]}, {"poem_id": "277", "title": "一丛花·车轱辘山有感", "genre": "一丛花", "date": "2020.05.18", "body": "当年荒径草萋萋，\n林暗鸟声稀。\n石垣断壁山腰处，\n院空空，残叶陈丝。\n往日人家，难寻踪影，\n老树记当时。\n今朝山下起新居，\n老少俱心怡。\n清溪筑坝平湖满，\n路宽宽，树茂花滋。\n袅袅炊烟，盈盈笑语，\n处处显生机。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "278", "title": "七律·痛悼刘总", "genre": "七律", "date": "2020.05.19", "body": "初夏晨风尚显凉，\n驱车郊外草茫茫。\n忍悲含泪别师长，\n掩面伤心断寸肠。\n笑貌音容难再见，\n良言暖语永留香。\n君今驾鹤西归去，\n无虑无忧日月翔。 ​​​", "image_files": []}, {"poem_id": "279", "title": "菩萨蛮·咏日晕", "genre": "菩萨蛮", "date": "2020.05.19", "body": "飞虹五彩萦白日，\n环心耀眼天光炽。\n奇特碧云空，\n赢得呐喊声。\n谁人挥巨笔？\n成此千年丽。\n无限叹苍穹，\n妙谜多少层？ ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "280", "title": "如梦令·520寄亲人", "genre": "如梦令", "date": "2020.05.20", "body": "三个字心中念，\n独默语千千遍。\n依旧未说出，\n只仰仗灵犀唤。\n心愿，心愿。\n来世今生难变！ ​​​", "image_files": []}, {"poem_id": "281", "title": "七绝·初夏暮色", "genre": "七绝", "date": "2020.05.21", "body": "黄昏夕照溢丁香，\n树下悠闲扯话长。\n翠叶微风人不倦，\n楼窗点点染红光。 ​​​", "image_files": []}, {"poem_id": "282", "title": "七绝·石门风雨", "genre": "七绝", "date": "2020.05.21", "body": "午后黑云城欲摧，\n惊雷阵阵鸟横飞。\n狂风骤雨窗前过，\n童稚闻声哭皱眉。 ​​​", "image_files": []}, {"poem_id": "283", "title": "破阵子·风云突变", "genre": "破阵子", "date": "2020.05.22", "body": "霎那雷鸣电闪，\n晴空骤暗天惊。\n枝叶丛花狂起落，\n乱卷黑云雨伴风。\n只闻刺耳声。\n无奈行人湿透，\n可怜飞鸟迷笼。\n戏水鸳鸯含恨去，\n遍地积流漫西东。\n老天也耍疯。 https://video.weibo.com/show?fid=1034:4507298748628996 ​​​", "image_files": []}, {"poem_id": "284", "title": "七绝·感恩前浪", "genre": "七绝", "date": "2020.05.23", "body": "新枝翠叶渐趋浓，\n烈日当头荫下行。\n幸有前人勤种树，\n方得今日夏凉风。 ​​​", "image_files": []}, {"poem_id": "285", "title": "洞仙歌·城河暮色", "genre": "洞仙歌", "date": "2020.05.24", "body": "黄昏云淡，又踏城河岸。\n柔软风来暗香漫。\n水波清，鱼戏垂柳悠闲，\n夕阳影，碧色波光零乱。\n余辉花亦灿，月季蔷薇，\n脉脉含情自争艳。\n莺啭彩蝶飞，结对成双，\n蹁跹舞，惹人目昡。\n子孙乐，苍音应童言，\n总笑语欢声，意浓情满。 ​​​", "image_files": []}, {"poem_id": "286", "title": "清平乐·咏麦浪", "genre": "清平乐", "date": "2020.05.25", "body": "晴空曦照，\n碧浪青烟袅。\n卧雪逢春情未了，\n风雨沉浮不倒。\n历经冻土冰霜，\n嫩苗细叶蔫黄。\n凭借东风又起，\n今朝万里飞扬。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "287", "title": "唐多令·雨后小园", "genre": "唐多令", "date": "2020.05.26", "body": "丝雨润芳茵，\n娇花翠叶新，\n径清幽，漫步菲林。\n望柳闻香溪水处，\n人不语，欲销魂。\n树杪鸟飞音，\n红黄月季亲，\n细风摇，煞是招人。\n雨送春归花却盛，\n尘间事，莫忧心。 ​​​", "image_files": []}, {"poem_id": "288", "title": "阮郎归·民心河畔", "genre": "阮郎归", "date": "2020.05.27", "body": "绿槐青柳响新蝉，\n晴空飒爽天。\n风轻香淡漫河边，\n神闲老少欢。\n歌舞秀，太极拳，\n花绳小狗牵。\n空竹花剑甩长鞭，\n悠悠日落山。 ​​​", "image_files": []}, {"poem_id": "289", "title": "清平乐·巅峰漫步", "genre": "清平乐", "date": "2020.05.28", "body": "珠峰雪动，\n玉帝山神醒。\n红色觇标华夏影，\n不惧风寒云冷。\n丈量巨子身高，\n神州脊背多娇。\n自古顶天立地，\n雄伟傲视今朝。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg", "04.jpg"]}, {"poem_id": "290", "title": "菩萨蛮·敬任总", "genre": "菩萨蛮", "date": "2020.05.29", "body": "九州内外千头绪，\n夜深独自思娇女。\n已是鬓白人，\n华为精气神。\n当初谋远虑，\n今日豺狼惧。\n厚禄不惟亲，\n方得威虎军。 ​​​", "image_files": []}, {"poem_id": "291", "title": "菩萨蛮·初夏晓寄", "genre": "菩萨蛮", "date": "2020.05.30", "body": "凭栏晓望西南月，\n闻听树杪蛩螀咽。\n清爽院前风，\n往来翠鸟鸣。\n红日东方起，\n霞光行万里。\n初夏又一天，\n心期好梦圆。 ​​​", "image_files": []}, {"poem_id": "292", "title": "菩萨蛮·人头鬼面", "genre": "菩萨蛮", "date": "2020.05.31", "body": "火光风景黑人泪，\n迎来川普开枪怼。\n异地事相同，\n一人两样声。\n煽风吹鬼火，\n信口雌黄客。\n肚里坏心肠，\n却披虚善装。 ​​​", "image_files": []}, {"poem_id": "293", "title": "唐多令·庚子学童", "genre": "唐多令", "date": "2020.06.01", "body": "童稚戏街园，\n天真无虑颜。\n踏轮滑，飞向花边，\n满目紫红情不尽。\n惊而叫，舞蹁跹。\n庚子疫情年，\n假期一再延。\n久宅家，身躁心烦，\n学校无缘嘻草地。\n人尚小，不知难。 ​​​", "image_files": []}, {"poem_id": "294", "title": "七绝·六一随想", "genre": "七绝", "date": "2020.06.01", "body": "童心未泯鬓飞霜，\n山水游学胜课堂。\n拜友访朋情不尽，\n尊贤敬老为孙忙。 ​​​", "image_files": []}, {"poem_id": "295", "title": "渔家傲·所谓灯塔", "genre": "渔家傲", "date": "2020.06.02", "body": "烟燎白宫风景线，\n黄毛歪嘴心神乱。\n虚伪说辞自呑咽。\n一浑蛋，\n威胁恶狗人群窜。\n信口胡诌天怒犯，\n熊熊烈火民声怨。\n失道赢得朋背叛。\n天正变，\n阑风伏雨年光换。 ​​​", "image_files": []}, {"poem_id": "296", "title": "七绝·题图", "genre": "七绝", "date": "2020.06.02", "body": "一腔坏水两张皮，\n醉语痴言独自迷。\n小丑跳梁天下笑，\n腥臊臭味万年遗。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "297", "title": "如梦令·廉州情谊", "genre": "如梦令", "date": "2020.06.03", "body": "兄弟黄昏相聚，\n把盏凭风萦趣。\n新友旧朋欢，\n南北东西飞绪，\n无虑，无虑。\n戴月扶墙归去。 ​​​", "image_files": []}, {"poem_id": "298", "title": "减字木兰花·遐思", "genre": "减字木兰花", "date": "2020.06.04", "body": "鬓丝飞坠，\n记取浮生欢与醉。\n华发稀松，\n历尽人间雨雪风。\n初心如水，\n细流向东终不悔。\n喜看苍山，\n暮色斜阳五彩天。 ​​​", "image_files": []}, {"poem_id": "299", "title": "七绝·农家乐", "genre": "七绝", "date": "2020.06.05", "body": "又是金黄麦浪翻，\n机收胜却手工镰。\n乡村父老开怀笑，\n免去弯腰背向天。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "300", "title": "满江红·闲看风云", "genre": "满江红", "date": "2020.06.06", "body": "今日寰球，\n凡乱处、难缺美帝。\n煽鬼火、阴风不断，\n魅魂频起。\n利己害人浑不顾，\n退群失信成新癖。\n恶棒飞、舞爪阻春风，\n白费力！\n瘟情漫、黑人死，\n平民怼、川普气。\n看白宫灯灭，黄毛躲避。\n军警开枪瞄百姓，\n人权落幕惊天地。\n霸式微，如落日云烟，\n终将逝！", "image_files": []}, {"poem_id": "301", "title": "七绝·高山雪莲", "genre": "七绝", "date": "2020.06.07", "body": "独立冰山笑碧空，\n无人欣赏亦从容。\n世间若此清心态，\n何惧东西雨雪风。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "302", "title": "七绝·石门风雨", "genre": "七绝", "date": "2020.06.08", "body": "午后黑云城欲摧，\n惊雷阵阵鸟横飞。\n狂风骤雨窗前过，\n童稚闻声哭皱眉。 ​​​", "image_files": []}, {"poem_id": "303", "title": "点绛唇·往事如烟", "genre": "点绛唇", "date": "2020.06.09", "body": "千载长城，\n今朝闲卧山川翠。\n旧砖昔垒，\n曾记英雄泪。\n塞外狼烟，\n将士心神碎。\n人难寐，\n死生无畏，\n凭挡匈奴锐。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "304", "title": "西江月·风光无限", "genre": "西江月", "date": "2020.06.10", "body": "早晚河边垂钓，\n午间树下歇凉。\n浮生往事不思量，\n且把今朝乐享。\n喜看金鱼戏水，\n厌听乌雀啼腔。\n夕阳正是好时光，\n一任鬓丝飞荡。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "305", "title": "踏莎行·夜行随想", "genre": "踏莎行", "date": "2020.06.11", "body": "夜色无尘，\n细风轻爽。\n闲行河岸心怀敞。\n波光流水静无声，\n丁香淡淡悠悠淌。\n暗柳低垂，\n银灯明朗。\n喧嚣褪去桥宽广。\n人生何必尽扎堆，\n疏篱曲径清幽享。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "306", "title": "七绝·咏竹", "genre": "七绝", "date": "2020.06.12", "body": "虚心向上志凌云，\n直挺身躯不染尘。\n翠叶青青根入地，\n迎风纳雪更精神。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "307", "title": "减字木兰花·中流击水", "genre": "减字木兰花", "date": "2020.06.13", "body": "无情暴雨，咆哮奔腾千万里。\n肆虐家园，毁物伤人百姓难。\n谁能击水，除害为民心最美。\n赤胆深情，伏虎降龙子弟兵。 ​​​", "image_files": []}, {"poem_id": "308", "title": "临江仙·乡村教师", "genre": "临江仙", "date": "2020.06.14", "body": "桃李芬芳心底梦，\n护苗培土耕耘，\n修枝剪叶总熬神。\n春秋寒暑苦，\n岁月几重轮。\n乡野寄身衾枕冷，\n霜丝飞鬓留痕，\n韶华默默伴童音。\n课堂学子笑，\n村上少闲人。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "309", "title": "小重山·惊闻", "genre": "小重山", "date": "2020.06.15", "body": "清晓传来霹雳声，\n惊回千里梦，\n绪难平。\n帝都冠肺又重生。\n来势猛，\n神骇北平城。\n防疫莫稀松，\n随身携口罩，\n慎出行。\n生鲜海货且消停。\n别为嘴，\n毁了子安宁。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "310", "title": "七绝·熊童子", "genre": "七绝", "date": "2020.06.16", "body": "初生浅绿态乖萌，\n嫩脸纤绒点缀红。\n今日盛开花粉色，\n群观独赏趣无穷。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "311", "title": "玉楼春·别样烟火", "genre": "玉楼春", "date": "2020.06.17", "body": "卖花沽酒街头市，\n早晚升腾烟火气。\n推车挑担挽箩筐，\n赔赚不攀人自喜。\n疫情耽误民生计，\n马路地摊堪好事。\n行人过客买心欢，\n翁妪来回寻可意。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "312", "title": "七律·闲咏", "genre": "七律", "date": "2020.06.17", "body": "耳闻目染春秋事，\n昼赋宵词满纸篇。\n绿水青山林草翠，\n银花火树月人圆。\n携朋聚友山间笑，\n换盏推杯席上颠。\n不为声名多显赫，\n只求文脉永相传。 ​​​", "image_files": []}, {"poem_id": "313", "title": "七绝·自醒", "genre": "七绝", "date": "2020.06.18", "body": "树有高低各向天，\n人生长短且心欢。\n切莫自寻烦恼事，\n免得神绪不能安。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "314", "title": "卜算子·逍遥游", "genre": "卜算子", "date": "2020.06.18", "body": "独自踏千山\n挥手峦峰站\n万里晴空鸿雁飞\n云卷思无限\n丽日醉春风\n远客迷花岸\n溪水潺潺翠鸟鸣\n紫陌红霞漫 ​​​", "image_files": []}, {"poem_id": "315", "title": "清平乐·农家乐", "genre": "清平乐", "date": "2020.06.18", "body": "庭轩窄小\n翠鸟鸣花草\n丽日青云风色好\n廊下欢言翁媪\n爷爷植绿墙东\n看鸡奶奶扶笼\n嘻耍童孙可爱\n追逐起落飞蓬 ​​​", "image_files": []}, {"poem_id": "316", "title": "江城子·百花颂", "genre": "江城子", "date": "2020.06.18", "body": "一年四季海棠花，\n水仙花，百合花。\n淡雅清香，还看吊兰花。\n皇后之花称月季，\n情浪漫，杜鹃花。\n公主悠悠品昙花，\n望莲花，赏梅花。\n大瓣七星，月月百兰花。\n飘逸芳香惟茉莉，\n真国色，牡丹花。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "317", "title": "七绝·咏松柏", "genre": "七绝", "date": "2020.06.19", "body": "塞北江南川岭处，\n风霜寒暑挺拔生。\n一任百花开又落，\n初心不改郁葱葱。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "318", "title": "一剪梅·思念", "genre": "一剪梅", "date": "2020.06.19", "body": "不尽长江滚滚流，\n望岳阳楼    ，\n倚岳阳楼。\n凭栏远眺绪难收，\n白浪飞鸥，\n往事悠悠。\n畅想当年携手游，\n五岳山头，\n四海潮头。\n而今独自在高楼，\n思念无休，\n憧憬无休。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "319", "title": "少年游·无奈", "genre": "少年游", "date": "2020.06.20", "body": "前期准拟去京城，\n不道疫情生。\n往来受限，情怀失落，\n好事又成空。\n瘟神南北沉浮起，\n此次更心惊。\n到底何时，风清云淡，\n万里自由行？ ​​​", "image_files": ["01.jpg"]}, {"poem_id": "320", "title": "七绝·闲咏", "genre": "七绝", "date": "2020.06.20", "body": "诗词文史大观园，\n诸子先贤心路宽。\n倚马荡舟揽仙气，\n赏云傍月柳桃边。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "321", "title": "浣溪沙·敬老父亲", "genre": "浣溪沙", "date": "2020.06.21", "body": "耋耄微躯耳渐残，\n难听言语自忧烦。\n时常郁闷使人怜。\n昔日当家成大事，\n今朝孤怯远人前。\n南山不老我心间。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "322", "title": "七绝·三重日", "genre": "七绝", "date": "2020.06.22", "body": "夏至日食六月天，\n长空万里耀金环。\n父亲节里恩情重，\n孝子贤孙二老前。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "323", "title": "七律·寄怀", "genre": "七律", "date": "2020.06.23", "body": "时光流逝朱颜换，\n斑鬓吟诗静自安。\n春日畅游山水绿，\n秋风饱览叶霞丹。\n人生有爱恩情厚，\n心底无私天地宽。\n万里穿行星斗亮，\n凭栏远眺夜阑珊。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "324", "title": "浣溪沙·饮抒怀", "genre": "浣溪沙", "date": "2020.06.23", "body": "玉液微酣意绪飞，\n悲愁欢喜更相催。\n花前月下梦中追。\n拂晓凭空翻巨浪，\n黄昏倚枕望斜晖。\n樽前言语似风吹。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "325", "title": "清平乐·神奇北斗", "genre": "清平乐", "date": "2020.06.23", "body": "星辰北斗，\n千载牵人走。\n今日凭辉观宇宙，\n华夏乾坤在手。\n苍茫山海云空，\n寰球巡望无穷。\n转眼投足微笑，\n丝丝尽纳其中。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "326", "title": "七绝·龙象之争", "genre": "七绝", "date": "2020.06.24", "body": "一拳打破阿三梦，\n称霸南亚似絮萍。\n飘落只应随水去，\n无碍江河起巨龙。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "327", "title": "七律·银滩风色", "genre": "七律", "date": "2020.06.24", "body": "红虾紫蟹当街市，\n母爱乳山华夏知。\n好客银滩花满路，\n迎人玉液酒盈瓻。\n碧宵天阔观明月，\n白昼水清吟古诗。\n草木漫山风色美，\n神州南北万人痴。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "328", "title": "山花子·端午寄怀", "genre": "山花子", "date": "2020.06.25", "body": "又是端阳棕米香，\n黎民情洒汨罗江。\n各路龙舟风正劲，\n渡潇湘。\n屈子楚辞千古诵，\n离骚天问韵悠长。\n今看神州山水秀，\n奏华章。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "329", "title": "七律·端午感怀", "genre": "七律", "date": "2020.06.25", "body": "棕情飘溢漫天香，\n万户千家蒸煮忙。\n南北龙舟齐奋进，\n东西乡友祝安康。\n古人含恨投江去，\n今客梦圆霄汉翔。\n覆地翻天山海秀，\n神州万里映高阳。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "330", "title": "七律·端午游", "genre": "七律", "date": "2020.06.25", "body": "雨后西山尽兴玩，\n飘香黄粽惹心甜。\n满坡红杏枝头挂，\n转角青梅人眼馋。\n峰顶飞云携玉色，\n山间栈道翠相连。\n亭台花鸟晴空下，\n南北清风任自然。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "331", "title": "七绝·端午寄", "genre": "七绝", "date": "2020.06.25", "body": "情倾汨罗千百年，\n文人骚客赋诗篇。\n悲词痛句哭屈子，\n凭粽飞舟问九天。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "332", "title": "七绝·屈原", "genre": "七绝", "date": "2020.06.26", "body": "凭风愁对江头月，\n天问九章悲愤歌。\n人去情怀昭万世，\n年年端午泪婆娑。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "333", "title": "七绝·明星恨", "genre": "七绝", "date": "2020.06.26", "body": "台前光艳万人追，\n窗后肮脏毒粉催。\n失律酿成千古恨，\n有何颜面再回归。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "334", "title": "十六字令·井冈山", "genre": "十六字令", "date": "2020.06.26", "body": "山，\n青翠茫茫袅袅烟。\n人居此，\n不愿做神仙。\n山，\n百里方圆峻岭连。\n黄洋界，\n一炮退敌千。\n山，\n遥望当年尽杜鹃。\n思先烈，\n血色映红天。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "335", "title": "水调歌头·荷花淀", "genre": "水调歌头", "date": "2020.06.27", "body": "日照荷塘水，鸿雁映云天。\n微风摇荡垂柳，翠叶藕相连。\n午后骄阳烈烈，花懒蝉鸣蛙叫，\n昏暮转清寒。\n湖碧光波漾，云影舞青莲。\n霓虹闪，笙歌漫，久难眠。\n倚栏昂首，遥望穹宇冷蟾圆。\n半世忙忙碌碌，奔波月月年年，\n家事不周全。\n往后心思少，日日共婵娟。", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "336", "title": "七绝·赏名画", "genre": "七绝", "date": "2020.06.27", "body": "墨香千载溢人间，\n闻宝凝情拜圣贤。\n神聚丹青思不尽，\n先朝人事在眼前。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "337", "title": "七绝·仝卓恨", "genre": "七绝", "date": "2020.06.28", "body": "丑事还当美事说，\n嬉皮笑脸却砸锅。\n曾经都把金银碗，\n口爽一时毁一窝。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "338", "title": "沁园春·旧照寄怀", "genre": "沁园春", "date": "2020.06.28", "body": "触物思人，念想师恩 ，\n往事胜新。\n忆当年少子，京城问道，\n家国社会、地理天文。\n何去何从、东西苦闷，\n总赖师长操碎心。\n经四载，历春秋寒暑，\n身瘦销魂。\n四十冬夏缤纷，\n虽不见，音容格外亲。\n愿时光倒转，师生再聚。\n天南地北、把酒微醺。\n北海同舟、香山携手。\n白发苍颜又一村。\n惟所盼，体康心情悦，\n轻看千金。", "image_files": ["01.jpg"]}, {"poem_id": "339", "title": "阮郎归·夏雨", "genre": "阮郎归", "date": "2020.06.29", "body": "惊风飘过玉珠连，\n新凉入锦帘。\n炎光湿热退窗前，\n气清人自闲。\n依案坐，旧书翻，\n钟情李杜篇。\n花溪蜀道默心间，\n悄然日已偏。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "340", "title": "一丛花·鹤翔桩", "genre": "一丛花", "date": "2020.06.30", "body": "晓来又落雨如帘，\n白雾卷窗前。\n出门晨练天难许，\n且屋内，意守丹田。\n经络并行，周身舒缓，\n任督气连绵。\n身躯松立手虚含，\n两眼视平川。\n天通百会收阳气，\n凭心念，浊泻涌泉。\n人静意空，浑然一体，\n日久自延年。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "341", "title": "卜算子·自乐", "genre": "卜算子", "date": "2020.06.30", "body": "只为爱诗词，\n彼此精心护。\n谁若心情不爽时，\n群里来相处。\n愁事任他流，\n换个新思路。\n咏赋吟诗韵味浓，\n时日悠然度。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "342", "title": "满江红·七一颂", "genre": "满江红", "date": "2020.07.01", "body": "九九为功，红旗艳，神州飘荡。\n庚子夏，转身难忘，鼠年春象。\n疫起江城民俱骇，\n情凝华夏心同向。\n政令通，赤子聚八方，争前上。\n白衣俏，迷彩壮。\n南山火，兰娟靓。\n险滩冲头阵，立杆为样。\n塞北江南迎紫陌，\n山清水秀繁花放。\n看寰球，\n魍魉魅魑惊，龙飞畅。", "image_files": ["01.jpg", "02.jpg", "03.jpg", "04.jpg"]}, {"poem_id": "343", "title": "长相思·再回归", "genre": "长相思", "date": "2020.07.01", "body": "国思安，\n民思安。\n忍耐多时客走偏。\n今朝出手牵。\n陆人欢，\n港人欢。\n少数蛀虫心胆寒。\n香江水更蓝。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "344", "title": "清平乐·七一感怀", "genre": "清平乐", "date": "2020.07.01", "body": "初心不忘，\n山海翻红浪。\n天路星桥千里望，\n五彩祥云卷放。\n天涯地角花开，\n林间岭上蜂来。\n平野庭轩硕果，\n城乡老少怡怀。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "345", "title": "七绝·老子第一章读感", "genre": "七绝", "date": "2020.07.02", "body": "可名可道皆玄妙，\n天地之始万物生。\n上下纵横多少事，\n人间精髓道德经。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "346", "title": "西江月·贺友生日", "genre": "西江月", "date": "2020.07.02", "body": "暑气漫袭南北，\n鸣莺劲舞东西。\n藉由鸿雁寄相思，\n岁岁年年如此。\n昔日同窗欢度，\n今朝异地心期。\n临屏把酒醉吟诗，\n句句杯杯情意。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "347", "title": "玉楼春·雨天有寄", "genre": "玉楼春", "date": "2020.07.03", "body": "云烟卷弄廉纤雨，\n阵阵轻雷来又去。\n绿杨高柳翠无声，\n叶底惊蝉缺意绪。\n高楼独自谁能语，\n嚼字咬文攀雅趣。\n心神交会圣贤人，\n期与苏辛梦相遇。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "348", "title": "清平乐·荷花", "genre": "清平乐", "date": "2020.07.04", "body": "芙蓉出水，\n风色莺蝶醉。\n嫩蕊清香枝叶翠，\n辉映曲塘明媚。\n韵和隐处鸣蛙，\n根通莲藕馨家。\n无愧花之君子，\n淤泥不染芳华。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "349", "title": "七律·晨练", "genre": "七律", "date": "2020.07.04", "body": "曦辉漫洒绿茵园，\n浅黛翩翩秀水边。\n粉面荷花争韵色，\n娇姿翠叶映云天。\n清风雨露晨光好，\n蛙鼓蝉鸣脆响绵。\n寒暑春秋终不辍，\n芳颜丽质俏人前。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "350", "title": "七绝·画石", "genre": "七绝", "date": "2020.07.05", "body": "人脸奇石把手中，\n黄毛歪嘴具神形。\n无缘相见天天见，\n日日恶心难舍扔。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "351", "title": "江城子·老娘", "genre": "江城子", "date": "2020.07.05", "body": "稀疏白发映苍颜，\n背钩弯，步蹒跚，\n高寿八十，日日不歇闲。\n总是心操家务事  ，\n千百计，使人欢 。\n历经万苦不曾言，\n几十年，弹指间。\n儿已鬓斑，再把娘手牵。\n霎那当年多少事，\n一幕幕，泪连连。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "352", "title": "浣溪沙·对酌", "genre": "浣溪沙", "date": "2020.07.05", "body": "夏日悠悠暑气长，\n夜来对饮享清凉。\n琼浆玉液溢浓香。\n三两笑谈今日事，\n半斤神侃往昔狂。\n不觉月影上花墙。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "353", "title": "七绝·夜斗", "genre": "七绝", "date": "2020.07.06", "body": "逢光躲闪暗中忙，\n专扰酣人梦里香。\n难耐起身心底怒，\n纱拍挥舞血飞墙。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "354", "title": "蝶恋花·学子吟", "genre": "蝶恋花", "date": "2020.07.07", "body": "大考来临思绪乱。\n李戴张冠，\n闻却心神颤。\n数载寒窗星月伴，\n平生命运一息变。\n喜看包公出手办。\n污吏奸人，\n翻滚篷头面。\n听得此讯颜灿烂，\n挥毫奋笔清华见。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "355", "title": "采桑子·圆梦", "genre": "采桑子", "date": "2020.07.07", "body": "夜来丝雨潇潇下，\n阵阵清风，\n吹散蒸笼，\n学子难得睡意浓。\n香眠恰助圆心梦，\n金榜题名，\n沐浴春风，\n跨马披花万紫红。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "356", "title": "七绝·致学子", "genre": "七绝", "date": "2020.07.07", "body": "（轱辘体）\n一\n莘莘学子跃龙门，\n题海畅游凭胆魂。\n一笔能圆十载梦，\n飞天莫忘故乡恩。\n二\n寒舍贫家几代人，\n莘莘学子跃龙门。\n而今昂首青山去，\n身正莫忧斜影痕。\n三\n寒暑春秋风雨雪，\n孤灯窗下熬心血。\n莘莘学子跃龙门，\n老少乡邻同喜悦。\n四\n家中二老妹兄贫，\n梦想于心常自温。\n处世为人遵法纪，\n莘莘学子跃龙门。", "image_files": ["01.jpg"]}, {"poem_id": "357", "title": "七律·七七寄怀", "genre": "七律", "date": "2020.07.07", "body": "芦沟晓月映山川，\n今日已非倭寇年。\n四海风云凭我荡，\n九州江河任君还。\n南疆峻峻千峰翠，\n东海清波万里绵。\n惟有七七永牢记！\n昔时悲剧不重篇。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "358", "title": "浣溪沙·天公助考", "genre": "浣溪沙", "date": "2020.07.08", "body": "丝雨清风送晓凉，\n万千学子绪飞扬，\n奇思妙想著华章。\n书本阅读千万遍，\n试题攻克百十箱，\n千锤百炼状元郎。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "359", "title": "西江月·岁月", "genre": "西江月", "date": "2020.07.08", "body": "昔日苦读勤奋，\n平生乐善清贫。\n至今不忘最初心，\n笑看银丝斑鬓。\n几度山花烂漫，\n曾经海浪急频。\n得失不误挽清樽，\n雨雪风霜无恨。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "360", "title": "踏莎行·望京都", "genre": "踏莎行", "date": "2020.07.09", "body": "阵阵雷声，\n潇潇暮雨。\n鸣莺啼燕双归去。\n庭轩萧索水潺湲，\n空阶台上愁绵续。\n白雾茫茫，\n兰烟缕缕。\n风前独自无言语。\n京城疫乱几时休？\n相思相望难相聚！ ​​​", "image_files": ["01.jpg"]}, {"poem_id": "361", "title": "五绝·遥望", "genre": "五绝", "date": "2020.07.09", "body": "篱径翠竹新，\n云天风色深。\n隔屏千里望，\n犹有鸟鸣音。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "363", "title": "踏莎行·高考后", "genre": "踏莎行", "date": "2020.07.10", "body": "卸却包袱，\n放飞梦想，\n玩朋学侣轻松逛。\n近来度日总如年，\n撇开纸笔心神畅。\n先去江南，\n再游青藏，\n登山戏水云天望。\n盼着暑去妙音来，\n追随红叶清华上。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "364", "title": "七绝·夏日雨后", "genre": "七绝", "date": "2020.07.10", "body": "天霁云清醒耳眸，\n微风入夜似凉秋。\n悠闲漫步城河岸，\n倒影飞光竞碧流。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "365", "title": "采桑子·战天灾", "genre": "采桑子", "date": "2020.07.11", "body": "揪心屏望江南雨，\n水漫楼窗，\n风卷舟樯，\n毁路伤桥恁是狂。\n千军万马同心力，\n旗展声扬，\n车载人扛，\n固坝强堤昼夜忙。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "366", "title": "行香子·健身乐", "genre": "行香子", "date": "2020.07.11", "body": "树下川前，漫步登山。\n斗寒暑，晓暮风烟。\n浑身匀称，步履翩翩。\n自睡得香，吃得好，顽得欢。\n鸟啭心闲，岭翠神安。\n交新友，故侣难偏。\n偶然远去，常聚尊前。\n对几声歌，几杯酒，几人酣。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "367", "title": "七绝·乐善", "genre": "七绝", "date": "2020.07.12", "body": "（轱辘体）\n一\n平凡乐善爱长留，\n似沐春风永不休。\n华夏子孙传万代，\n犹如江水向东流。\n二\n老少相亲释百愁，\n平凡乐善爱长留。\n乡邻和睦春常在，\n快乐生活无尽头。\n三\n绿水青山潇洒去，\n神州南北亲相聚。\n平凡乐善爱长留，\n触景生情吟古句。\n四\n人生在世几春秋，\n且莫寻常独自忧。\n三五相知心永伴，\n平凡乐善爱长留。", "image_files": ["01.jpg"]}, {"poem_id": "368", "title": "七律·仲夏寄语", "genre": "七律", "date": "2020.07.13", "body": "连日阴凉似入秋，\n几宵沉睡不知愁。\n晓辉柳下闻莺语，\n夜暮河边理钓钩。\n风色宜人心不躁，\n云天舒雁翅无休。\n可怜多少商家苦，\n惟愿天闷汗水流。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "369", "title": "七律·老有所乐", "genre": "七律", "date": "2020.07.14", "body": "闲来戏水又登山，\n惬意逍遥年复年。\n处事平和谁恼恨，\n为人宽厚自神安。\n酒朋诗侣常相聚，\n飞韵猜拳俱笑颜。\n四海五湖情不尽，\n千山万岭与君欢。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "370", "title": "水调歌头·楼院夏夜", "genre": "水调歌头", "date": "2020.07.15", "body": "四处银灯照，\n一阵晚来风。\n孩童打闹嘻笑，\n稚脸悦眉峰。\n脚踏滑轮飞跃，\n手把单车横纵，\n欢快语声声。\n心里无忧虑，\n逢聚更从容。\n广场舞，歌声荡，\n满腔情。\n东边棋手相遇，\n西畔剑飞鸣。\n老少神怡心旷，\n满院飞光流影，\n花木乐融融。\n夜半情难尽，\n人去月胧明。", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "371", "title": "相见欢·庚子暑伏", "genre": "相见欢", "date": "2020.07.16", "body": "晓来依旧频风，\n绪思清。\n草木欣欣花鸟俱从容。\n云空淡，莺声乱，\n日彤彤。\n早起行人眉展脸轻松。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "372", "title": "七律·四姑娘山", "genre": "七律", "date": "2020.07.16", "body": "雾掩云遮隐丽容，\n冰川九道越山峰。\n层林叠翠青烟起，\n溪水流芳白浪鸣。\n深谷柏杉争日月，\n漫川花草吻尘风。\n连天丝雨随来去，\n难挡游人乐趣行。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "373", "title": "鹧鸪天·暮思", "genre": "鹧鸪天", "date": "2020.07.17", "body": "向晚斜阳细柳垂，\n清馨庭院软风吹。\n亲邻饭后悠闲步，\n仰望长空倦鸟归。\n天色淡，漾星辉，\n疫情趋稳绪思飞。\n青山翠岭芳郊绿，\n踏浪出游共与谁。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "374", "title": "七绝·伏天", "genre": "七绝", "date": "2020.07.18", "body": "夜袭骤雨却无风，\n清晓潮闷雾气腾。\n溽暑来临天色变，\n汗湿衣裤莫心惊。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "375", "title": "七绝·农院芳姿", "genre": "七绝", "date": "2020.07.19", "body": "一.\n何处丝瓜两米长？\n农家小院菜花香。\n依墙藤蔓随人意，\n巧手谁能胜爹娘。\n二.\n丝瓜垂立比人高，\n青翠娉婷细柳腰。\n自使馨家添韵色，\n且随翁妪共逍遥。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "376", "title": "七绝·荷塘垂钓", "genre": "七绝", "date": "2020.07.20", "body": "荷芰亭亭碧水中，\n风姿难扰钓鱼翁。\n心神只在垂丝上，\n不问芳塘绿与红。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "377", "title": "浣溪沙·寄妻生日", "genre": "浣溪沙", "date": "2020.07.21", "body": "退而不休来帝都，\n高楼深户总难出。\n为迎孙辈又读书。\n一日三餐心费尽，\n成年累月意无图。\n今朝惟愿子媳福。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "378", "title": "减字木兰花·家宴", "genre": "减字木兰花", "date": "2020.07.22", "body": "花香萦面，\n精美蛋糕生日宴。\n子孝媳贤，\n语暖情深心底甜。\n灯柔气爽，\n和睦家庭福禄广。\n共盼娇孙，\n送子观音梦里亲。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "379", "title": "七律·阆中张飞祠", "genre": "七律", "date": "2020.07.22", "body": "镇守古城七载多，\n修文尚武不蹉跎。\n为消关羽生死恨，\n却被张达头颅割。\n身首失连千古怨，\n阴阳别恨万人说。\n可怜威猛三国将，\n黄土一堆野草坡。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "380", "title": "七绝·诗心", "genre": "七绝", "date": "2020.07.23", "body": "（轱辘体）\n兰亭雅韵漾诗心，\n曲水流觞尽兴吟。\n明月清风桥上过，\n疏星闪闪似弹琴。\n才子佳人各觅寻，\n兰亭雅韵漾诗心。\n合情投意相携去，\n来往花前月下临。\n待到洞房红火日，\n两情相悦香罗系。\n兰亭雅韵漾诗心，\n地角天涯前后继。\n白头偕老醉花阴，\n赏月凭风望翠林。\n闲赋诗词合咏调，\n兰亭雅韵漾诗心。", "image_files": ["01.jpg"]}, {"poem_id": "381", "title": "破阵子·贺天问发射", "genre": "破阵子", "date": "2020.07.23", "body": "胖五升空耀眼，\n千年天问成真。\n探索深空圆众梦，\n飞向火星憾吾心。\n茫茫宇宙巡。\n沉睡巨龙腾起，\n山川霄汉惊闻。\n今日兴国凭大志，\n自古安邦赖铁军。\n神州万里亲。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "382", "title": "七律·感怀", "genre": "七律", "date": "2020.07.24", "body": "薄暮高楼感细风，\n朦胧淡月隐穹东。\n星空遥望千年远，\n心绪松舒百事通。\n路上人流奔似水，\n街边店影乱飘红。\n浮生如梦终无怨，\n不作随风起落蓬。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "383", "title": "喝火令·暑夜庭院", "genre": "喝火令", "date": "2020.07.26", "body": "日暮云霞炫，\n庭轩起阵风。\n暑天无躁绪思清。\n楼院彩灯初上，\n佳丽舞轻盈。\n童稚追逐闹，\n欢声溢草坪。\n渐疏星朗月分明。\n夜色如银，\n夜色亦多情，\n夜色绚光飞度。\n缤彩映长空。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "384", "title": "山花子·老人劫", "genre": "山花子", "date": "2020.07.27", "body": "羸弱登阶似越山，\n最宜扶杖缓趋前。\n一旦失足筋骨裂，\n痛延绵。\n坐卧不安愁永夜，\n心神无奈整天烦。\n美味佳肴难下咽，\n苦相连。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "385", "title": "风入松·七二八寄怀", "genre": "风入松", "date": "2020.07.28", "body": "又逢此日忆唐山，\n四十四年前。\n天崩地裂人悲泣，\n高楼倾，断壁残垣。\n内外全无音讯，\n妻离子散愁颜。\n神州南北手相牵，\n齐力克时艰。\n废墟之上建家园，\n新城立，楼密街宽。\n古老凤凰腾起，\n黎民百姓心甜。 ​​​", "image_files": []}, {"poem_id": "386", "title": "钗头凤·热", "genre": "钗头凤", "date": "2020.07.30", "body": "食无味，宵难睡。\n溽湿浸遍厅堂柜。\n空调伴，频出汗。\n可行何处？炙闷连片。\n乱、乱、乱。\n人疲惫，心神累。\n苦烦无奈成双倍。\n谁能唤？天公办。\n雨风齐降，气清凉漫。\n盼、盼、盼。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "387", "title": "七律·三伏天", "genre": "七律", "date": "2020.07.31", "body": "堪当酷热不虚名，\n静坐芳荫汗自盈。\n无奈蝉蛩声调软，\n悲催枝叶盼清风。\n水滴石板腾白雾，\n手触栏杆玉指红。\n耐受天光尘世考，\n方得安逸度余生。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "388", "title": "梅花引·八一颂", "genre": "梅花引", "date": "2020.08.01", "body": "枪声响，城头上，\n燎原星火蒸蒸旺。\n工农情，井冈红，\n古田会议，\n旌旗色更浓。\n长征万里寰球望，\n抗日八年华夏壮。\n蒋匪平，碧空晴，\n威武之师，\n昂首踏征程。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "389", "title": "临江仙·庆八一", "genre": "临江仙", "date": "2020.08.01", "body": "枪响南昌惊夜色，\n秋收起义成军。\n井冈山上聚红心。\n长征行万里，\n抗日为家亲。\n歼灭蒋匪宏大业，\n援朝抗美封神。\n赢得华夏有如今。\n钢枪跟党走，\n日月映忠魂。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "390", "title": "如梦令·子弟兵", "genre": "如梦令", "date": "2020.08.01", "body": "疆场纵横威猛，\n抢险舍身英勇。\n可爱胜亲人，\n鱼水情深谁更？\n当敬、当敬，\n万语千言难颂！\n临江仙    庆八一\n枪响南昌惊夜色，\n秋收起义成军。\n井冈山上聚红心。\n长征行万里，\n抗日为家亲。\n歼灭蒋匪宏大业，\n援朝抗美封神。\n赢得华夏有如今。\n钢枪跟党走，\n日月映忠魂。\n梅花引    八一颂\n枪声响，城头上，\n燎原星火蒸蒸旺。\n工农情，井冈红，\n古田会议，\n旌旗色更浓。\n长征万里寰球望，\n抗日八年华夏壮。\n蒋匪平，碧空晴，\n威武之师，\n昂首踏征程。", "image_files": ["01.jpg"]}, {"poem_id": "391", "title": "御街行·伏天雨后", "genre": "御街行", "date": "2020.08.03", "body": "雨歇午后骄阳烈，\n树上蝉声切。\n无言花草忍天光，\n自是低头卷叶。\n桐荫人聚，\n频摇蒲扇，\n依旧难消热。\n黄昏风起飞莺雀，\n落日余辉谢。\n气凉人爽绪思平，\n暮色孩童欢跃。\n夜深人静，\n月移花影，\n渐渐酣声彻。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "392", "title": "七律·杜甫草堂", "genre": "七律", "date": "2020.08.04", "body": "诗圣旧居千古韵，\n书家墨宝与时新。\n水流溪径青荷翠。\n竹绕亭台老树亲。\n壁刻言辞龙凤舞，\n窗含花草映烟云。\n一朝迈步文香院，\n日后亦能词赋吟。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "393", "title": "玉楼春·老人叹", "genre": "玉楼春", "date": "2020.08.05", "body": "人老意疏伤病近，\n寡语孤闻心里闷。\n不识文字更无聊，\n耳背言迟疑懒问。\n风吹草动惊难禁，\n落叶飞声多少恨。\n一朝跌倒卧床头，\n苦痛无穷愁染鬓。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "394", "title": "减字木兰花·立秋前日", "genre": "减字木兰花", "date": "2020.08.06", "body": "雨宵声切，\n晨晓依然珠打叶。\n暑气全消，\n触目清凉水漫漂。\n蝉蛩不语，\n碧绿池塘荷芰举。\n明日归秋，\n期待山川硕果收。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "395", "title": "阮郎归·立秋有寄", "genre": "阮郎归", "date": "2020.08.07", "body": "晓凉惊梦已初秋，\n年光似水流。\n镜中斑鬓岂须愁，\n诗情漾小楼。\n回首望，院清幽，\n柳蝉歌不休。\n鹰飞雁舞映双眸，\n云空万里柔。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "396", "title": "七律·赠同龄", "genre": "七律", "date": "2020.08.08", "body": "人逢花甲不得闲，\n老少两端天复年。\n父母至亲恩必报，\n儿孙极爱虑相连。\n东西忙碌虽无怨，\n上下奔波怎尽欢。\n愿有双头三五臂，\n家中琐事九肩担。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "397", "title": "点绛唇·初秋晨光", "genre": "点绛唇", "date": "2020.08.09", "body": "院静无风，\n长空遥望云光淡。\n出门晨练，\n迈步浑身汗。\n绿处人多，\n老少声歌乱。\n抬头看，\n舞姿飞旋，\n红穗刀枪剑。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "398", "title": "清平乐·赠伪君", "genre": "清平乐", "date": "2020.08.10", "body": "大洋彼岸，\n恶语胡言漫。\n不见出头来理断，\n却骂国民争辩。\n文辞自作聪明，\n偷梁换柱歪声。\n只许匪兵放火，\n杜绝百姓点灯？ ​​​", "image_files": ["01.jpg"]}, {"poem_id": "399", "title": "卜算子·有所思", "genre": "卜算子", "date": "2020.08.11", "body": "域外疫情高，\n应对千般乱。\n政府轻敌百策疏，\n民众行思漫。\n同在地球村，\n心态相差万。\n信口胡言尽甩锅，\n百姓频遭难。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "400", "title": "踏莎行·赠文朋诗侣", "genre": "踏莎行", "date": "2020.08.12", "body": "韵海扬帆，\n文坛劲舞。\n蕴诗笔墨频飞度。\n律绝词赋领风骚，\n唐魂宋魄吟千古。\n鸣燕浮鹰，\n藏龙卧虎。\n碧空云淡争翔翥。\n神州南北映光辉，\n江河山岳情无数。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "401", "title": "采桑子·秋后伏雨", "genre": "采桑子", "date": "2020.08.13", "body": "夜闷喜降倾盆雨，\n风骤雷急，\n叶落花凄，\n拂晓依然垂玉丝。\n中伏秋后消烦暑，\n高柳蝉嘶，\n不似前时，\n早晚风凉语调低。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "402", "title": "七绝·雨后故宫", "genre": "七绝", "date": "2020.08.14", "body": "天霁楼台景色新，\n清波倒影更消魂。\n昔时百姓谁能见，\n今日疯传老少群。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "403", "title": "清平乐·尘世人间", "genre": "清平乐", "date": "2020.08.15", "body": "年光不住，\n斗转星河度。\n日月轮回寒又暑，\n尘世朝朝暮暮。\n人间万物兴衰，\n庭前花落花开。\n依重地规天意，\n得失无忌舒怀。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "404", "title": "七绝·铭记", "genre": "七绝", "date": "2020.08.15", "body": "日寇投降心未死，\n隔三差五事非生。\n今朝吾辈当同力，\n不负九泉英烈情。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "405", "title": "鹧鸪天·南海风云", "genre": "鹧鸪天", "date": "2020.08.16", "body": "域外搅局胡乱言，\n焦灼无奈跳台前。\n扭曲嘴脸人神恨，\n丑陋心魂魑魅欢。\n云水暗，浪涛翻，\n陈虾腐蟹映苍天。\n神州日丽山河壮，\n且看流星落野边。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "406", "title": "清平乐·失道寡助", "genre": "清平乐", "date": "2020.08.17", "body": "贼心费尽，\n提案遭人恨。\n昔日跟班浑不论，\n老大风光怎混。\n言行失道胡为，\n优先米帝难随。\n天下苦之久矣，\n今朝此幕怨谁！ ​​​", "image_files": ["01.jpg"]}, {"poem_id": "407", "title": "七律·武隆天坑地缝", "genre": "七律", "date": "2020.08.17", "body": "地裂奇坑百丈深，\n神工鬼斧不留痕。\n天生桥洞连环套，\n泉吐琼珠飞瀑频。\n四壁怪石人慨叹，\n一溪清水鸟鸣音。\n古来传颂多神密，\n今日穿行探伪真。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "408", "title": "忆秦娥·秋思", "genre": "忆秦娥", "date": "2020.08.18", "body": "年光逝，\n春花开落秋来矣。\n秋来矣，\n蝉声趋软，\n渐消暑气。\n风轻云淡神难静，\n家中老少心头事。\n心头事，\n昼思夜念，\n平安为寄。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "409", "title": "南歌子·电之情", "genre": "南歌子", "date": "2020.08.19", "body": "银线凌空越，\n高人线上行。\n云中漫舞远山横，\n俯瞰岭峰千里送光明。\n遥望江南北，\n凭借电传情。\n城乡万户乐融融，\n挥汗成川无悔写人生。 https://video.weibo.com/show?fid=1034:4539523669884937 ​​​", "image_files": []}, {"poem_id": "410", "title": "清平乐·武隆天坑地缝", "genre": "清平乐", "date": "2020.08.19", "body": "天光一线，\n坑底云烟漫。\n百丈深渊从未见，\n远客寻游感叹。\n何方刀斧翩跹，\n何年飘落人间。\n惟有天神发力，\n轻轻撕裂山川。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "411", "title": "梅花引·山水行", "genre": "梅花引", "date": "2020.08.20", "body": "高台卧，小窗侧，风雨难阻远行客。\n懒观花，闲品茶，对酒当歌，乡野访人家。\n雁鹰同行山海道，惬意随心越芳草。\n桃红时，菊黄时，无穷往复，谁似老夫痴。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "412", "title": "浣溪沙·遥思", "genre": "浣溪沙", "date": "2020.08.21", "body": "在外儿心念老娘，\n日前病腿遇新伤。\n最愁宵昼不离床。\n陪护当中急有事，\n离开之后更思量。\n幸得俩妹尽周详。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "413", "title": "清平乐·秋菊", "genre": "清平乐", "date": "2020.08.22", "body": "晚晴云淡，\n五彩霞光漫。\n风色清新花满院，\n丛菊争香竞艳。\n当年陶氏钟情，\n赢得千古留名。\n每到金秋送爽，\n城乡映紫堆红。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "414", "title": "南乡子·秋思", "genre": "南乡子", "date": "2020.08.23", "body": "游子各奔忙，\n木叶凭风老树黄。\n又是东篱当酒季，\n思量，\n何日窗前共把觞。\n少壮总呈强，\n山海寻游恣意狂。\n席地而眠天作被，\n荒唐，\n霜鬓更觉家饭香。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "415", "title": "浣溪沙·赠黄毛", "genre": "浣溪沙", "date": "2020.08.24", "body": "撒谎胡为瘾已深，\n内心黑暗影沉沉。\n神州花茂乱贼神。\n结派拉帮营恶势，\n吹风点火助阴魂。\n斜眉歪脸众人喷。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "416", "title": "卜算子·七夕", "genre": "卜算子", "date": "2020.08.25", "body": "千古鹊桥边，\n多少天仙恨？\n织女牛郎洒泪别，\n离苦言难尽。\n化作雨飘潇，\n却引人悲悯。\n天上不如尘世间，\n相爱凭缘分。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "417", "title": "七绝·七夕怨", "genre": "七绝", "date": "2020.08.25", "body": "又是鹊桥仙女泪，\n一年一度落人间。\n离多聚少千秋恨，\n何日长圆笑九天。\n七绝        七夕情\n牛郎织女彩云间，\n一岁一逢天水边。\n聚短别长心不悔，\n此情此景几千年。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "418", "title": "七绝·酌思", "genre": "七绝", "date": "2020.08.26", "body": "人逢难事玉樽行，\n两盏三杯乱绪通。\n老酒一壶天地阔，\n凭高望远释愁情。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "419", "title": "七绝·闲咏", "genre": "七绝", "date": "2020.08.27", "body": "人生逆旅且前行，\n莫管东西南北风。\n晴日偷闲把茶品，\n雨天笑对酒一盅。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "420", "title": "夜游宫·七夕望", "genre": "夜游宫", "date": "2020.08.28", "body": "廊叶秋声乍起，\n望弦月，雪辉千里。\n楼上凭栏聚眸子，\n眺星空，觅银河、天界事。\n都道七夕日，\n鹊桥上，情深语密。\n一岁一逢苦悲泣，\n牛女泪，落人间、竞淅沥。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "421", "title": "七绝·叹李白", "genre": "七绝", "date": "2020.08.29", "body": "凭酒赋诗山海行，\n惊天词句溢豪情。\n可怜一世难得志，\n无奈迷樽醉死生。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "422", "title": "七绝·咏李白", "genre": "七绝", "date": "2020.08.30", "body": "千古诗坛北斗星，\n豪情逸兴万年惊。\n殿前假旨羞权贵，\n傲视小人堪为峰。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "423", "title": "菩萨蛮·秋夜吟", "genre": "菩萨蛮", "date": "2020.08.31", "body": "三伏早过依然热，\n蝉声未减人难乐。\n月下扇频摇，\n闲情趣话聊。\n鼠年多怪事，\n最数新冠疫。\n域外任逍遥，\n新坟竞日高。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "424", "title": "七律·咏农家", "genre": "七律", "date": "2020.09.01", "body": "世间最苦数黎民，\n阡陌耕耘日月辛。\n呵护田园凭己力，\n尊崇老幼尽身心。\n良言善事传家训，\n置地修房为子孙。\n儿女双全千古梦，\n可怜白发映黄昏。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "425", "title": "生查子·秋晓", "genre": "生查子", "date": "2020.09.02", "body": "朝云漫卷飞，\n风色秋来早。\n红日映长空，\n群雁飘飖小。\n柳丝袅袅垂，\n叶底蝉声老。\n楼院起童音，\n老少追清晓。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "426", "title": "破阵子·铭记", "genre": "破阵子", "date": "2020.09.03", "body": "抗日情怀激荡，\n英魂浩气长存。\n先烈芳名传万代，\n贼寇魔行警亿人。\n苍天爱恨分。\n世界风云涌动，\n飞言乱语时闻。\n吾辈子孙惟奋力，\n赢取神州万里春。\n山河日月新。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "427", "title": "七绝·秋晓", "genre": "七绝", "date": "2020.09.04", "body": "日月同辉万里秋，\n晓空雁鹤竞风流。\n菊黄恰似春红好，\n袅袅云烟小院幽。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "428", "title": "七绝·秋色", "genre": "七绝", "date": "2020.09.05", "body": "（轱辘体）\n金风渡彩果儿鲜，\n冉冉秋阳笑脸甜。\n溪水远山云似画，\n无边花草竞娇颜。\n山野游人尽笑颜，\n金风渡彩果儿鲜。\n遥天鸿雁南飞去，\n戏水鸳鸯比蜜甜。\n俊男靓女两心甜，\n踏草穿林舞丽颜。\n遥望鹊桥心荡漾，\n金风渡彩果儿鲜。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "429", "title": "醉花阴·致敬军人", "genre": "醉花阴", "date": "2020.09.06", "body": "平安岁月知多少，\n遥看边防哨。\n卧雪斗风寒，\n似火骄阳，\n时有豺狼闹。\n功勋将士终究老，\n请对他真好。\n激励后来人，\n发奋图强，\n万代山河笑。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "430", "title": "醉花阴·变", "genre": "醉花阴", "date": "2020.09.07", "body": "淮河南北橘和枳，\n本是一颗籽。\n水土不相同，\n形状微别，\n果味差千里。\n人生落地皆尘世，\n性善无差异。\n近赤或拥黑，\n日久潜移，\n颜色毋能比。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "431", "title": "卜算子·白露", "genre": "卜算子", "date": "2020.09.07", "body": "风色正当时，\n云卷云飘落。\n遍处金秋雁鹤飞，\n天地悠悠过。\n将士枕金戈，\n骚客挥香墨。\n尚武崇文万里安，\n百姓樽前乐。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "432", "title": "采桑子·动车见闻", "genre": "采桑子", "date": "2020.09.08", "body": "飞驰如箭山川去，\n甩落斜阳，\n树闪边窗，\n秋韵黄花遍地香。\n疫情过后趋活跃，\n南北通商，\n内外皆忙，\n鼎沸人声笑语扬。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "433", "title": "临江仙·缅怀主席", "genre": "临江仙", "date": "2020.09.09", "body": "今古奇才谁可比，\n世间文武绝伦。\n神州千古圣贤贫。\n无私心底阔，\n有爱为黎民。\n盖世功名传万代，\n惠及华夏儿孙。\n宏光浩气映人心。\n犹苍天地久，\n似日月长存。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "434", "title": "御街行·寄恩师", "genre": "御街行", "date": "2020.09.10", "body": "讲台三尺终生站，\n桃李芬芳远。\n呕心沥血育新苗，\n笑脸慈祥满。\n言传身教，\n嘘寒问暖，\n解惑释人难。\n一生受益记犹深，\n梦里长相见。\n依稀又聚至君前，\n清泪盈双面。\n书香馥郁，\n师恩荡荡，\n心语千千万。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "435", "title": "渔家傲·电厂评审", "genre": "渔家傲", "date": "2020.09.11", "body": "府谷深山忙昼夜，\n机炉几案人急切。\n文海书山逐字阅，\n熬心血，\n点滴只为厂飞跃。\n废寝忘食评与写，\n各方合作皆欢悦。\n楼下惜别言感谢，\n听秋叶，\n山中早晚寒风烈。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "436", "title": "七绝·飞行有寄", "genre": "七绝", "date": "2020.09.12", "body": "滚滚白云足下踩，\n乘风破浪悦心怀。\n凝眸俯瞰山河秀，\n万里神州画卷开。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "437", "title": "风入松·归来", "genre": "风入松", "date": "2020.09.13", "body": "风轻日暮叶微黄，\n征雁映斜阳。\n归鸦栖树云烟淡，\n柳边菊，竞艳飞香。\n人静月移花影，\n空明星闪辉光。\n金秋夜半气清凉，\n樽酒热衷肠。\n奔波在外多年后，\n转头看，坎坷刚强。\n独自凭栏望远，\n温馨何似家乡。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "438", "title": "减字木兰花·798艺术区", "genre": "减字木兰花", "date": "2020.09.14", "body": "京都老厂，今日奇思叠妙想。\n旧壁残垣，粉彩黑白映九天。\n俊郎靓女，追梦求新檐下聚。\n暮色朝阳，意境朦胧万里香。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "439", "title": "七绝·秋思", "genre": "七绝", "date": "2020.09.15", "body": "西风扫过尽残荷，\n败草余香映旧波。\n花落蝉歇情未老，\n故乡人事梦中多。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "440", "title": "少年游·秋晓", "genre": "少年游", "date": "2020.09.16", "body": "夜来纤雨晓清凉，\n风色近重阳。\n天高云淡，\n舞鹰飞雁，\n篱下漫花香。\n外出急促家中返，\n只为老爹娘。\n递水床头，\n身边谈笑，\n细语热衷肠。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "441", "title": "七律·秋", "genre": "七律", "date": "2020.09.17", "body": "西风舞彩染金秋，\n云淡空朗碧水流。\n赤绿橙黄峰岭漫，\n梨桃瓜果陌阡熟。\n蝉声渐老情难断，\n雁阵虽高意不休。\n此去衡阳还暂驻，\n明年春暖又回头。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "442", "title": "破阵子·铭记九一八", "genre": "破阵子", "date": "2020.09.18", "body": "难忘当年今日，\n倭贼半夜炮轰。\n霎那间烟光四起，\n淫火侵烧北大营。\n可怜我众生。\n十四春秋惨烈，\n万千罪恶分明。\n抵赖模糊强盗事，\n妄想乾坤向后行。\n语出世界惊。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "443", "title": "浪淘沙·居安思危", "genre": "浪淘沙", "date": "2020.09.18", "body": "警报刺长空，\n唤起悲情。\n当年日寇炮声隆。\n东北无端频挑事，\n借故攻营。\n贼盗露真容，\n山海无宁。\n神州烈火淬英雄。\n十四春秋得胜利，\n石刻碑铭。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "444", "title": "浪淘沙·农家乐", "genre": "浪淘沙", "date": "2020.09.19", "body": "秋色染农家，\n紫粉黄花。\n耄耋二老乐哈哈。\n当年梦里谁能想，\n海蟹河虾。\n小院众人夸，\n果菜鸡鸭。\n晨昏无虑理桑麻。\n多彩夕阳无限好，\n景秀神佳。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "445", "title": "十六字令·秋", "genre": "十六字令", "date": "2020.09.20", "body": "秋，\n花草黄红碧水流。\n云空丽，\n山海任君游。\n秋，\n如画山川映两眸。\n经行处，\n鸟啭果香稠。\n秋，\n水岸汀州起鹭鸥。\n鱼欢跃，\n轻荡木兰舟。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "446", "title": "南歌子·金秋寄怀", "genre": "南歌子", "date": "2020.09.21", "body": "黄叶中秋近，\n银丝染鬓霜。\n人间天上月清朗，\n喜看金风碧水雁争翔。\n庚子年多事，\n啼乌噪雀慌。\n呲牙奋爪几番忙，\n难阻神州万里熠星光。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "447", "title": "七律·秋分有寄", "genre": "七律", "date": "2020.09.22", "body": "蝉声渐老昼宵均，\n庚子年光最费神。\n白日出行思口罩，\n夜深梦里念亲人。\n妻儿异地难相顾，\n父母同居病扰身。\n期盼晚秋天气爽，\n忧烦伤痛远家亲。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "448", "title": "七律·咏鸡有喻", "genre": "七律", "date": "2020.09.23", "body": "（折腰）\n铁笼三尺把鸡圈，\n寸步难行日月年。\n无虑吃喝非自主，\n随音歌唱己难欢。\n失去自由她最苦，\n生得笨蛋为谁甜。\n若能遍野寻食去，\n最是开心尘世间。", "image_files": ["01.jpg"]}, {"poem_id": "449", "title": "七绝·秋喜", "genre": "七绝", "date": "2020.09.24", "body": "飞雨飘红满院香，\n可心冷暖度秋光。\n入眸风物招人喜，\n酒不盈怀意绪伤。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "450", "title": "浪淘沙·晓闻有思", "genre": "浪淘沙", "date": "2020.09.25", "body": "不意望朝霞，\n辉映黄花。\n行人早起又离家。\n如水车流急驶去，\n只为生涯？\n世道任谁夸，\n雨润风佳。\n辛勤劳作不愁发。\n且莫仰天期馅饼，\n手懒心暇。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "451", "title": "七绝·山海关", "genre": "七绝", "date": "2020.09.26", "body": "长城入水水连天，\n阻断扰袭千百年。\n万里纵横绝险处，\n奇雄天下第一关。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "452", "title": "七绝·新诗旧韵", "genre": "七绝", "date": "2020.09.26", "body": "泳雪\n昔日童鞋花色好，\n而今脚大穿来小。\n依然不愿置新鞋，\n却道当年颜料老。#中国诗词大会[超话]##中华好诗词##古诗词# ​​​", "image_files": []}, {"poem_id": "453", "title": "减字木兰花·咏妻舞", "genre": "减字木兰花", "date": "2020.09.27", "body": "翩跹起舞，\n锣鼓争鸣情自主。\n雅韵芳姿，\n月满金秋国庆时。\n人欢红炫，\n尽日风光花灿烂。\n花甲之身，\n心气弥高总是春。", "image_files": ["01.jpg"]}, {"poem_id": "454", "title": "长相思·韵", "genre": "长相思", "date": "2020.09.27", "body": "你吟诗，\n他吟诗，\n平水读音谁可知？\n倚猫说虎姿。\n人赋词，\n我赋词，\n新韵朗朗意境奇。\n山河景物滋。 ​​​", "image_files": []}, {"poem_id": "455", "title": "鹧鸪天·游侠", "genre": "鹧鸪天", "date": "2020.09.28", "body": "世上如仙山水郎，\n古来豪迈俱疏狂。\n凭风踏浪江河去，\n诗赋文辞著华章。\n歌一首，酒三觞，\n每天潇洒胜侯王。\n珠楼玉阙难请进，\n仗剑独行向远方。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "456", "title": "西江月·金秋颂", "genre": "西江月", "date": "2020.09.29", "body": "国庆中秋奇遇，\n红旗明月重辉。\n银空万里彩云飞，\n灯影星光交汇。\n燕舞莺鸣鸟乐，\n江涛海浪声威。\n故人欢聚不思归，\n心悦樽频陶醉。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "457", "title": "定风波·九三〇抒怀", "genre": "定风波", "date": "2020.09.30", "body": "秋雨催寒晓色清，\n天安门下祭英灵。\n云淡风轻人伫静，\n心敬！\n追思先烈绪难平。\n华夏祥和千古梦，\n今幸！\n山河无恙任从容。\n纪念前贤凭自警，\n长醒！\n神州江海可安宁。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "459", "title": "蝶恋花·缅怀先烈", "genre": "蝶恋花", "date": "2020.09.30", "body": "静默无言齐肃立，\n纪念碑前，\n俱为英魂泣。\n浴血神州家万里，\n子孙代代心铭记。\n今日山河风景丽，\n矗立东方，\n国盛云天碧。\n带路连通欧亚体，\n且凭北斗龙腾起。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "460", "title": "长相思·十一寄怀", "genre": "长相思", "date": "2020.10.01", "body": "升国旗，\n敬国旗，\n玉露金秋红叶时。\n故人万里思。\n先辈期，\n吾辈期，\n锦绣神州天地齐。\n黎民百姓滋。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "461", "title": "夜游宫·洛阳望月", "genre": "夜游宫", "date": "2020.10.02", "body": "庚子中秋典礼，\n傍伊水、龙门开启。\n万众倾心聚眸子。\n歌舞妍，月明圆，\n灯火丽。\n自古都王地，\n俏牡丹，欣逢盛世。\n久卧中原又腾起。\n倚今宵，壮山河，\n赢人气。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "462", "title": "七绝·银滩望月", "genre": "七绝", "date": "2020.10.03", "body": "千里驱车观海月，\n清蟾戏水照无眠。\n广寒宫里飘丹桂，\n玉液清香溢世间。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "463", "title": "临江仙·银滩晓望", "genre": "临江仙", "date": "2020.10.04", "body": "遥望海天升旭日，\n彩霞万里云飞。\n渔舟满载伴歌归。\n银滩鸥鹭起，\n燕雀树梢追。\n无际晴空心绪畅，\n闲行堤岸风吹。\n叶鸣蛩唱浪花催。\n金秋凭晓色，\n人道胜春晖。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "464", "title": "七绝·赠老特", "genre": "七绝", "date": "2020.10.04", "body": "懂王不懂老天心，\n乱语胡为罪上身。\n尘世人间公道在，\n无关统领与平民。 ​​​", "image_files": []}, {"poem_id": "465", "title": "八声甘州·银滩寄怀", "genre": "八声甘州", "date": "2020.10.05", "body": "望水天空阔海鸥翔，\n正时令金秋。\n看白云舒卷，南飞鸿雁，\n影落汀洲。\n映岸芦花飘荡，\n远处隐渔舟。\n滚滚千层浪，\n涛涌潮流。\n四面气清霞灿，\n更斜阳冉冉，\n思绪难收。\n叹匆来急去，\n惟愿久居留。\n踏金沙、欢歌戏水，\n品果珍、享虾蟹山馐。\n凭昼夜，海风吹处，\n无影烦忧。", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "466", "title": "踏莎行·银滩夜欢舞", "genre": "踏莎行", "date": "2020.10.06", "body": "月照长堤，涛鸣曲岸。\n海风阵阵歌声漫。\n群芳劲舞溢心怀，\n沙滩广场银花灿。\n夜色微寒，凉亭爆满。\n诚邀明月真情展。\n盛妆浓彩共秋声，\n双节喜气盈眉眼。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "467", "title": "水调歌头·十一颂", "genre": "水调歌头", "date": "2020.10.07", "body": "秋日云天碧，\n山水好风光。\n神州国庆民奋，\n旗展舞飞扬。\n塞北江南红遍，\n燕舞蝉鸣竞秀，\n喜气遍城乡。\n草树迎人笑，\n街角溢花香。\n欣回首，\n情不尽，\n韵悠长。\n举国防疫，\n凝聚万众创辉煌。\n又为小康同进，\n北斗指明航向，\n江海映高阳。\n华夏齐心力，\n圆梦谱新章。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "468", "title": "踏莎行·银滩日暮观潮", "genre": "踏莎行", "date": "2020.10.08", "body": "浪滚山移，\n涛击壁立。\n轰隆震耳弥寒气。\n苍茫碧水望无边，\n霞光万道千辉熠。\n月挂星空，\n海连天地。\n秋光夜色凭栏倚。\n一人于世一微尘，\n万人凝聚擎天力。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "469", "title": "浣溪沙·银滩早市", "genre": "浣溪沙", "date": "2020.10.08", "body": "拂晓出门星月天，\n摆摊街巷肩并肩。\n清莹果菜蟹鱼鲜。\n北调南腔争问价，\n老翁少妇紧收钱。\n公平买卖两相欢。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "470", "title": "踏莎行·养老绝佳地", "genre": "踏莎行", "date": "2020.10.09", "body": "水岸晨辉，\n山前晚照。\n银滩秋色风光俏。\n八方远客慕名来，\n朝歌暮舞街头笑。\n院后楼前，\n南腔北调。\n古今趣事家常唠。\n一年一度总相逢，\n都说负氧能防老。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "471", "title": "七律·游银滩多福山", "genre": "七律", "date": "2020.10.09", "body": "晨曦四射耀福山，\n木翠草葱风色仙。\n半米方池盈玉液，\n两排圆顶袅云烟。\n石阶千磴三潭落，\n花径九折一线天。\n越岭攀岩极远眺，\n秋光福禄纳心间。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "472", "title": "渔家傲·游多福山", "genre": "渔家傲", "date": "2020.10.10", "body": "十月多褔山灿烂，\n黄花红叶云空炫，\n曲径丛幽莺鸟啭。\n轻挥汗，\n飞身跃顶天池畔。\n香客游人盈笑脸，\n玉皇庙顶俯身瞰，\n楼伫银滩清水岸。\n高声唤，\n秋风漫卷英雄汉。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "473", "title": "七绝·闻讯心惊", "genre": "七绝", "date": "2020.10.10", "body": "正是丰华不惑年，\n秋宵梦里命归天。\n无心撒手突然去，\n留下痛伤家道残。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "474", "title": "减字木兰花·银滩夜雨", "genre": "减字木兰花", "date": "2020.10.11", "body": "狂风彻夜，\n骤雨时歇时肆虐。\n木叶飘零，\n阵阵凄寒梦里惊。\n醒来无奈，\n静坐独思霄汉外。\n鸡唱窗明，\n山远海空天地平。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "475", "title": "七绝·咏石榴", "genre": "七绝", "date": "2020.10.12", "body": "一.\n娇容似火染窗彤，\n招引阶前燕雀鸣。\n风霜无奈心灵美，\n小院秋晖韵味浓。\n二.\n枝头冉冉舞裙红，\n绿叶悠悠晓露清。\n万千赤子同心聚，\n暮色秋光情意凝。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "476", "title": "浣溪沙·海堤夜行", "genre": "浣溪沙", "date": "2020.10.13", "body": "皓月繁星耀海空，\n波光潋滟水多情，\n夜深人静弄琴声。\n万里舞台风伴乐，\n千年涛浪共弦鸣。\n悠悠思绪落蟾宫。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "477", "title": "临江仙·圆梦", "genre": "临江仙", "date": "2020.10.13", "body": "傍水依山昨日梦，\n银滩此刻成真。\n登高望远景萦身。\n出门天地阔，\n幽静少杂音。\n临近福山东海水，\n云空花木清新。\n夏秋风色最宜人。\n渔村亲远客，\n心醉乐晨昏。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg", "04.jpg", "05.jpg", "06.jpg"]}, {"poem_id": "478", "title": "七绝·芦花二首", "genre": "七绝", "date": "2020.10.14", "body": "一.\n飘洒芦花染晚秋，\n不须谁赏自欢悠。\n为人行事皆如此，\n心里清安少乱愁。\n二.\n风摆苇丛飞浪花，\n芦塘深处有渔家。\n船头偶见金鱼跃，\n笑靥微微映晚霞。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "479", "title": "减字木兰花·秋雨闲赋", "genre": "减字木兰花", "date": "2020.10.14", "body": "云飘雨落，\n窗外清风亲远客。\n节气宜人，\n望海休闲最销魂。\n琴音楼上，\n顿挫悠扬思绪畅。\n诗画品读，\n缕缕书香浸玉壶。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "480", "title": "虞美人·银滩独酌", "genre": "虞美人", "date": "2020.10.15", "body": "楼台远眺银空月，\n千里思乡切。\n中秋已过近重阳，\n斜倚栏杆、\n飒飒北风凉。\n玉樽盈酒谁能语，\n独自频频举。\n无心邀月共干杯，\n寒气袭人、\n落叶几番催。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "481", "title": "卜算子·秋日", "genre": "卜算子", "date": "2020.10.16", "body": "雨过细风凉，\n纸扇收叠了。\n庭院桐荫渐渐稀，\n蝉响声声老。\n又是艳阳天，\n遥望高飞鸟。\n沐日迎风漫步行，\n无限情思好 。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "482", "title": "七绝·深秋暮色", "genre": "七绝", "date": "2020.10.17", "body": "赤绿黄橙映远天，\n谁人法力大无边。\n等闲信手丹青画，\n胜却尘间俏粉颜。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "483", "title": "念奴娇·银滩夜行有寄", "genre": "念奴娇", "date": "2020.10.18", "body": "月明波冷，\n望蟾光淡淡，\n夜色如银。\n潮退沙平风浪小，\n天海空阔宜人。\n静岸独行，\n银灯高照，\n星影伴蝉音。\n凭风惬意，\n低声赋咏诗吟。\n千里圆梦银滩，\n已深秋寒露，\n花木犹新。\n母爱乳山风色好，\n鱼蟹鲜果频频。\n远道而来，\n登山眺海，\n日久意情深。\n乡民好客，\n余生长作芳邻。", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "484", "title": "七绝·咏松三首", "genre": "七绝", "date": "2020.10.19", "body": "时入金秋阵阵风，\n黄花红叶少蝉声。\n山崖挺立犹苍翠，\n笑看尘间几世雄。\n昂首青峦向碧空，\n暑寒无惧傲长风。\n一生笑对人间客，\n寂静悠悠不老翁。\n籽随风荡落坡崖，\n立志岭峰根叶发。\n雨雪冰霜浑不惧，\n一棵胜似万千花。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "485", "title": "七绝·松", "genre": "七绝", "date": "2020.10.20", "body": "（轱辘体）\n黄山顶上一棵颂，\n惊世风光在险峰。\n苍翠向天情韵远，\n倩姿迎客意无穷。\n千载白云万里风，\n黄山顶上一棵松。\n迎霜斗雪浑无怕，\n影弱身单不自轻。\n随处安身根入地，\n枝繁叶茂真神气。\n黄山顶上一棵松，\n激励世人当自立。\n诗吟词颂俱含情，\n南北东西雅韵声。\n五夜三天歌不尽，\n黄山顶上一棵松。", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "486", "title": "点绛唇·赠群友", "genre": "点绛唇", "date": "2020.10.21", "body": "词赋江湖，\n诗情曲韵清波漾。\n偶飞花浪，\n舟上心神旷。\n鱼跃帆扬，\n把酒凭栏畅。\n高天望，\n鹭鸥争上，\n无限情怀荡。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "487", "title": "七律·毛岸英", "genre": "七律", "date": "2020.10.22", "body": "异域归来愤入朝，\n别离父母远新娇。\n闻鸡劲舞挥长剑，\n催马争前抖战袍。\n思想开明盈血气，\n言行得体飒姿骄。\n身遭不幸神州痛，\n领袖情怀举世昭。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "488", "title": "踏莎行·战而扬威", "genre": "踏莎行", "date": "2020.10.23", "body": "…入朝作战70周年\n举世心惊，\n超人胆魄。\n鸭绿江水千军过。\n援朝抗美保家园，\n同仇敌忾刀枪握。\n领袖儿先，\n黎民子跃。\n上甘岭上乌云破。\n国威远震屹东方，\n神龙昂首山河阔。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "489", "title": "破阵子·大会观感", "genre": "破阵子", "date": "2020.10.23", "body": "话语铿锵有力，\n掌声经久难息。\n参战英雄盈热泪，\n好汉今朝擎大旗，\n戎装谁可敌。\n收取台湾宝岛，\n神州山海统一。\n狼子野心当自碎，\n龙跃长空万里奇。\n苍天百姓期。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "490", "title": "江城子·重阳寄怀", "genre": "江城子", "date": "2020.10.24", "body": "悠悠岁月又重阳，\n叶红黄  ，漫菊香。\n万里晴空 ， 鸿雁奋高翔。\n无悔春秋今更是，\n心不老  ，鬓微霜。\n尽情放眼路宽长，\n跨川江  ，越城乡。\n秀丽神州，山海赤旗扬。\n企盼春风化雨日，\n华夏梦 ，世无双。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "491", "title": "点绛唇·夜思", "genre": "点绛唇", "date": "2020.10.25", "body": "九九重阳，\n凭栏遥望家亲苦。\n寄情三处，\n无限思难住。\n老少相离，\n新病添伤楚。\n斜阳暮，\n冷窗寒露，\n孤影灯前度。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "492", "title": "浣溪沙·抗美援朝寄怀", "genre": "浣溪沙", "date": "2020.10.25", "body": "一战立威狼虎前，\n和平红利几十年。\n神州大地百花妍。\n敬重英雄风气正，\n缅怀历史忆先贤。\n豪情血脉永相传。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "493", "title": "青玉案·塞罕坝", "genre": "青玉案", "date": "2020.10.27", "body": "茫茫沙漠无花树，\n更吹落，尘和土。\n竟日昏沉难辩路。\n水缺风大，\n少人稀物，\n四季黄龙舞。\n扎根坝上知青户，\n数秩春秋无所顾。\n绿化沙洲千百度。\n蓦然回首，\n鸟虫花木，\n满眼清幽处。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "494", "title": "七绝·感怀", "genre": "七绝", "date": "2020.10.28", "body": "人生于世万千难，\n雨雪风霜落眼前。\n跌倒扬头微笑过，\n红花翠叶映芳园。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "495", "title": "七绝·秋色", "genre": "七绝", "date": "2020.10.29", "body": "满眼金黄人欲醉，\n云天辉染万千媚。\n斜阳馨暖胜春风，\n泼洒人间弥可贵。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "496", "title": "七绝·秋望金山岭", "genre": "七绝", "date": "2020.10.30", "body": "车至山前正晚晴，\n映天苍翠染黄红。\n长城无语峰峦上，\n难挡深秋万里风。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "497", "title": "少年游·望金山岭长城", "genre": "少年游", "date": "2020.10.31", "body": "京承路上，金山脚下，日暮舞云霞。\n岭坡苍郁，枫红欲燃，点点缀黄花。\n遥朓远山游人醉，寒叶撩衣纱。\n万里长城无言卧，凭栏望，乱啼鸦。\n七绝\n眺望金山万里秋，\n长城难阻帝王愁。\n不堪回首当年事，\n寂寞残墙过客游。", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "498", "title": "踏莎行·祝岳母生日", "genre": "踏莎行", "date": "2020.11.01", "body": "华鬓欢朝，\n银丝笑晚。\n妪翁携手芳邻羡。\n冬阳夏雨品书香，\n风霜雪露心神淡。\n四世同堂，\n一家美满。\n木兰胜似无情汉。\n春秋南北俱相思，\n东西朝暮嘘寒暖。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "499", "title": "七绝·银杏树", "genre": "七绝", "date": "2020.11.01", "body": "曾经风雨叶金黄，\n笑对严寒傲雪霜。\n依旧挺拔春又绿，\n钟情大地与天长。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "500", "title": "水调歌头·避暑山庄", "genre": "水调歌头", "date": "2020.11.02", "body": "自古风凉处，清帝建行宫。\n方圆十里苍翠，四面邈山峰。\n夏日烟波致爽，南木殿堂无虑，\n闻远近泉声。\n眺水芳岩秀，沐万壑松风。\n勤政殿，水心榭，冷香亭。\n云山松鹤清樾，赏万树莺鸣。\n烟雨楼中议事，素尚斋前谈笑，\n芝径念苍生。\n西岭晨霞落，夕照磬锤峰。", "image_files": ["01.jpg", "02.jpg", "03.jpg", "04.jpg", "05.jpg", "06.jpg"]}, {"poem_id": "501", "title": "七绝·赏菊感怀", "genre": "七绝", "date": "2020.11.03", "body": "黄花也趁秋光老，\n天道轮回梅更俏。\n一夜东风百苑香，\n紫燕黄莺桃李笑。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg", "04.jpg"]}, {"poem_id": "502", "title": "七律·普宁普佑寺游感", "genre": "七律", "date": "2020.11.04", "body": "天下清宁千古愿，\n皇家寺庙隐虚玄。\n人心所向佛门事，\n他念无生社稷安。\n教养官僧凭圣意，\n策驱百姓不挥鞭。\n铜炉香火天天旺，\n代代良民自苦甘。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "503", "title": "相见欢·晓梦惊妻", "genre": "相见欢", "date": "2020.11.05", "body": "醒来残月当楼，\n冷嗖嗖，\n一夜西风桐叶舞京秋。\n黄花乱，\n寒云卷，\n有人愁。\n晓梦惊魂枕泪暗啼流。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "504", "title": "七绝·遥看擂台", "genre": "七绝", "date": "2020.11.05", "body": "各自称赢一夜间，\n冷嘲怒骂闹翻天。\n斯文扫地寻常事，\n俩老爷们怪可怜。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "505", "title": "清平乐·活佛行宫", "genre": "清平乐", "date": "2020.11.06", "body": "鎏金庙顶，\n突显皇恩盛。\n御笔题名趋者众，\n二百年来胜境。\n期求满藏一家，\n神州万里无瑕。\n达赖班禅二主，\n热河行住皆佳。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg", "04.jpg", "05.jpg", "06.jpg"]}, {"poem_id": "506", "title": "七绝·冬夜有感", "genre": "七绝", "date": "2020.11.07", "body": "梦里寒来又立冬，\n掌灯欹枕绪无穷。\n遥思彼岸情和事，\n何脸说人黑与红？ ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "507", "title": "清平乐·鸡狗斗", "genre": "清平乐", "date": "2020.11.08", "body": "岂知真假？\n各自说赢话。\n彼此隔空胡乱骂，\n别样文明灯塔。\n欣然台下吃瓜，\n可该偏向谁家？\n且看鸡飞狗跳，\n悠悠乐乐哈哈。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "508", "title": "卜算子·迫不及待", "genre": "卜算子", "date": "2020.11.08", "body": "墙破众人推，\n树倒猢狲散。\n驴象之争未定时，\n狼狗挑边站。\n昔日语缠绵，\n此刻无相伴。\n一哨从前受气人，\n纷泄心头怨。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "509", "title": "减字木兰花·困兽", "genre": "减字木兰花", "date": "2020.11.09", "body": "远观风景，\n对岸懂王心火盛。\n无奈选情，\n懊恼生疑喊不公。\n人浑嘴硬，\n斜眼黄毛常耍横。\n留恋王宫，\n痴梦随风或落空。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "510", "title": "点绛唇·游棒槌山", "genre": "点绛唇", "date": "2020.11.10", "body": "遥望锤峰，\n神针定海乾坤转。\n绝除灾患，\n峻峻金蟾现。\n夕照秋山，\n苍翠红黄点。\n枫欲燃，\n叶飘风灿，\n暮色云烟漫。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg", "04.jpg"]}, {"poem_id": "511", "title": "点绛唇·寒夜思乡", "genre": "点绛唇", "date": "2020.11.11", "body": "露冷风清，\n凭栏无语观星斗。\n蓦然回首，\n桐叶窗前瘦。\n无奈离亲，\n遥望家山久。\n娘知否？\n重阳别后，\n思念浓如酒。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "512", "title": "点绛唇·寄同窗", "genre": "点绛唇", "date": "2020.11.12", "body": "谊厚情深，\n韶华共奋寒窗案。\n酒香茶酽，\n不惧斜辉晚。\n长忆当年，\n劲舞屠龙剑。\n楼头看，\n夕阳无限，\n红叶迎风炫。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "513", "title": "七律·山庄温泉", "genre": "七律", "date": "2020.11.13", "body": "泉汤午浴艳阳天，\n悠雅乐音萦远山。\n池净水滑人欲醉，\n风轻云淡叶蹁跹。\n一丛香草安神气，\n几片灵芝养玉颜。\n纵使三宫妃子笑，\n帝王有几若今欢？ ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg", "04.jpg"]}, {"poem_id": "514", "title": "踏莎行·人心向背", "genre": "踏莎行", "date": "2020.11.14", "body": "众叛亲离，孤愁群奋。\n懂王四载人神恨。\n昔时盟友苦难堪，\n今朝对手怡心寸。\n老泪盈眸，黄毛乱鬓。\n被人抛弃心头困。\n不知自视却矫情，\n苍天有眼除骚棍。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "515", "title": "踏莎行·远眺感怀", "genre": "踏莎行", "date": "2020.11.15", "body": "滚滚车流，\n声声笛响。\n纵横灯火人来往。\n风霜寒暑不停歇，\n辛劳且为儿孙闯。\n两鬓华斑，\n一怀梦想。\n满腔心血滴滴淌。\n神州南北度春秋，\n回眸细把千红赏。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "516", "title": "减字木兰花·对峙", "genre": "减字木兰花", "date": "2020.11.16", "body": "白宫门外，\n火浪烟涛都不怪。\n荷弹携枪，\n老特粉丝痴欲狂。\n疫情谁顾，\n早被谎言蒙蔽住。\n败选难承，\n宣泄聊发痛苦情。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg", "04.jpg"]}, {"poem_id": "517", "title": "七律·求学叹", "genre": "七律", "date": "2020.11.17", "body": "望子成龙父母心，\n娇儿未降校区寻。\n都城旧院楼台破，\n学教新规钱袋贫。\n隐处一间茅厕价，\n他乡半片小楼群。\n可怜老少倾全力，\n只为将来彩凤临。\n注：学区房每平\n十几万多，落户\n6年方能入学。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "518", "title": "七绝·游唐家湾", "genre": "七绝", "date": "2020.11.18", "body": "秋山小院望天门，\n叶浪松涛晓色新。\n岭舞云叠湖水碧，\n骆驼峰上最销魂。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "519", "title": "采桑子·余晖", "genre": "采桑子", "date": "2020.11.19", "body": "老来恰似秋光晚，\n鬓角飞霜，\n岁月沧桑，\n苦乐得失胸腹藏。\n余年宛若夕阳好，\n五彩霞光，\n韵味悠长，\n缓缓柔晖暖故乡。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "520", "title": "清平乐·歪风斜景", "genre": "清平乐", "date": "2020.11.20", "body": "输赢不认，\n胡搅添风韵。\n百姓难言多少恨，\n欲火熊烧更甚。\n宫中戏码迭新，\n街头杂乱纷纷。\n怒目持枪对峙，\n长空弥漫烟云。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "521", "title": "小重山·冬晓望乡", "genre": "小重山", "date": "2020.11.21", "body": "夜雨天寒更北风，\n晓来残叶舞、乱鸦鸣。\n楼头衰草映初冬，\n花无语、偶见水成冰。\n无奈滞都城，\n凭栏思二老、绪无穷。\n苍颜病腿耳还聋，\n行且慢、诸事莫匆匆。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "522", "title": "五绝·今古恨", "genre": "五绝", "date": "2020.11.22", "body": "人骄国力小，\n割地赔钱了。\n含恨泪滴流，\n尊严谈个鸟。\n打脸“宁要小\n民尊严，不\n要大国崛起” ​​​", "image_files": ["01.jpg"]}, {"poem_id": "523", "title": "踏莎行·生日抒怀", "genre": "踏莎行", "date": "2020.11.22", "body": "落座人欢，铜锅家宴。\n欣逢小雪生辰见。\n五十八载度春秋，\n悠然回首心无憾。\n祖辈农夫，后生企管。\n都城遥望乡居远。\n喜期来月又添丁，\n阖家兴旺今朝愿。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "524", "title": "卜算子·初冬有寄", "genre": "卜算子", "date": "2020.11.23", "body": "节序不欺人，小雪准时到。\n风荡云空乱叶飞，残柳啼鸦闹。\n庭院粉红稀，楼外冰当道。\n老友重逢把酒欢，情奋千杯少。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "525", "title": "七律·贺嫦娥五升空", "genre": "七律", "date": "2020.11.24", "body": "又见嫦娥舞碧空，\n万里骄飞韵味浓。\n俯瞰神州山水秀，\n慕思人世蜡灯明。\n千年寂寞今朝去，\n一缕欢欣天地同。\n辛苦不辞凭昼夜，\n聚凝华夏月圆情。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "526", "title": "木兰花·触景感怀", "genre": "木兰花", "date": "2020.11.25", "body": "惊风又起疏篱院，\n萧瑟菊花争舞乱。\n远山斜照映塘中，\n潋滟清波吹不断。\n人生宛若游丝短，\n心事且行当莫缓。\n流年易逝恨无长，\n不意苍颜霜鬓染。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "527", "title": "蝶恋花·寄友抒怀", "genre": "蝶恋花", "date": "2020.11.26", "body": "莫对黄花孤负酒，\n畅饮高歌，\n笑过重阳九。\n谁道老来心怀瘦，\n亲山乐水诗情秀。\n一曲新词思故旧，\n锦色芳华，\n山海常携手。\n无悔当初南北走，\n凭栏遥望推心友。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "528", "title": "鹧鸪天·遣怀", "genre": "鹧鸪天", "date": "2020.11.27", "body": "一介书生鬓染霜，\n半生江海任疏狂。\n搏涛击浪风云后，\n赏月观花倚草堂。\n别闹市、近书香，\n文情诗韵漫幽窗。\n晴天几案茶一盏，\n雨夜灯前酒半觞。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "529", "title": "卜算子·咏松柏", "genre": "卜算子", "date": "2020.11.28", "body": "野外傲秋风，苍干峥峥骨。\n枝叶悠悠翠不衰，无惧寒冬苦。\n伫立越千年，涛浪犹天鼓。\n岁月无言人世非，笑看雄鹰舞。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "530", "title": "踏莎行·冬夜思", "genre": "踏莎行", "date": "2020.11.29", "body": "日暮灯红，\n冷风明月。\n中庭残柳栖鸦雀。\n行人稀少院清清，\n疏桐零乱寒声咽。\n时序逢冬，\n银空欲雪。\n千山万岭芳香谢。\n墙梅独自笑长天。\n迎春玉蕊娇人靥。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg", "04.jpg"]}, {"poem_id": "531", "title": "七绝·望雪寻梅", "genre": "七绝", "date": "2020.11.30", "body": "北风吹雪雪天寒，\n银粟茫茫覆岭川。\n放眼云空无翠鸟，\n回眸玉蕊绽篱边。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "532", "title": "七律·都城闲咏", "genre": "七律", "date": "2020.12.01", "body": "清冷微风晓色明。\n层楼庭院舞红灯。\n商家造市求出货，\n物业搭台赚美名。\n午后舒心人漫步，\n柳前惬意鸟争鸣。\n冬寒虽甚神州暖，\n不道西方乱疫情。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "533", "title": "少年游·平湖秋色", "genre": "少年游", "date": "2020.12.02", "body": "秋风弄影，老鱼吹浪，\n水岸映芦花。\n湖光潋滟，飘枫如画，\n声渺隐歌娃。\n远处夕阳悠然落，\n暮色赛朝华。\n摇橹荡舟心怡事，\n情难尽，戏莎沙。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "534", "title": "清平乐·冬晓心奋", "genre": "清平乐", "date": "2020.12.03", "body": "月残风冷，\n晨练催人醒。\n杠上飞身双臂挺，\n翻转腾空立定。\n人称腿脚非凡，\n自觉不抵当年。\n已是风霜白发，\n心神还似从前。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg", "04.jpg"]}, {"poem_id": "535", "title": "七律·望黄鹤楼", "genre": "七律", "date": "2020.12.04", "body": "白云千载绕空楼，\n独立江边水自流。\n墨客文人诗并赋，\n彩亭碑字毁重修。\n古人期盼春江绿，\n今子莫发秋日愁。\n地北天南楼上客，\n只宜潇洒乐悠悠。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "536", "title": "七律·黄鹤楼寄怀", "genre": "七律", "date": "2020.12.05", "body": "疫去众来黄鹤楼，\n登高望远散忧愁。\n龟山蔼蔼尖峰翠，\n汉水清清细浪流。\n岁末年初瘟肆虐，\n江头秋暮起飞鸥。\n若得仙鹤今朝至，\n盛叹萋萋鹦鹉洲。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "537", "title": "卜算子·望庐山瀑布", "genre": "卜算子", "date": "2020.12.06", "body": "日照古庐山，烟紫炉香酽。\n倒挂银河亿万年，瀑布琼珠乱。\n迷倒太白仙，把酒声声唤。\n翠影红霞映九天，日落苍山暗。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "538", "title": "七绝·冬夜闲吟", "genre": "七绝", "date": "2020.12.07", "body": "故人别聚又东西，\n馐馔万千终散席。\n人世风光似花艳，\n寒霜过后化青泥。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "539", "title": "七绝·大雪有寄", "genre": "七绝", "date": "2020.12.08", "body": "银装素裹千山静，\n玉镜无言万水凝。\n篱落红梅娇欲放，\n人间祥瑞又春风。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "540", "title": "七律·遥看闲咏", "genre": "七律", "date": "2020.12.09", "body": "神州域外起狼烟，\n更忆当年祖辈贤。\n国弱家贫恒有志，\n山河南北渺强权。\n一星两弹惊天地，\n五岭三山改旧颜。\n几代先人不遗力，\n英雄气概至今传。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "541", "title": "虞美人·旗映蟾宫", "genre": "虞美人", "date": "2020.12.10", "body": "广寒宫里红旗俏，\n惊醒嫦娥笑。\n千年寂寞舞长空，\n四下无人、怎可诉衷情。\n而今可晓神州事，\n万里相思寄。\n往来天地不须愁，\n凭借飞船、山海任欢游。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "542", "title": "破阵子·壶口冰瀑", "genre": "破阵子", "date": "2020.12.11", "body": "千里滔滔凝滞，\n琼花玉柱惊魂。\n一抹飞虹萦两岸，\n炫彩当空撩眼神。\n风光胜夏春。\n不用工雕匠刻，\n晶莹剔透绝伦。\n休怨隆冬无景色，\n且看黄河俏美人。\n冰壶情意真。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "543", "title": "七绝·趣题", "genre": "七绝", "date": "2020.12.12", "body": "闲来无事坐桌旁，\n风雨不惊闻酒香。\n多少投机名利客，\n每逢此处自神伤。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "544", "title": "七绝·绝望", "genre": "七绝", "date": "2020.12.12", "body": "懂王无奈谁人懂，\n失落之情日益浓。\n以为一根香稻草，\n到头却是水中萍。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "545", "title": "菩萨蛮·公祭抒怀", "genre": "菩萨蛮", "date": "2020.12.13", "body": "雨花台下飞寒露，\n当年多少冤魂度。\n日寇灭人寰，\n血光映远天。\n国殇时刻记，\n勿忘山河耻。\n吾辈自当强，\n同心固汉疆。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "546", "title": "蝶恋花·遥思", "genre": "蝶恋花", "date": "2020.12.14", "body": "夜冷窗寒独对酒，\n灯影无言，\n恰似知心友。\n苦乐不离相看久，\n开怀畅饮同厮守。\n更深人静山衔斗，\n月转星移，\n望北频搔首。\n不道家妻伤病手，\n而今自主如前否？ ​​​", "image_files": ["01.jpg"]}, {"poem_id": "547", "title": "五律·戏和行者老弟", "genre": "五律", "date": "2020.12.15", "body": "山中望旧庵，独坐小溪南。\n香客难超五，鸣禽不过三。\n铜壶茶欲沸，施主睡方酣。\n梦里听佛语，醒来望岭岚。\n附原玉：\n五律 • 踏雪访友\n健行者\n寻阶向草庵，雪掩老门南。\n犬踱梅花五，鸡蹁竹叶三。\n闲吟炉正沸，小酌酒方酣。\n醉卧听风语，霜林漫夕岚。", "image_files": ["01.jpg"]}, {"poem_id": "548", "title": "如梦令·无赖", "genre": "如梦令", "date": "2020.12.16", "body": "撒谎扯皮宫斗，\n顶上黄毛腥臭。\n鸦嘴总无休，\n已令世间烦透。\n难受，难受，\n且待春风除垢。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "549", "title": "清平乐·冬练见闻", "genre": "清平乐", "date": "2020.12.17", "body": "晓寒湿雾，\n阻断东西路。\n残月无形多冷露，\n败叶枯枝鸦宿。\n街园隐隐行人，\n跳绳舞剑频频。\n老少眉山飞雪，\n笑谈别有精神。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "550", "title": "踏莎行·贺嫦五回家", "genre": "踏莎行", "date": "2020.12.17", "body": "夜色虹光，\n寒天娥影。\n蟾宫一对风情种。\n依依别过下凡间，\n圆了千载回归梦。\n袖纳奇香，\n怀揣异景。\n蹁跹晓落惊人醒。\n神州大地马牛欢，\n燕鹰高唱山河咏。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "551", "title": "一丛花·冬晓有见", "genre": "一丛花", "date": "2020.12.18", "body": "北风卷叶舞清寒，\n刺骨痛心尖。\n残星斜月千般躲。\n冷霜漫，灯影飞悬。\n路静人稀，\n薄冰障眼，\n鸦雀正枝眠。\n勿闻隐隐扫街边，\n车动又挥锨。\n时时嘘气呵双手。\n鬓飞雪，步履蹒跚。\n美容城市，\n孤身默默，\n日月复年年。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "552", "title": "卜算子·和维真", "genre": "卜算子", "date": "2020.12.19", "body": "越岭过重山，又至云天寺。\n祈祷福财屡进香，堂殿频求字。\n日夜拜佛陀，奢望生无死。\n坐想行思几近痴，富者多如此。\n附原玉：\n卜算子      卦\n维真\n云渺绕幽山，烟锁寒凉寺。\n怨子祈添手上香，欲解乾坤字。\n福祸鉴弥陀，易卜玄生死。\n恍若心魔枉自痴，命注签如此。", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "553", "title": "清平乐·感京都车辆新政", "genre": "清平乐", "date": "2020.12.20", "body": "官人动嘴，\n百姓愁双腿。\n你往他来南复北，\n岁末车潮似水。\n商家买卖兴隆，\n情急难保公平。\n最苦黎民心血，\n这般如此折腾。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "554", "title": "浣溪沙·喜逢冬至", "genre": "浣溪沙", "date": "2020.12.21", "body": "星耀京城夜欲阑，\n子添娇女喜迎年。\n阖家欢畅更空前。\n梅雪逢春花自好，\n门庭飞瑞鹊留连。\n东风紫气艳阳天。\n七绝 冬至子得女\n昼短宵长数九天，\n始生阳气逆风寒。\n无言岁月人欢喜，\n乖女飘然落吾边。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "555", "title": "踏莎行·家喜众贺", "genre": "踏莎行", "date": "2020.12.23", "body": "母女平安，\n家门欢乐。\n恰逢冬至亲朋贺。\n爷爷奶奶喜眉梢，\n姑姨舅姥心怀阔。\n浓发娇颜，\n薄唇靥窝。\n喃喃自语娘边卧。\n众人期盼早回家，\n身揣手把灯宵彻。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "556", "title": "点绛唇·盼", "genre": "点绛唇", "date": "2020.12.24", "body": "姣女将归，\n秀床花被馨屋暖。\n楼台凝眼，\n晴晓风云淡。\n遥望冬阳，\n万道霞光远。\n梢头看，\n鹊鸣莺啭，\n欢响萦庭院。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "557", "title": "看花回·玉蕊初绽", "genre": "看花回", "date": "2020.12.25", "body": "娇小归来，长是靥放眉展。且看一双嫩手，似燕莺飞舞，时隐时现。芳脸细眸，偶尔寻声头自转。吃复睡，无虑心甜，梦里低语笑声浅。\n门户喜，光盈几案。老少乐，气和香漫。金锁银镯在手，聚长辈情怀，宾朋意愿。只盼将来，体康神安前程远。吾虽累，却无怨，乖巧天天见。", "image_files": ["01.jpg"]}, {"poem_id": "558", "title": "七律·冬夜寄怀", "genre": "七律", "date": "2020.12.25", "body": "静无喧闹过寒天，\n网上清新任我观。\n惟有军人风雪立，\n岂因洋鬼送平安。\n居家当念边关苦，\n出外犹思华夏甘。\n隔夜主席生诞日，\n请君默默记心间。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "559", "title": "念奴娇·领袖颂", "genre": "念奴娇", "date": "2020.12.26", "body": "冷天寒地，恰主席生日，万众追思。休道伟人行已远，山海曾记当时。橘子洲头，井冈山上，足迹遍东西。古田明断，红军所向披靡。\n遵义城上空前，看核心确立，迈步身齐。赤水来回三四次，对手无奈皆迷。抗日八年，神州解放，华夏创新奇。至今犹唱，沁园春雪之词。", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "560", "title": "七绝·铭记", "genre": "七绝", "date": "2020.12.27", "body": "吃水感恩挖井人，\n复兴凝聚圣贤魂。\n韶山旭日千辉照，\n江海清波万里春。 https://video.weibo.com/show?fid=1034:4586670562148362 ​​​", "image_files": []}, {"poem_id": "561", "title": "沁园春·主席颂", "genre": "沁园春", "date": "2020.12.28", "body": "千古一人，绝代英豪，\n文秀字飘。\n望神州内外，文哲政史；\n名家无数，岂有追超。\n对阵列强，武装百姓，\n诸子谁人可比高。\n秋暴动，长工农志气，\n山海妖娆。\n赤旗多彩多娇，\n引华夏英雄竞折腰。\n反蒋家内战，运筹帷幄；\n缜思遥控，独领风骚。\n抗美援朝，国威远震，\n万里云空射大雕。\n豪气荡，更精神永在，\n激励今朝。", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "562", "title": "七绝·婴儿乐", "genre": "七绝", "date": "2020.12.29", "body": "梦里终究何喜事？\n三番五次笑由衷。\n安然无虑舒心卧，\n惟愿悠悠乐此生。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg", "04.jpg"]}, {"poem_id": "563", "title": "西江月·冬夜感怀", "genre": "西江月", "date": "2020.12.30", "body": "冷月银空高挂，\n寒风树杪低鸣。\n街头巷尾少人行，\n楼宇窗灯相映。\n已是年前岁暮，\n又燃疫火瘟情。\n世人胆颤梦魂惊，\n祈望神州安定。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "564", "title": "踏莎行·岁暮抒怀", "genre": "踏莎行", "date": "2020.12.31", "body": "岁月如流，\n年光无迹。\n韶华锦绣终将逝。\n银丝斑鬓又何妨，\n窗前闲望云空碧。\n咏诵苏辛，\n追寻杜李。\n唐风宋雨催天丽。\n吟霜赋雪好迎春，\n纵情山水抒豪气。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "565", "title": "念奴娇·新年寄怀", "genre": "念奴娇", "date": "2021.01.01", "body": "无声岁月，又悄悄暗换，喜迎元旦。\n万里神州山海笑，日月星辰光灿。\n回首春时，疫情肆虐，霎那江城乱。\n精明决策，聚人心势翻转。\n更有纾困脱贫、嫦娥辞月、北斗巡天眼。\n不管风吹千里浪，且看巨龙腾远。\n百姓安居，城乡同进，诸事随人愿。\n燕莺翔奋，竞风流翼高展。", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "566", "title": "夜游宫·跨年情", "genre": "夜游宫", "date": "2021.01.02", "body": "窗外寒声阵阵，\n冷侵月，夜深风劲。\n窒内温馨却无困。\n共言欢，品香茗，\n清觯饮。\n且看婵娟晕，\n渐西下，漫消辉尽。\n红日东升更人奋，\n又新年，丽云空，\n迎好运。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "567", "title": "踏莎行·别样新年", "genre": "踏莎行", "date": "2021.01.03", "body": "政客犹狂，\n疫情愈甚。\n白宫内斗街头愤。\n谁当总统吵无休，\n平民群死鲜人问。\n日本封国，\n克龙确诊。\n伦敦动荡争逃遁。\n中欧贸易立新规，\n神州山水风云劲。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "568", "title": "踏莎行·夜遣怀", "genre": "踏莎行", "date": "2021.01.04", "body": "长近尊前，\n少思身外。\n老来心淡行难快。\n孩儿自是路千条，\n乌鸦亦有他人爱。\n安度春秋，\n缓行岳岱。\n无言山水真情在。\n赏临花草气幽清，\n免生烦恼无妨碍。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "569", "title": "渔家傲·小寒寄怀", "genre": "渔家傲", "date": "2021.01.05", "body": "时入小寒风色冷，\n啼鸦零乱惊宵梦。\n晓起窗栊盈玉冻。\n寒气盛，\n残枝瑟瑟频摇动。\n岁暮袭来情难胜，\n银丝斑鬓毋堪镜。\n多少浮生尘世影。\n人不静，\n年光似水伤心痛。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "570", "title": "采桑子·祈盼", "genre": "采桑子", "date": "2021.01.06", "body": "京门南望情怀乱，\n愁念家乡，\n疫又猖狂，\n心上眉间点点慌。\n由衷惟愿风云过，\n雨霁虹光，\n山海飞阳，\n无恙亲朋共举觞。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "571", "title": "卜算子·闻疫有感", "genre": "卜算子", "date": "2021.01.07", "body": "武汉疫情消，\n不道石门烈。\n零下寒风刺骨疼，\n夜里核酸确。\n灾患总无常，\n且莫轻欢跃。\n却是忧思谨慎行，\n苦难终能越。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "572", "title": "浣溪沙·送老特", "genre": "浣溪沙", "date": "2021.01.07", "body": "怨地仇天怼选民，\n黄毛丑脸恶心人。\n终遭唾弃似烟尘。\n搅乱寰球得报应，\n撕开美帝费贼心。\n四年埋下祸灾根。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg", "04.jpg"]}, {"poem_id": "573", "title": "踏莎行·缅怀总理", "genre": "踏莎行", "date": "2021.01.08", "body": "磊落无私，\n清廉大爱。\n西花厅里春常在。\n诙谐睿智语平和，\n谦尊老少人心快。\n梁栋高才，\n山峰巨岱。\n谁人堪比情豪迈。\n一生无子爱无疆，\n飘然神影千年拜。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "574", "title": "七律·颂总理", "genre": "七律", "date": "2021.01.09", "body": "周公无子更无私，\n沥血为民才智奇。\n少壮明心华夏起，\n终生践志未曾移。\n虚怀待事情思满，\n和气与人诚不失。\n处世清廉堪典范，\n神州内外美名遗。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "575", "title": "点绛唇·瑞雪香梅", "genre": "点绛唇", "date": "2021.01.10", "body": "银粟纷纷，\n叶寒香冷枝梅秀。\n晓风辞旧，\n红日驱星斗。\n便是晴空，\n户外难伸手。\n正三九，\n鹊鸣残柳，\n欢喜迎辛丑。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "576", "title": "踏莎行·望乡", "genre": "踏莎行", "date": "2021.01.11", "body": "地冻天寒，\n千家万户。\n悲情燕赵风云度。\n毒虫肆虐暗苍空，\n英雄儿女无穷数。\n白甲逆行，\n赤心飞步。\n一方有难八方助。\n神州同盼艳阳天，\n喜逢辛丑花开处。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg", "04.jpg"]}, {"poem_id": "577", "title": "七绝·画皮", "genre": "七绝", "date": "2021.01.12", "body": "曾记当时佩洛西，\n暴徒祸港却心期。\n而今风景桌边秀，\n怒目仇言老脸急。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "578", "title": "踏莎行·凭图寄怀", "genre": "踏莎行", "date": "2021.01.13", "body": "忠孝难全，\n阴阳无怨。\n纯真儿女心怀善。\n凝神抗疫品行高，\n银屏内外同声赞。\n华夏辉煌，\n国人奉献。\n寻常日夜频挥汗。\n恒心似水向东流，\n换来今日山河灿。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "579", "title": "七律·遥望", "genre": "七律", "date": "2021.01.14", "body": "惊闻疫害近家门，\n彻夜愁眠念远村。\n父母需人儿不在，\n亲朋有苦我分心。\n非常举措难归去，\n无限忧伤更费神。\n幸有东风送温暖，\n驱除寒冷好逢春。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "580", "title": "七绝·心声", "genre": "七绝", "date": "2021.01.15", "body": "疫情唤醒人间爱，\n萤火微光夜路明。\n独自宵行心胆怯，\n高歌携手唱英雄。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "581", "title": "卜算子·寒夜明珠", "genre": "卜算子", "date": "2021.01.16", "body": "……赠国网石电人\n慷慨送光明，\n万户寒灯亮。\n刺骨西风雪满身，\n眉眼冰花酿。\n不道疫突来，\n逆进谁思量。\n电入方舱病患安，\n赤胆真情漾。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg", "04.jpg", "05.jpg", "06.jpg"]}, {"poem_id": "582", "title": "定风波·趣闻戏吟", "genre": "定风波", "date": "2021.01.17", "body": "饮酒归来偶犯迷，\n忘乎席上俏芳姿。\n他日相逢歌店里，\n无视。\n朱唇秀靥话当时。\n再挽金尊推玉臂，\n杯起。\n情深肠断语迟迟。\n没早搭言恨无比，\n窃喜。\n又朦南北落东西。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "583", "title": "千秋岁·岁暮吟", "genre": "千秋岁", "date": "2021.01.18", "body": "腊八将近，\n冷叶霜风奋。\n梅绽放，飞清韵。\n篱枝摇玉蕊，\n莺报春音信。\n昂首盼，\n层冰溶化新芽嫩。\n庚子年光钝，\n冠疫生心恨。\n临岁杪，情趋紧。\n闭城封户策，\n期待幽虫遁。\n闻境外，\n漫无章法人神愤！ ​​​", "image_files": ["01.jpg"]}, {"poem_id": "584", "title": "七绝·岁末闲吟", "genre": "七绝", "date": "2021.01.19", "body": "人生有限愿无穷，\n岁月蹉跎怨恨成。\n若使尘心终向善，\n云天寥廓总为晴。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "585", "title": "七律·腊八寄怀", "genre": "七律", "date": "2021.01.20", "body": "风摇月影九霄寒，\n腊日更逢飞雪天。\n一碗浓粥心里热，\n几颗香枣口中甘。\n悠悠揣品非常味，\n慢慢琢磨异往年。\n客地疫留思故里，\n梦闻父母与儿言。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "586", "title": "七律·寄若煊满月", "genre": "七律", "date": "2021.01.20", "body": "一从娇女落儿家，\n蓬荜温馨胜百花。\n长是欢声盈牖户，\n鲜闻哭闹透帏纱。\n朱唇粉面纤香手，\n黑发浓眉嫩脚丫。\n乖巧灵通诚可爱，\n犹如玉蕾似朝霞。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg", "04.jpg", "05.jpg", "06.jpg"]}, {"poem_id": "587", "title": "采桑子·别了老特", "genre": "采桑子", "date": "2021.01.21", "body": "黄毛怎耐随风去，\n带走乌云，\n终作烟尘。\n树倒猢狲各自奔。\n可怜无数痴川粉，\n奢望翻身，\n断梦惊魂。\n不解风情枉费神。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "588", "title": "减字木兰花·二首", "genre": "减字木兰花", "date": "2021.01.22", "body": "一.\n黯然离去，\n覆水难回人若絮。\n枉费心机，\n自恋多疑癞脸皮。\n谎言盗语，\n四载嚣张伤几许。\n四处狂嘶，\n败落孤狼独自啼。\n二.\n并非挺拜，\n举世反川情意在。\n米帝阴浑，\n祸乱神州是为根。\n打消幻想，\n利剑长缨凭手仗。\n江海齐鸣，\n巨浪滔滔起大鹏。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg", "04.jpg"]}, {"poem_id": "589", "title": "清平乐·冬泳", "genre": "清平乐", "date": "2021.01.23", "body": "霜天雪地，\n冻水凝寒气。\n且看健儿挥赤臂，\n壮美琼花四起。\n北风吹荡残枝，\n冷光辉映冰池。\n最喜蛟龙勇色，\n身萦玉甲银丝。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "590", "title": "七律·疫中人", "genre": "七律", "date": "2021.01.24", "body": "难耐闲居苦掩门，\n寒窗宵昼对灯昏。\n凭栏遥想生微惧，\n望月愁思忆远村。\n无虑盘餐聊自慰，\n分心杯盏寄孤魂。\n啼鸦零乱惊晨梦，\n欹枕凝眉又把尊。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "591", "title": "七律·疫中人2", "genre": "七律", "date": "2021.01.25", "body": "居家睡傻下厨房，\n刀俎锅盆灶上忙。\n猪肉红烧肥不腻，\n蟹虾焖炒户飘香。\n餐餐丰色盘鲜美，\n日日盈杯酒泛黄。\n疫害渐消回首望，\n横腰对镜暗心伤。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "592", "title": "汉宫春·庚子吟", "genre": "汉宫春", "date": "2021.01.26", "body": "岁暮时光，望年初疫起，武汉人愁。春寒扫枝卷叶，晴日难留。东风号令，聚八方、赤子如流。历数月，云消雨霁，花香又漫神州。\n回看西洋世界，却哀鸿遍野，怒火无由。当初信口胡语，祸水难收。如今怎奈，害无穷，人死街头。凭对比，东西两岸，此番谁劣谁优。", "image_files": ["01.jpg"]}, {"poem_id": "593", "title": "七律·疫中人3", "genre": "七律", "date": "2021.01.27", "body": "午后无聊凑将台，\n愁思欲坐却徘徊。\n东西南北风寒起，\n九饼三条赤绿来。\n杠上开花人窃喜，\n牌中失算己悲哀。\n忧伤不只钱输尽，\n更苦家门几日开！ ​​​", "image_files": ["01.jpg"]}, {"poem_id": "594", "title": "踏莎行·腊月十五夜", "genre": "踏莎行", "date": "2021.01.28", "body": "明月盈空，\n冷霜匝地。\n西风彻夜浑无忌。\n帝都虽是近春天，\n依然檐下冰垂涕。\n欲进牛年，\n愤离庚子。\n愁心惟愿新冠毙。\n开门纳客喜迎春，\n南来北往随君意。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "595", "title": "七律·疫中人4", "genre": "七律", "date": "2021.01.29", "body": "从前股票偷偷看，\n惟恐被辞丢饭碗。\n近日行情细细研，\n居家独大谁能管。\n开盘闭市起波涛，\n滞涨急跌心绪乱。\n红绿难期却倾心，\n而今处处无钱赚。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "596", "title": "七律·疫中人5", "genre": "七律", "date": "2021.01.30", "body": "寥落尘心庭院间，\n掩门自饮味难甘。\n独听残月无言语，\n孤对寒窗绪不安。\n梦里常惊冠疫事，\n醒来又看手屏前。\n有谁知晓除封日？\n旧友重逢把酒欢。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "597", "title": "七律·疫中人6", "genre": "七律", "date": "2021.01.31", "body": "历雨经风度晚晴，\n闭门防疫绪难平。\n机言屏语传情意，\n咏赋吟诗递爱声。\n遥望隔山同日月，\n近闻临院对筹觥。\n严寒过后春相聚，\n柳陌桃磎乐此生。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "598", "title": "七律·疫中人7", "genre": "七律", "date": "2021.02.01", "body": "石门疫讯渐消停，\n多少英雄可勒铭。\n医者逆行忙日月，\n警民遵命戴辰星。\n社区灯火千家暖，\n屏上官言万户宁。\n邻里隔空传信语，\n比肩寒夜待天明。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "599", "title": "踏莎行·寄同窗", "genre": "踏莎行", "date": "2021.02.02", "body": "天上星辰，\n人间烟火。\n岭峰千载飞云朵。\n古今江海水无穷，\n纵横阡陌飘花果。\n世态多姿，\n犹如你我。\n风霜苦乐谁能躲。\n悠悠岁月且心欢，\n尽情携酒山前卧。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "600", "title": "七绝·立春二首", "genre": "七绝", "date": "2021.02.03", "body": "一.\n梅动诗情雪喜人，\n琼花玉蕊俏迎春。\n多愁子鼠含悲去，\n憨态丑牛诚可亲。\n二.\n神州山海映朝晖，\n情满人间燕子归。\n细语声声勤问候，\n唤来紫气染芳菲。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "601", "title": "七绝·晓吟", "genre": "七绝", "date": "2021.02.04", "body": "旗舞红灯入小年，\n肉香飘溢院堂间。\n殷勤洒扫污尘尽，\n情系新春丽日妍。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "602", "title": "七律·闻事有感", "genre": "七律", "date": "2021.02.05", "body": "人心膨胀忘初衷，\n方向迷离醉眼红。\n不惧天高偏欲往，\n却从虎口拟偷生。\n蓬随风起终将落，\n絮入川流了作萍。\n骤响惊雷魂胆破，\n黄粱一梦事无成。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "603", "title": "踏莎行·亮剑", "genre": "踏莎行", "date": "2021.02.06", "body": "拔地飞星，\n御天长剑。\n夜空惊破弧光艳。\n神州万里网恢恢，\n八方贼寇谁能犯。\n隐姓埋名，\n爬坡过坎。\n荒凉戈壁英雄胆。\n几多赤子写辉煌，\n苍茫宇宙风云撼。#中国诗词大会[超话]##中华好诗词# ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg", "04.jpg"]}, {"poem_id": "604", "title": "浣溪沙·吟望", "genre": "浣溪沙", "date": "2021.02.07", "body": "春色先从草际归，\n随风泛绿弄朝晖。\n纵横阡陌尽芳菲。\n物态山光精气满，\n心怀胸次喜盈眉。\n金牛奋舞燕莺飞。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "605", "title": "采桑子·望梅闲吟", "genre": "采桑子", "date": "2021.02.08", "body": "年华已伴梅花晚，\n南北西东，\n晓暮匆匆。\n无悔今生笔墨浓。\n翩翩少子霜侵鬓，\n明月清风，\n天际无穷。\n淡事闲思不老松。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "606", "title": "浣溪沙·乡愁", "genre": "浣溪沙", "date": "2021.02.09", "body": "迎面不寒六九风，\n轻微摇荡满街红。\n路人来往更匆匆。\n已是年关归欲甚，\n难离京洛绪思浓。\n且依樽酒掩乡情。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "607", "title": "七律·夜望", "genre": "七律", "date": "2021.02.10", "body": "一江明月送流年，\n辛丑春风近眼前。\n瑞雪纷纷庭院落，\n梅花袅袅映窗轩。\n芳茗数盏思家事，\n挚友三人盼世安。\n炉火红情深意暖，\n酒香淡夜色将阑。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "608", "title": "踏莎行·除夕愿", "genre": "踏莎行", "date": "2021.02.11", "body": "福禄心期，\n安康人盼。\n红灯劲舞春光灿。\n离乡游子欲团圆，\n阖家相聚情无限。\n玉鼠回归，\n金牛又见。\n神州草树祥和漫。\n万民携手力无穷，\n千年华夏山河换。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "609", "title": "点绛唇·思念", "genre": "点绛唇", "date": "2021.02.11", "body": "别样三十，\n远离二老心头苦。\n望乡凝伫，\n故里封门户。\n防疫当前，\n即便亲难助。\n心飞渡，\n隔空遥祝，\n牛载千福禄。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "610", "title": "踏莎行·辛丑贺岁", "genre": "踏莎行", "date": "2021.02.12", "body": "转眼新年，\n回头旧岁。\n东风荡漾春湖水。\n金牛开拓力无穷，\n踏枝喜鹊声声翠。\n江海欢腾，\n山川秀美。\n人逢盛世心无悔。\n阖家团聚挽金樽，\n红灯照暖同陶醉。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "611", "title": "清平乐·新年乐", "genre": "清平乐", "date": "2021.02.13", "body": "亲家相聚，\n漫诉心头语。\n共捧娇孙乖巧女，\n春暖馨家欢趣。\n真情玉液盈杯，\n香茗珍果轮回。\n美味佳肴丰盛，\n归来醉眼星辉。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "612", "title": "踏莎行·新春乐", "genre": "踏莎行", "date": "2021.02.14", "body": "牛气冲天，\n福辉映砌。\n门庭街巷盈春意。\n郊原细草望青青，\n山河风暖云空丽。\n燕舞鹰翔，\n马欢人喜。\n亲朋挚友情无比。\n重逢故里笑频频，\n搓麻斗酒谈天地。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "613", "title": "减字木兰花·春夜吟", "genre": "减字木兰花", "date": "2021.02.15", "body": "红灯暖照，篱处梅香枝影俏。\n夜色斑斓，庭院飞光玉树间。\n芳邻闲聚，小径清幽言有趣。\n畅想牛年，何处栖身稳赚钱？ ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "614", "title": "七绝·初五寄怀", "genre": "七绝", "date": "2021.02.16", "body": "一.\n破五心期破疫情，\n火光阵阵炮声鸣。\n妖魔鬼怪随烟去，\n还我神州万里晴。\n二.\n拂晓送穷门敞开，\n清街净院纳鸿财。\n九天神圣循常道，\n凭借前缘进户来。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "615", "title": "踏莎行·依依不舍", "genre": "踏莎行", "date": "2021.02.17", "body": "把酒重逢，\n含情别去。\n匆匆故里家团聚。\n感恩父母意情长，\n寄怀乡土萦思绪。\n无限心言，\n尽穷词句。\n来生愿作乖儿女。\n庭前月下望星空，\n踏阶携手同风雨。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg", "04.jpg"]}, {"poem_id": "616", "title": "相见欢·时令有感", "genre": "相见欢", "date": "2021.02.18", "body": "悠悠雨水侵春，\n气清芬，\n草木芳香鸟哢、暖风薰。\n千百味，\n谁不醉，\n恁销魂。\n蝶舞鹰翔天地、抖精神。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "617", "title": "七律·新春寄若煊", "genre": "七律", "date": "2021.02.19", "body": "一月有余称两岁，\n千金宝贝与时新。\n呀呀欲语摇头晃，\n款款含情俏喜人。\n沉稳宵眠哭闹少，\n舒心昼耍自凝神。\n每逢戏水长欢乐，\n最是怀中各销魂。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "618", "title": "画堂春·初春晓望", "genre": "画堂春", "date": "2021.02.20", "body": "东风夜雨动林池，\n霁光穿树参差。\n水边燕舞翠莺啼，\n细叶轻枝。\n路上车流如水，\n行人步快奔驰。\n街园芳草欲萋萋，\n一派生机。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "619", "title": "踏莎行·致敬英雄", "genre": "踏莎行", "date": "2021.02.21", "body": "血肉之躯，\n军魂如铁。\n戍边对阵寒风烈。\n英雄气概壮山河，\n空拳赤手迎钩钺。\n气贯长虹，\n刀削残雪。\n铮铮豪骨蛮人灭。\n丰碑矗立熠星辉，\n威名激荡神州彻。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg", "04.jpg", "05.jpg", "06.jpg"]}, {"poem_id": "620", "title": "蝶恋花·闻讯而喜", "genre": "蝶恋花", "date": "2021.02.22", "body": "门户解封枝鹊喜，\n树杪轻盈，\n欢语飘阶砌。\n多少节前年后事，\n今朝渐渐除心际。\n先自京城回故里，\n二老床前，\n叩首香茶递。\n旧友亲朋扶酒觯，\n大江南北开怀议。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "621", "title": "七律·千古豪气", "genre": "七律", "date": "2021.02.23", "body": "精气神情一脉承，\n秦兵汉将似骄龙。\n赤心铁胆驱豺豹，\n利剑长缨斗虎熊。\n雪域高原旌旆烈，\n昆仑山谷马嘶鸣。\n男儿自古凌云志，\n威震边关万里雄。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "622", "title": "鹧鸪天·和洛水伊人", "genre": "鹧鸪天", "date": "2021.02.24", "body": "华夏牛年一缕光，云霞万里映檐廊。开心笔就朱砂砚，惬意浆盈紫玉觞。\n临画扇，望梅窗，凭栏诗赋颂尧唐。舒膺昂首豪情展，傲雪琼花淡淡香。\n附：洛水伊人原玉\n鹧鸪天.贺新春\n雪藻春风沐旭光，兰襟新岁贺轩廊。瑶琴辞赋梅花砚，阙月传歌桂子觞。\n画帏扇，韵诗窗。又承词曲响华唐。且看鹏凤青云展，独领风骚四季香。", "image_files": ["01.jpg"]}, {"poem_id": "623", "title": "七律·初春无奈", "genre": "七律", "date": "2021.02.25", "body": "云暖风薰似夏天，\n棉衣褪却露香肩。\n街头靓女纱裙短，\n庭院型男半袖衫。\n忽至寒宵冰阻路，\n奈何老幼苦难堪。\n上苍不解人心意，\n如此折腾为那般？ ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "624", "title": "浣溪沙·元宵乐", "genre": "浣溪沙", "date": "2021.02.26", "body": "漫煮汤圆细浪翻，\n清香水气润心田。\n滑绵入口蜜连环。\n春日云霞盈洞户，\n楼台花色映窗轩。\n怀中娇女喜空前。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "625", "title": "蝶恋花·元宵感怀", "genre": "蝶恋花", "date": "2021.02.27", "body": "犹记当年元夜闹，\n火树银花、似水人流笑。\n十里长街龙马俏，\n烟辉月影灯谜妙。\n今夜街头情趣少，\n网聚心怀、男女银屏泡。\n却是嫦娥宫里恼，\n蟾光难道非常好？ ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "626", "title": "七绝·吟望", "genre": "七绝", "date": "2021.02.28", "body": "元宵翌晚月明圆，\n年味于今散远天。\n收敛情怀当鼓劲，\n且凭牛气好耕田。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "627", "title": "七绝·乖孙", "genre": "七绝", "date": "2021.03.01", "body": "俩月娇儿知晓暮，\n白天玩睡两分明。\n每当入夜安眠后，\n一觉通宵少闹声。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "628", "title": "鹧鸪天·敬戍边将士", "genre": "鹧鸪天", "date": "2021.03.02", "body": "塞北山南守界关，\n常年寂寞对云天。\n夏阳蒸烤皮开裂，\n冬日寒潮骨缝钻。\n穿雪岭，踏冰川。\n饮风餐露伴星眠。\n豺狼虎豹浑无惧，\n屹立边陲万户安。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg", "04.jpg"]}, {"poem_id": "629", "title": "七绝·初春寄语", "genre": "七绝", "date": "2021.03.03", "body": "一过元宵渐客稠，\n多来京洛觅金牛。\n满怀憧憬须发奋，\n莫使雄心付水流。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "630", "title": "临江仙·学区叹", "genre": "临江仙", "date": "2021.03.04", "body": "为使娇娃学业好，\n潜心谋划前期。\n西城海淀几番思。\n算来七载后，\n今日抢先机。\n一套旧房八百万，\n厅堂残破窗低。\n空间窄小苦难栖。\n紧身俯首过，\n渺望凤凰枝。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "631", "title": "五律·惊蛰", "genre": "五律", "date": "2021.03.05", "body": "雷震地虫惊，\n阳和草木青。\n芳晨盈玉露，\n昏暮荡清风。\n万物萌欣态，\n千家竞世生。\n花芽娇欲放，\n翠鸟戏枝鸣。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "632", "title": "减字木兰花·春晓即事", "genre": "减字木兰花", "date": "2021.03.06", "body": "凭栏浅笑，燕语莺声枝上闹。\n楼院春辉，天上归鸿振翅飞。\n忽闻妻叫，却是娇孙沾屎尿。\n一阵匆忙，又见婴眉稚脸祥。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "633", "title": "采桑子·探春", "genre": "采桑子", "date": "2021.03.07", "body": "东风漫野传春信，\n陌上花开，\n燕子归来。\n池水清波映绿苔。\n城人假日寻芳去，\n溪径徘徊，\n喜煞童孩。\n逸兴闲情趣满怀。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "634", "title": "蝶恋花·三八赠妻", "genre": "蝶恋花", "date": "2021.03.08", "body": "半世辛劳霜染鬓，\n长是无闲、内外心操尽。\n教子相夫齐奋进，\n尊亲厚友赢嘉论。\n时下看孙终日紧，\n伤累难休、情似春晖润。\n烧菜逗娃行谨慎，\n倾心老少家和顺。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "635", "title": "钗头凤·敬陈薇院士", "genre": "钗头凤", "date": "2021.03.09", "body": "兰溪女。从军旅。聚情防疫心无惧。迎非典。赴江汉。病毒攻克，疫苗如愿。干！干！干！\n经风雨。名寰宇。俏将军重行轻誉。凡参战。影辉炫。沉着坚毅，奋而夺冠。赞！赞！赞！ ​​​", "image_files": ["01.jpg"]}, {"poem_id": "636", "title": "七律·两会有寄", "genre": "七律", "date": "2021.03.10", "body": "春风三月聚英豪，\n国士良谋妙计高。\n实策安邦兴百姓，\n诤言固土绿江涛。\n倾听民意渠通畅，\n擘画宏图运伟韬。\n圆梦中华千载愿，\n巨龙腾起碧空翱。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "637", "title": "南乡子·轮回", "genre": "南乡子", "date": "2021.03.11", "body": "年少入京城，\n寻道求知学苑行。\n事就毅然回故里，\n心宁，\n为报双亲养育情。\n儿又入皇京，\n立志凭身业半成。\n雪鬓帝都孙女伴，\n娇声，\n花甲之年似梦生。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "638", "title": "清平乐·友文读感", "genre": "清平乐", "date": "2021.03.12", "body": "读书益智，\n儒雅兼豪气。\n八裔古今收眼底，\n俯首纵横天际。\n胸盈日月情怀，\n心游峻岭瀛台。\n风雨凭栏眺望，\n静观花落花开。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "639", "title": "七绝·春日暮吟", "genre": "七绝", "date": "2021.03.13", "body": "近日忙来乐趣多，\n今朝将去奈愁何。\n别离娇小正安睡，\n醒后可知爷过河？ ​​​", "image_files": ["01.jpg"]}, {"poem_id": "640", "title": "木兰花令·石门吟", "genre": "木兰花令", "date": "2021.03.14", "body": "帝里归来天欲暮，\n飞速动车春满路。\n观柳陌，望游人，\n漫野萋萋花映树。\n冉冉夕辉山隐日，\n夜色降临空寂寂。\n孤灯独对与谁言，\n幸有梦中孙女忆。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "641", "title": "踏莎行·春望", "genre": "踏莎行", "date": "2021.03.15", "body": "风动花枝，\n春归草地。\n人情物态欣欣意。\n陌阡垂柳染鹅黄，\n纵横车马穿街市。\n抖擞精神，\n聚盈牛气。\n南来北往浮生事。\n寻机拓业百般忙，\n辛劳无悔为家计。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "642", "title": "浪淘沙·突变", "genre": "浪淘沙", "date": "2021.03.16", "body": "塞外卷黄风，\n沙落京城。\n灰头土脸昼如冥。\n阡陌纵横芳草苦，\n枝叶飞横。\n树杪鸟儿惊，\n振翅悲鸣。\n大街小巷路难行。\n嫩蕊鲜花皆暗色，\n扰乱春情。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "643", "title": "清平乐·湖园春色", "genre": "清平乐", "date": "2021.03.17", "body": "枝芽竞翠，\n花惹游人醉。\n碧水清波鸳几对，\n别有一番情味。\n宜人三月春晖，\n轻寒浅暖芳菲。\n细柳缠绵丝雨，\n漫空蝶舞莺飞。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "644", "title": "五律·春雨", "genre": "五律", "date": "2021.03.18", "body": "丝雨入芳庭，\n草青花色浓。\n云空霾雾去，\n阶砌燕莺鸣。\n香气侵人面，\n软风盈袖中。\n一年春晓好，\n却是最匆匆。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "645", "title": "菩萨蛮·疫后归来", "genre": "菩萨蛮", "date": "2021.03.19", "body": "儿归二老情怀奋，\n楼台锅灶飞欢韵。\n苍鬓脑神清，\n出门脚步轻。\n当时防疫紧，\n闭户心愁闷。\n不见远方人，\n犹如少了魂。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "646", "title": "如梦令·春分", "genre": "如梦令", "date": "2021.03.20", "body": "昼夜均分和煦，\n柳绿桃红花雨。\n迎面吻春风，\n喜见鸟飞人趣。\n谁语 ，\n谁语，\n林下闹童欢聚。\n七绝        春分吟\n千红万紫映芳春，\n无限风光昼夜分。\n放眼青山莺燕喜，\n回眸绿水醉佳人。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "647", "title": "清平乐·扬眉", "genre": "清平乐", "date": "2021.03.21", "body": "昔今对比，\n慨叹抒豪气。\n情景犹如天与地。\n峰岭川流欢涕。\n神州万里逢春，\n东风漫卷缤纷。\n碧海长空清丽，\n向阳草木欣欣。\n七绝            龙腾\n舌剑唇枪眼射光，\n巨龙腾起渺西方。\n云霄万里千年翥，\n归隐九州今又翔。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "648", "title": "清平乐·春煦", "genre": "清平乐", "date": "2021.03.22", "body": "经年又聚，\n推盏心怀叙。\n家稳国强鹏正举，\n觯满醇香尽趣。\n新冠虽狠难逃，\n西方无奈飘摇。\n中美双雄对峙，\n风轻云淡天朝。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "649", "title": "菩萨蛮·偶感", "genre": "菩萨蛮", "date": "2021.03.23", "body": "春天冷暖无人料，\n晴空隔日寒风闹。\n老少苦难堪，\n病伤再又三。\n幸亏儿或女，\n前后轻声语。\n不惧累和烦，\n亲情日复年。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "650", "title": "蝶恋花·老少视频", "genre": "蝶恋花", "date": "2021.03.24", "body": "千里亲情屏上见，\n仨月乖孙，\n喜把爷爷辩。\n笑靥欢眉红粉面，\n双眸炯炯机灵现。\n血脉相连思不断，\n别后长宵，\n梦里频相看。\n惟愿娇娃心体健，\n犹如花蕾迎春绽。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "651", "title": "七绝·东西对决", "genre": "七绝", "date": "2021.03.25", "body": "欺人之道返其身，\n怒怼西洋假圣人。\n傲慢谎言天下怨，\n龙声击碎鬼蛇魂。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "652", "title": "菩萨蛮·春日暮行", "genre": "菩萨蛮", "date": "2021.03.26", "body": "黄昏伫望花枝满，\n徐行芳苑春风暖。\n柳翠映桃红，\n笛音透碧空。\n孩童欢戏水，\n翁媪心陶醉。\n无虑释情怀，\n明朝许再来。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "653", "title": "七绝·谁之过", "genre": "七绝", "date": "2021.03.27", "body": "烦事攻心行必乱，\n再三跌倒凭谁怨。\n黑衣老大困舷梯，\n许是苍天传意念！ ​​​", "image_files": ["01.jpg"]}, {"poem_id": "654", "title": "定风波·今非昔比", "genre": "定风波", "date": "2021.03.28", "body": "白净棉花于世间，\n不曾招惹鬼蛇仙。\n却被无端空问罪，\n无畏！\n怒烧烈火映长天。\n无事生非成恶性，\n毛病！\n今朝被刺痛心肝。\n还欲当年行霸道，\n胡闹！\n神州山海异从前！ ​​​", "image_files": ["01.jpg"]}, {"poem_id": "655", "title": "南乡子·春湖", "genre": "南乡子", "date": "2021.03.29", "body": "又是一年春，\n盈眼芳菲万象新。\n防疫解封心底奋，\n邀人，\n漫步踏青湖水滨。\n花树绿芳茵，\n燕鹭凌空鸟哢频。\n荡漾木舟鱼跃起，\n缤纷，\n碧浪船头笑语闻。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "656", "title": "七古·赠若煊百日", "genre": "七古", "date": "2021.03.30", "body": "若云似雾弄春妍，\n煊烂芳菲映远天。\n百鸟齐鸣争翠柳，\n日光馨暖洒人间。\n万里长空鹰燕翥，\n事随人愿自甘甜。\n如今娇女身心健，\n意绪长欢舞蹁跹。\n清平乐 寄语若煊\n乖孙百日，\n千里祥福寄。\n多想周身萦稚气，\n背上娇声轻泣。\n先前无奈分开，\n而今愁事难排。\n一旦急情着落，\n转头宝贝拥怀。", "image_files": ["01.jpg"]}, {"poem_id": "657", "title": "山花子·春祭", "genre": "山花子", "date": "2021.03.31", "body": "临近清明袅纸烟，\n亲人祭祖忆从前。\n恩重情深难忘却，\n泪涟涟。\n昔日家贫多苦难，\n今朝国盛少忧烦。\n告慰先贤魂与魄，\n且长安。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "658", "title": "采桑子·友文读感", "genre": "采桑子", "date": "2021.04.01", "body": "老来忆起当年事，\n思绪蹁跹，\n犹似昨天，\n人物清晰在眼前。\n曾经苦乐终难忘，\n风雨人间，\n吹皱心田，\n岁月无声年复年。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "659", "title": "西江月·侍老感怀", "genre": "西江月", "date": "2021.04.02", "body": "楼外春风荡水，\n窗前愁绪凝颜。\n老人伤痛近身前。\n耋耄微躯堪叹。\n珍重青春年少，\n养存血脉芳颜。\n百年岁月且悠闲。\n雨霁晚霞为盼。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "660", "title": "长相思·老人愿", "genre": "长相思", "date": "2021.04.03", "body": "愁一宵，\n苦一宵。\n老病萦身日夜熬。\n心期妙手消。\n深一刀，\n浅一刀。\n济世仁心各有招。\n白衣医术高。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "661", "title": "七绝·清明感怀", "genre": "七绝", "date": "2021.04.04", "body": "今朝日子火红红，\n祭祖青烟滚滚浓。\n昔往饮风餐露叶，\n万千坟上冷清清。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "662", "title": "定风波·赞友家风", "genre": "定风波", "date": "2021.04.05", "body": "父母传家重品行，\n细微之处见真情。\n针线穿梭铺锦绣，\n合奏。\n齐家携手愿终成。\n邻里不争瓜果事，\n和气。\n刚柔爱恨两分明。\n二老言行恩后辈，\n受惠。\n春风和煦享安平。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "663", "title": "朝中措·春夜吟", "genre": "朝中措", "date": "2021.04.06", "body": "春光无奈骤晴阴，\n乍暖又寒心。\n檐下凭栏听雨，\n夜来苦煞双亲。\n陈年旧病，\n悄然发作，\n阵痛时侵。\n辗转愁思难睡，\n遥天残月西沉。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "664", "title": "踏莎行·神州寄怀", "genre": "踏莎行", "date": "2021.04.07", "body": "世界风云，\n东西较量。\n巨龙腾起掀波浪。\n豺狼虎豹恁心虚，\n贼眉斜眼呲牙向。\n江海涛涛，\n胸怀荡荡。\n卧薪尝胆终相望。\n一朝精气满回归，\n神兵恰似从天降。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "665", "title": "清平乐·娇儿识画", "genre": "清平乐", "date": "2021.04.08", "body": "有模有样，\n书本身前放。\n仨月小儿昂首望，\n双目凝神半晌。\n图文好似心明，\n不时娇态欢萌。\n如此这般长久，\n何须父母多情。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "666", "title": "万里春·芳园", "genre": "万里春", "date": "2021.04.09", "body": "桃红柳翠，\n浸漫芳香滋味。\n草青青、碧水潺潺，\n鸟音枝上碎。\n嫩叶摇鲜蕊，\n入青眼、态娇容媚。\n且春光、细软无声，\n悄然心陶醉。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "667", "title": "七绝·春日闲吟", "genre": "七绝", "date": "2021.04.10", "body": "巧言域外月明圆，\n却是仇怀看眼前。\n日有阴晴天下事，\n劝君切记莫心偏。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "668", "title": "占春芳·假日游园", "genre": "占春芳", "date": "2021.04.11", "body": "纤柳翠，\n繁花艳，\n满眼尽春芳。\n碧水红桃相映，\n小园遍处飘香。\n惬意自徜徉。\n且凭栏、安享天光。\n听闻莺燕枝头啭，\n心绪飞扬。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "669", "title": "清平乐·赠学弟", "genre": "清平乐", "date": "2021.04.12", "body": "多年未见，\n怎肯金樽浅。\n昔日同窗情意远，\n晨练曦光浮现。\n高低相差一年，\n仿佛就在跟前。\n别后今朝握手，\n谁怜鬓发苍颜。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "670", "title": "五律·春晓", "genre": "五律", "date": "2021.04.13", "body": "光熠花枝碎，\n风轻景色明。\n万丝垂翠柳，\n一片晕红樱。\n晨练桃扇舞，\n闲聊笑语萦。\n莺飞云漫卷，\n遍处喜盈盈。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "671", "title": "太常引·春暖乡村", "genre": "太常引", "date": "2021.04.14", "body": "小村遍地起层楼，\n彩瓦卧檐头。\n宝马弄堂留。\n夜如昼，声光岂休。\n街平路阔，\n欢颜老少，\n自是远烦忧。\n昔往梦中求，\n到今日，家家不愁。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "672", "title": "七律·赠友", "genre": "七律", "date": "2021.04.15", "body": "心中营地胜江南，\n锦瑟年华映远山。\n稚脸戎装凝血气，\n深秋霞色舞云天。\n胸怀梦想书灯亮，\n脚踏风沙日月还。\n八载枕戈寒暑度，\n一川烟雨润心田。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "673", "title": "画堂春·敬二老", "genre": "画堂春", "date": "2021.04.16", "body": "耄耋携手度余生，\n银丝斑鬓多情。\n对方寒暖记怀中，\n日夜心同。\n一起浇花弄草，\n芳馨小院安宁。\n晓来无虑沐春风，\n日晚霞红。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "674", "title": "朝中措·闻讯惊叹", "genre": "朝中措", "date": "2021.04.17", "body": "春宵灯下酒微酲，\n独自对银屏。\n偶览环球时政，\n惊闻废水排空。\n茫茫大海，\n倭人核料，\n缓慢长行。\n此后海鲜渔货，\n任谁还敢多情。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "675", "title": "七绝·无垠", "genre": "七绝", "date": "2021.04.18", "body": "路到远方天为界，\n茫茫人海漫无疆。\n尘心寥廓乾坤大，\n坦荡胸怀日月藏。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "676", "title": "太常引·夜练有感", "genre": "太常引", "date": "2021.04.19", "body": "春宵夜色映红灯，\n月下踏街行。\n迎面树含情。\n气清爽，心神自明。\n寻常健体，\n长年不断，\n迈步越来轻。\n若为老安宁，\n勤动腿，风霜莫停。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "677", "title": "踏莎行·车祸甚虎", "genre": "踏莎行", "date": "2021.04.20", "body": "滚滚车流，\n茫茫尘世。\n瞬间多少魂飞逝。\n铁轮不驻向前奔，\n千家万户伤元气。\n子痛妻悲，\n哭天恸地。\n苍颜父老心无寄。\n人生有梦莫慌忙，\n出行且把平安记。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "678", "title": "踏莎行·踏青", "genre": "踏莎行", "date": "2021.04.21", "body": "迷恋春光，\n钟情碧水。\n桃蹊柳陌莺声碎。\n蝶飞蜂舞映长空，\n绿茵锦绣花枝坠。\n倚望云天，\n寻游花蕊。\n风烟袅袅芳香味。\n纸鸢鹰燕尽情欢，\n舟行鱼跃人陶醉。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "679", "title": "太常引·遇事有感", "genre": "太常引", "date": "2021.04.22", "body": "乱忙两日晚回京，\n心血竟无成。\n对面欠真诚。\n几来往，\n功前变生。\n黯然感慨，\n几多无奈，\n何处诉衷情。\n昂首唤苍穹，\n人守信，\n尘间纵横。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "680", "title": "山花子·进京路上", "genre": "山花子", "date": "2021.04.23", "body": "漫野青葱映远空，\n群楼遥望瓦当红。\n劳者田间同奋力，\n笑声浓。\n四季勤耕黄土地，\n长年少语亦英雄。\n盛世今朝人可敬，\n且从容。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "681", "title": "清平乐·又见乖宝", "genre": "清平乐", "date": "2021.04.24", "body": "别离一月，\n相见心神怯。\n昂首凝眸思绪烈，\n转瞬欢颜亲切。\n翻身轻似翻书，\n笑声朗朗观图。\n最是表情乖巧，\n逗爷烦恼皆无。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "682", "title": "寻芳草·春日晓吟", "genre": "寻芳草", "date": "2021.04.25", "body": "草树雨来翠，\n更花朵、满枝摇缀。\n水清清，\n潋滟波影碎。\n引莺鸣，使人醉。\n意绪漫长空，\n半生过，\n往来无悔。\n日无忧，\n夜夜平安睡。\n今且乐，看孙辈。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "683", "title": "太常引·看邻国", "genre": "太常引", "date": "2021.04.26", "body": "阿三自大疫难消，\n近日创新高。\n老少苦难熬。\n更闻道、焚炉罢烧。\n防方缺氧，\n病人无奈。\n求美却期遥。\n惟盼望明朝，\n新德里、天晴日骄。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "684", "title": "唐多令·人生悟", "genre": "唐多令", "date": "2021.04.27", "body": "赤手落尘间，\n往来三万天。\n为浮名，恐后争前。\n到了都随风火去，\n任富贵，尽云烟。\n悟透且心安，\n善行从己边。\n少积多，日日年年。\n梦里不惊神鬼事，\n凭昼夜，不孤单。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "685", "title": "清平乐·碧水春岸", "genre": "清平乐", "date": "2021.04.28", "body": "清河芳径，\n春色晨晖盛。\n花草葳蕤莺雀兴，\n翠叶欢声相竞。\n无忧老少闲行，\n心忙青壮粗声。\n尘世多姿多彩，\n且安苦乐人生。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "686", "title": "七律·和潇湘月夜", "genre": "七律", "date": "2021.04.29", "body": "闲来独坐紫云轩，\n今古寻思三五番。\n俗世人生谁不老，\n凡间春暮岂能援。\n且凭泼墨挥毫手，\n散尽烟尘愤恨冤。\n块垒磨平堪慰笑，\n犹如羁客越篱樊。\n附潇湘月夜原玉：\n题紫云轩\n春风不度紫云轩，\n暗洒相思泪几番。\n玄鬓影孤愁易老，\n美人觚破力难援。\n长嗟千载丹青手，\n自洗三生不白冤。\n困在此中君莫笑，\n终能解脱出尘樊。", "image_files": ["01.jpg"]}, {"poem_id": "687", "title": "采桑子·梦天行", "genre": "采桑子", "date": "2021.04.30", "body": "文昌箭射天和跃，\n云破星惊，\n霄汉宫成。\n携手牵牛织女行。\n生来傲作神州客，\n碧海峥嵘，\n无限深情。\n俯瞰山河景色明。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "688", "title": "蝶恋花·致敬劳动者", "genre": "蝶恋花", "date": "2021.05.01", "body": "铺瓦添砖华夏富，\n节日无闲，\n奋斗难停步。\n汗水浸洇身下路，\n春秋寒暑风霜度。\n遍地英雄今瞩目，\n挂彩披红，\n名响千家户。\n且记寻常辛与苦，\n真情奉献无穷数。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "689", "title": "临江仙·五一乐", "genre": "临江仙", "date": "2021.05.02", "body": "节日出行诚可爱，\n盛妆乖宝招人。\n春风满面见相亲。\n每逢双笑靥，\n两眼映香魂。\n玩具可心双手握，\n明眸朱口童真。\n音容灿烂气芳芬。\n娇姿无限俏，\n稚脸意欣欣。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "690", "title": "鹧鸪天·舍得", "genre": "鹧鸪天", "date": "2021.05.03", "body": "望子成龙父母忧，\n一心择校几多愁。\n东西海淀千番看，\n尖校名师万众谋。\n南家问，北邻求，\n钱银不够友朋筹。\n稚童欢喜书堂去，\n爷奶余生作马牛。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "691", "title": "七绝·五四感怀", "genre": "七绝", "date": "2021.05.04", "body": "老来不似想当年，\n力弱情衰意渐残。\n偶有梦中心绪涨，\n登高越上又争前。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "692", "title": "七绝·立夏有感", "genre": "七绝", "date": "2021.05.05", "body": "凌空风絮送春归，\n临夏无云日却微。\n比似寻常寒色久，\n天公任性老人悲。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "693", "title": "安平乐慢·回望感怀", "genre": "安平乐慢", "date": "2021.05.06", "body": "节日神州，燕莺奋翼，游人塞北江西。\n长城远眺，碧海欣行，柔风霞色晨曦。\n绿水青山，鸟花争鸣放，遍处生机。\n正翠柳垂丝，释情怀、拈韵成诗。\n望寰宇风寒，雾缭烟乱，来往翻复迷离。\n美俄频相斗，个中情，谁又能知。\n域外新冠，灭又起，民哀鸟啼。\n众尸横，万千泪泣，惺惺唇齿相依。", "image_files": ["01.jpg"]}, {"poem_id": "694", "title": "点绛唇·初夏暮吟", "genre": "点绛唇", "date": "2021.05.07", "body": "乍起风沙，\n黄烟滚滚迷人眼。\n凌霄云乱，\n高柳丝翻卷。\n无奈天公，\n暗自空长叹。\n把金盏，\n酒香肠暖，\n醉不知深浅。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "695", "title": "踏莎行·贺外甥女订婚", "genre": "踏莎行", "date": "2021.05.08", "body": "情定终身，\n手牵一世。\n梦中秦晋良缘起。\n火红五月艳阳天，\n槐香莺啭云空丽。\n日月为媒，\n亲朋贺喜。\n东风款款深情寄。\n连枝比翼任翔飞，\n天长地久随心意。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "696", "title": "太常引·母恩浩荡", "genre": "太常引", "date": "2021.05.09", "body": "一生铭记母亲恩，\n万苦育儿身。\n尽孝莫辞辛。\n最当是，\n思行两真。\n时光难驻，\n亲颜将老，\n寒暖问宜频。\n床侧顾晨昏。\n才无愧，\n为人子孙。\n寄语\n为儿莫忘母恩，\n为夫莫忘妻亲。\n天下女人不易，\n惟期男子情真。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "697", "title": "七绝·闲暮吟", "genre": "七绝", "date": "2021.05.10", "body": "今朝放眼尘寰看，\n喜见九州花盛开。\n曾历百年羞辱恨，\n睡狮已醒又归来。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "698", "title": "朝中措·初夏吟", "genre": "朝中措", "date": "2021.05.11", "body": "芬芳五月艳阳天，\n云淡碧空妍。\n月季多情似火，\n妖娆无限牡丹。\n游人遍处，\n登山戏水，\n惬意流连。\n尽释忧怀愁绪，\n归来无虑无烦。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "699", "title": "七绝·扭转乾坤", "genre": "七绝", "date": "2021.05.12", "body": "一对山桃把手中，\n犹如日月宇寰行。\n腾挪翻转春秋过，\n无语乾坤却有情。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "700", "title": "踏莎行·夏日吟", "genre": "踏莎行", "date": "2021.05.13", "body": "晓雨如丝，\n晚晴若画。\n微风惊动葡萄架。\n星辉闪闪影重重，\n蟾光漫洒层楼下。\n柳叶藏莺，\n桐荫隔夏。\n凌空烈日浑无怕。\n花前午后品茶香，\n闲情畅意烦忧罢。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "701", "title": "七绝·初夏", "genre": "七绝", "date": "2021.05.14", "body": "碧水青蛙夜有声，\n绿槐高柳渐蛩鸣。\n风柔日暖娇荷睡，\n花影桐荫恁有情。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "702", "title": "菩萨蛮·天伦乐", "genre": "菩萨蛮", "date": "2021.05.15", "body": "娇娃翻转天将晓，\n惺忪睡眼闻声笑。\n浅靥自多情，\n明眸左右行。\n一天心态好，\n傍晚稍烦躁。\n爷奶爱萦身，\n怀中恁是亲。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "703", "title": "太常引·祝融问天", "genre": "太常引", "date": "2021.05.16", "body": "祝融轻落火星间，\n漫步舞蹁跹。\n惊起旧尘烟。\n九州客，真诚问天。\n生来几载，\n曾经往事，\n可否与人言？\n独自恁孤单，\n从今后，飞龙共欢。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "704", "title": "清平乐·买房有寄", "genre": "清平乐", "date": "2021.05.17", "body": "娇儿学位，\n父母心操碎。\n爷奶暗愁垂老泪，\n多少良宵无寐。\n全家左右求援，\n低眉欲语难言。\n真个人生如梦，\n谁知后世前缘。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "705", "title": "感恩多·荷塘夏日", "genre": "感恩多", "date": "2021.05.18", "body": "睡莲娇欲展，\n风起萍波远。\n翠莺穿柳烟，\n燕翔天。\n曲岸荷香气爽，\n醉心田，\n醉心田。\n草木欣欣，\n自情愉忘还。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "706", "title": "太常引·闲思", "genre": "太常引", "date": "2021.05.19", "body": "养儿防老古人心，\n此理与诸君，\n未必可成真。\n世间事，\n横生乱云。\n深情父母，\n娇生子女，\n不孝苦双亲。\n寄语鬓霜人，\n余生乐，\n还期自身。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "707", "title": "浪淘沙·520有寄", "genre": "浪淘沙", "date": "2021.05.20", "body": "情爱漫人间，\n春意绵绵。\n花红柳翠映长天。\n便是乌云雷阵阵，\n亦自安然。\n珍视个中缘，\n意满心田。\n同舟日月笑清寒。\n欣喜人生能巧遇，\n风雨同檐。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "708", "title": "浪淘沙·感吟", "genre": "浪淘沙", "date": "2021.05.21", "body": "走狗乱伤人，\n利令头昏。\n欺乡蔑祖毁龙根。\n一幅可怜摇尾相，\n狼狈为亲。\n华夏日趋新，\n江海逢春。\n川原锦绣映青云。\n偶有几声哀犬吠，\n难扰心神。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "709", "title": "鹧鸪天·乖孙出行", "genre": "鹧鸪天", "date": "2021.05.22", "body": "孙乘豪车爷伴行，\n桃蹊柳院绕芳亭。\n初来人处心神紧，\n片刻花丛手脚横。\n眸乱转，嗓无停，\n莺声童语四边萦。\n娇娃感受云天好，\n笑靥欢眉别样情。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "710", "title": "鹧鸪天·痛悼袁老", "genre": "鹧鸪天", "date": "2021.05.22", "body": "当代神农驾鹤归，\n惊闻噩耗痛心扉。\n有人从未谋君面，\n谁个能离稻米炊。\n真国士，万家悲，\n江河哭泣泪横飞。\n山原翻卷阴云雨，\n今日神州景式微。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "711", "title": "清平乐·送袁老", "genre": "清平乐", "date": "2021.05.23", "body": "为民谋事，\n山海风云记。\n悼念声惊天恸地，\n痛表深深敬意。\n田畴九秩人生，\n倾心稻米躬耕。\n换取香飘万户，\n无言岁月峥嵘 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "712", "title": "太常引·雨中情", "genre": "太常引", "date": "2021.05.24", "body": "长沙昨日雨含情，\n和泪送袁公。\n鸟雀默无声。\n菊花淡，随人缓行。\n连绵不断，\n时移午夜，\n灯火更通明。\n星月耀苍鹰。\n神农去，宛如永生。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "713", "title": "朝中措·越野之殇", "genre": "朝中措", "date": "2021.05.25", "body": "跑圈惊炸震天雷，\n九死一生悲。\n魂破白银山马，\n顶尖高手难归。\n极端天气，\n不曾相遇，\n雹雨横飞。\n挑战人生极限，\n万千准备别吹。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "714", "title": "生查子·晓闻", "genre": "生查子", "date": "2021.05.26", "body": "旭日溢霞辉，\n百啭流莺醉。\n细风拂柳丝，\n晓院飘青翠。\n早起纳纷芳，\n晨练成双对。\n无语却和谐，\n飞眉自心会。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "715", "title": "浪淘沙·奇观", "genre": "浪淘沙", "date": "2021.05.27", "body": "苍狗咬红蟾，\n奇景悬天。\n月当十五却无圆\n玉帝有心难作为，\n千古犹然。\n诸事到人间，\n总想周全。\n奈何万物自牵连。\n且把杞人心放好，\n免去忧烦。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "716", "title": "破阵子·赠财郎兄弟", "genre": "破阵子", "date": "2021.05.28", "body": "蒙面遮头墨镜，\n轻妆上下提神。\n万里骑行山海客，\n正气盈身豪爽人。\n相逢分外亲。\n酷暑寒冬无惧，\n风霜雨雪飞奔。\n一路赏观山水美，\n阡陌芳香笑语频。\n人生总是春。\n七绝        单车乐\n一人潇洒踏车行，\n似马奔驰啸远空。\n烦恼随风千里去，\n迎星笑月自轻松。", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "717", "title": "感恩多·喜与叹", "genre": "感恩多", "date": "2021.05.29", "body": "校区今已占，\n先解心头念。\n六年寒暑天，\n可安眠？\n半岁娇娃不盈月，\n令人怜，\n令人怜。\n梦里无忧，\n却书山在前。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "718", "title": "踏莎行·舟行霄汉", "genre": "踏莎行", "date": "2021.05.30", "body": "二号天舟，\n一支神箭。\n瞬间飞向云空远。\n核心仓处喜相逢，\n九霄营造神州苑。\n泪洒当年，\n心生宏愿。\n太空深处凝眸干。\n如今仙女舞娇姿，\n轻盈身段惊霄汉。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "719", "title": "蝶恋花·阖家欢", "genre": "蝶恋花", "date": "2021.05.31", "body": "暇日帝京郊野去，\n水岸芬芳，\n林下闻莺语。\n满目青葱花几许，\n游人乐逗乖孙女。\n笑靥明眸眉首举，\n时望云空，\n欢意千千缕。\n父母轻松无所虑，\n得闲爷奶舒心绪。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "720", "title": "一七令·儿童节有寄", "genre": "一七令", "date": "2021.06.01", "body": "欢。\n节日，芳天。\n童稚乐，竞林园。\n挥剑骑马，戏鱼乘船。\n亮眸频闪动，微靥映心田。\n神悦鸟鸣水岸，意飞红杏山前。\n沐清风父母陶醉，望子孙爷奶泪甘。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "721", "title": "七律·童欢无限", "genre": "七律", "date": "2021.06.02", "body": "而今童稚乐无忧，\n玩具成堆岂用求。\n纸笔行描心里梦，\n胶泥塑造手中牛。\n水光池内金鱼钓，\n日月湖边荡小舟。\n娇嫩脸庞常带笑，\n挥金如土度春秋。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg", "04.jpg"]}, {"poem_id": "722", "title": "踏莎行·寰宇风云", "genre": "踏莎行", "date": "2021.06.03", "body": "尘世流氓，\n丛林虎豹。\n随心作歹山湖闹。\n绵羊群里恁疯狂，\n猎人枪下徒悲叫。\n擦亮睛眸，\n巧藏枪炮。\n命门瞄准时机妙。\n一声惊响破长空，\n芸芸弱者谁无笑。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "723", "title": "一七令·童心未泯", "genre": "一七令", "date": "2021.06.04", "body": "人，\n莫忘，童真。\n霜染鬓，少年心。\n花底观鸟，树丛隐身。\n望云空紫燕，寻翠苑芳茵。\n临柳岸欢戏水，踏单车笑山村。\n世间烦恼任他去，遇事无争万里春。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "724", "title": "浪淘沙·芒种寄怀", "genre": "浪淘沙", "date": "2021.06.05", "body": "南北欲开镰，\n麦浪滔天。\n金黄硕果促丰年。\n越过秋冬春夏盛，\n能不心欢。\n珍爱碗中餐，\n粒粒难圆。\n农人辛苦且依天。\n地里谋生恁大事，\n亘古延绵。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "725", "title": "七绝·苏诗读感", "genre": "七绝", "date": "2021.06.06", "body": "三餐一日似从前，\n同样杯盘味百千。\n缘自人生风雨过，\n曾经霜露落心田。\n附苏轼：\n庐山烟雨浙江潮，\n未到千般恨不消。\n到得还来别无事，\n庐山烟雨浙江潮。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "726", "title": "鹧鸪天·寄语高考", "genre": "鹧鸪天", "date": "2021.06.07", "body": "学子莘莘争过桥，\n神州遍地热情高。\n乡邻关注寻常问，\n父母心期昼夜熬。\n连两日，使千招，\n胸中彩墨任挥毫。\n来时金榜题名处，\n起凤腾龙入九霄。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "727", "title": "朝中措·鸿蒙", "genre": "朝中措", "date": "2021.06.08", "body": "横空出世破天荒，\n贼子暗抓狂。\n打破独家垄断，\n国人眉眼飞扬。\n从今网络，\n通联情物，\n渐渐更张。\n幸有华为执剑，\n屏行免受妖伤。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "728", "title": "渔家傲·初夏晓吟", "genre": "渔家傲", "date": "2021.06.09", "body": "夜雨霁晴连数日，\n夏庭幽静晨风细。\n翠柳欢摇浮快意，\n云旖旎，\n虫鸣鸟哢清音起。\n又是一年风爽季，\n舒心凉热和天地。\n远近出行山水丽，\n抒长气，\n醉人景色堪迢递。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "729", "title": "浣溪沙·稚儿趣", "genre": "浣溪沙", "date": "2021.06.10", "body": "楼院黄昏聚幼童，\n胖丫豌豆小橙橙。\n若煊相遇眼神萌。\n车上无言招手笑，\n花前欲语字难清。\n娇音香径晚风轻。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "730", "title": "一七令·期待", "genre": "一七令", "date": "2021.06.11", "body": "强。\n箭起，眉扬。\n云海翥，九天翔。\n辉映寰宇，响彻四方。\n揽星辰日月，得雨露霞光。\n千古梦今日景，会嫦娥桂花香。\n喜神龙劲舞霄汉，情注天宫久久长。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "731", "title": "清平乐·芍药花", "genre": "清平乐", "date": "2021.06.12", "body": "人称花相，\n艳丽朱栏上。\n春暮薰风才绽放，\n入夏色香争旺。\n声名遍布城乡。\n山前水畔芬芳。\n不似牡丹骄贵，\n赏期却比她长。\n鹧鸪天    芍药花\n水畔山前灿烂开，\n蜂游蝶舞踏云来。\n清泉有意增姿色，\n冷露多情落粉怀。\n寻野径，入瑶台。\n芳香袅袅任风裁。\n紫红苑里称花相，\n堪比牡丹何用猜。", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "732", "title": "江城子·花妍城丽", "genre": "江城子", "date": "2021.06.13", "body": "一池芍药映城台，\n盼花开，赏花来。\n远近乡朋，\n暇日喜盈怀。\n色晕妖娆佳丽笑，\n蜂蝶舞，戏香钗。\n芬芳朵朵少尘埃，\n引童孩，染红腮。\n稚嫩娇音，\n穿柳透青槐。\n啭鸟枝头浑欲醉，\n清响远，任风裁。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "733", "title": "七律·端午祭", "genre": "七律", "date": "2021.06.14", "body": "离骚千古溢芬芳，\n苦闷情深韵味长。\n天问九章求索道，\n国殇一阙魄魂飏。\n秉书明志遭人害，\n抱恨投江楚自伤。\n屈子沉冤惊日月，\n汨罗逝水粽花香。\n七绝        端午吟\n又临端午粽飘香，\n五色丝绳情意长。\n棹促龙舟灵均祭，\n神州遍咏楚辞章。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "734", "title": "七绝·兰亭闲吟", "genre": "七绝", "date": "2021.06.15", "body": "兰亭集默序名扬，\n诗赋寻常字闪光。\n醉里挥毫神韵远，\n人前一霎墨池苍。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "735", "title": "七律·时闻有感", "genre": "七律", "date": "2021.06.16", "body": "宋家徒子乱清辉，\n别有情怀戾气微。\n讥骂鸿蒙行蠢事，\n狂喷国货露心扉。\n谎称学者遭人笑，\n却是庸才使众非。\n不当之言羞自取，\n劝君且莫与天违。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "736", "title": "点绛唇·短暂交锋", "genre": "点绛唇", "date": "2021.06.17", "body": "普拜相逢，\n青蜓点水挥挥手。\n各怀九九，\n敌视难开口。\n瑞士风光，\n看罢分头走。\n轻回首，\n世间依旧，\n暗里频相斗。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "737", "title": "清平乐·圆梦", "genre": "清平乐", "date": "2021.06.18", "body": "神舟又起，\n长驻天宫里。\n寂寞嫦娥歌舞丽，\n织女牵牛欢涕。\n星河欲转蹁跹，\n欢腾华夏山川。\n天地飞龙往复，\n今朝圆梦千年。\n太常引 天上人间\n炎黄赤子入天宫，\n玉帝满怀情，\n星月喜相迎。\n俱回首，\n神州夜明。\n山河劲舞，\n川原锦绣，\n遍处鸟欢鸣。\n万里视频通，\n诚可爱，\n英雄笑容。", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "738", "title": "五律·晓院", "genre": "五律", "date": "2021.06.19", "body": "雨霁晴空丽，\n清晨柳色新。\n白云舒笑脸，\n翠鸟舞芳茵。\n小狗闲人遛，\n家童老者亲。\n相安悠自乐，\n如画染心神。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "739", "title": "朝中措·老父亲", "genre": "朝中措", "date": "2021.06.20", "body": "稀疏银发耳偏聋，\n人善嗓门洪。\n个矮身勤手巧，\n满腔质朴情浓。\n乡村闲事，\n辛劳不计，\n意气重重。\n看似心怀未老，\n镜前已是苍翁。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "740", "title": "踏莎行·百善孝先", "genre": "踏莎行", "date": "2021.06.20", "body": "父爱如山，\n母恩似水。\n亲情浩荡儿陶醉。\n人生弹指鬓如霜，\n呀呀童稚银丝缀。\n更念娘亲，\n更知爹累。\n养家不易心生愧。\n百忙岂忘孝当先，\n得闲二老床头睡。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "741", "title": "八声甘州·冬至宝宝夏至欢", "genre": "八声甘州", "date": "2021.06.21", "body": "……寄语若煊半周岁\n看娇孙粉脸映浓眉，明眸透天真。\n手纤纤空舞，不时飞向、秀口朱唇。\n爬滚翻仰头坐，扭动小腰身。\n最是招人处，浅靥轻颦。\n笑似春风化雨，顷刻间奶奶、颠倒心神。\n喜轻声软语，长是醉爷魂。\n与乖娃，烦忧俱散；苦自消，夏至亦如春。\n欢难寐，夜深人静，梦里犹亲。", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "742", "title": "七绝·夏夜思", "genre": "七绝", "date": "2021.06.22", "body": "夜短昼长邻夏至，\n蝉声高远热难消。\n荷花莲叶清香溢，\n细柳蟾光意绪摇。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "743", "title": "蝶恋花·报志愿", "genre": "蝶恋花", "date": "2021.06.23", "body": "学子觅桥寻左右，\n途远坑多，\n谨慎思前后。\n一旦行偏难转首，\n书山陡峭凝神走。\n尘世浮生多路口，\n惟有今番，\n此去悠长久。\n且愿诸君携挚友，\n畅游学海千帆秀。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "744", "title": "踏莎行·祖孙回家", "genre": "踏莎行", "date": "2021.06.24", "body": "三代离京，\n一行南下。\n寻根问祖情牵挂。\n纤纤细雨软风随，\n心怀愉悦消长夏。\n家在石门，\n娃来感化。\n温馨洞户红楼瓦。\n花香鸟语境堪幽，\n颜欢手舞开心耍。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "745", "title": "菩萨蛮·望榜兴叹", "genre": "菩萨蛮", "date": "2021.06.25", "body": "一分改变人生路，\n早知今日何辞苦。\n年少度寒窗，\n本该灯下忙。\n奈何心向外，\n书卷香无爱。\n眼看各东西，\n心中惆怅思。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "746", "title": "鹧鸪天·石门有感", "genre": "鹧鸪天", "date": "2021.06.26", "body": "庄里归来景貌新，\n街头商店喜盈门。\n支农路面刚铺就，\n两侧青砖无破痕。\n家照旧，却添人。\n初来便乐小娇孙。\n东瞧西看腰身扭，\n地上翻爬稚语频。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "747", "title": "临江仙·夏夜小聚", "genre": "临江仙", "date": "2021.06.27", "body": "热浪滔天千里外，\n清凉袅袅楼中。\n乡朋约聚豆捞宫。\n年来都未见，\n闻讯喜相逢。\n乖宝席间频对笑，\n腰身眉眼灵聪。\n金尊玉液更情浓。\n人生一代代，\n日子火红红。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "748", "title": "踏莎行·欢聚故里", "genre": "踏莎行", "date": "2021.06.28", "body": "四世同堂，\n一桌欢宴。\n娇娃曾祖初相见。\n只缘血脉有传承，\n乍逢熟似寻常面。\n笑靥轻盈，\n细眉舒展。\n稚音嫩脸和亲愿。\n阖家老少恁多人，\n门厅前后争相看。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "749", "title": "减字木兰花·百年党颂", "genre": "减字木兰花", "date": "2021.06.29", "body": "初心不改，\n奋斗百年朝气在。\n血脉传承，\n动地惊天山水明。\n红旗招展，\n四海五湖风色远。\n带路飞虹，\n小小寰球舞赤龙。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "750", "title": "清平乐·高歌颂党", "genre": "清平乐", "date": "2021.06.30", "body": "百年华诞，\n举世神州看。\n立党为民天地远，\n万里风高云璨。\n城乡鸟啭民康，\n国人平视八方。\n将士伏山跃海，\n巨龙霄汉翱翔。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "751", "title": "沁园春·百年风华", "genre": "沁园春", "date": "2021.07.01", "body": "湖上红船，辉映八方，旗舞锤镰。望十三赤子，满腔热血。百年岁月，星火燎原。万里长征，合歼日寇，蒋匪烟消换地天。凭豪气，抗美援朝胜，赢取边安。\n春风化雨轩辕，携众手，神州奋向前。看创新开放，巨龙腾起。脱贫致富，华夏翩跹。带路连通，亚欧一体，世纪辉煌已必然。今昂首，跨五湖四海，跃马山川。", "image_files": ["01.jpg"]}, {"poem_id": "752", "title": "采桑子·七一", "genre": "采桑子", "date": "2021.07.02", "body": "百年华诞城楼丽。\n天上银鹰，\n地上欢声。\n漫卷红旗赤子情。\n宏音沉稳千均重。\n告慰英灵，\n擘画今生。\n华夏腾飞万里鹏。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "753", "title": "采桑子·认祖归来", "genre": "采桑子", "date": "2021.07.03", "body": "匆匆来去行京冀。\n故里八天，\n乖宝悠然。\n短暂时光尽是欢。\n亲朋相见由衷笑。\n虽不能言，\n到处翩跹。\n无虑童真韵态妍。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "754", "title": "七律·七一抒怀", "genre": "七律", "date": "2021.07.04", "body": "…敬父亲在党50年\n一门四代党徽红，\n尚有三人志向明。\n逝者毕生无己欲，\n祖孙今岁袖风清。\n分居南北齐心力，\n俱为城乡景色荣。\n华诞百年同奋悦，\n胸怀激荡九州情。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "755", "title": "蝶恋花·夏日晓吟", "genre": "蝶恋花", "date": "2021.07.05", "body": "室内闷潮楼外爽，\n仲夏清晨，\n云淡霞光放。\n莺燕梢头流脆响，\n闲行庭院心欢畅。\n一处久居愁绪广，\n且向周边，\n寻水依山傍。\n亲近自然情意荡，\n忧烦不见人无恙 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "756", "title": "五律·傍晚", "genre": "五律", "date": "2021.07.06", "body": "乖宝刚安睡，\n得闲楼院行。\n辉消缘日隐，\n暑退赖风清。\n倦鸟归高树，\n鼓蛙池上鸣。\n玩童灯下闹，\n嘻笑伴蝉声。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "757", "title": "踏莎行·时闻有感", "genre": "踏莎行", "date": "2021.07.07", "body": "利欲头昏，\n私心脑胀。\n挥拳踢脚频相向。\n可怜院士弱腰身，\n却存风骨人难忘。\n媒体追寻，\n警方跟上。\n恶人监所蹲凉炕。\n此番事件再昭人，\n当今处世休狂妄。\n七绝    时闻有感\n满口恶言拳脚向，\n私心膨胀太猖狂。\n若非舆论铺天报，\n冠下伪君多久藏？", "image_files": ["01.jpg"]}, {"poem_id": "758", "title": "太常引·七七有寄", "genre": "太常引", "date": "2021.07.07", "body": "防空警报刺云天，\n激起恨无边。\n倭寇至今年，\n未思过，\n时而妄言。\n协防台海，\n掺和印太，\n恶意自昭然。\n吾辈攥双拳，\n剑挥扫，\n东瀛弹丸。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "759", "title": "诉衷情·为人民", "genre": "诉衷情", "date": "2021.07.08", "body": "寰球政党聚云端，\n伟业共翩跹。\n倾情亿万民众，\n谋远利当前。\n同命运，\n克时艰，\n惠千年。\n志当携手，\n合力通赢，\n丽景无边。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "760", "title": "清平乐·敬航天员", "genre": "清平乐", "date": "2021.07.09", "body": "云空漫步，\n万里飘然舞。\n兄弟无间潇洒度，\n闲看吴刚伐树。\n天和矫健身姿，\n翩跹长臂如期。\n霄汉随心翻转，\n追星捧月凭思。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "761", "title": "七绝·看图有感", "genre": "七绝", "date": "2021.07.10", "body": "一.\n弥天大谎漫人间，\n无奈平民最可怜。\n一仗死伤千百万，\n何时能够怨魂安。\n二.\n狼狈相欢祸世间，\n不知何处又遭难。\n猎枪紧握终毋懈，\n瞄准心门一二三。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "762", "title": "朝中措·入伏吟", "genre": "朝中措", "date": "2021.07.11", "body": "伏天前夜雨敲窗，\n拂晓感轻凉。\n昨日闷潮消却，\n今朝心绪飞扬。\n穿行庭院，\n鸣蝉噪柳，\n啭鸟云翔。\n期盼清阴夏日，\n微风飒爽悠长。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "763", "title": "七绝·娇孙贺喜", "genre": "七绝", "date": "2021.07.12", "body": "醒来车上向东行，\n太姥家中喜气盈。\n二老钻婚南北聚，\n子孙满地寄深情。\n踏莎行 贺岳父母钻婚\n耋耄之年，\n钻婚之喜。\n枝盈叶茂花妍丽。\n耕耘六秩果繁多，\n甘甜可口香不腻。\n两鬓丝飞，\n一怀情寄。\n凝神四代群星起。\n行居京冀总齐心，\n尊崇二老由衷意。", "image_files": ["01.jpg", "02.jpg", "03.jpg", "04.jpg"]}, {"poem_id": "764", "title": "七绝·闻讯闲吟", "genre": "七绝", "date": "2021.07.13", "body": "善恶于天终有报，\n妄言岂可变成真。\n平生莫作违心事，\n留取福荫为子孙。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "765", "title": "太常引·初伏吟", "genre": "太常引", "date": "2021.07.14", "body": "伏来连日雨飘摇，\n京洛水滔滔，\n波漾广渠桥。\n路难过，\n人车避逃。\n风云漫卷，\n枝梢零落，\n鸟雀远危巢。\n闷热未曾消，\n雨声住，\n汗流似浇。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "766", "title": "朝中措·爷孙同乐", "genre": "朝中措", "date": "2021.07.15", "body": "娇娃半岁荡秋千，\n怀里望云天。\n手舞眉开眼笑，\n神欢心悦流连。\n今朝童稚，\n身骄体健，\n远胜从前。\n黑发红颜飞韵，\n聪声慧语多妍。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "767", "title": "太常引·帝国之殇", "genre": "太常引", "date": "2021.07.16", "body": "当年冒进气高扬，\n今日脸灰黄，\n折将损兵忙。\n奈回撤，\n宵行昼藏。\n若知有此，\n当初何必，\n独霸藐穹苍。\n一任己张狂，\n可曾想，\n将来灭亡？ ​​​", "image_files": ["01.jpg"]}, {"poem_id": "768", "title": "满庭芳·乖孙夏日", "genre": "满庭芳", "date": "2021.07.17", "body": "云淡风清，芳庭翠院，稚童三五相逢。\n点头挥手，尽笑脸盈盈。\n环看枝飞叶舞，听啭鸟、流响西东。\n林荫道，童车来去，碾树影重重。\n时光轻逝去，午前人奋，饭后神宁。\n待醒来，儿歌音乐欢鸣。\n玩具随心戏耍，无忧虑、爷奶怀中。\n斜阳落，娇身沐浴，香气漫帘栊。", "image_files": ["01.jpg"]}, {"poem_id": "769", "title": "五绝·寄怀", "genre": "五绝", "date": "2021.07.18", "body": "眼前童稚乐，\n故里老人悲，\n谁有双全策，\n于心两不违。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "770", "title": "踏莎行·利剑出鞘", "genre": "踏莎行", "date": "2021.07.19", "body": "亚轨飞行，\n群情振奋。\n云空万里星光衬。\n神州大地遍生辉，\n此情最解心头恨。\n贼寇挥矛，\n良人擎盾。\n东西对垒风云震。\n多年积怨待平舒，\n辱仇必报凭锋刃。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "771", "title": "卜算子·夏日吟", "genre": "卜算子", "date": "2021.07.20", "body": "闷热易伤身，\n咳嗽随风到。\n只为当时扇底凉，\n清涕胸前闹。\n鼻塞脸通红，\n转眼高烧了。\n难作尘间钢铁侠，\n一路前奔啸。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "772", "title": "七律·敬妻生日", "genre": "七律", "date": "2021.07.21", "body": "牛年过半滞京华，\n梦里常回自己家。\n花甲弱身忙内外，\n伤残细手为吾他。\n子孙身上倾心血，\n父母床头少果茶。\n每日厨房灯火晚，\n何时芳院享闲暇？ ​​​", "image_files": ["01.jpg"]}, {"poem_id": "773", "title": "破阵子·雨后感怀", "genre": "破阵子", "date": "2021.07.22", "body": "暴雨洪灾肆虐，\n可怜无奈苍生。\n谁料途遭生死难，\n更痛别来无影形。\n车桥如絮萍。\n惊看江河决口，\n又闻英武官兵。\n四面八方伸暖手，\n汇聚神州万里情。\n中原天霁明。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "774", "title": "浪淘沙·雨后有寄", "genre": "浪淘沙", "date": "2021.07.23", "body": "暴雨虐中原，\n百态人间。\n逆行涉水手相牵。\n赠物捐钱修洞路，\n情寄灾前。\n喜见善良言，\n刺耳闻欢。\n无聊谩骂惹人烦。\n险害当头齐奋力，\n大难同担。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "775", "title": "五律·吟伏天", "genre": "五律", "date": "2021.07.24", "body": "大暑却风凉，\n浑身汗扫光，\n行人开笑脸，\n飞鸟脆音扬。\n柳乐云空舞，\n鱼欢闹水塘。\n凭栏观落日，\n总道异平常。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "776", "title": "七律·东京奥运", "genre": "七律", "date": "2021.07.25", "body": "丑闻不断幕难开，\n延至今朝客未来。\n纸板当床遭诟病，\n核材烧饭被疑猜。\n气氛萧瑟辉光暗，\n景物凄清冷看台。\n原本借机耍花样，\n新冠无奈只悲哀。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "777", "title": "七律·赠神州健儿", "genre": "七律", "date": "2021.07.26", "body": "首金射落气冲霄，\n惊艳东瀛华夏骄。\n学子谦谦盈笑靥，\n国人奋奋热情高。\n歌声飞荡银空震，\n旗帜飘扬卷赤涛。\n险恶风云浑不惧，\n神州威武看今朝。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "778", "title": "菩萨蛮·曲终峰现", "genre": "菩萨蛮", "date": "2021.07.27", "body": "世间一曲天津散，\n谢锋强硬刚舒曼。\n心意不真诚，\n只和虚此行。\n不知当有愧，\n别却多回味。\n宇宙九重天，\n鲲鹏任翥旋。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "779", "title": "一剪梅·夏日暮歌", "genre": "一剪梅", "date": "2021.07.28", "body": "童稚黄昏聚院庭，\n各色儿车，\n老少同行。\n滑梯上下态憨萌，\n踏板穿梭，\n彩泡飞萦。\n倦鸟闻观亦动情，\n抖翅高翔，\n盘绕争鸣。\n斜晖暮色乐融融，\n纸扇风凉，\n阵阵欢声。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "780", "title": "朝中措·看西方", "genre": "朝中措", "date": "2021.07.29", "body": "无聊政客是非多，\n梦里也胡说。\n埋怨天公下雨，\n指摘春水秋波。\n一身狗屎，\n惯闻其味，\n到处撒泼。\n妻妾家中肚胀，\n赖人替己背锅。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "781", "title": "山花子·离京寄怀", "genre": "山花子", "date": "2021.07.30", "body": "别却娇娃忍泪行，\n廉州二老亦牵情。\n此去家山消父病，\n盼安平。\n来往城乡愁聚散，\n怀思老少绪疏盈。\n恨是两全无好策，\n梦难宁。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "782", "title": "蝶恋花·夏日闲吟", "genre": "蝶恋花", "date": "2021.07.31", "body": "旧友新朋前夜聚，\n畅诉心言，\n把酒千欢绪。\n且看白啤浑不拒，\n红虾紫蟹无人举。\n两盏三杯难尽趣，\n昂首扬眉，\n一口吹瓶去。\n醉望天河星共语，\n宵深人静寻诗句。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "783", "title": "破阵子·八一寄怀", "genre": "破阵子", "date": "2021.08.01", "body": "凭仗三军固本，\n频添剑盾提神。\n将士赤心明壮志，\n瀚海长空日夜巡。\n川原疆界亲。\n天际风烟动荡，\n地阶贼寇纷纭。\n西北东南闻鬼闹，\n且看钟馗锁魅魂。\n神州春复春。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "784", "title": "七绝·赞巩立姣", "genre": "七绝", "date": "2021.08.02", "body": "震天怒吼转乾坤，\n惊落铅球第一金。\n廿载未移娇女志，\n争光华夏有恒心。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "785", "title": "烛影摇红·赞举重健儿", "genre": "烛影摇红", "date": "2021.08.03", "body": "举铁抓金，\n气冲霄汉频称冠。\n更红旗漫卷飞扬，\n内外皆惊叹。\n平日俯身流汗，\n换今朝、亿人慨赞。\n骄容可爱，赤子红心，\n如珠璀璨。\n举重队获七金一银 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "786", "title": "行香子·中伏午吟", "genre": "行香子", "date": "2021.08.04", "body": "噪起蝉蛩，光炙梧桐。\n恰云天闷热潮浓。\n无风叶静，雾气濛濛。\n看车儿停，鸟儿卧，树儿弓。\n午休难睡，浑身汗浸。\n似这般人在蒸笼。\n躺平难奈，坐立难从。\n盼阵儿雷，阵儿雨，阵儿风。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "787", "title": "踏莎行·见闻有思", "genre": "踏莎行", "date": "2021.08.05", "body": "所谓明星，\n堪称恶棍。\n光鲜龌龊阴阳混。\n贪金好色醉青烟，\n沾花惹草招人恨。\n官府擒凶，\n民间泄愤。\n道长揭短随公论。\n掀开黑伞莫稀松，\n扭风正气人心顺。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "788", "title": "眼儿媚·少女非凡", "genre": "眼儿媚", "date": "2021.08.06", "body": "平台起跳众人惊，\n一跃水花轻。\n胜情锁定，眼神飞彩，\n稚态呆萌。\n少年坚毅心怀梦，\n嫩脸踏征程。\n东京奥运，非凡佳绩，\n举世闻名。\n注：中国代表队最小\n的运动员，十四岁全\n红婵10米跳水，数次\n满分，一骑绝尘，轻\n松夺冠。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "789", "title": "七绝·立秋吟", "genre": "七绝", "date": "2021.08.07", "body": "心期天际起清风，\n溽暑行消暮色明。\n飒爽银空星闪烁，\n梧桐叶上泛秋声。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "790", "title": "满江红·赠华夏奥运健儿", "genre": "满江红", "date": "2021.08.08", "body": "鏖战东京，风头盛，举枪金落。\n喜新人，锦华正茂，搏身求索。\n奥运争光心底快，\n家乡父老同天乐。\n赞老将，矍铄屡传奇，惊魂魄。\n凭实力，频收获。神州势，今非昨。\n似钢铁军团，虎奔龙跃。\n拔寨攻城长志气，曾经弱项添花萼。\n占鳌头，赤子映红旗，星光烁。", "image_files": ["01.jpg", "02.jpg", "03.jpg", "04.jpg", "05.jpg", "06.jpg", "07.jpg", "08.jpg", "09.jpg"]}, {"poem_id": "791", "title": "七绝·初秋闲吟", "genre": "七绝", "date": "2021.08.09", "body": "西风携雨过南楼，\n带走伏天潮闷愁。\n枝上蝉蛩欢咏唱，\n门前流水自无忧。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "792", "title": "烛影摇红·美轮美奂", "genre": "烛影摇红", "date": "2021.08.10", "body": "落日余晖，\n晚霞飞度彤如画。\n伫阶遥望满怀情，\n回味消长夏。\n奥运东京酷耍，\n众健儿，金银各挂。\n女童添乐，\n学子称奇，\n传为佳话。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "793", "title": "蝶恋花·爷孙连线", "genre": "蝶恋花", "date": "2021.08.11", "body": "数日别离屏上见，\n小眼迷茫，\n稚脸神情乱。\n似是而非苍老面，\n怎能把我娇名唤。\n七月乖娃添判断，\n最喜爬行，\n期待加餐饭。\n庭院花香心里愿，\n童车一坐听尊便。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "794", "title": "七绝·闲思", "genre": "七绝", "date": "2021.08.12", "body": "酸言醋语暗伤人，\n阵阵阴风似鬼魂。\n亦若乌云图蔽日，\n奈何光烈碎其身。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "795", "title": "卜算子·黄昏吟", "genre": "卜算子", "date": "2021.08.13", "body": "冠疫乱呈威，\n故友难相聚。\n暮色匆匆独自行，\n迎著秋风去。\n暑气渐消沉，\n一路残蝉语。\n凄切声声总不停，\n招惹愁思绪。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "796", "title": "鹊桥仙·七夕怨", "genre": "鹊桥仙", "date": "2021.08.14", "body": "牛郎织女，鹊桥相会。\n怎抵人间尘世。\n云空连线霎时通，\n千万里、犹如临莅。\n若非王母，无情拆散。\n秋月春花惬意。\n青山绿水恁风流，\n天伦乐、温馨萦地。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "797", "title": "忆秦娥·七夕恨", "genre": "忆秦娥", "date": "2021.08.15", "body": "逢乞巧，\n牛郎织女难欢笑。\n难欢笑。\n桥头刚见，\n星空将晓。\n纤云情鹊纷飞了，\n天河又现凄凉貌。\n凄凉貌。\n依依不舍，\n恨离催老。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "798", "title": "满江红·闻事寄怀", "genre": "满江红", "date": "2021.08.16", "body": "倭寇曾降，今又闹，贼心不死。\n眄神州，无端招惹，言污行耻。\n孤岛窝居肝胆胀，\n心胸狭隘窝斜气。\n似小丑，尽舞爪欺人、蒙尘世。\n钓鱼岛，谣称己。窥台海，频生事。\n想印太结盟，招人非议。\n昔日恶行无悔过，今朝丑事谁堪比。\n再放肆，惟马踏刀飞、弹丸地。", "image_files": ["01.jpg"]}, {"poem_id": "799", "title": "忆秦娥·梦碎", "genre": "忆秦娥", "date": "2021.08.17", "body": "……喀布尔之夏\n机声咽，\n人潮骚动情悲切，\n情悲切。\n争相夺路，\n景光凄烈。\n自由米帝心如铁，\n而今头破浑身血，\n浑身血。\n曾经许诺，\n灰飞烟灭。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "800", "title": "踏莎行·见闻抒怀", "genre": "踏莎行", "date": "2021.08.18", "body": "一脉相承，\n两张图片。\n这般风景人惊颤。\n可怜走狗苦哀求，\n多情终了难随愿。\n廿载攻心，\n一朝现眼。\n自由米帝辉光散。\n人权不过口中词，\n周边无利神思远。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "801", "title": "十六字令·三首", "genre": "十六字令", "date": "2021.08.19", "body": "一.\n秋，\n晓色霞光碧水流。\n云空丽，\n莺鹊啭无忧。\n二.\n秋，\n紫绿橙红果渐收。\n香风漫，\n喜气绕枝头。\n三.\n秋，\n袅袅清风夜色幽。\n蟾光淡，\n桐叶映西楼。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "802", "title": "渔家傲·日暮闲吟", "genre": "渔家傲", "date": "2021.08.20", "body": "碌碌人生行已半，\n凭栏回首风云卷。\n眺望远方霞色漫，\n桥路转，\n长河自有高山伴。\n日月浮沉星火灿，\n寒冬过后春风暖。\n花落花开青帝管，\n凝神看，\n风光无意争长短。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "803", "title": "太常引·初秋暮吟", "genre": "太常引", "date": "2021.08.21", "body": "斜风细雨舞清秋，\n爽意染心头。\n黄叶水中流。\n暮空霁，\n凭栏自悠。\n霞光远照，\n飞云漫卷。\n鸦鹊啭无休。\n把酒更何求？\n向梦里，\n山川畅游。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "804", "title": "朝中措·中元感怀", "genre": "朝中措", "date": "2021.08.22", "body": "今朝祭祖古来同，\n香火漫长空。\n虽是阴阳两界，\n凭风遥寄深情。\n时光流转，\n循环往复。\n日夜周行。\n便是人间别却，\n黄泉终会相逢。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "805", "title": "山花子·处暑吟", "genre": "山花子", "date": "2021.08.23", "body": "日暮风柔岸柳垂，\n清波碧水映斜晖。\n桐叶趋黄将欲落，\n雁高飞。\n暑去秋来云淡淡，\n昼晴夜爽露微微。\n故里神思情渐盛，\n客心归。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "806", "title": "太常引·赠诗弟", "genre": "太常引", "date": "2021.08.24", "body": "菇娘果粒溢清香，\n千里自龙江，\n兄弟意情长。\n味鲜嫩，\n芳馨满堂。\n未曾谋面，\n心连诗韵。\n如此热衷肠，\n东北好儿郎。\n感君意，\n频交梦乡。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "807", "title": "朝中措·卖房有感", "genre": "朝中措", "date": "2021.08.25", "body": "为儿筹备一新房，\n静卧二环旁。\n岂料京城落户，\n春秋几度彷徨。\n今朝转手，\n倚栏难舍，\n暗自心伤。\n期许儿孙快乐，\n老来亦或沾光。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "808", "title": "踏莎行·梅韵飞香", "genre": "踏莎行", "date": "2021.08.26", "body": "……贺早梅香诗刊百期\n雪藻兰襟，\n唐风宋雨。\n早梅香韵屏中聚。\n山川江海丽霞飞，\n星光云色添情趣。\n百卷华章，\n万家心绪。\n裁成长短人生句。\n一枝一叶总关情，\n随风吹遍尘寰去。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "809", "title": "踏莎行·京秋暮色", "genre": "踏莎行", "date": "2021.08.27", "body": "雨过京华，\n虹飞帝里。\n初秋暮色云空丽。\n天光楼影水悠悠，\n尘间一派祥和气。\n世道安平，\n黎民欢喜。\n古今华夏翻天地。\n莺歌燕舞啭清音，\n神龙玉凤乘风起。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "810", "title": "蝶恋花·闻事有感", "genre": "蝶恋花", "date": "2021.08.28", "body": "善恶尘间终有报，\n无论何人，\n早晚能收到。\n侥幸一时休自耀，\n周身检点方为好。\n日夜轮回天地道，\n月有阴晴，\n人有悲和笑。\n得意忘形心易傲，\n秋风落叶凭空啸。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "811", "title": "踏莎行·谁之过", "genre": "踏莎行", "date": "2021.08.29", "body": "无奈离开，\n又遭伤死。\n多年反恐何如此。\n一心称霸妄言行，\n寰球招惹千般事。\n己处优先，\n人家垫底。\n鬼神不敢行斯理。\n众生苍海命相当，\n应同凉热于天地。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "812", "title": "七绝·一骑绝尘", "genre": "七绝", "date": "2021.08.30", "body": "红旗三面耀星空，\n勇冠东京华夏情。\n不畏身残心志远，\n今秋奥战起雄风。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "813", "title": "菩萨蛮·相逢有寄", "genre": "菩萨蛮", "date": "2021.08.31", "body": "月余未见娇孙女，\n相逢生怯无言语。\n两眼紧盯瞧，\n凝神苍鬓毛。\n欢情飞稚脸，\n笑舞身忙乱。\n毕竟血相连，\n转晴一瞬间。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "814", "title": "七绝·渔家乐", "genre": "七绝", "date": "2021.09.01", "body": "清波荡漾泛金晖，\n秋水潺潺客晚归。\n日暮蝉蛩声切切，\n小舟仓满蟹鱼肥。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "815", "title": "少年游·秋日晓吟", "genre": "少年游", "date": "2021.09.02", "body": "深宵枕簟感清凉，\n落叶打西窗。\n雨促秋声，冷蟾斜下，\n惊梦绕回肠。\n晓来旭日霞晖满，\n晨练好风光。\n曲调歌音，贯拳飞腿，\n舞剑弄刀枪。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "816", "title": "清平乐·英烈安息", "genre": "清平乐", "date": "2021.09.03", "body": "魂归故里，\n且把英雄记。\n凭仗当年豪迈气，\n才有今朝盛世。\n和平尊尚三军，\n战时勇猛绝伦。\n将士守疆固土，\n黎民昼夜安神。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "817", "title": "眼儿媚·来者不善", "genre": "眼儿媚", "date": "2021.09.04", "body": "梅开二度落天津，\n克里为何因？\n巧言气候，\n百般刁难，\n地暗天昏。\n巨龙腾起西方怵，\n恶意舞烟尘。\n三番五次，\n神情颠倒，\n祸乱纷纷。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "818", "title": "五律·秋之韵", "genre": "五律", "date": "2021.09.05", "body": "秋日恁多情，\n飞云伴雁行。\n双眸盈晕色，\n两耳尽蝉声。\n碧水翻波浪，\n青山木叶横。\n凭高风气爽，\n远眺景光明。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "819", "title": "点绛唇·秋日寄怀", "genre": "点绛唇", "date": "2021.09.06", "body": "何必悲秋，\n雁飞云卷长空丽。\n水清波细，\n五彩斑斓地。\n鹤引诗情，\n把酒凭风寄。\n蟾宫里，\n桂香迢递，\n直漫人间世。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "820", "title": "眼儿媚·娇儿乐", "genre": "眼儿媚", "date": "2021.09.07", "body": "孙女逢秋更销魂，\n满地落香痕。\n床头伫立，\n几边弄笑，\n恁是天真。\n清风送爽安眠睡，\n半宿未翻身。\n醒来眸亮，\n红腮粉靥，\n分外招人。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "821", "title": "踏莎行·秋日闲吟", "genre": "踏莎行", "date": "2021.09.08", "body": "缓度流年，\n闲思岁月。\n一篇一幕从头越。\n曾经多少事追心，\n而今心底无疆界。\n浊酒一杯，\n新词两阙。\n庭花遥对清蟾夜。\n浮生已半鬓飞丝，\n开怀栏角闻莺雀。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "822", "title": "满江红·缅怀主席", "genre": "满江红", "date": "2021.09.09", "body": "今日寰球，如君料，狼心米帝。\n屠刀举，横行四海，妄称仁义。\n陷害栽赃无底线，\n热心搅乱人家事。\n似西风，漫卷起尘烟，污盈地。\n华夏幸，腾朝气。\n新丝路，神龙起。\n仗高天北斗，俯仰千里。\n广袤川原山水秀，\n无垠江海风光丽。\n百姓安，更忆伟人明，情无比。", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "823", "title": "七律·教师节抒怀", "genre": "七律", "date": "2021.09.10", "body": "解惑释疑同古今，\n先生誉望几浮沉。\n栽培桃李千千代，\n孕育梁椽万万人。\n师者言行垂典范，\n世间情事有佳音。\n若得重教成风气，\n华夏山河总是春。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "824", "title": "蝶恋花·别样教师", "genre": "蝶恋花", "date": "2021.09.11", "body": "身在讲堂思在外，\n故漏精华，草草图轻快。\n学子奈何心里怪，\n岂知课后家中卖。\n劣马乱群为一害，\n此病如成，势必园丁败。\n培土修枝规若坏，\n毁伤桃李情难耐。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "825", "title": "南歌子·911有寄", "genre": "南歌子", "date": "2021.09.12", "body": "反恐风头劲，\n回头双秩年。\n当今寰宇可平安。\n世上谁知？\n把酒问苍天。\n几欲强权灭，\n还来塔利班。\n最终无奈卷衣衫。\n四海纷纷，\n岂是自家园。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "826", "title": "玉楼春·吟望", "genre": "玉楼春", "date": "2021.09.13", "body": "东望乳山心已醉，\n宵梦银滩千里会。\n登山遥眺景无边，\n临海高歌人不累。\n今日逢秋难迈腿，\n情滞京城陪晚辈。\n何时还作自由身，\n塞北江南尝美味。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "827", "title": "踏莎行·天生一对", "genre": "踏莎行", "date": "2021.09.14", "body": "鬼斧神工，\n左男右女。\n眉清目秀无言语。\n欲亲还罢恁多情，\n水中为伴终相聚。\n不似人间，\n无常情侣。\n朝三暮四如飞絮。\n风来各自去无踪，\n那堪共沐狂天雨。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "828", "title": "忆王孙·秋日童乐", "genre": "忆王孙", "date": "2021.09.15", "body": "乖宝逢秋鲜吵闹，\n眠有序，晚安晨早。\n晓来梳洗乐加餐，\n绿院里，观花草。\n开上奔驰神态俏，\n红嫩脸，眉开眼笑。\n一颦一靥更招人，\n秀唇润，娇娃巧。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg", "04.jpg"]}, {"poem_id": "829", "title": "朝中措·贺全运会开幕", "genre": "朝中措", "date": "2021.09.16", "body": "古城昨夜焕新姿，\n雁塔映江池。\n钟鼓齐鸣欢奏，\n健儿歌舞今时。\n全民参与，\n强身壮体，\n亿万雄狮。\n腾跃堪惊世界，\n神龙万里东西。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "830", "title": "长相思·遥望", "genre": "长相思", "date": "2021.09.17", "body": "星光明，月光明。\n临近中秋云色轻。\n微寒鸟不惊。\n忆亲情，念友情。\n无限相思日夜萦。\n团圆惟梦成。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "831", "title": "蝶恋花·天外归客", "genre": "蝶恋花", "date": "2021.09.18", "body": "……贺神舟十二返回\n环宇神舟飞赤子，\n载誉归来，\n眉眼舒豪气。\n曾问天公商玉帝，\n九州山水风云丽。\n往返穿梭天与地，\n留驻苍穹，\n日后随心意。\n尘世人间多少事，\n天和宫里从长计。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "832", "title": "忆秦娥·918警示", "genre": "忆秦娥", "date": "2021.09.19", "body": "贼心起，\n偷窥台海行孬计。\n行孬计。\n拉帮结派，\n欲行不义。\n风潮暗涌雷声厉，\n九州汀岸人须记。\n人须记。\n绸缪未雨，\n狼来当毙。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "833", "title": "踏莎行·望月", "genre": "踏莎行", "date": "2021.09.20", "body": "丹桂馨香，\n西风飒爽。\n中秋临近神思荡。\n天南地北盼团圆，\n家亲朋侣情相向。\n几许随心，\n几多失望。\n缘由千百难重样。\n月明昂首瞩星空，\n深情会聚银盘上。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "834", "title": "鹧鸪天·中秋吟望", "genre": "鹧鸪天", "date": "2021.09.21", "body": "我欠家乡一首诗，\n廉州镇里少年时。\n无穷快乐心头印，\n几个朋俦梦里期。\n人恋世，鬓飞丝。\n客居京邑尽相思。\n今朝又是团圆夜，\n南望星空泪染衣。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "835", "title": "七绝·中秋望", "genre": "七绝", "date": "2021.09.21", "body": "秋水长空一色天，\n斜阳漫洒韵无边。\n徜徉曲岸心头醉，\n期待今宵月更圆。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "836", "title": "踏莎行·中秋玉女", "genre": "踏莎行", "date": "2021.09.22", "body": "细细眉峰，\n盈盈秋水。\n轻颦浅笑招人醉。\n乖娃九月恰中秋，\n玉盘萦绕情丝缀。\n宝贝多欢，\n予心不累。\n天天呵护娇花蕊。\n幼苗茁壮老人安，\n惟期如此年年岁 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg", "04.jpg"]}, {"poem_id": "837", "title": "鹧鸪天·话丰收", "genre": "鹧鸪天", "date": "2021.09.23", "body": "一派金黄眼底收，\n农人欢悦溢双眸。\n天公不负春耕苦，\n地母凭添喜获秋。\n粮万斗，解千愁。\n举杯邀月恁风流。\n艰辛一分心毋悔，\n百倍赢回在后头。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "838", "title": "眼儿媚·看西方", "genre": "眼儿媚", "date": "2021.09.24", "body": "一单生意闹翻天，\n浊浪望无边。\n愤招使者，\n震惊元首，\n怒气仇言。\n本非钢板伤痕重，\n碎镜岂能圆。\n凋花败蕊，\n随流而下，\n此后难欢。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "839", "title": "行香子·秋叶晚红", "genre": "行香子", "date": "2021.09.25", "body": "…..贺扬振宁先生百岁\n百岁杨公，多少传奇。\n到如今几许人知。\n仰观宇宙，俯辨珠丝。\n解人间情，物间力，世间谜。\n青春溢彩，霞光晚照。\n寄情华夏费神思。\n流言淡对，行做无私。\n默为人友，引人路，作人梯。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "840", "title": "鹧鸪天·秋晚归舟", "genre": "鹧鸪天", "date": "2021.09.26", "body": "彼岸豺狼贼眼垂，\n无端招惹咬华为。\n历经三载云涛怒，\n漫卷孤峰巨浪催。\n龙引路，晚舟归。\n茫茫沧海映霞晖。\n青山绿水连天碧，\n万里长空白鹤飞。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "841", "title": "太常引·归舟寄怀", "genre": "太常引", "date": "2021.09.27", "body": "国贫岂有小民安？\n中法事同然，\n结果异千般。\n慨而叹，\n遥如地天。\n平生难忘，\n神州远阔，\n山海万民欢。\n情奋舞翩跹，\n展鹏翼，\n长空劲翻。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "842", "title": "浣溪沙·暂别娇孙", "genre": "浣溪沙", "date": "2021.09.28", "body": "一早乖娃打疫苗，\n临行怀里恁多娇。\n清眉笑靥更妖娆。\n却是归来人不见，\n思乡爷奶去今朝。\n再逢惟盼智身高。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "843", "title": "踏莎行·秋日吟", "genre": "踏莎行", "date": "2021.09.29", "body": "明月娟娟，\n繁星款款。\n黄花丹桂香情远。\n西风寒露又中秋，\n回头往事心无怨。\n天上银盘，\n人间玉盏。\n蟾光醇液金尊满。\n举杯只愿梦成真，\n无边闲事何须管。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "844", "title": "临江仙·敬慰英烈", "genre": "临江仙", "date": "2021.09.30", "body": "先烈英魂千百万，\n而今尽可安眠。\n后生承志奋争前。\n九州山水换，\n旗赤五星妍。\n两弹一星依北斗，\n神舟圆梦飞天。\n古来丝路喜延绵。\n川原盈锦绣，\n峰岭袅炊烟。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "845", "title": "贺新郎·国庆抒怀", "genre": "贺新郎", "date": "2021.10.01", "body": "旗赤金星闪，遍城乡、迎风飘荡，频亲君脸。\n欣喜穿行神州路，悦看红黄尽染。\n长天外，雁高云淡。\n江海无忧涛浪浅，晚舟归，温暖人心坎。\n情不禁，齐声喊。\n今朝秋水波光滟，\n碧连天，晴空万里，金风拂槛。\n寰宇天宫凭留去，一任英雄俯瞰。\n九州美，夜光点点。\n无悔人生今更是，且高歌，挥笔豪情蘸。\n写不尽，心头念。", "image_files": ["01.jpg"]}, {"poem_id": "846", "title": "七绝·咏叹秋叶", "genre": "七绝", "date": "2021.10.02", "body": "秋风无意叶花心，\n摇拽飘零羡彩云。\n也想凭空行万里，\n奈何离断自消沉。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "847", "title": "眼儿媚·珠海航展", "genre": "眼儿媚", "date": "2021.10.03", "body": "银鹰鸣刺湛篮天，\n靓艳舞翩跹。\n炫光幻影，\n彩虹弥漫，\n袅袅云烟。\n几多矛盾惊人眼，\n华夏可长安。\n迎风鼓荡，\n情舒心展，\n众悦无边。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "848", "title": "太常引·秋日寄怀", "genre": "太常引", "date": "2021.10.04", "body": "人生易老世无穷，\n何必怨秋风。\n且赏叶趋红。\n把酒向，\n层云碧空。\n凭思往事，\n情怀飞荡，\n暗自笑西东。\n放眼晚霞彤，\n闲迈步，\n山幽水淙。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "849", "title": "念奴娇·长津湖寄怀", "genre": "念奴娇", "date": "2021.10.05", "body": "欺人太甚！手挥三军聚，跨江明志。\n巧设长津湖畔计，怎耐酷寒天气。\n人似冰雕，神魂未了，赤子情坚毅。\n卧艰行苦，却无谁怨天地。\n击碎贼子狂言，弃盔卸甲，一败何千里。\n从此惊心怀噩梦，更昼夜浮生涕。\n华夏扬威，国安家稳，赢取和平世。\n而今回望，拜英雄永相记。", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "850", "title": "五绝·秋雨叹", "genre": "五绝", "date": "2021.10.06", "body": "秋日连天雨，\n禾田谷未收。\n而今难种麦，\n年后景堪忧。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "851", "title": "七绝·忽悠", "genre": "七绝", "date": "2021.10.06", "body": "清晨播报雨将停，\n中午又传临暮晴。\n夜里滴阶声未断，\n醒来烟水雾蒙蒙。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "852", "title": "清风满桂楼·秋雨愁人", "genre": "清风满桂楼", "date": "2021.10.07", "body": "风轻雨细。\n数日连绵，泥污漫流田里。\n刚好种麦时，无可奈，黎民怨心窝气。\n凭栏远伫望，九霄外，廉纤难止。\n苍穹拜！良机错过，更无能替。\n都知饭香腻，日月难离，何人管天公事？\n乡下已成灾，阡陌上，牛羊恨君无计。\n今朝未撒子，怎能望，明年物喜。\n谁愁苦，惟有农家泪涕。", "image_files": ["01.jpg"]}, {"poem_id": "853", "title": "玉楼春·红与黑", "genre": "玉楼春", "date": "2021.10.08", "body": "来往三番宇宙宽，\n大洋彼岸两重天。\n当年霸道横于世，\n今日低声对面言。\n盈酒盏，淡心田。\n阴晴难定莫悲欢。\n旦凭北斗银空照，\n便是风霜亦向前。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "854", "title": "眼儿媚·屏上乖宝", "genre": "眼儿媚", "date": "2021.10.09", "body": "别娃一日似三秋，\n网见喜心头。\n两眸闪亮，\n辨音挥手，\n站立无忧。\n看书端坐翻来去，\n竞自乐难休。\n鸡熊为友，\n观颜闻事，\n摆弄圈球。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg", "04.jpg"]}, {"poem_id": "855", "title": "鹧鸪天·赠儿媳新疆挂职", "genre": "鹧鸪天", "date": "2021.10.10", "body": "九月娇娃别母亲，\n人生几个似如今。\n三年西域君无怨，\n每日东边扯汝心。\n思稚脸，盼儿音。\n一天伏案几分神。\n今朝桃李经风雨，\n日后芳欣果更淳。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "856", "title": "蝶恋花·双十寄怀", "genre": "蝶恋花", "date": "2021.10.11", "body": "辛亥当年回首望，\n翻转乾坤，\n江海掀波浪。\n万岭千山思变样，\n神州到处风云荡。\n更起红船人向党，\n赤子齐心，\n万丈豪情漾。\n无数英雄同继往，\n如今凯奏高歌唱。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "857", "title": "七律·秋夜闲吟", "genre": "七律", "date": "2021.10.12", "body": "一望篱边菊蕊黄，\n微风寒露夜趋凉。\n清光东滞裁桐叶，\n明月西移过女墙。\n把酒飞思千里远，\n剪音成韵几诗行。\n灯前吟赋人无寐，\n梦里念君情意长。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "858", "title": "风入松·外甥女出嫁", "genre": "风入松", "date": "2021.10.13", "body": "妹家喜事聚乡邻，\n笑语声频。\n楼前炉火蒸香溢，\n情盈碗，意满瓯盆。\n旭日金风送爽，\n笼灯五彩萦门。\n闺中娇女醉心神，\n喜雾氤氲。\n红花玉照床头上，\n轻回首，顾盼郎君。\n携手人生长路，\n连枝比翼销魂。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg", "04.jpg", "05.jpg", "06.jpg"]}, {"poem_id": "859", "title": "太常引·玉女完婚", "genre": "太常引", "date": "2021.10.14", "body": "王家俏女入冯门，\n惊艳众乡邻。\n鸟雀醉心神。\n俊眉眼，\n红唇浅颦。\n芳庭落轿，\n花童拥簇，\n轻踏起香尘。\n心里念娘恩，\n盈喜泪，\n回头望亲。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg", "04.jpg", "05.jpg", "06.jpg"]}, {"poem_id": "860", "title": "鹧鸪天·重阳吟", "genre": "鹧鸪天", "date": "2021.10.15", "body": "九九重阳万里秋，\n枫红气爽老无忧。\n居家漫看尘间事，\n野外闲观碧水流。\n攀俊岭，泛轻舟。\n凭风把酒醉难休。\n登高望远心怀畅，\n胜似天堂岂用求。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "861", "title": "菩萨蛮·神舟又起", "genre": "菩萨蛮", "date": "2021.10.16", "body": "酒泉夜起飞天客，\n逐星伴月寒光彻。\n地上过重阳，\n云空万里翔。\n天和增喜气，\n宫里迎娇女。\n半载宇寰行，\n三人事竟成。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "862", "title": "菩萨蛮·心欲碎", "genre": "菩萨蛮", "date": "2021.10.17", "body": "节前别过今相见，\n孙娃一霎心神乱。\n或许想妈妈，\n明眸润欲花。\n此情催老泪，\n将语心头碎。\n九月小娇人，\n家亲来往频。\n注：十一前爷爷奶奶\n走，姥爷姥姥来。十\n月九日奶奶来，十日\n妈妈去新疆三年。今\n朝爷爷来，姥爷姥姥\n走。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "863", "title": "七绝·秋风美韵", "genre": "七绝", "date": "2021.10.18", "body": "浮云吹去尽蓝天，\n早晚无风亦冷寒。\n秋染京城美如画，\n香山红叶醉心田。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "864", "title": "菩萨蛮·闻事闲吟", "genre": "菩萨蛮", "date": "2021.10.19", "body": "当年半管凭空粉，\n无端开战人神恨。\n不见愧心怀，\n苍天报应来。\n新冠尘世祸，\n老米委人过。\n却有信其真，\n到头伤自身。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "865", "title": "七绝·闻事有感", "genre": "七绝", "date": "2021.10.20", "body": "祸害人家招众恨，\n狐朋狗党情相近。\n冥冥天道在尘间，\n终了声名岂用问。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "866", "title": "行香子·秋夜吟", "genre": "行香子", "date": "2021.10.21", "body": "明镜飞天，水静蟾寒。\n望银空夜色难眠。\n繁星闪烁，落叶无言。\n恰秋儿暮，风儿细，月儿圆。\n灯前缃帙，文辞入眼。\n似先贤古圣来前。\n追寻李杜，遥访苏韩。\n品诗中事，词中水，赋中山。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "867", "title": "七律·秋日寄同窗", "genre": "七律", "date": "2021.10.22", "body": "鬓角飞丝任剪裁，\n而今谁个不头白。\n曾经坎坷风霜落，\n赢取甘甜雨露来。\n遥望今朝千里外，\n相思往事一襟怀。\n凭栏慨叹云霞色，\n喜看秋菊遍处开。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "868", "title": "采桑子·时令吟", "genre": "采桑子", "date": "2021.10.23", "body": "西风漫卷催霜降，\n星月高悬，\n晓色清寒，\n疏柳栖鸦对老蝉。\n黄花红叶凭空舞，\n庭院篱边，\n窗下尊前，\n岁月悠悠年复年。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "869", "title": "鹧鸪天·心慰", "genre": "鹧鸪天", "date": "2021.10.24", "body": "灯下孙娃才睡安，\n一天忙碌此时闲。\n端详稚脸生红晕，\n抚触眉头汗已干。\n娘别后，爸趋前。\n通宵陪护女儿边。\n深情母爱今相续，\n昼夜无忧渐始欢。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "870", "title": "虞美人·白头吟", "genre": "虞美人", "date": "2021.10.25", "body": "当年无空娇儿侍，\n昼夜凭妻继。\n而今得空弄孙娃，\n斑鬓霜丝合力育妍花。\n人生代代情相递，\n千古成今世。\n爱倾耆少益神州，\n始有泱泱华夏万年秋。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "871", "title": "长相思·任性妄为", "genre": "长相思", "date": "2021.10.26", "body": "人凝眸，虎凝眸。\n相对无言万众愁。\n谁能解个由。\n早风流，晚风流。\n为客之行当敛收。\n性情家里留。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "872", "title": "七绝·游园有寄", "genre": "七绝", "date": "2021.10.27", "body": "百子湾中看野鸭，\n娇孙嫩脸乐开花。\n天真童稚无忧虑，\n戏水金鱼可似她？ ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "873", "title": "忆王孙·闻事有感", "genre": "忆王孙", "date": "2021.10.28", "body": "钢琴王子意飘然，\n心若游丝乱为欢。\n终有今朝车马翻。\n霎时间，\n无数光环散远天。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "874", "title": "七绝·闲吟游人", "genre": "七绝", "date": "2021.10.29", "body": "重阳秋兴漾心头，\n惬意携家塞外游。\n不料疫情今又起，\n胡杨未见走难筹。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "875", "title": "少年游·秋日闲吟", "genre": "少年游", "date": "2021.10.30", "body": "已然霜降却无寒，\n秋暮似春天。\n午后微风，斜阳横照，\n征雁奋翩跹。\n花前庭院凭栏望，\n耆少自悠闲。\n翁老争棋，粉人劲舞，\n童稚荡秋千。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "876", "title": "七绝·假日闲吟", "genre": "七绝", "date": "2021.10.31", "body": "久闻集市晓趋前，\n横锁穿门叶寂寒。\n借问今番竟何事？\n疫情逼近保民安。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "877", "title": "蝶恋花·苦乐吟", "genre": "蝶恋花", "date": "2021.11.01", "body": "怡弄孙娃忙早晚，\n窗下台前，\n净手清眉眼。\n热奶烧汤蒸煮饭，\n新潮玩具收还乱。\n便是得闲眠亦浅，\n梦里分神，\n生怕婴声远。\n苦乐交加金不换，\n欣然回首娇容灿。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "878", "title": "七绝·婴鸟相乐", "genre": "七绝", "date": "2021.11.02", "body": "金秋庭院弄朝晖，\n十月娇孙看雀飞。\n眉眼清圆纤手舞，\n多情小鸟不思归。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "879", "title": "蝶恋花·挚爱深情", "genre": "蝶恋花", "date": "2021.11.03", "body": "母爱深深千里寄，\n人在边关，\n念女京城事。\n细乳涓涓凭空递，\n温情宛转千方计。\n自古娘亲无可替，\n不惧艰辛，\n只为儿孙丽。\n多少后生明此意，\n终身能把娘恩记。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "880", "title": "七律·赞获奖者", "genre": "七律", "date": "2021.11.04", "body": "埋头研创奖加身，\n无悔平生历苦辛。\n二弹一星凭志远，\n巡天探月赖情深。\n冷观寰宇风云暗，\n喜看神州景色春。\n昂首扬眉依重器，\n龙腾霄汉仰诸君。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "881", "title": "太常引·寒秋晓雾", "genre": "太常引", "date": "2021.11.05", "body": "寒潮南北卷神州，\n晓色冷飕飕。\n霾雾更堪忧。\n恁无奈，人悲鸟愁。\n枯枝黄叶，\n层层霜露，\n无语诉深秋。\n冠疫乱行游。\n外出苦，\n居家为囚。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "882", "title": "蝶恋花·闻事抒怀", "genre": "蝶恋花", "date": "2021.11.06", "body": "绝地逢生凭士气，\n智取舟桥，\n更把豺狼避。\n留有青山长远计，\n再图叶茂风华易。\n霸主情怀今又是，\n尝胆披荆，\n铸就英雄势。\n多路出兵前后继，\n等闲且看东山起。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "883", "title": "七绝·立冬", "genre": "七绝", "date": "2021.11.07", "body": "通宵雨雪斗西风，\n除尽污霾洒玉冰。\n树上寒鸦慵不起，\n爷孙楼角望花凌。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "884", "title": "七绝·立冬寄同窗", "genre": "七绝", "date": "2021.11.08", "body": "飘絮飞花冷色浓，\n朔风催我入初冬。\n三鲜水饺寻常事，\n一盏醇醪慰此生。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "885", "title": "七绝·雪后楼院", "genre": "七绝", "date": "2021.11.09", "body": "雪霁天晴水又冰，\n楼前庭院少人声。\n寻常童叟悠闲处，\n今日寒鸦避北风。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "886", "title": "秋蕊香引·雪梅报春", "genre": "秋蕊香引", "date": "2021.11.10", "body": "冬已到。风寒霜降，败枝衰草。暮鸦静，栖树杪。\n晚霞散尽空清冷，路人渐稀少。\n临夜半，玉絮纷飞弄巧。雪来早。\n六花满地，万里银光袅。\n冷香处，红梅蕊，欲将春报。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "887", "title": "踏莎行·闻事有感", "genre": "踏莎行", "date": "2021.11.11", "body": "尘世无常，\n人生不易。\n身前多少功名利。\n今朝不料尽随风，\n音容一霎如烟逝。\n语要迎心，\n行宜合体。\n少争无怨舒肝气。\n山间水畔醉天光，\n云来涛去由它意。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "888", "title": "五律·初冬趣", "genre": "五律", "date": "2021.11.12", "body": "楼台萦翠色，\n冬日恁温馨。\n盆里栽生菜，\n栏边育嫩芹。\n老妻堪巧手，\n童稚口食亲。\n免却担惊怕，\n婴餐尽可心。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "889", "title": "七绝·别后初逢", "genre": "七绝", "date": "2021.11.13", "body": "母女别离情不断，\n银屏声貌日相闻。\n醒来惊喜床头见，\n十月孙娃笑更频。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "890", "title": "七律·半老抒怀", "genre": "七律", "date": "2021.11.14", "body": "人生能有几时闲？\n忙碌今朝日复年。\n少子读书灯下苦，\n壮丁立业梦中难。\n儿孙总念宵无寐，\n父母常思昼不安。\n斑鬓飞丝心未老，\n钟情山水又趋前。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "891", "title": "长相思·惜宝岛", "genre": "长相思", "date": "2021.11.15", "body": "说台湾，\n看台湾。\n今被他人桌上摊。\n听来好可怜。\n蒙一天，\n算一天。\n孤井为家竟自欢。\n无缘天外天。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "892", "title": "采桑子·冬日闲吟", "genre": "采桑子", "date": "2021.11.16", "body": "耳根清净功名远。\n事少心闲，\n灯下尊前。\n喜看今朝似过年。\n火红日子风云淡。\n碧水蓝天，\n思绪无边。\n鸥鹭为盟醉海天。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "893", "title": "朝中措·交锋", "genre": "朝中措", "date": "2021.11.17", "body": "前番几次将相逢，\n彼此探军情。\n几许心中有数，\n今朝两帅交锋。\n年来暗战，\n云烟迷漫，\n难论输赢。\n惟有言欢握手，\n才能世态安宁。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "894", "title": "七绝·颙望", "genre": "七绝", "date": "2021.11.18", "body": "百态人生或短长，\n朝霞冉冉至夕阳。\n曾经绚丽心无悔，\n何虑青丝染露霜。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "895", "title": "鹧鸪天·咏柳", "genre": "鹧鸪天", "date": "2021.11.19", "body": "黄绿参差漫剪风，\n枝条垂落诉曾经。\n秋光不似春光暖，\n老叶深含嫩叶情。\n听暮雨，映晨星。\n从前草碧百花红。\n如今霜降多凋谢，\n独对寒鸦意亦浓。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "896", "title": "长相思·爷孙乐", "genre": "长相思", "date": "2021.11.20", "body": "橙子甘，\n柚子甘。\n滋润双唇两靥甜。\n娇娃自是欢。\n乐一天，\n玩一天。\n打过秋千还套圈。\n细眉飞耳边。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "897", "title": "七绝·寄银滩李兄", "genre": "七绝", "date": "2021.11.21", "body": "相思不必长相见，\n情寄银屏字句真。\n望水隔山闲事少，\n倚栏邀月醉同心。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "898", "title": "朝中措·生日有寄", "genre": "朝中措", "date": "2021.11.22", "body": "今年家宴不同昔，\n孙女最称奇。\n往日尊前平淡，\n她来无限生机。\n平添滋味，\n徒增欢笑，\n任鬓飞丝。\n忘却平生烦恼，\n与娃心醉神怡。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "899", "title": "七绝·冬日有感", "genre": "七绝", "date": "2021.11.23", "body": "时临小雪卷寒风，\n残叶横飞乱远空。\n出手即回心底颤，\n路人无奈苦谋生。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "900", "title": "踏莎行·闻事有感", "genre": "踏莎行", "date": "2021.11.24", "body": "恶狗伤人，\n庸差了事。\n周遭百姓难平气。\n新潮媒体助人心，\n喜来官府迎民意。\n显案刚平，\n隐情又起。\n为人切莫依权势。\n举头三尺有神明，\n心存敬畏长空丽。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "902", "title": "七绝·酬友", "genre": "七绝", "date": "2021.11.25", "body": "问候临屏冬日暖，\n真情驱散九天寒。\n神州防疫民为本，\n山海同辉草木安。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "903", "title": "蝶恋花·述怀", "genre": "蝶恋花", "date": "2021.11.26", "body": "人重人轻身外事，\n浮利虚名，\n不必心头计。\n宠辱无惊湖畔倚，\n泛舟弄水鱼鸥戏。\n云淡风轻人惬意，\n畅望山峰，\n袅袅腾烟气。\n满眼霞光飞旎旖，\n余生闲度清幽地 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "904", "title": "七绝·渴望", "genre": "七绝", "date": "2021.11.27", "body": "百岁人生能有几？\n同窗相聚古来稀。\n促膝闲坐茗香淡，\n多少英豪梦里期。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "905", "title": "南歌子·咏望", "genre": "南歌子", "date": "2021.11.28", "body": "天上星河转，\n人间岁月流。\n今朝山水乐无忧。\n翠岭闲观轻浪、\n戏沙鸥。\n塞北风光丽，\n江南景色柔。\n莺飞燕舞啭枝头。\n万里层云欣喜、\n望神州。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "906", "title": "朝中措·高人妙方", "genre": "朝中措", "date": "2021.11.29", "body": "见风转舵好行船，\n妙理越千年。\n凭此畅游江海，\n浪中笑看长天，\n丛林世界，\n云烟跌宕，\n龙虎争前。\n到底谁能随愿，\n渐崇华夏军团。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "907", "title": "蝶恋花·联想有感", "genre": "蝶恋花", "date": "2021.11.30", "body": "杨柳青青人欲问，\n昔日豪情，\n惟剩心头恨？\n司马滔滔抛妙论，\n至今谁可消疑闷。\n有理说开民释忿，\n何必无声，\n背地挥刀棍。\n若使他人言语尽，\n还须自己行为顺。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "908", "title": "七绝·冬日闲吟", "genre": "七绝", "date": "2021.12.01", "body": "与人常笑身心少，\n胜似灵丹堪妙药。\n年老情闲何所求，\n无忧岁月风光好。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "909", "title": "南乡子·冬日感怀", "genre": "南乡子", "date": "2021.12.02", "body": "镜里鬓飞霜，\n将老还行远故乡。\n来为子孙勤料理。\n穷忙，\n常是无闲夜未央。\n儿辈梦中香，\n自是无忧脸目详。\n晓起转身清爽去。\n阳光，\n洒向周边紫气扬。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "910", "title": "七绝·无题", "genre": "七绝", "date": "2021.12.03", "body": "知音难觅梦中求，\n欲诉心怀网上游。\n虚拟空间多少事，\n光阴无奈指尖流。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "911", "title": "定风波·知足自乐", "genre": "定风波", "date": "2021.12.04", "body": "多是生来为口忙，\n果鲜未必尽穿肠。\n天下珍馐千百万，\n休怨。\n且留后世子孙尝。\n万事中庸方为好，\n愁少。\n魂安拥枕梦宵香。\n日夜无忧心绪远，\n闲看。\n悠悠山水好风光。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "912", "title": "踏莎行·时光欢逝", "genre": "踏莎行", "date": "2021.12.05", "body": "苍鬓童心，\n无愁有笑。\n与娃相处心怀俏。\n一周转眼又轮回，\n时光飞逝余生妙。\n爷奶欢行，\n祖孙嘻闹。\n楼前院后闻啼鸟。\n天寒无惧赖貂裘，\n篱边梅蕊春将报。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "913", "title": "七绝·遥看", "genre": "七绝", "date": "2021.12.06", "body": "七把长枪一个班，\n阵容威武啸云天。\n为迎圣诞阖家照，\n难怪街头祸患连。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "914", "title": "菩萨蛮·寄语孙娃", "genre": "菩萨蛮", "date": "2021.12.07", "body": "梦香不晓妈妈去，\n醒来依旧盈欢绪。\n毕竟小天真，\n别离未动心。\n说来还算好，\n爷奶忧愁少。\n父母也神安，\n征途志远天。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "915", "title": "七绝·霞光晚照", "genre": "七绝", "date": "2021.12.08", "body": "风轮星月染霞晖，\n万里澄空日色归。\n已是黄昏情亦好，\n登高送目绪思飞。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "916", "title": "踏莎行·闻事感吟", "genre": "踏莎行", "date": "2021.12.09", "body": "无事生非，\n魂消烟灭。\n葬身山谷寒虫啮。\n曾经狂妄蔑神州，\n而今梦语随风月。\n好自为人，\n切毋撒野。\n阿三上下当思略。\n与邻友善共云天，\n并行致远歌长阕。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "917", "title": "桂殿秋·太空开讲", "genre": "桂殿秋", "date": "2021.12.10", "body": "仙女课，在天宫。\n释疑解惑宇寰行。\n神州赤子心怀奋，\n仰望星空月色明。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "918", "title": "浣溪沙·痛击疯会", "genre": "浣溪沙", "date": "2021.12.11", "body": "打脸何须对面抽，\n一言击中癞皮猴。\n贼心窝火恨难流。\n尘世阳光谁可阻，\n人间正道自追求。\n桑田沧海写春秋。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "919", "title": "七绝·冬日闲吟", "genre": "七绝", "date": "2021.12.12", "body": "时逢大雪雨纤纤，\n烟雾濛濛漫远天。\n依照寻常本该冷，\n春衫秋裤意超然。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "920", "title": "清平乐·祝娘亲高寿", "genre": "清平乐", "date": "2021.12.13", "body": "倚栏伫立，\n遥祝娘生日。\n身陷京城思故里，\n心愧双亲难抑。\n惟期慈母平安，\n与邻说笑聊天。\n二老相依为伴，\n还凭贤妹朝前。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "921", "title": "七绝·感悟", "genre": "七绝", "date": "2021.12.14", "body": "亲人如玉友如金，\n百倍珍惜莫染尘。\n多少钱财难买断，\n真诚一分久于心。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "922", "title": "七绝·午后童趣", "genre": "七绝", "date": "2021.12.15", "body": "娇孙睡醒乐无穷，\n地上翻爬趣更浓。\n厨卫明知不许去，\n回头媚笑恣前行。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "923", "title": "浣溪沙·云", "genre": "浣溪沙", "date": "2021.12.16", "body": "来不相知去不留，\n长空万里任行游。\n浮生名分岂须求。\n酷暑临江非有意，\n严寒出岫亦无由。\n随心舒卷恁风流。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "924", "title": "七绝·冬晓吟", "genre": "七绝", "date": "2021.12.17", "body": "一夜狂风梦不圆，\n打窗枝叶送清寒。\n翻身恐怕家人醒，\n暗自劳神忆往年。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "925", "title": "七绝·闻事偶感", "genre": "七绝", "date": "2021.12.18", "body": "人来尘世鸣天地，\n魂逝云空悄不言。\n多少亲情留未住，\n声名无奈向黄泉。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "926", "title": "七律·玉鼠学步", "genre": "七律", "date": "2021.12.19", "body": "将临周岁起身行，\n颤颤悠悠腿不灵。\n脚底歪斜花影动，\n眉心上下舞春风。\n开怀最是词难表，\n得意谁能语悦情。\n看似寻常蹀躞步，\n却从此刻走人生。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "927", "title": "鹧鸪天·浮生悟", "genre": "鹧鸪天", "date": "2021.12.20", "body": "莫道人间行路难，\n心怀宽阔纳云天。\n依山且走林中径，\n傍水勤摇浪里船。\n当努力，忌空言。\n捕鱼采果自成欢。\n粗茶淡饭凭栏望，\n闲看星辰梦里甜。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "928", "title": "鹧鸪天·若煊生日", "genre": "鹧鸪天", "date": "2021.12.21", "body": "玉鼠一周岁悄然，\n秀眉娇靥立人前。\n常添笑料心怀悦，\n总作谈资伴美餐。\n情不尽，趣无边。\n流年逝月指挥间。\n万金难买阖家乐，\n惟有孙娃笑破天。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg", "04.jpg"]}, {"poem_id": "929", "title": "七绝·冬至", "genre": "七绝", "date": "2021.12.22", "body": "昼短夜长天数九，\n寒鸦冷树怯西风。\n红梅傲雪花枝绽，\n拟报春来玉宇清。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "930", "title": "桂殿秋·闻事吟", "genre": "桂殿秋", "date": "2021.12.23", "body": "灯塔灭，树将倾。\n猢狲各自觅前程，\n呼风唤雨今难再，\n马下麾旁恁冷清。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "931", "title": "采桑子·岁暮吟", "genre": "采桑子", "date": "2021.12.24", "body": "时光无意催人老，\n且享余生，\n潇洒闲行。\n何必回头恋旧名。\n香醪一盏心微醉，\n梦稳神宁，\n缭绕乡情。\n悬月娟娟故里明。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "932", "title": "蝶恋花·小聚有感", "genre": "蝶恋花", "date": "2021.12.25", "body": "物是人非心底叹。\n岁暮围炉，\n不见桃花面。\n或许多情疏信念，\n惟期日后身康健。\n往事萦怀难逝远。\n待友于朋，\n曾似春光漫。\n笑语盈盈风物暖，\n而今音讯如丝断。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "933", "title": "南乡子·缅怀主席", "genre": "南乡子", "date": "2021.12.26", "body": "己正影难歪，\n挥手清除玉宇埃。\n倾力为民宵继日。\n奇哉，\n千古神州万世才。\n身后亿人怀，\n历久情深滚滚来。\n最是预言今俱应。\n明白，\n野寇狼心岂用猜！ ​​​", "image_files": ["01.jpg"]}, {"poem_id": "934", "title": "七绝·敬颂主席", "genre": "七绝", "date": "2021.12.27", "body": "一.\n百姓心中一杆秤，\n可量千古山河重。\n东方红日熠神州，\n激荡情怀波浪涌。\n二.\n日耀东方万里霞，\n贫家敝户亦生花。\n阳光温暖禾苗壮，\n葱郁芳馨紫气佳。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "935", "title": "菩萨蛮·冬练有感", "genre": "菩萨蛮", "date": "2021.12.28", "body": "寒天欲晓驱残月，\n北风刺面穿心彻。\n街上路人稀，\n啼鸦荡柳枝。\n常年晨练早，\n自是忧烦少。\n安稳度平生，\n萦怀父老情。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "936", "title": "踏莎行·雪藻兰襟韵飞扬", "genre": "踏莎行", "date": "2021.12.29", "body": "玉女飞歌，\n琼楼漫韵。\n芳音宛转心头润。\n丝丝缕缕总萦回，\n魂追梦绕情难尽。\n曲赋悠扬，\n诗词激奋。\n临屏怎不神思振。\n唐风宋雨妙无穷，\n摘星揽月凭谁问。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "937", "title": "七绝·冬日吟", "genre": "七绝", "date": "2021.12.30", "body": "飞雪深情唤早春，\n年关将近念朋亲。\n寒窗灯下一杯酒，\n梦里相逢尽故人。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "938", "title": "清平乐·望长安", "genre": "清平乐", "date": "2021.12.31", "body": "古都蒙难，\n百姓心怀乱。\n情似去年追武汉，\n却是从容应战。\n鼓楼雁塔清清，\n街头白色流行。\n鸟雀盘旋纳闷，\n犹期人跃笙鸣。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg", "04.jpg"]}, {"poem_id": "939", "title": "苏幕遮·元旦", "genre": "苏幕遮", "date": "2022.01.01", "body": "晓晖明，心底暖。\n伫立楼台，眺望云空远。\n遥想天和帆翼展，\n宇外英雄，笑把神州看。\n壮山河，霞色漫。\n塞北江南，遍地红旗卷。\n楼若繁星光璀璨。\n万众豪情，劲舞欢歌赞。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "940", "title": "喝火令·元旦升旗", "genre": "喝火令", "date": "2022.01.02", "body": "百姓情真切，\n三军气欲吞。\n景光宏阔撼人心。\n千里冒寒相聚，\n浑是抖精神。\n广场摩肩立，\n银屏把手亲。\n万家凝目细追寻。\n晓看星残，\n晓看月西沉。\n晓看赤旗飞卷，\n映彻九州人。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "941", "title": "七绝·元旦有寄", "genre": "七绝", "date": "2022.01.03", "body": "风云岁月入新年，\n趣味人生色彩添。\n看似无心加一笔，\n回头再望更光鲜。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "942", "title": "南乡子·吟将别", "genre": "南乡子", "date": "2022.01.04", "body": "把酒劝君留，\n将语难言泪欲流。\n家母寝行应莫念，\n毋愁。\n游走安心在外头。\n驱步几回眸，\n岂奈分离自是忧。\n父子一心都不舍，\n无由。\n别后相思怎个休。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "943", "title": "七绝·闻事有寄", "genre": "七绝", "date": "2022.01.05", "body": "夫妻互敬日悠长，\n子散家离苦断肠。\n覆水难收蒸逝易，\n儿忧破镜少明光。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "944", "title": "七绝·天道", "genre": "七绝", "date": "2022.01.06", "body": "时钟周转不知愁，\n日月轮回岂用忧。\n花落花开天作主，\n人间悲乐水长流。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "945", "title": "江城梅花引·五常之举", "genre": "江城梅花引", "date": "2022.01.07", "body": "拥核大佬弄声明，\n讲和平，议和平。\n举世围观，期待宇寰宁。\n从此或消核恐怖？\n日趋稳，有谁能，\n不领情。\n领情，领情。盼执行。\n俄美中，带法英。\n或许各自，有想法，\n只怕难成。\n丑帝奸滑，\n一味耍贼聪。\n失信欺人终自毁。\n遭唾弃，愧于天，\n地不容。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "946", "title": "七绝·闻事有感", "genre": "七绝", "date": "2022.01.08", "body": "残杨败柳不心甘，\n冬日逆风强欲欢。\n纵使枯枝追落叶，\n惘然愁寂对长天。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "947", "title": "蝶恋花·遥望云烟", "genre": "蝶恋花", "date": "2022.01.09", "body": "为害街头多有鬼，\n口喊民生，\n心意偏离嘴。\n内外暗通犹祸水，\n污涛恶浪谁之罪？\n相似情形相似味，\n几欲垂成，\n终是前功废。\n霹雳雷霆惩乱匪，\n有人夜梦惊天碎。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "948", "title": "诉衷情·腊日", "genre": "诉衷情", "date": "2022.01.10", "body": "乖孙初试腊香粥，\n八宝润娇喉。\n欢情笑染双靥，\n灵动闪清眸。\n盛一碗，\n粒无留，\n再三求。\n手招头晃，\n舌卷朱唇，\n玉口涎流。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "949", "title": "蝶恋花·客访未成", "genre": "蝶恋花", "date": "2022.01.11", "body": "中午时分铃作响，\n投箸倾听，\n一霎心神荡。\n故友失联今欲访，\n寻声旧事凭浮想。\n意外忽来难细讲，\n车至途中，\n怎奈遥相望。\n同在京城桥路傍，\n欣期日后交如往。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "950", "title": "减字木兰花·悟", "genre": "减字木兰花", "date": "2022.01.12", "body": "天宽地厚，\n江海横流峰岭瘦。\n岁月悠长，\n万古星辰几色光。\n人来人往，\n风起云生花绽放。\n尘世悲欢，\n尽在情思物欲间。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "951", "title": "七绝·辛丑冬吟", "genre": "七绝", "date": "2022.01.13", "body": "云霄不见雪花飞，\n三九时光冷色微。\n曾记去年冬至后，\n嘶天裂地朔风吹。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "952", "title": "七绝·冬日吟望", "genre": "七绝", "date": "2022.01.14", "body": "凭栏常羡他人好，\n行客慕君依暖阳。\n飞鸟不知深水浪，\n金鱼向往碧云翔。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "953", "title": "踏莎行·众望", "genre": "踏莎行", "date": "2022.01.15", "body": "街貌清新，\n花蓝璀璨。\n欲迎冬奥容妆换。\n新春冰上待相逢，\n五洲四海情怀远。\n宾友为欢，\n妖魔使乱。\n云烟半缕空消散。\n风行玉宇扫尘埃，\n神州万里霞光漫。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "954", "title": "风入松·游芳园里", "genre": "风入松", "date": "2022.01.16", "body": "携孙假日赏楼园，\n物秀光妍。\n旋梯廊道迷人眼。\n游乐处，次第相连。\n潮涌温馨老少，\n比肩亲子同欢。\n家庭微景恁齐全，\n巧手蹁跹。\n狗猫鱼兔空遥望，\n欲摩触，投币趋前。\n童稚开心一刻，\n多情长辈烧钱。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "955", "title": "菩萨蛮·岁暮吟", "genre": "菩萨蛮", "date": "2022.01.17", "body": "流年似水依涛去，\n潮生潮落长如许。\n踏浪舞人生，\n倚帆江海行。\n仰天观日月，\n回首风摇叶。\n淡看世间情，\n心闲梦亦宁。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "956", "title": "七绝·月圆吟", "genre": "七绝", "date": "2022.01.18", "body": "寻常腊月日趋欢，\n明月中天喜近年。\n今夜清蟾辉照旧，\n疫情无奈隐心酸。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "957", "title": "太常引·天灾叵测", "genre": "太常引", "date": "2022.01.19", "body": "火山云漫蔽长空，\n海啸卷洲城。\n一霎宇寰惊。\n胜核弹，余威不穷。\n浮尘遮日，\n数年难散，\n夏季少凉风。\n无奈是苍生。\n岛湮没，悲催泪零。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "958", "title": "朝中措·时令吟", "genre": "朝中措", "date": "2022.01.20", "body": "大寒飞雪舞京都，\n花影树间无。\n但见栖鸦瑟瑟，\n啼声凄断飘乎。\n年关将近，\n疫情突起，\n心意难舒。\n举首家乡遥望，\n谁知绪乱情孤。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "959", "title": "鹧鸪天·同床异梦", "genre": "鹧鸪天", "date": "2022.01.21", "body": "四九听风彻夜寒，\n孙娃栖侧久深眠。\n满床翻转舒心梦，\n双脚伸勾浅靥圆。\n挥玉手，抖香肩。\n暖身锦被乱朝天。\n晓来稚脸眉梢乐，\n老眼飞星头欲旋。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "960", "title": "菩萨蛮·望", "genre": "菩萨蛮", "date": "2022.01.22", "body": "疫情阻断归乡路，\n情牵父子心头堵。\n京洛望廉州，\n天寒两处忧。\n家亲尊二老，\n年货筹谋早。\n闻讯略心宽，\n迎春向虎年。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "961", "title": "鹧鸪天·雪映京都", "genre": "鹧鸪天", "date": "2022.01.23", "body": "细玉盈空鸟雀寒，\n梨花满树冷晖妍。\n红灯漫舞迎祥瑞，\n银粟婆娑入虎年。\n童子乐，雪人憨。\n琼英着处尽情喧。\n寻常学业心头苦，\n天赋今朝怎不欢。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "962", "title": "七绝·闲吟", "genre": "七绝", "date": "2022.01.24", "body": "莫问人生寿短长，\n心宽骨硬自风光。\n樽前潇洒山川醉，\n日月盈怀一缕阳。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "963", "title": "五绝·小年吟", "genre": "五绝", "date": "2022.01.25", "body": "物丰情趣淡，\n心气不如初。\n鬓染风霜色，\n梦魂何所图。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "964", "title": "七绝·岁暮吟", "genre": "七绝", "date": "2022.01.26", "body": "虎近新年雪洗尘，\n银妆门户俏迎春。\n红梅一簇窗前闹，\n满院生辉喜照人。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "965", "title": "太常引·望乡", "genre": "太常引", "date": "2022.01.27", "body": "乡情似酒漫年关，\n醇烈殢樽前。\n便醉亦难眠。\n夜光下，\n人浮事缠。\n少时光景，\n小门深院。\n恋物绪蹁跹，\n最忆是家山。\n恰岁杪、相思万千。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "966", "title": "七绝·F35坠南海", "genre": "七绝", "date": "2022.01.28", "body": "彼岸尘烟暗水空，\n风云诡异怒涛生。\n黑鹰无奈失魂坠，\n别样浪花鱼鸟惊。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "967", "title": "朝中措·寄思", "genre": "朝中措", "date": "2022.01.29", "body": "老爹疑病夜难安，\n坐卧自心烦。\n总是思亲念旧，\n替人悲地愁天。\n吾身在外，\n疫情难返，\n俩妹趋前。\n万苦养儿育女，\n耆年福寿如山。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "968", "title": "七绝·股市瞭望", "genre": "七绝", "date": "2022.01.30", "body": "深绿微红一丑牛，\n年关羞愧不抬头。\n伏身或为迎寅虎，\n期许腾空啸九州。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "969", "title": "七绝·除夕", "genre": "七绝", "date": "2022.01.31", "body": "盈樽守岁夜分年，\n五彩银屏万户欢。\n歌舞迎春寅虎啸，\n转天喜看九州妍。\n祝大家虎年快乐\n吉祥！！！ ​​​", "image_files": ["01.jpg"]}, {"poem_id": "970", "title": "朝中措·别样祝福", "genre": "朝中措", "date": "2022.02.01", "body": "天宫虎啸贺新春，\n激荡亿人心。\n寰宇英雄笑貌，\n今朝分外相亲。\n一元复始，\n万家欢乐，\n天地温馨。\n寒气消春日胜，\n九州四海缤纷。\n祝大家虎年吉\n祥欢乐！[玫瑰][玫瑰][玫瑰] ​​​", "image_files": ["01.jpg"]}, {"poem_id": "971", "title": "蝶恋花·新年乐", "genre": "蝶恋花", "date": "2022.02.02", "body": "精美红包情意表，\n压岁迎春，\n惟愿孙娃好。\n稚脸娇甜频浅笑，\n轻盈眉眼舒心貌。\n刚满一周身段俏，\n胜日来临，\n手舞花灯闹。\n慨叹去年怀里宝，\n今朝无碍穿堂跑。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "972", "title": "七绝·新年感怀", "genre": "七绝", "date": "2022.02.03", "body": "岁月无言奏阕章，\n人生百态韵悠长。\n波涛依旧东流去，\n梅雪迎春绿染香。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "973", "title": "五律·赠师友", "genre": "五律", "date": "2022.02.04", "body": "石门曾共事，\n京邑又相逢。\n天冷心头暖，\n茗香齿底浓。\n慢言传妙理，\n浅盏蕴深情。\n漫漫人生路，\n儿怀渐次明。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "974", "title": "五律·抒怀", "genre": "五律", "date": "2022.02.05", "body": "春回冬奥秀，\n胜友远方来。\n壁垒连番破，\n心胸次第开。\n京张飞雪处，\n旌旆舞云台。\n风卷欢声浪，\n英雄醉染怀。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "975", "title": "蝶恋花·一起向未来", "genre": "蝶恋花", "date": "2022.02.06", "body": "片片雪花萦火炬，\n国号清新，冉冉辉光煦。\n冬奥五环连广宇，\n相思相望今朝聚。\n滑雪溜冰君且去，\n各展风姿，飒爽骄儿女。\n圆梦神州情自许，\n鸟巢惊艳舒心绪。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "976", "title": "蝶恋花·女足夺冠有感", "genre": "蝶恋花", "date": "2022.02.07", "body": "男女足球天与地，\n万丈之差，或在精神气。\n短发娇颜拼勇智，\n油头浪子无心意。\n对待粉丝情态异，\n善策良言，能否融怀里。\n非是金钱成大事，\n惟期革面凝心志。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "977", "title": "七绝·童真", "genre": "七绝", "date": "2022.02.08", "body": "虎娃高唱鸟巢惊，\n一缕清新华夏风。\n山里纯真呼远客，\n童音迢递九州情。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "978", "title": "蝶恋花·逐梦", "genre": "蝶恋花", "date": "2022.02.09", "body": "顾盼新年年过了，\n转眼春来，又见人行早。\n追梦逐天抛父老，\n心中景色知多少。\n南北穿梭如雀鸟，\n不畏风寒，日暮栖枝杪。\n冷气袭来惊梦晓，\n争飞振羽云空渺。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "979", "title": "蝶恋花·冬奥趣", "genre": "蝶恋花", "date": "2022.02.10", "body": "萌俏冰墩诚可爱，\n眉眼情浓，一副娇憨态。\n自是吉祥添异彩，\n怎能不被人青睐。\n一个难求堪奥赛，\n百计千方，且为儿孙带。\n更有佳宾来域外，\n还乡生怕亲朋怪。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "980", "title": "采桑子·冠军随想", "genre": "采桑子", "date": "2022.02.11", "body": "功成岂有寻常事。\n不立恒心，\n不付千辛，\n铁杵无缘作绣针。\n羡人励己从今日。\n俯首凝神，\n寸土耕耘，\n终会花香万里春。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "981", "title": "七绝·岁初闲吟", "genre": "七绝", "date": "2022.02.12", "body": "年来玉虎啸春风，\n放眼五洲谁与同。\n无奈躺平浑不醒，\n新冠难问是归程。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "982", "title": "浣溪沙·叹春雪", "genre": "浣溪沙", "date": "2022.02.13", "body": "春晓风寒玉粟飞，\n空庭晨练冷潮摧。\n枝鸦瑟瑟泣声微。\n残雪刚溶冰又厚，\n东君欲放蕊还悲。\n云空何日映新辉？ ​​​", "image_files": ["01.jpg"]}, {"poem_id": "983", "title": "庆春泽·月将圆", "genre": "庆春泽", "date": "2022.02.14", "body": "楼角红灯相映，交火树银花，宿鸦难定。天暮谢余辉，霄寒云冷。月夜朦胧，玉台泛清影。\n新年气色犹胜，娇孙女情浓，颜欢随性。常甚喜于怀，凭栏观景，手舞眉扬，靥甜笑声永。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "984", "title": "太常引·元宵吟", "genre": "太常引", "date": "2022.02.15", "body": "虎年遭遇倒春寒，\n雪地映苍天。\n风起卷青烟。\n更蟾冷，\n姮娥喟然。\n花灯寂寞，\n鱼龙慨叹。\n倩女俊郎烦，\n苦向柳梢看。\n共期许，\n悠悠梦欢。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "985", "title": "七绝·元夕", "genre": "七绝", "date": "2022.02.16", "body": "可怜寅虎初圆月，\n雪映花灯少热情。\n巷陌匆匆行走客，\n裘裳紧裹避寒风。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "986", "title": "七律·域外风云", "genre": "七律", "date": "2022.02.17", "body": "烟笼俄乌看客多，\n心怀各色起秧歌。\n一声锣鼓媒婆跳，\n数列幡旗醉汉说。\n乱舞刀枪夸友善，\n巧言生死搅山河。\n终究闪电能来否，\n谁道雷公忍几何。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "987", "title": "蝶恋花·好客神州", "genre": "蝶恋花", "date": "2022.02.18", "body": "京北春寒冬奥热，\n飞雪凌空，帅酷骄姿落。\n冰上轻盈情脉脉，\n晶台频闪金银色。\n各路英豪皆忘我，\n语暖言周，处处情如火。\n赛事无忧心不忑，\n泪眸回首神难舍。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "988", "title": "踏莎行·爱凌飞渡", "genre": "踏莎行", "date": "2022.02.19", "body": "多少艰辛，\n高低飞越。\n钟情万岭千山雪。\n非常苦乐溢云空，\n无穷信念溶心血。\n往日之功，\n今朝一跃。\n人惊鸟啭欢声烈。\n梦中夙愿映神州，\n青春无悔鸣新阕。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "989", "title": "五绝·远行", "genre": "五绝", "date": "2022.02.20", "body": "京都寒欲尽，\n却向冷疆行。\n携手孙娃去，\n缘圆母女情。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "990", "title": "踏莎行·难忘北京", "genre": "踏莎行", "date": "2022.02.21", "body": "精彩绝伦，\n欢声雷动。\n赤蓝光色辉相映。\n折杨赠柳话今朝，\n依依不舍心潮涌。\n双奥之城，\n万家称颂。\n不分中外情思共。\n五洲携手未来寻，\n更高更快齐追梦。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg", "04.jpg"]}, {"poem_id": "991", "title": "朝中措·孙女乘机", "genre": "朝中措", "date": "2022.02.22", "body": "飞行初次不觉生，\n玩乐在云空。\n昂首前张后望，\n与人满目春风。\n吱呀乱语，\n开心手舞，\n稚脸轻盈。\n最是平安落地，\n新奇无限频惊。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "992", "title": "踏莎行·迷向", "genre": "踏莎行", "date": "2022.02.23", "body": "南北门翻，\n东西墙换。\n初来乍到神思乱。\n定睛日月绪微清，\n转头几案违心愿。\n睡后无忧，\n醒来总眩。\n脑中自斗天昏暗。\n何如故里旧蓬窗，\n不分宵昼星光灿。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "993", "title": "太常引·边关闲问", "genre": "太常引", "date": "2022.02.24", "body": "鬓霜谁料尚西行，\n春日到边城。\n残雪未消溶。\n冷潮甚，\n丝丝北风。\n轻尘薄雾，\n云烟缭绕，\n不似旧心情。\n何日絮飞萦，\n花草翠，\n亭台暖晴。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "994", "title": "七绝·悲叹", "genre": "七绝", "date": "2022.02.25", "body": "头领跳梁如演戏，\n可怜百姓街头泣。\n蚍蜉撼树耍聪明，\n一阵风来难自立。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "995", "title": "七绝·边城吟", "genre": "七绝", "date": "2022.02.26", "body": "昔时荒漠无毛地，\n今日高楼连片立。\n回汉炊烟袅碧空，\n闲庭鸟雀欢情溢。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "996", "title": "朝中措·西域风色", "genre": "朝中措", "date": "2022.02.27", "body": "边城初逛大巴扎，\n春日碧云霞。\n丝路风光荟萃，\n葡萄美酒人夸。\n香馕烤肉，\n豹裘皮帽，\n茶奶梨瓜。\n农牧交融于此，\n新疆故土繁华。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg", "04.jpg", "05.jpg", "06.jpg"]}, {"poem_id": "997", "title": "菩萨蛮·迪化灯会", "genre": "菩萨蛮", "date": "2022.02.28", "body": "春宵梦幻如仙境，\n冰灯火树霓虹影。\n玉虎啸寒空，\n金牛卧雪中。\n银星天璀璨，\n华夜嫦娥叹。\n应悔一时贪，\n无缘尘世欢。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg", "04.jpg", "05.jpg", "06.jpg"]}, {"poem_id": "998", "title": "七绝·随感", "genre": "七绝", "date": "2022.03.01", "body": "因果相随尘世间，\n识人辨事莫心偏。\n周思慎语云空阔，\n独处纵游天地宽。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "999", "title": "五律·咏新疆", "genre": "五律", "date": "2022.03.02", "body": "昔时边塞苦，\n今日酒花香。\n喜见楼林立，\n欣闻鸟啭长。\n牛羊芳草地，\n巷陌丽云光。\n放眼天山秀，\n伊梨水润疆。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1000", "title": "五律·边城吟", "genre": "五律", "date": "2022.03.03", "body": "故乡天已暮，\n此地日高悬。\n相距八千里，\n飞来一瞬间。\n春风还未至，\n残雪尚依然。\n不见东君影，\n百花谁敢言。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1001", "title": "七绝·龙抬头", "genre": "七绝", "date": "2022.03.04", "body": "神龙昂首傲长天，\n日月远迎霄汉间。\n俯瞰九州山水秀，\n烟霞袅袅百花妍。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1002", "title": "朝中措·闲看风云", "genre": "朝中措", "date": "2022.03.05", "body": "一番操作世人惊，\n呆看假文明。\n封你自由言论，\n钱财落己囊中。\n何来公理，\n诸君莫问，\n霜道无穷。\n虚伪天花乱坠，\n野林谁敢不从。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1003", "title": "清平乐·春日感怀", "genre": "清平乐", "date": "2022.03.06", "body": "盲人点火，\n炬焰花中卧。\n残奥迎春情脉脉，\n期待英姿硕果。\n欣逢两会齐开，\n悠悠紫气东来。\n华夏云空晴丽，\n巨龙昂首舒怀。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1004", "title": "七绝·闲思", "genre": "七绝", "date": "2022.03.07", "body": "众人多角感烟云，\n凉热自知凭本心。\n莫道他言非我意，\n实情未必己为真。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1005", "title": "朝中措·新女性", "genre": "朝中措", "date": "2022.03.08", "body": "寻常浅靥黛眉长，\n今日更悠扬。\n自信人生满满，\n茫茫尘世流芳。\n门厅内外，\n持家执业，\n妙手留香。\n无愧青天半面，\n宛如闪闪星光。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1006", "title": "太常引·边地初春", "genre": "太常引", "date": "2022.03.09", "body": "背阴残雪渐消融，\n晨晓起春风。\n阳处草初青。\n见枝鸟，\n柔音嫩声。\n长裘辞退，\n棉靴别后，\n顿感意轻松。\n闲望碧云空，\n纸鸢闹，\n争翔趣浓。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1007", "title": "朝中措·遥念", "genre": "朝中措", "date": "2022.03.10", "body": "边城初到故人稀，\n夜里费神思。\n总把双亲梦念，\n苍颜斑鬓飞丝。\n隔天通话，\n情传千里，\n语暖心池。\n更喜春回老院，\n厅堂一派生机。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1008", "title": "七绝·边城初春", "genre": "七绝", "date": "2022.03.11", "body": "草芽嫩色有还无，\n莺燕初飞细语酥。\n仰面舒怀心欲醉，\n云霄深处舞宏图。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1009", "title": "踏莎行·世事有感", "genre": "踏莎行", "date": "2022.03.12", "body": "真假难分，\n言行各异。\n丛林难讲公平理。\n豺狼当道乱无穷，\n良人多有烦心事。\n宇宙风云，\n尘间非是。\n阴阳两面常交替。\n凭栏远望绪难安，\n强身之外无他计。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg", "04.jpg"]}, {"poem_id": "1010", "title": "鹧鸪天·观屏有感", "genre": "鹧鸪天", "date": "2022.03.13", "body": "遥望银滩，\n梦思兄弟。\n海都花苑盈春气。\n南腔北调客相逢，\n东拉西扯心无忌。\n丽水人家，\n乳山福地。\n蝶飞莺舞云霞丽。\n隔空万里百花香，\n海鲜风味凭栏忆。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "1011", "title": "五律·边城眺望", "genre": "五律", "date": "2022.03.14", "body": "昔日天山远，\n今朝映眼前。\n东西峰岭秀，\n日月照清寒。\n畅想瑶池景，\n盛传卧雪莲。\n风光独到处，\n王母宴群仙。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "1012", "title": "朝中措·宇宙风云", "genre": "朝中措", "date": "2022.03.15", "body": "狼烟漫卷暗尘寰，\n蔽日苦难言。\n谁点干柴烈火，\n奈何魔鬼摇幡。\n丛林豺豹，\n恃强凌弱，\n为霸多端。\n呼唤武松打虎，\n景阳山静人安。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1013", "title": "太常引·孙女逛街", "genre": "太常引", "date": "2022.03.16", "body": "频挥小手路人欢，\n灵气溢眉间，\n稚脸靥娇圆。\n嫩声语，\n摇身向前。\n不时张望，\n同龄拥抱，\n闹处喜流连。\n过客扭头看，\n惊赞许，\n回身笑言。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "1014", "title": "七绝·罗马交锋", "genre": "七绝", "date": "2022.03.17", "body": "​手翻云雨渐失灵，\n怎耐东方有巨龙。\n鹿马混淆天下乱，\n一朝人破世难容。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1015", "title": "七绝·吟望", "genre": "七绝", "date": "2022.03.18", "body": "三月边城未见花，\n枝头残叶映人家。\n天涯路远春风怨，\n便是迟来莫怪她。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1016", "title": "七绝·倒春寒", "genre": "七绝", "date": "2022.03.19", "body": "劲风吹却初阳暖，\n雨雪袭来冷画栏。\n雾浪云涛天欲暮，\n树梢孤雀与谁言。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "1017", "title": "踏莎行·寰宇吟望", "genre": "踏莎行", "date": "2022.03.20", "body": "邻里失和，\n贼人拱火。\n手摇蒲扇情怀恶。\n斜眉歪嘴映私心，\n黑白颠倒遮非过。\n谎语花言，\n拉帮结伙。\n虚声造势分敌我。\n不嫌事大搅浑天，\n呼云蔽日终遭唾。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1018", "title": "浣溪沙·观屏有感", "genre": "浣溪沙", "date": "2022.03.21", "body": "论事抒怀各自言，\n争鸣心态且从宽。\n抬头遥望共云天。\n日月轮回恒有道，\n星辰明灭瞬时间。\n人生谁可越千年。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1019", "title": "朝中措·悼空难同胞", "genre": "朝中措", "date": "2022.03.22", "body": "银鹰折翅九州悲，\n多少泪花飞。\n春日晴天霹雳，\n寒风漫卷惊雷。\n痛心无限，\n凝眸回首，\n逝者难追。\n生命从来无价，\n寻常珍重休违。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1020", "title": "七律·随感", "genre": "七律", "date": "2022.03.23", "body": "舆情时事静思观，\n遥望方能透远山。\n莫信他人酸辣语，\n且凭自己悟辛甘。\n是非总会明天下，\n真假终究映眼前。\n别有用心今者众，\n多从域外起谣言。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1021", "title": "五律·边城春雪", "genre": "五律", "date": "2022.03.24", "body": "楼高气色深，\n银粟覆芳茵。\n曲径人稀少，\n华亭隐鸟痕。\n寻常童稚闹，\n今日断清音。\n春院花无影，\n庭失草木魂。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1022", "title": "南乡子·空难寄怀", "genre": "南乡子", "date": "2022.03.25", "body": "近日暗伤神，\n遥望搜寻欲断魂。\n荒岭野原将踏遍，\n寒心，\n残片凄凄不见人。\n风雨卷乌云，\n万里家亲泪眼深。\n以为寻常别又聚，\n难吞，\n此后阴阳两处分。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1023", "title": "减字木兰花·丛林乱象", "genre": "减字木兰花", "date": "2022.03.26", "body": "妖魔共舞，\n尘世人间能不苦。\n暮打朝拉，\n为利食言最数它。\n横行欺霸，\n怎奈神龙浑不怕。\n妄想独尊，\n日渐西山气色沉。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1024", "title": "七绝·赏玉随感", "genre": "七绝", "date": "2022.03.27", "body": "宝石翡翠夺人目，\n圆润晶莹闪异光。\n璧玉深藏凭慧眼，\n可怜和氏久悲伤。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "1025", "title": "太常引·迪化初雨", "genre": "太常引", "date": "2022.03.28", "body": "廉纤丝雨润边城，\n暮色掩春情。\n宵夜静无声。\n月西坠，\n天晴梦惊。\n阶前草嫩，\n泥虫渐醒，\n树杪舞啼莺。\n拂面晓风轻。\n还几日，\n繁花竞明？ ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1026", "title": "七绝·闻事闲吟", "genre": "七绝", "date": "2022.03.29", "body": "覆水难收自古今，\n恶言相向冷人心。\n一时口快终生恨，\n遇事三思巧作君。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1027", "title": "采桑子·春日有约", "genre": "采桑子", "date": "2022.03.30", "body": "故人招我樽前聚。\n千里传声，\n一片深情。\n意绪欣然却不能。\n且凭鸿雁凌空去。\n人在边城，\n思念无穷。\n日后还乡醉五更。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1028", "title": "太常引·故乡新友", "genre": "太常引", "date": "2022.03.31", "body": "几碟小菜恁悠闲，\n谈笑望云天。\n初坐似从前。\n巧相遇，\n浮生有缘。\n同乡河北，\n情怀趋近，\n边地度流年。\n交往悦心田。\n茶胜酒，\n香浓味甘。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1029", "title": "七绝·闲吟", "genre": "七绝", "date": "2022.04.01", "body": "半吊司机路跑偏，\n弃邻拜鬼怨苍天。\n不闻乘客心头苦，\n媚眼西方闯险关。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1030", "title": "太常引·春院一瞥", "genre": "太常引", "date": "2022.04.02", "body": "春来童稚尽开颜。\n时聚院堂前，\n娇靥映眉欢。\n踏滑板，\n前驱后翻。\n旋梯飞舞，\n招猫戏狗，\n纤手荡秋千。\n莺燕啭枝边。\n情不尽，\n欣欣乐园。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "1031", "title": "七律·疆塞寄思", "genre": "七律", "date": "2022.04.03", "body": "春到清明未见花，\n边城寂落似天涯。\n枯枝残叶盈人眼，\n冷月寒星照客家。\n梦里山村桃李秀，\n乡中朋侣醉烟霞。\n上坟纸火郊原烈，\n祭祖思亲敬酒茶。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1032", "title": "浣溪沙·祖孙暂别", "genre": "浣溪沙", "date": "2022.04.04", "body": "念老还乡娃不知，\n寻常娇笑对分离。\n明眸浅靥惹人思。\n春日芳园花竞放，\n此间乖宝胜花枝。\n奈何爷奶鬓添丝。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg", "04.jpg"]}, {"poem_id": "1033", "title": "七绝·清明", "genre": "七绝", "date": "2022.04.05", "body": "辗转晨昏夜半归，\n凌空越岭促云飞。\n回乡祭祖随心愿，\n故里春风暖日晖。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "1034", "title": "太常引·神州防疫", "genre": "太常引", "date": "2022.04.06", "body": "且凭绿码过乡关。\n堪验手机端，\n开口测核酸。\n疫情紧，\n群防自安。\n白衣天使，\n辛劳假日，\n昼夜苦难眠。\n情暖九州天。\n诚可敬，\n当今世间。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "1035", "title": "七绝·闲题", "genre": "七绝", "date": "2022.04.07", "body": "丐帮之主口悬河，\n望月贪天梦境多。\n唤雨支风嗔玉帝，\n醒来依旧傍鸡窝。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1036", "title": "蝶恋花·春日寄怀", "genre": "蝶恋花", "date": "2022.04.08", "body": "回到家乡心底畅。\n风暖空明，庭院飞花浪。\n紫粉黄红相竞放，\n疫情难阻春波漾。\n尽日鹊莺窗下唱。\n来去无忧，彩翼凭人望。\n伫立凝眸思绪旷，\n芳菲满眼神魂爽。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "1037", "title": "蝶恋花·父高寿", "genre": "蝶恋花", "date": "2022.04.09", "body": "目不识丁身手巧。\n口快心良，\n嗓大鞋偏小。\n耋耄之年人尚好，\n苍颜耳背家中宝。\n午宴庆生筹划早。\n晚辈奔忙，\n各把真情表。\n满院生机春不老，\n舒怀父母儿孙俏。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1038", "title": "鹧鸪天·春晓吟", "genre": "鹧鸪天", "date": "2022.04.10", "body": "冷暖宜人四月天，\n清明过后草如烟。\n杏红桃粉云天碧，\n燕舞莺鸣竞纸鸢。\n杨絮乱，李花妍。\n归鸦栖树夜深眠。\n晓来风色天光好，\n郊野游人阡陌欢。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1039", "title": "蝶恋花·春趣", "genre": "蝶恋花", "date": "2022.04.11", "body": "姑嫂踏青寻野菜。\n入眼桃花，\n摇曳随风摆。\n朵朵轻盈蜂不怪，\n撩人思绪青霄外。\n望里碧空云自在。\n回首弯腰，\n葱翠心头快。\n纤手摘来香满袋，\n午餐饺子招人爱。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "1040", "title": "七律·亲情", "genre": "七律", "date": "2022.04.12", "body": "相思相念最伤神，\n游子双亲望断魂。\n父沐冬阳心不暖，\n儿逢春色苦为人。\n却从相见眉头俏，\n便总欣闻鹊啭音。\n疑病如云九霄散，\n花开朝暮笑容频。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1041", "title": "七绝·春晓吟行", "genre": "七绝", "date": "2022.04.13", "body": "夜雨无心翠色生，\n晓风花绽露娇容。\n红阳冉冉云天外，\n郊野芳香缓步行。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1042", "title": "点绛唇·暮春夜吟", "genre": "点绛唇", "date": "2022.04.14", "body": "明月清风，\n良宵一刻千般好。\n凭栏远眺，\n银汉星河俏。\n院静心闲，\n惟恐春将老。\n情难了。\n花红又少，\n惊鹊枝头闹。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1043", "title": "七绝·赏文赠友", "genre": "七绝", "date": "2022.04.15", "body": "字句珠玑胜似金，\n奈何拜票苦衷心。\n宜凭杯酒云台醉，\n闲看银霄月起沉。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1044", "title": "鹧鸪天·遣兴", "genre": "鹧鸪天", "date": "2022.04.16", "body": "花甲斑颜未老心，\n晨昏两练久强身。\n秋冬不畏风霜苦，\n春夏尤觉雨露亲。\n翻卷卧，挺直蹲。\n单双杠上笑晴阴。\n繁花翠柳凝神望，\n飞鸟回头探个真。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1045", "title": "踏莎行·巡宇归来", "genre": "踏莎行", "date": "2022.04.17", "body": "半载飞天，\n三杰落地。\n东风激荡英雄气。\n神舟万里客安归，\n鲜花朵朵欢声溢。\n亿万人观，\n无穷情寄。\n莺歌燕舞云霄丽。\n高空巨伞绪飘飘，\n草原怀抱深深意。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "1046", "title": "七绝·遥看", "genre": "七绝", "date": "2022.04.18", "body": "临屏万里望孙娃，\n两眼晶莹一朵花。\n雨润云娇飞鸟悦，\n春风桃李映朝霞。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "1047", "title": "太常引·春岸吟", "genre": "太常引", "date": "2022.04.19", "body": "民心河水漾清波，\n草岸柳婆娑。\n莺鹊踏枝歌。\n晓风细，\n红欣翠多。\n春回大地，\n云祥日丽，\n花影妙音和。\n晨练乐呵呵。\n心无虑，\n阴晴奈何。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "1048", "title": "七绝·谷雨春望", "genre": "七绝", "date": "2022.04.20", "body": "草木欣欣花色艳，\n枝头翠鸟清音啭。\n田间谷物嫩芽生，\n春笋香茶谁不羡！ ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "1049", "title": "鹧鸪天·遥望闲吟", "genre": "鹧鸪天", "date": "2022.04.21", "body": "暴雨袭来鸟雀惊，\n危巢难耐对狂风。\n残枝败叶随天去，\n云卷雷劈电闪鸣。\n家道破，念思空。\n梦宵悲断苦求生。\n蓬头乱撞无着处，\n魂魄凄迷失北东。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1050", "title": "鹧鸪天·对酒当歌", "genre": "鹧鸪天", "date": "2022.04.22", "body": "逆旅人生且向前，\n犹如溪水下高山。\n历经坎坷心无悔，\n漫度春秋气不残。\n悲复乐，苦含甜。\n世间百味自缠绵。\n万千财物终消去，\n惟有声名殢远天。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1051", "title": "七绝·闻事吟", "genre": "七绝", "date": "2022.04.23", "body": "风云叵测且由天，\n道路尽头宜转弯。\n莫撞南墙生悔恨，\n谨行远眺度关山。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1052", "title": "七绝·主仆怨", "genre": "七绝", "date": "2022.04.24", "body": "舞棒弄枪伤己身，\n家奴远看暗销魂。\n不知南北如何是，\n乱起风烟天地昏。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1053", "title": "五律·听与看", "genre": "五律", "date": "2022.04.25", "body": "遇事两边听，\n切毋凭感情。\n书生多意气，\n自古少英雄。\n常陷蜗牛角，\n鲜闻海浪声。\n倘如埋首看，\n难见碧云空。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1054", "title": "蝶恋花·殃及池鱼", "genre": "蝶恋花", "date": "2022.04.26", "body": "股市风云谁搅动？\n绿劲红衰，\n多少人生痛。\n一路狂奔留暗影，\n似花零落心难静。\n往日春来牛市盛。\n却是今朝，\n熊势波涛涌。\n战火未休魂不定，\n金牛无奈情难纵。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1055", "title": "蝶恋花·河边春趣", "genre": "蝶恋花", "date": "2022.04.27", "body": "春暮绿阴多几许。\n落絮飘香，\n时见飞红雨。\n莺鹊同欢枝杪聚，\n城河戏水鸳鸯侣。\n岸柳风摇丝缕缕。\n影动鱼争，\n情惹寻花女。\n伫立凝眸盈笑语，\n凭栏俯首思吟句。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1056", "title": "七绝·赠同窗", "genre": "七绝", "date": "2022.04.28", "body": "笔歌盛世颂新春，\n酣畅抒怀墨色珍。\n挚友欣闻吟百遍，\n何须陌路客倾心。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1057", "title": "太常引·惜春", "genre": "太常引", "date": "2022.04.29", "body": "暮春晓雨落花风，\n一并卷红英。\n鸦雀亦伤情。\n怎无奈，\n枝头泣鸣。\n朝夕相伴，\n而今别去，\n何日再重逢。\n愁啭送君行。\n从此后，\n难寻俏容。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1058", "title": "七绝·闲看水军", "genre": "七绝", "date": "2022.04.30", "body": "假作真时心里怕，\n无为有处夜来惊。\n撕去伪装皆丑态，\n魅魑魍魉露原形。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1059", "title": "浣溪沙·五一寄怀", "genre": "浣溪沙", "date": "2022.05.01", "body": "劳者今朝气自扬，\n披红昂首入厅堂。\n身心陶醉焕荣光。\n五月来临风色好，\n三春将尽果蔬香。\n花开月季久芬芳。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "1060", "title": "七绝·错位", "genre": "七绝", "date": "2022.05.02", "body": "千里相投作演员，\n惊神瞥眼给谁看。\n自家琴瑟无心奏，\n醉恋他人破管弦。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1061", "title": "五律·问春", "genre": "五律", "date": "2022.05.03", "body": "春归何处去，\n把酒问东风。\n悲为花零落，\n愁于鸟泣鸣。\n林空失丽色，\n山水少清莹。\n谁若能留驻，\n金樽敬不停。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1062", "title": "清平乐·寄怀", "genre": "清平乐", "date": "2022.05.04", "body": "百年五四，\n跌宕风云起。\n夏华曾经多少事，\n换了山河天地。\n九州盛世今朝，\n东方屹立情豪。\n更借天宫远望，\n神龙四海逍遥。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1063", "title": "七绝·立夏", "genre": "七绝", "date": "2022.05.05", "body": "春花零落夏风来，\n飞絮消停月季开。\n草树浓阴蛙戏水，\n芰荷漫舞尽舒怀。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1064", "title": "七绝·中风", "genre": "七绝", "date": "2022.05.06", "body": "处事不公遭众怨，\n言谈失理落人嫌。\n本应手脚同凉热，\n却是心歪嘴眼偏。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "1065", "title": "七绝·老父亲种菜", "genre": "七绝", "date": "2022.05.07", "body": "小院阶前腾一角，\n种瓜点豆老来忙。\n葱葱郁郁苍颜乐，\n轻汗舒身饭菜香。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1066", "title": "七绝·母亲节寄怀", "genre": "七绝", "date": "2022.05.08", "body": "妈在家馨饭菜香，\n晚归早起任匆忙。\n粥汤盈碗心头暖，\n尘世忧烦一扫光。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "1067", "title": "太常引·勿忘国耻", "genre": "太常引", "date": "2022.05.09", "body": "当年恶意却虚称，\n欺世隐真情，\n我自愤难平。\n恨贼子，狂言横行。\n忍悲自励，\n军民苦奋，\n华夏唱英雄。\n劲舞仗东风。\n傲寰宇，冲天巨龙。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "1068", "title": "七绝·观阅兵有寄", "genre": "七绝", "date": "2022.05.10", "body": "以子之心度普京，\n犹如蝼蚁望长城。\n狂风恶雨拂墙过，\n难损秦砖质地青。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "1069", "title": "唐多令·芳华竞度", "genre": "唐多令", "date": "2022.05.11", "body": "盛世正青春，\n欣欣当代人。\n展情怀，筑业为民。\n心向神州肝胆赤，\n蔑雨雪，傲风云。\n万漉聚沙金，\n千锤锻铁身。\n烈火中，铸造忠魂。\n山海江河君自笑，\n波浪里，抖精神。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1070", "title": "七绝·赠韦东奕", "genre": "七绝", "date": "2022.05.12", "body": "数字盈心织锦绣，\n指尖符合写春秋。\n天惊地叹堪神异，\n当代奇才耀九州。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg", "04.jpg", "05.jpg", "06.jpg"]}, {"poem_id": "1071", "title": "五绝·夏夜吟", "genre": "五绝", "date": "2022.05.13", "body": "连日阴天雨，\n夏初风色寒。\n犹闻疫情紧，\n入夜苦难眠。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1072", "title": "七律·雨霁花娇", "genre": "七律", "date": "2022.05.14", "body": "雨过空明月季鲜，\n粉黄映翠玉珠圆。\n红砖幽径千娇美，\n绿叶纤枝一色妍，\n飞鸟争鸣音调脆。\n游人漫步笑声连，\n春归渐远情难老，\n夏日风光醉眼前。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "1073", "title": "七绝·和行者老弟", "genre": "七绝", "date": "2022.05.15", "body": "人生一世似征蓬，\n凭借南来北往风。\n海角天涯追日月，\n瑶台圣境笑仙翁。\n七绝           随感\n常万行者\n岁临六十又飘蓬，\n也遇尘霾也遇风。\n幸得两三知己伴，\n珍馐百里犒衰翁。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1074", "title": "阮郎归·赠天吉", "genre": "阮郎归", "date": "2022.05.16", "body": "挥毫泼墨写春秋，\n不觉霜染头。\n珠玑词字万人求，\n意情风韵流。\n携朋侣，藐公侯。\n乐于山水游。\n时光飞逝雅名留，\n书香胜馔馐。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "1075", "title": "江城子·赠维真", "genre": "江城子", "date": "2022.05.17", "body": "征文竞榜动亲朋。\n聚银屏，力无穷。\n点赞欢呼，\n久久意情浓。\n冉冉新星初耀眼。\n风月里，闪光明。\n笔歌盛世亿家宁。\n唱繁荣，颂安平。\n万众争传，\n江海喜盈盈。\n水秀山青莺鹊舞。\n天远阔，地深情。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1076", "title": "西江月·故友重逢", "genre": "西江月", "date": "2022.05.18", "body": "前日归休五载，\n今朝相聚一餐。\n深情怎不玉樽干。\n回首沉思无限。\n多少难眠共月，\n曾经至乐同天。\n并肩携手越关山。\n远处斗明星闪。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1077", "title": "七绝·赠老友", "genre": "七绝", "date": "2022.05.19", "body": "故朋小聚热衷肠，\n厚意深情赖酒量。\n欲止又言多少事，\n蕲福祷愿玉樽藏。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1078", "title": "七绝·大爱无声", "genre": "七绝", "date": "2022.05.20", "body": "挚爱深沉语却难，\n真情无限隐心田。\n犹如江海胸怀阔，\n归纳百川谁与言。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1079", "title": "阮郎归·小满吟", "genre": "阮郎归", "date": "2022.05.21", "body": "垄禾浆满柳鸣蝉，\n薰风吻麦田。\n穗头摇拽籽青圆。\n农家喜梦眠。\n楼欲立，瓦飞檐。\n朱门立院前。\n儿孙嘻闹画堂边，\n寻常似过年。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1080", "title": "七绝·闲吟", "genre": "七绝", "date": "2022.05.22", "body": "人生小满梦初成，\n寡欲闲心乐自生。\n日月无忧晖永曜，\n山溪高处水云青。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1081", "title": "浣溪沙·农家晚景", "genre": "浣溪沙", "date": "2022.05.23", "body": "初夏黄昏小院幽，\n层云漫卷细风流。\n几声远吠过墙头。\n落日斜晖风色好，\n酒香余味绕唇喉。\n阶前闲坐更何求。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1082", "title": "七绝·奇事", "genre": "七绝", "date": "2022.05.24", "body": "好心却咽伤心果，\n人性凭颜岂可知。\n当代农夫未生恨，\n如蛇妖女害家妻。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1083", "title": "七绝·赠马飞", "genre": "七绝", "date": "2022.05.25", "body": "种瓜点豆神农事，\n医者种牙今日忙。\n妙手解除餐咀苦，\n言周技湛暖人肠。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1084", "title": "踏莎行·夏日晚霞", "genre": "踏莎行", "date": "2022.05.26", "body": "落日熔金，\n层林染翠。\n长空万里千山媚。\n赤橙黄绿彩云飞，\n丹青妙手谁能绘。\n人造失真，\n天然可贵。\n琼枝玉叶娇姿美。\n风光无限惹闲情，\n凭栏颙望心神醉。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1085", "title": "破阵子·警惕贼子", "genre": "破阵子", "date": "2022.05.27", "body": "血债未偿难忘，\n又闻挑衅狂言。\n贼寇北约频舞爪，\n欲向神州台海湾。\n以为似旧年。\n华夏军民警惕，\n东风远胜从前。\n胆敢举足插手处，\n马仰人翻不许还。\n一朝雪耻烦。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1086", "title": "七绝·阖家欢", "genre": "七绝", "date": "2022.05.28", "body": "妈妈生日女儿娇，\n两眼不停瞄蛋糕。\n只待烛光星火起，\n鲜香入口乐滔滔。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "1087", "title": "太常引·赠维珍", "genre": "太常引", "date": "2022.05.29", "body": "老来回味少时情，\n最忆是军营。\n豪迈远山行。\n野芜处，黄沙北风。\n长年操练，\n争时自奋。\n枕畔弄书声，\n星月映窗灯。\n换今日，心闲笔耕。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1088", "title": "蝶恋花·当心被骗", "genre": "蝶恋花", "date": "2022.05.30", "body": "开口胡诌遭打脸，\n搔首装聋，或许真瞎眼。\n芳草萋萋独不见，\n光天化日心头暗。\n天上风云须细判，\n岂可蒙人，风雨言晴灿。\n闻者有心凭己断，\n经行莫被泥沟陷。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1089", "title": "五绝·咏竹", "genre": "五绝", "date": "2022.05.31", "body": "心有凌云志，\n无言逐日高。\n当初人不见，\n隐忍秀今朝。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1090", "title": "菩萨蛮·六一孙女乐", "genre": "菩萨蛮", "date": "2022.06.01", "body": "去年今日怀中抱，\n此时早已穿堂闹。\n蹦跳又登高，\n可怜身体娇。\n寻常多少事，\n灵巧心中记。\n出外一枝花，\n相逢邻里夸。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg", "04.jpg"]}, {"poem_id": "1091", "title": "阮郎归·童趣", "genre": "阮郎归", "date": "2022.06.02", "body": "凭添玩具喜娇童，\n初尝意趣浓。\n飞车弯道影匆匆，\n高台绿映红。\n纤手快，眼含情。\n往来乐不穷。\n临窗鸟雀探芳厅，\n满堂笑语盈。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1092", "title": "念奴娇·边地归来", "genre": "念奴娇", "date": "2022.06.03", "body": "母携娇女，倚银鹰万里，暂回京邑。\n父女重逢，眉眼动，霎那亲情难抑。\n挚爱相拥，臂托怀抱，酷乐人将泣。\n当初音貌，幼儿今刻还记。\n惬意端午团圆，温馨闲聚，美好同欢忆。\n金海家园烟树下，草木荫浓葱郁。\n豌豆柠檬，前期玩伴，又可齐肩立。\n楼前相见，更添节日惊喜。", "image_files": ["01.jpg", "02.jpg", "03.jpg", "04.jpg"]}, {"poem_id": "1093", "title": "七绝·端午愿", "genre": "七绝", "date": "2022.06.04", "body": "祈祷上苍开慧眼，\n施恩眷顾老来人。\n阖家姐妹三人怨，\n苦待慈萱往日音。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1094", "title": "采桑子·痛", "genre": "采桑子", "date": "2022.06.05", "body": "云空明媚心情重，\n愁绪萦怀，\n挥去还来。\n无尽悲思解不开。\n老人为善疼千忍，\n夜里徘徊，\n不扰儿孩。\n错过良机我辈哀。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1095", "title": "鹧鸪天·神舟又起", "genre": "鹧鸪天", "date": "2022.06.06", "body": "刚过端阳入太空，\n三杰携手驻天宫。\n粽香飘溢姮娥喜，\n银箭穿梭鸟雀迎。\n芒种日，碧霄明。\n无边麦浪映苍穹。\n人间天上齐心力，\n山海神州日月同。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1096", "title": "五绝·登顶", "genre": "五绝", "date": "2022.06.07", "body": "十年窗下苦，\n策马在今朝。\n笔墨犹刀剑，\n扬鞭气势高。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1097", "title": "五绝·逐梦", "genre": "五绝", "date": "2022.06.08", "body": "学子出行早，\n晨星争报晓。\n鹊莺枝杪啼，\n金榜题名号。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1098", "title": "太常引·代妻作", "genre": "太常引", "date": "2022.06.09", "body": "别时暖语胜春风，\n送我九州行。\n两眼恁含情。\n再相见，\n无言病容。\n双眸紧闭，\n呼吸难耐，\n吾辈痛余生。\n惟恨晚来逢。\n愿天许，\n慈萱日宁。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1099", "title": "朝中措·期许", "genre": "朝中措", "date": "2022.06.10", "body": "三天或可定终生，\n几许梦中同。\n多是喜忧参半，\n将行南北西东。\n青春年少，\n苍天不负，\n勿躁神宁。\n四载春秋苦度，\n今朝立志能赢。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1100", "title": "浣溪沙·端午有寄", "genre": "浣溪沙", "date": "2022.06.11", "body": "腌肉今朝入粽鲜，\n不同往日枣微甜。\n醇香盈口绕喉间。\n糯米端阳凭纪念，\n灵均重五怨苍天。\n隐声汨水两千年。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1101", "title": "五绝·人与物", "genre": "五绝", "date": "2022.06.12", "body": "酷夏望秋声，\n寒冬盼暖风。\n江河峰岭异，\n千古自从容。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1102", "title": "七律·冀东凤凰城", "genre": "七律", "date": "2022.06.13", "body": "当年地震起悲哀，\n今日打人涛浪来。\n歌手不堪遭辱禁，\n微商无耐店难开。\n多家倾诉寻常苦，\n一语激发旧怨怀。\n百姓共鸣心里恨，\n警方于事不应该。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1103", "title": "七绝·夏日闲吟", "genre": "七绝", "date": "2022.06.14", "body": "乌鸦麻雀唱双簧，\n摇动羽毛遮太阳。\n炽热天光铺满地，\n无聊乱鸟趁阴凉。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1104", "title": "七绝·遥望有感", "genre": "七绝", "date": "2022.06.15", "body": "风雷激起千层浪，\n水底鱼争蛙鼓鸣。\n昔日乌云暗天地，\n今朝骤雨净尘空。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1105", "title": "蝶恋花·思念", "genre": "蝶恋花", "date": "2022.06.16", "body": "半月卧床从未醒。\n吾辈煎熬，\n哭叫无回应。\n医护匆忙情与共，\n至亲昼夜浑如梦。\n昔日待人多笑影。\n细语轻言，\n邻里皆称颂。\n祈祷苍天怜百姓，\n一朝惊喜心头送。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1106", "title": "七绝·糗事", "genre": "七绝", "date": "2022.06.17", "body": "稻草虚称救命船，\n嘻哈打斗庙堂前。\n政经大事如儿戏，\n贼子谋独枉费钱。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "1107", "title": "踏莎行·贺航母下水", "genre": "踏莎行", "date": "2022.06.18", "body": "昔日辽宁，\n今朝福建。\n山东并作屠龙剑。\n追星逐月下洋洲，\n深蓝所向波涛漫。\n白手持家，\n赤心立愿。\n银鹰弹射撩人眼。\n军民血汗汇江流，\n染红山海云光灿。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "1108", "title": "阮郎归·老父亲", "genre": "阮郎归", "date": "2022.06.19", "body": "近来苦闷不多言，\n时常昼卧眠。\n眼虚耳背对苍颜，\n体衰年复年。\n听不见，字无缘。\n梦宵独自烦。\n却忧晚辈世间难，\n椿庭最可怜。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1109", "title": "七绝·恨", "genre": "七绝", "date": "2022.06.20", "body": "刻意逢迎区外鬼，\n无情丑化自家亲。\n三星堆里灵光现，\n羞煞先贤上古人。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1110", "title": "五绝·夏至吟", "genre": "五绝", "date": "2022.06.21", "body": "暑气愁心躁，\n晚风蝉乱鸣。\n病亲难自语，\n吾辈泣无声。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1111", "title": "七绝·赠友", "genre": "七绝", "date": "2022.06.22", "body": "偶遇相知必有缘，\n银丝回首忆前欢。\n无声岁月风霜去，\n历久情怀似水蓝。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1112", "title": "鹧鸪天·苦待", "genre": "鹧鸪天", "date": "2022.06.23", "body": "积秒成分熬昼宵，\n心怀苦闷绪无着。\n凭栏愁望云空寂，\n欹凳忧听医护招。\n情切切，意滔滔。\n三更风雨打窗绡。\n惟期晓霁乌云远，\n病里家亲醒眼梢。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1113", "title": "七绝·感悟", "genre": "七绝", "date": "2022.06.24", "body": "青壮不知生命短，\n老来悔恨未惜身。\n以钱换物寻常事，\n无价光阴枉费金。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1114", "title": "五律·盼分", "genre": "五律", "date": "2022.06.25", "body": "昨夜众难眠，\n聚眸银幕前。\n家长愁不语，\n学子躁无言。\n屏闪悲和喜，\n神惊地与天。\n各思今后事，\n入梦踏关山。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1115", "title": "七律·贼心", "genre": "七律", "date": "2022.06.26", "body": "与己意合吹上天，\n花腔糊弄宇寰间。\n废除木炭说环保，\n褒奖风光少女言。\n今日自身难兑付，\n昔时她语碍当前。\n此番操作惊尘世，\n盗寇情思不一般。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg", "04.jpg"]}, {"poem_id": "1116", "title": "鹧鸪天·仲夏晚趣", "genre": "鹧鸪天", "date": "2022.06.27", "body": "将暮门南集市兴，\n招呼买卖耳边声。\n果蔬鲜嫩归家喜，\n鱼蟹繁多过道腥。\n宜老少，易轻松。\n唠嗑淘货望西东。\n窝居一日心头闷，\n散步舒怀沐晚风。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1117", "title": "五绝·吟望", "genre": "五绝", "date": "2022.06.28", "body": "一朝霜鬓矣，\n铜镜深情记。\n回首望浮生，\n烟涛风浪里。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1118", "title": "鹧鸪天·其辱当戒", "genre": "鹧鸪天", "date": "2022.06.29", "body": "幕后偷鸡，\n众前撒米。\n盗铃掩耳雕虫技。\n跳梁取辱把人丢，\n此般小丑终遭弃。\n大道羞行，\n偏门楞挤。\n夹头撞脸徒生气。\n改心回首路平宽，\n归宗认祖苍生计。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "1119", "title": "五绝·晓吟", "genre": "五绝", "date": "2022.06.30", "body": "雨过夜清凉，\n星光笼病房。\n愁思人不寐，\n悲绪转衷肠。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1120", "title": "阮郎归·庆七一", "genre": "阮郎归", "date": "2022.07.01", "body": "百年华诞转来年，\n神州奋向前。\n蟾宫往返九霄眠，\n赤旗飞宇间。\n添鹰舰，射星船。\n海空疆域安。\n经商防疫顾禾田，\n苍生许梦圆。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "1121", "title": "临江仙·香江颂", "genre": "临江仙", "date": "2022.07.02", "body": "今日波光清水漾，\n荆花娇艳芬芳。\n二十五载似朝阳。\n阵云遮不住，\n万里放霞光。\n过往狂风携恶雨，\n亦曾零落悲伤。\n红旗高挺且飞扬。\n钟馗扫魅影，\n百姓更安康。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1122", "title": "七绝·赠子玉会友", "genre": "七绝", "date": "2022.07.03", "body": "夏晚吹来渤海风，\n狮乡音韵话深情。\n三年别却思无断，\n玉斝迎朋醉眼胧。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1123", "title": "七绝·吟望", "genre": "七绝", "date": "2022.07.04", "body": "晓来骤雨叶飞声，\n寒浸病房愁梦惊。\n凭望窗前风色暗，\n何时阴影转光明。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1124", "title": "踏莎行·赠友", "genre": "踏莎行", "date": "2022.07.05", "body": "翠柏浓荫，\n苍松茂密。\n晨昏苦练一贤弟。\n英姿飒爽意风发，\n凭空横贯刀枪戟。\n日寇曾来，\n硝烟滚去。\n虎林此乃英雄地。\n今朝不可忘当年，\n悠闲岁月强筋体。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1125", "title": "踏莎行·乳山晚景", "genre": "踏莎行", "date": "2022.07.06", "body": "图画烟云，\n丹青草木。\n浑然山水如天幕。\n红颜翠色两相和，\n入眸养眼君休误。\n威海银滩，\n乳山溪路。\n人生向往绝佳处。\n世间乐土鸟争鸣，\n桃源怎比天仙府。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1126", "title": "南乡子·七七寄怀", "genre": "南乡子", "date": "2022.07.07", "body": "警报刺长空，\n今日神州绪不平。\n回首当年多少恨，\n填膺。\n倭寇卢沟始兽行。\n华夏聚豪英，\n破灭阴霾万里晴。\n不道东瀛兴鬼魅，\n神惊。\n地动山崩怒九龙。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1127", "title": "七律·狼出鬼没", "genre": "七律", "date": "2022.07.08", "body": "又一金毛谢幕前，\n年来玩闹乐翻天。\n脱欧撕裂英伦岛，\n舔美窜游台海湾。\n内丑出新波浪涌，\n外忧依旧雨浇檐。\n猢狲辞树云烟灭，\n残日斜辉没远山。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "1128", "title": "朝中措·赠安倍", "genre": "朝中措", "date": "2022.07.09", "body": "台前幕后两张皮，\n倭寇罪无思。\n拜鬼连番愈甚，\n亦能媚主眉低。\n垂涎钓岛，\n妄言台海，\n醉眼迷离。\n枪响世惊人去，\n是非地与天知。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "1129", "title": "七绝·闻事吟", "genre": "七绝", "date": "2022.07.09", "body": "乡邻好坏己分明，\n喜乐悲伤自有情。\n祖辈当年遭苦难，\n仇家人死恨难平。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1130", "title": "七绝·闲吟", "genre": "七绝", "date": "2022.07.10", "body": "人道三郎赴九泉，\n一心拜鬼鬼前欢。\n狂言台海他家事，\n倭寇阴魂乱世间。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1131", "title": "七绝·午蝉", "genre": "七绝", "date": "2022.07.11", "body": "临窗高柳隐鸣蝉，\n鼓噪长音午不闲。\n撩乱尖声冲入耳，\n凭风得意惹人烦。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1132", "title": "踏莎行·出门有感", "genre": "踏莎行", "date": "2022.07.12", "body": "壮岁持家，\n暮时养老。\n古今此理皆知晓。\n奈何苍鬓染霜丝，\n乡间落拓街头倒。\n或许无亲，\n几多不孝。\n耆年诸事宜谋早。\n惟当体健乐心怀，\n粗餐贫舍疏烦恼。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1133", "title": "鹧鸪天·东瀛一景", "genre": "鹧鸪天", "date": "2022.07.13", "body": "庙宇门前人马稠，\n长枪短炮竞风流。\n争观寺院烟霞晚，\n静待灵车早露头。\n躯体灭，是非留。\n功名成败已无求。\n情分左右声涛半，\n入土难安余者愁。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1134", "title": "蝶恋花·夏日闲吟", "genre": "蝶恋花", "date": "2022.07.14", "body": "倭寇儿孙遭暗算，\n窝里相残，\n魂魄烟云散。\n吾辈惊闻情毕现，\n缘于昨日仇和怨。\n不道有人心绪乱，\n忘祖欺宗，\n秽语污言漫。\n小丑凄声盈泪眼，\n独行渐与神州远。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1135", "title": "七绝·感吟", "genre": "七绝", "date": "2022.07.15", "body": "平日三餐细讲究，\n病床鼻饲味难求。\n世间馐馔千般态，\n身体不支徒自愁。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1136", "title": "采桑子·伏前雨", "genre": "采桑子", "date": "2022.07.16", "body": "多情夏日风兼雨。\n暑气炎消，\n柳翠枝摇。\n不道蝉声何处逃。\n黄昏明霁心怀阔。\n霞色妖娆，\n燕舞云飘。\n庭院清凉爽鬓毛。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1137", "title": "如梦令·祖孙视频", "genre": "如梦令", "date": "2022.07.17", "body": "千里对屏嘻闹，\n爷奶这厢呼叫。\n娇靥语甜甜，\n手舞眉舒情妙。\n花俏，花俏。\n梦里无由频笑。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1138", "title": "七绝·咏茶", "genre": "七绝", "date": "2022.07.18", "body": "居壶不作声，\n遇水恁欢腾。\n眉叶舒心展，\n霎时香气浓。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1139", "title": "鹧鸪天·夏日寄妻", "genre": "鹧鸪天", "date": "2022.07.19", "body": "姐妹三人守病房，\n慈萱不语痛断肠。\n无人能解心头苦，\n愁夜更超前日长。\n居老大，语双方。\n倾心沥血为亲娘。\n命悬一线千般唤，\n祈祷天公降瑞祥。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1140", "title": "七绝·题图", "genre": "七绝", "date": "2022.07.20", "body": "有眼不睁晴亦阴，\n秃眉缺耳恨娘亲。\n鼻塌憋气胸怀恶，\n闭嘴无言狼子心。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1141", "title": "阮郎归·寄妻生日", "genre": "阮郎归", "date": "2022.07.21", "body": "人逢花甲本应休，\n横来万缕愁。\n娘亲病里苦争求，\n身家不自由。\n餐无定，梦常忧。\n霜丝落满头。\n原先盘算付东流。\n奈何多事秋。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1142", "title": "七绝·夏日荷塘", "genre": "七绝", "date": "2022.07.22", "body": "菡萏飞红碧水间，\n婷婷玉立笑长天。\n随风浮起清凉意，\n袅袅云烟向远山。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "1143", "title": "浣溪沙·岳母出院", "genre": "浣溪沙", "date": "2022.07.23", "body": "端午胃疼医护求，\n昏迷未醒卧床头。\n苍天有眼命无忧。\n今日回家须慢养，\n何时开口细交流。\n更期缓步下层楼。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1144", "title": "七绝·愁夜吟", "genre": "七绝", "date": "2022.07.24", "body": "星月萦窗探病亲，\n微光抚慰守床人。\n世间多少愁心事，\n缘自无穷养育恩。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1145", "title": "七律·闻事有感", "genre": "七律", "date": "2022.07.25", "body": "佛门净地藏污垢，\n虚假禅师错念经。\n崇拜钱财朝恶鬼，\n贱伤民众损真情。\n昔时英魄无安处，\n今日秃僧落骂名。\n呼唤悟空千里棒，\n高天劲舞宇寰清。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1146", "title": "朝中措·答谢", "genre": "朝中措", "date": "2022.07.27", "body": "顺缘玉盏映白衣，\n美誉满林西。\n挽救家亲生命\n真情绝技人思。\n回春妙手，\n温馨倍至，\n暖语如丝。\n感动阖家老少，\n举杯漫饮相知。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1147", "title": "太常引·泪别", "genre": "太常引", "date": "2022.07.28", "body": "挥别古冶向石门，\n风色暗沉沉。\n忍泪语家人。\n细照料，\n床头病亲。\n今番探看，\n廉州二老，\n了却念思心。\n惟愿几分身。\n多头顾，\n情长意真。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1148", "title": "清平乐·伏天异", "genre": "清平乐", "date": "2022.07.29", "body": "云霄雨漏，\n夜半凉窗透。\n正是二伏还未够，\n却似秋风盈袖。\n晓来冷意丝丝，\n枝头珠露频滴。\n酷暑今朝不见，\n莫非玉帝营私？ ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1149", "title": "七绝·戏看", "genre": "七绝", "date": "2022.07.30", "body": "引吭曲颈两只鸡，\n失调雌雄东与西。\n疑把海峡当己舍，\n纵身逝水浪花稀。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1150", "title": "五绝·无题", "genre": "五绝", "date": "2022.07.31", "body": "池小纳云天，\n层楼卧水边。\n凡尘多少事，\n只在一心尖。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1151", "title": "五绝·无题", "genre": "五绝", "date": "2022.07.31", "body": "池小纳云天，\n层楼卧水边。\n凡尘多少事，\n只在一心尖。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1152", "title": "采桑子·八一寄怀", "genre": "采桑子", "date": "2022.08.01", "body": "军旗血染星徽艳。\n玖五春秋，\n钢铁洪流。\n反蒋驱倭气势牛。\n梦圆华夏歌声彻。\n将猛兵优，\n万马千舟。\n壮志盈怀宝岛收！ ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "1153", "title": "鹊桥仙·伏天午后", "genre": "鹊桥仙", "date": "2022.08.02", "body": "枝垂叶卷，\n蛙鸣蝉噪。\n悲调催生热浪。\n炎光晴日少飞云，\n便是伫、浓荫不爽。\n午休难睡，\n萦身汗透。\n辗转心烦乱想。\n何如四季总为春，\n凭昼夜、气清风畅。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1154", "title": "七绝·夏夜有感", "genre": "七绝", "date": "2022.08.03", "body": "狂雨夜来风扰楼，\n寒声萧瑟似深秋。\n惟期晓日升腾起，\n万里明霞映九州。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1155", "title": "行香子·情系日月潭", "genre": "行香子", "date": "2022.08.04", "body": "耋耄巫婆，夜落松山。\n讯传来恨满心田。\n咬牙投笔，撕碎银笺。\n火胸中赤，盏中烈，梦中燃。\n台湾宝岛，宵思昼念。\n手足情何止千年。\n遭人虏掠，几次三番。\n盼浪儿归，鱼儿跃，鸟儿欢。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1156", "title": "采桑子·七夕有寄", "genre": "采桑子", "date": "2022.08.04", "body": "鹊仙桥上千年泪。\n岁岁盈眸，\n今又盈眸。\n多少情人两处愁。\n人间长有分离恨。\n门户无忧，\n南北漂流。\n老少来回几度秋。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1157", "title": "五律·吟望", "genre": "五律", "date": "2022.08.05", "body": "位低难看远，\n霜鬓且闲心。\n儒道千年智，\n神州万事新。\n兵家围小岛，\n国策有高人。\n举首登山望，\n垂竿戏水滨。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1158", "title": "鹧鸪天·喜相逢", "genre": "鹧鸪天", "date": "2022.08.06", "body": "别却新疆四月多，\n京城相见靥婀娜。\n头扎小辫身灵动，\n指认图形眼泛波。\n情照旧，态非昨。\n腰枝柔美舞婆娑。\n士别三日惊相看，\n孙女归来燕雀歌。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1159", "title": "踏莎行·立秋吟", "genre": "踏莎行", "date": "2022.08.07", "body": "雨过秋来，\n炎消暑避。\n微风阵阵清凉意。\n寻常晨练喜眉梢，\n更逢旧友舒心气。\n刀剑飞光，\n腰身垂壁。\n高低杠上平衡立。\n且将娱乐不强求，\n原装零件难相替。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1160", "title": "鹧鸪天·夏日吟望", "genre": "鹧鸪天", "date": "2022.08.08", "body": "非是年关烟火浓，\n东南围岛炮声隆。\n无端盗寇滋斜事，\n恶意家奴趁乱风。\n营水阵，降天兵。\n势成圈套锁妖虫。\n独谋激起人神愤，\n贼子焉能叛祖宗。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1161", "title": "七绝·夏日有寄", "genre": "七绝", "date": "2022.08.09", "body": "归来金海碧云亲，\n庭院莺鸣景色新。\n别日娇娃多不语，\n而今个个吐芳音。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1162", "title": "太常引·秋雨风寒", "genre": "太常引", "date": "2022.08.10", "body": "秋来雨后晚风凉，\n薄暮隐斜阳，\n鸦雀宿归忙。\n溽暑去，微微夜长。\n盈眸暗绿，\n清幽庭院，\n霄色泛寒光。\n短袖略心慌，\n天之力，谁人可防！ ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1163", "title": "五绝·情", "genre": "五绝", "date": "2022.08.11", "body": "侍狗如亲子，\n倾心忘老娘。\n漫街闻犬吠，\n苍鬓守空床。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1164", "title": "临江仙·闲吟", "genre": "临江仙", "date": "2022.08.12", "body": "自作聪明人不语。\n花笺指点江山，\n梦中挥剑踏雄关。\n醒来浑不是，\n只在绣床边。\n万马飞奔腾赤兔。\n名留于世千年，\n缘功屡树胜军前。\n高飞凭展翅，\n远渡赖扬帆。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1165", "title": "鹧鸪天·秋老虎", "genre": "鹧鸪天", "date": "2022.08.13", "body": "秋后天凉又闷沉，\n清晨薄雾色轻阴。\n无风庭院花凝重，\n卧鸟枝头断丽音。\n人微动，汗如淋。\n初秋老虎肆相侵。\n漫天飒爽黎民愿，\n呼唤天公顺我心。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1166", "title": "七绝·秋晓窃喜", "genre": "七绝", "date": "2022.08.14", "body": "开门晨练雨潇潇，\n无奈回头且自嘲。\n知我奔忙平日苦，\n天翻云碎洒今朝。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1167", "title": "清平乐·贺男排", "genre": "清平乐", "date": "2022.08.15", "body": "十年隐忍，\n赢取今朝奋。\n雄冠亚洲消耻恨，\n恰似秋风解闷。\n华夏骄子高歌，\n红旗漫卷山河。\n江海同心携力，\n无穷巨浪清波。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1168", "title": "五律·夜问", "genre": "五律", "date": "2022.08.16", "body": "秋风消暑气，\n桐叶欲飘离。\n月色清高远，\n蝉声苦闷稀。\n新冠还肆虐，\n百姓又愁思。\n何日瘟神灭，\n谁人告我知？ ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1169", "title": "朝中措·六十抒怀", "genre": "朝中措", "date": "2022.08.17", "body": "东奔西走赚浮名，\n到了事无成。\n犹似桃花柳絮，\n风来雨后漂萍。\n人生如梦，\n黄泉永伴，\n何必纷争。\n且把心源安放，\n山河江海为营。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1170", "title": "浣溪沙·童儿乐", "genre": "浣溪沙", "date": "2022.08.18", "body": "竟日娇孙庭院间。\n花生豌豆近身前，\n扯衣牵手草坪欢。\n去岁相逢还不语，\n今朝每遇巧能言。\n娃聪爷笨甚前年。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1171", "title": "采桑子·童趣", "genre": "采桑子", "date": "2022.08.19", "body": "孙娃戏耍芳园里。\n碧水黄鸭，\n微景人家。\n锅碗瓢勺手上抓。\n橡皮泥土随心造。\n桂子桃花，\n白兔乌鸦。\n一晌时光笑属她。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "1172", "title": "朝中措·秋夜闲吟", "genre": "朝中措", "date": "2022.08.20", "body": "轻凉闷热岂当秋，\n鸿雁亦生愁。\n不道南行与否，\n谁知何处巡游。\n风云乱卷，\n时空紊序，\n水欲西流。\n大地难堪重负，\n苍天拒应人求。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1173", "title": "鹧鸪天·有所思", "genre": "鹧鸪天", "date": "2022.08.21", "body": "天不欺人人自欺，\n削山填海梦中痴。\n丛林古木年年少，\n淡水鲜鱼日日稀。\n丰雨季，断云丝。\n沙烘石烤惹愁思。\n曾经所作违天意，\n事到今朝悔晚知。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1174", "title": "一剪梅·童趣", "genre": "一剪梅", "date": "2022.08.22", "body": "开口哥哥步向前。\n娇态轻盈，\n小手相牵。\n粉红花伞树丛间。\n两小无猜，\n草畔同欢。\n日日相逢过一年。\n快乐时光，\n共赏婵娟。\n幼儿无虑远忧烦。\n柳下花边，\n悄语心妍。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "1175", "title": "五绝·望石门", "genre": "五绝", "date": "2022.08.23", "body": "狂雨起狼烟，\n城中浪打船。\n纵横南北路，\n不见旧时颜。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1176", "title": "清平乐·秋风吟", "genre": "清平乐", "date": "2022.08.25", "body": "层云漫卷，\n天际青无限。\n京邑秋风今又见，\n眺望南征鸿雁。\n回眸暗起愁情，\n新冠延误归程。\n二老家中应念，\n不知何日成行。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1177", "title": "七律·悼行者弟", "genre": "七律", "date": "2022.08.26", "body": "丹青词赋醉于心，\n意气挥毫万里春。\n岂料严霜摧秀木，\n更惊恶雨毁兰君。\n芳香四溢声名远，\n清气独留桂魄存。\n驾鹤凭风追日月，\n化身光影耀乾坤。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1178", "title": "采桑子·初秋吟望", "genre": "采桑子", "date": "2022.08.27", "body": "时逢周末心头静。\n闲望云天，\n雁奋莺欢。\n秋野晴柔景色妍。\n人成三五山前聚。\n水秀风绵，\n葡紫桃圆。\n笑靥舒怀忘却烦。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1179", "title": "踏莎行·致敬重庆", "genre": "踏莎行", "date": "2022.08.28", "body": "山火无情，\n山城有爱。\n崎峰陡岭真情在。\n官兵头阵铸铜墙，\n平民无畏浓烟害。\n野路深林，\n人提车载。\n火龙虽猛终无奈。\n浩歌一曲荡长空，\n成渝儿女多豪迈。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg", "04.jpg"]}, {"poem_id": "1180", "title": "清平乐·《采葛》读后", "genre": "清平乐", "date": "2022.08.29", "body": "醒思梦盼，\n日唤千千遍。\n长昼无音愁寝饭，\n夜永如年神倦。\n三言两语情深，\n韵声直透人心。\n自古恋中儿女，\n望穿欲眼低吟。\n【附原作：诗经•玉风•采葛】\n朝代：先秦周代    作者：佚名\n彼采葛兮！一日不见，如三月兮!\n彼采萧兮！一日不见，如三秋兮!\n彼采艾兮！一日不见，如三岁兮!", "image_files": ["01.jpg"]}, {"poem_id": "1181", "title": "七绝·秋晓有见", "genre": "七绝", "date": "2022.08.30", "body": "半宵风雨转天凉，\n赶早行人露染裳。\n时见枝头飘落叶，\n周边青翠漫趋黄。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "1182", "title": "七绝·吟望十月", "genre": "七绝", "date": "2022.08.31", "body": "欣闻党代会将开，\n万里航程锦绣来。\n又一百年刚起步，\n金风助力上高台。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1183", "title": "满江红·游万牲园", "genre": "满江红", "date": "2022.09.01", "body": "早有心怀，携孙去，巡观鸟兽。\n今如愿，清风朗日，午前秋后。\n三代同行狮虎苑，万人围看猩猴秀。\n雀开屏，鹦鹉语欢迎，人争逗。\n熊猫馆，漫步走。犀牛处，凝眸久。\n鹿颈向云天，象鼻柔瘦。\n童稚龟前相对眼，妪翁斑马栏边凑。\n风色好，一晌尽情欢，频回首。", "image_files": ["01.jpg"]}, {"poem_id": "1184", "title": "七绝·秋晓有见", "genre": "七绝", "date": "2022.09.02", "body": "青天无际渺如银，\n庭院微风飒爽人。\n舞剑挥刀鸟鸣处，\n漫歌飞扇亦精神。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1185", "title": "沁园春·九三寄怀", "genre": "沁园春", "date": "2022.09.03", "body": "七秩重七，难忘当年，锣鼓滔天。\n正倭儿降溃，军民同乐；乾坤翻转，山海齐欢。\n多少英雄，抛头洒血，后继先驱誓向前。\n终赢取，我九州胜日，百姓神安。\n今朝天际云烟，似溪水，有汹涛暗澜。\n望延绵带路，贼人使绊，通连峡岸；寇子狂言。\n螳臂当车，蚍蜉撼树，花落花开谁可拦。\n神州丽，看鹏征万里，马跃长川。", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "1186", "title": "诉衷情·疫中情", "genre": "诉衷情", "date": "2022.09.04", "body": "三年防疫渐无惊，\n赖有逆前行。\n心无畏，臂双擎。\n壮举映豪情。\n浅靥笑长风。\n望银屏，\n亲人备酒万千盅。\n待重逢。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "1187", "title": "七绝·京秋日暮", "genre": "七绝", "date": "2022.09.05", "body": "风狂雨骤裹冰雹，\n黄叶银珠乱路桥。\n一霎行人不知措，\n受惊鸟雀久哀嚎。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1188", "title": "七绝·遥寄", "genre": "七绝", "date": "2022.09.06", "body": "疫情震害两重难，\n多事之秋笼四川。\n冷露寒霜终会去，\n峨眉山月更明圆。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "1189", "title": "水调歌头·月将圆孙远去", "genre": "水调歌头", "date": "2022.09.07", "body": "白露中秋近，月向九霄圆。\n晓昏风色，已然多带几分寒。\n无奈娇孙挥手，随母行留西域，长夜可安眠？\n地角爷思念，孤望对青天。\n六千里，沙草冷，柳蝉残。\n天宽地阔，迪化自古少人烟。\n鸿雁愁飞不到，黄叶忧伤早谢，老少两心烦。\n便是银屏看，何似在身边。", "image_files": ["01.jpg"]}, {"poem_id": "1190", "title": "西江月·月夜吟", "genre": "西江月", "date": "2022.09.08", "body": "白露回乡探母，\n中秋望月思妻。\n廉州古冶远东西，\n怎奈相逢梦里。\n四秩同经风雨，\n半生共赏花枝。\n老来父母病相欺，\n各绕椿萱情寄。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1191", "title": "蝶恋花·长相忆", "genre": "蝶恋花", "date": "2022.09.09", "body": "又是一年重九日，\n难忘当时，\n闻讯悲流涕。\n地恸山崩江海泣，\n神州万里情难寄。\n且看今朝秋旖旎，\n俊岭长川，\n龙凤飞无际。\n古老东方腾紫气，\n韶山冲里人相忆。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "1192", "title": "七绝·楼台觅月", "genre": "七绝", "date": "2022.09.10", "body": "中秋前夜月无形，\n或为团圆蕴意情。\n期待来宵飞玉兔，\n银盘转动宇寰明。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1193", "title": "采桑子·中秋寄怀", "genre": "采桑子", "date": "2022.09.11", "body": "怎教眼底无离恨。\n遥望清蟾，\n辗转难眠。\n绪若波涛浪卷山。\n五人四地天涯远。\n夜永如年，\n把酒凭栏。\n无奈今宵梦里圆。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1194", "title": "七绝·闻思", "genre": "七绝", "date": "2022.09.12", "body": "煞女上台王者崩，\n秋山日落冷西风。\n天寒水逝云飞散，\n零乱尘烟袅暮空。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "1195", "title": "五绝·中秋赠友", "genre": "五绝", "date": "2022.09.13", "body": "衣锦还乡去，\n扬眉瓦舍前。\n留香身影后，\n意气胜当年。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1196", "title": "五绝·屏望", "genre": "五绝", "date": "2022.09.14", "body": "灯下娇孙女，\n宵深不肯眠。\n坐床书在手，\n可是为来年？ ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1197", "title": "五绝·秋院", "genre": "五绝", "date": "2022.09.15", "body": "借光藤架明，\n繁叶嫩瓜生。\n影动浮香处，\n时来酿蜜蜂。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1198", "title": "忆江南·秋望", "genre": "忆江南", "date": "2022.09.16", "body": "黄河北，\n五彩胜江南。\n枫叶飘来红似火，\n岭香回荡味甘甜。\n云淡水空蓝。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "1199", "title": "朝中措·魂归故里", "genre": "朝中措", "date": "2022.09.17", "body": "雄魂无奈异乡眠，\n今日把家还。\n棺柩红旗覆盖，\n水门洗却尘烟。\n秋高气爽，\n山河锦绣，\n鸟雀翩跹。\n告慰英灵毅魄，\n归来永世为安。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "1200", "title": "七律·回望9.18", "genre": "七律", "date": "2022.09.18", "body": "贼谋祸起柳条湖，\n铁路自袭别有图。\n欲霸满州倭寇梦，\n觑觎黄鹤老蟾蜍。\n中华儿女多奇志，\n抗日云烟岭海浮。\n后继前英十四载，\n凯旋策马踏新途。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "1201", "title": "七绝·闲思", "genre": "七绝", "date": "2022.09.19", "body": "多少登楼为赋愁，\n吟来乏味害人羞。\n眼前风物无穷尽，\n何必娇情不自由。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1202", "title": "采桑子·秋韵", "genre": "采桑子", "date": "2022.09.20", "body": "多天未雨秋阳烈。\n昨日堆云，\n漏作丝琴。\n润物催花自可人。\n连绵滴露声无断。\n隐没星辰，\n退却蝉音。\n拂晓寒窗冷我心。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1203", "title": "七绝·王如秋叶", "genre": "七绝", "date": "2022.09.21", "body": "人死生前万事休，\n穷奢身后己难求。\n愚儿借此胡操弄，\n别有用心留下仇。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1204", "title": "小重山·咏秋", "genre": "小重山", "date": "2022.09.22", "body": "落叶纷飞舞不休，\n依风南北走，\n自悠悠。\n奈何骚客乱生愁，\n笔底下，哀叹皱眉头。\n溪水向东流，\n花开花落去，本无忧。\n尘间万事莫强求，\n云空阔，且唱信天游。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1205", "title": "七绝·秋分", "genre": "七绝", "date": "2022.09.23", "body": "昼夜均分草色寒，\n交锋冷暖雨廉纤。\n桂花香处农家乐，\n遍地金黄稻谷妍。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "1206", "title": "霜天晓角·城河晩景", "genre": "霜天晓角", "date": "2022.09.24", "body": "秋分日暮，\n水岸悠闲步。\n远处斜阳归去。\n声摇动，鸣蝉树。\n草路，风漫舞。\n柳荡云飞渡。\n黄叶残枝飘落。\n菊花竞，鸟争翥。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1207", "title": "七绝·吟思", "genre": "七绝", "date": "2022.09.25", "body": "三天捅过又三天，\n一个呈阳累万千。\n若问心头甚滋味，\n酸甜苦辣涩中咸。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1208", "title": "朝中措·遇事有思", "genre": "朝中措", "date": "2022.09.26", "body": "又闻白发泪双流，\n儿壮却仙游。\n昨日床前曾语，\n今朝撒手难留。\n梦中别却，\n家亲未扰，\n最使人愁。\n日子更趋红火，\n何来长寿难求？ ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1209", "title": "七绝·远思", "genre": "七绝", "date": "2022.09.27", "body": "千里银屏玉照传，\n明眸浅靥自悠闲。\n浑然不晓亲人梦，\n秋到北疆风色寒。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1210", "title": "清平乐·秋日寄怀", "genre": "清平乐", "date": "2022.09.28", "body": "老街相聚，\n故友新朋叙。\n既往今朝情几许，\n把盏开怀无虑。\n昔时志满为公，\n赢来斑鬓苍容。\n笑对霜风玉觯，\n悠然乐趣难穷。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1211", "title": "诉衷情·桥上吟", "genre": "诉衷情", "date": "2022.09.29", "body": "红枫黄叶正金秋。\n漫步小桥头。\n楼光云影鱼戏，\n耆老正垂钩。\n逢盛世，少烦忧，\n更何求。\n远离闲事，常坐书前，\n香沁心头。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "1212", "title": "诉衷情·缅怀先烈", "genre": "诉衷情", "date": "2022.09.30", "body": "当年华夏几多愁，\n内外寇无休。\n山河破碎天怒，\n赤子血倾流。\n旗奋举，漫神州，\n换春秋。\n赢来今日，四海蛟龙，\n寰宇翔游。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "1213", "title": "桂枝香·十一抒怀", "genre": "桂枝香", "date": "2022.10.01", "body": "高天雁舞，列人字阵形，雨风难阻。\n振翅争鸣奋进，北方辞顾。\n翱翔俯瞰山河秀，胜前年，花枝萦树。\n陌阡禾盛，江湖鱼跃，景光飞度。\n望今朝，神州瑟鼓。正国庆人欢，世昌民富。\n圆梦中华，齐迈向慷庄路。\n百年耻辱行消尽，更扬眉挥手腾步。\n江山一统，必将不久，宇寰争睹。", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "1214", "title": "七绝·吟望", "genre": "七绝", "date": "2022.10.02", "body": "十月开门雨不休，\n廉纤朝暮瓦檐流。\n尘空洗净盈新气，\n锦绣山河万里秋。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1215", "title": "七绝·偷袭", "genre": "七绝", "date": "2022.10.03", "body": "四声巨响宇寰惊，\n碧海腾涛气射空。\n战火未消添猛药，\n疑云深处几时明？ ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "1216", "title": "七律·重阳有寄", "genre": "七律", "date": "2022.10.04", "body": "连阴频雨少清辉，\n何处登高卧翠微。\n阵阵寒风鸣燕怯，\n垂垂败柳冷蝉悲。\n水流遍地伤街况，\n烟笼苍天障鸟飞，\n节假于今难尽兴，\n思乡愁客几人归。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1217", "title": "七绝·秋日吟", "genre": "七绝", "date": "2022.10.05", "body": "凭栏眺望碧霄空，\n缕缕霜丝簇眼瞳。\n易老人生天不老，\n吹来还是去年风。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1218", "title": "撼庭秋·夜间行", "genre": "撼庭秋", "date": "2022.10.06", "body": "欲深眠又惊起，独自驱车矣。\n月光相伴，廉州古冶，晓来千里。\n重阳已过，情怀无减，绪思迢递。\n念家妻遥远，宵行路阔，或能惊喜。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "1219", "title": "五绝·情难禁", "genre": "五绝", "date": "2022.10.07", "body": "连日困高楼，\n谁知孙女愁。\n疫情今晓去，\n出外喜盈眸。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "1220", "title": "七律·赠妻", "genre": "七律", "date": "2022.10.08", "body": "深秋寒露人心暖，\n久病床前女更亲。\n姐妹轮番精照料，\n慈萱长卧未伤身。\n白天烧饭依鼻饲，\n半夜吸痰顺骨筋。\n莫道儿孙能养老，\n木兰行孝盛如今。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "1221", "title": "七绝·床前吟", "genre": "七绝", "date": "2022.10.09", "body": "喂药饲汤浑不知，\n从前苦乐逝东西。\n今朝难晓忧和怨，\n留下悲伤若柳丝。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1222", "title": "七绝·闻事寄怀", "genre": "七绝", "date": "2022.10.10", "body": "---贺国球夺冠\n小球飞舞宇寰间，\n笑傲江湖数秩年。\n昔日破冰惊旧世，\n老人帷幄谱新篇。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "1223", "title": "醉花阴·秋望", "genre": "醉花阴", "date": "2022.10.11", "body": "午后高阳风色暖，\n霄碧云舒卷。\n极目向长空，\n时闻流莺，\n偶有南飞雁。\n空余独坐闲庭院，\n黄叶来相伴。\n相对两飘零，\n欲诉无言，\n各有心头愿。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1224", "title": "七律·望山河", "genre": "七律", "date": "2022.10.12", "body": "碧水蓝天寸土金，\n千年守固仗三军。\n英雄手里挥长剑，\n虎豹眸中怯意深。\n万古河山华夏壮，\n满腔热血九州春。\n风云乱渡何足虑，\n北斗情牵赤子心。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "1225", "title": "七绝·秋夜吟", "genre": "七绝", "date": "2022.10.13", "body": "床头久卧病吞金，\n多少钱财入海深。\n倘若换回亲笑脸，\n躬身万苦亦甘心。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1226", "title": "七绝·深秋晓雨", "genre": "七绝", "date": "2022.10.14", "body": "晓来丝雨细无音，\n黄叶垂珠不舍分。\n一旦离将两相去，\n此生难望再逢君。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1227", "title": "醉花阴·遥送同窗", "genre": "醉花阴", "date": "2022.10.15", "body": "千里传来悲痛讯，\n霹雳惊天震。\n花甲一英才，\n撒手人寰，\n了却尘间恨。\n少同苦乐心头近，\n共事多齐奋。\n挥泪送君行，\n仙界云游，\n玉帝趋前问。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1228", "title": "七绝·晓风吟", "genre": "七绝", "date": "2022.10.16", "body": "深秋月夜冷风吹，\n黄叶离枝乱处飞。\n客至老年伤此甚，\n不知故里可能归。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1229", "title": "醉花阴·遥望寄思", "genre": "醉花阴", "date": "2022.10.17", "body": "黄叶飘零秋色晚，\n望断高飞雁。\n日暮更西风，\n吹卷残云，\n影暗闲庭院。\n故园旧事空长叹，\n人去情难散。\n千里寄哀思，\n寒夜销魂，\n泪眼心头颤。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1230", "title": "醉花阴·遥望寄思", "genre": "醉花阴", "date": "2022.10.17", "body": "黄叶飘零秋色晚，\n望断高飞雁。\n日暮更西风，\n吹卷残云，\n影暗闲庭院。\n故园旧事空长叹，\n人去情难散。\n千里寄哀思，\n寒夜销魂，\n泪眼心头颤。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1231", "title": "唐多令·十月寄怀", "genre": "唐多令", "date": "2022.10.18", "body": "我党百年兴，\n九州盛世情。\n几代人，砥砺前行。\n星火燎原摧旧势，\n天地换，日安宁。\n今又聚群英，\n筹谋再远征。\n定五年，方略航程。\n北斗高悬明日月，\n山更秀，水更清。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1232", "title": "七绝·吟望", "genre": "七绝", "date": "2022.10.19", "body": "金秋十月望神京，\n九夏英豪意气浓。\n为党兴帮争献策，\n尽心职守立新功。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1233", "title": "七绝·闲吟", "genre": "七绝", "date": "2022.10.20", "body": "霄汉霞晖陌上尘，\n云泥思悟两厢人。\n并行出走不同念，\n难定东西最费神。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1234", "title": "七绝·日渐落", "genre": "七绝", "date": "2022.10.21", "body": "一.\n大厦将倾梁木朽，\n无由频断烂椽头。\n不才之女偷机上，\n走马下台骄气休。\n二.\n狂言犹热气先衰，\n意料之中败擂台。\n撼树蚍蜉徒费力，\n春来大地百花开。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1235", "title": "七绝·吟望", "genre": "七绝", "date": "2022.10.22", "body": "红叶蹁跹楼宇间，\n含情脉脉向窗轩。\n金风袅袅人心荡，\n无耐禁足难共欢。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1236", "title": "七绝·翘首以待", "genre": "七绝", "date": "2022.10.23", "body": "十秩红船再起帆，\n今朝舵手展新颜。\n五洲瞩目争相望，\n浪涌涛行四海间。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1237", "title": "七绝·时令吟", "genre": "七绝", "date": "2022.10.24", "body": "深秋晓露渐为霜，\n枫叶新添白玉裳。\n红晕凌花莺鹊羡，\n飞来飞去啭声扬。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1238", "title": "踏莎行·品果有寄", "genre": "踏莎行", "date": "2022.10.25", "body": "大小分明，\n甘甜迥异。\n外观取物君当忌。\n并非好看最相宜，\n歪瓜裂枣精皮里。\n目秀眉清，\n巧言能事。\n与人未必真情义。\n平生处世要当心，\n慎行思辩长牢记。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1239", "title": "踏莎行·秋晓行寄", "genre": "踏莎行", "date": "2022.10.26", "body": "古冶凌晨，\n廉州晌午。\n朝霞迎送云飞度。\n秋风千里伴车行，\n红枫黄叶无闲顾。\n来去匆忙，\n情怀难诉。\n两头亲老皆需助。\n今朝所幸已归休，\n身心尽在床前驻。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1240", "title": "清平乐·阶前吟", "genre": "清平乐", "date": "2022.10.27", "body": "鬓华如雪，\n闲看飞黄叶。\n草木深秋悠自谢，\n人到晚年情切。\n世上花落花开，\n谁能白发重来。\n把握今朝偷乐，\n邀朋携酒登台。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1241", "title": "七绝·暮秋晓吟", "genre": "七绝", "date": "2022.10.28", "body": "天公抖落满庭金，\n小院青檐鸟雀吟。\n秋色宜人风露爽，\n诗情画韵胜如春。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1242", "title": "踏莎行·引领", "genre": "踏莎行", "date": "2022.10.29", "body": "圣地延安，\n山坡窑洞。\n神州史册辉相映。\n十三春夏聚英才，\n杨家岭上星辰众。\n舵手明航，\n红船涌动。\n今朝湖海千帆弄。\n高歌一曲棹齐飞，\n逐涛成就中华梦。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1243", "title": "踏莎行·引领", "genre": "踏莎行", "date": "2022.10.29", "body": "圣地延安，\n山坡窑洞。\n神州史册辉相映。\n十三春夏聚英才，\n杨家岭上星辰众。\n舵手明航，\n红船涌动。\n今朝湖海千帆弄。\n高歌一曲棹齐飞，\n逐涛成就中华梦。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1244", "title": "七绝·闻事伤怀", "genre": "七绝", "date": "2022.10.30", "body": "人生已到秋冬季，\n时有周边落叶飘。\n草木尚能春又绿，\n鬓毛霜色夏难消。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1245", "title": "七绝·望梨泰院", "genre": "七绝", "date": "2022.10.31", "body": "万圣夜来魂魄飞，\n人叠上下几能归。\n可怜百姓愁肠断，\n寒露秋风落叶悲。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "1246", "title": "朝中措·逐梦巡天", "genre": "朝中措", "date": "2022.11.01", "body": "问天之后梦天来，\n玉宇筑高台。\n华夏千年畅想，\n九霄放眼开怀。\n凌云长箭，\n腾空一跃，\n抖落尘埃。\n笑傲苍穹万里，\n巡航日夜悠哉。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg", "04.jpg"]}, {"poem_id": "1247", "title": "如梦令·吟望", "genre": "如梦令", "date": "2022.11.02", "body": "秋暮疫情重现，\n可恨毒虫多变。\n布控总难防，\n更趁西风捣乱。\n征战，征战。\n豪气白衣堪赞。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1248", "title": "七绝·农家晓吟", "genre": "七绝", "date": "2022.11.03", "body": "阶前闲地菜青葱，\n几朵小花迎雨风。\n点缀门庭人气旺，\n暮秋农户趣无穷。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1249", "title": "长相思·遥相望", "genre": "长相思", "date": "2022.11.04", "body": "念童颜，望童颜。\n娇态纤姿笑靥妍。\n传神手眼间。\n忆天山，梦天山。\n万里乖孙山脚边。\n夜思飞笔端。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "1250", "title": "七绝·题天宫摄影", "genre": "七绝", "date": "2022.11.05", "body": "太空俯瞰黄河远，\n横贯东西到海边。\n昔日豪情凭意性，\n今朝山水映屏前。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1251", "title": "太常引·暮秋吟", "genre": "太常引", "date": "2022.11.06", "body": "深秋日暮笼尘烟，\n乱叶舞长天。\n辉冷更风寒。\n疫情甚，城乡不安。\n核酸连测，封门闭户，\n多少夜难眠。\n云影掩残蟾。\n待何日，霄明月圆。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1252", "title": "五律·京跑迎冬", "genre": "五律", "date": "2022.11.07", "body": "秋尽初冬俏，迎宾枝叶闹。\n骄儿健步飞，靓女扬眉笑。\n南北客飘然，东西情满道。\n乘风意绪开，长跑身心少。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "1253", "title": "七律·遥望珠海", "genre": "七律", "date": "2022.11.08", "body": "航展新潮看客惊，\n神州重器溢豪情。\n昔时众叹他人剑，\n今日群夸自个弓。\n昂首银鹰翔宇宙，\n凝眸铁甲映苍穹。\n任由天际风云变，\n入海腾空有巨龙。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg", "04.jpg", "05.jpg", "06.jpg", "07.jpg", "08.jpg", "09.jpg"]}, {"poem_id": "1254", "title": "七绝·十月十五夜吟", "genre": "七绝", "date": "2022.11.09", "body": "故宫古月喜相逢，\n天狗金蟾戏碧空。\n本是明圆霄汉夜，\n嫦娥掩脸晕微红。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg", "04.jpg"]}, {"poem_id": "1255", "title": "减字木兰花·遥望闲吟", "genre": "减字木兰花", "date": "2022.11.10", "body": "封城闭户，多少辛酸人欲诉。\n汝在高台，生日为儿乱了怀。\n自成反面，检点言行心莫怨。\n警示官人，天冷凝神暖予民。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "1256", "title": "七绝·颙望", "genre": "七绝", "date": "2022.11.11", "body": "…贺空军73诞辰\n银鹰七秩三周岁，\n羸弱到强翔九天。\n今日鹏程千万里，\n世人昂首望无边。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg", "04.jpg"]}, {"poem_id": "1257", "title": "沁园春·疫中吟望", "genre": "沁园春", "date": "2022.11.12", "body": "叶落梧桐，风起长天，院落趋寒。\n更初冬半夜，濛濛细雨，清晨一早，袅袅云烟。\n树上乌鸦，阶前黄狗，潮冷凄凄亦少欢。\n街头喊，请大家出户，再做核酸。\n疫情肆虐三年。几起落、近来更野蛮。\n恨如狼似虎，踪痕难控，犹云若雨，形影无边。\n店铺关张，家亲难聚，多少心头愁苦连。\n仰天啸，唤白衣圣手，予世平安。", "image_files": ["01.jpg"]}, {"poem_id": "1258", "title": "七绝·冬日晓吟", "genre": "七绝", "date": "2022.11.13", "body": "气寒天冷疫情狂，\n近日随风扰故乡。\n时有异常邻里住，\n心头掠过一丝凉。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1259", "title": "七绝·敬白衣", "genre": "七绝", "date": "2022.11.14", "body": "敲门惊晓梦，\n入户为核酸。\n来者无私欲，\n通宵更可怜。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1260", "title": "菩萨蛮·吟石门", "genre": "菩萨蛮", "date": "2022.11.15", "body": "入冬寒透飞霜雪，\n冠虫乘势难将灭。\n山海漫悲情，\n黎民心不宁。\n借名精准控，\n普测归如梦。\n只怕事相违，\n掉头岂可回。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1261", "title": "鹧鸪天·寄80亿人", "genre": "鹧鸪天", "date": "2022.11.16", "body": "寰宇茫茫球似村，\n苍生各色古来今。\n曾经无数魔和难，\n面对千般星与辰。\n天依旧，地呻吟。\n不堪重负费人心。\n探寻土火空中去，\n或许将来万世春。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1262", "title": "采桑子·望巴厘岛", "genre": "采桑子", "date": "2022.11.17", "body": "寰球大佬齐相聚，\n不是过年，\n不为休闲。\n只道眉毛火欲燃。\n海滨美景心头乱，\n气候忧烦，\n笼罩新冠。\n说起俄乌难上难。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1263", "title": "五绝·困", "genre": "五绝", "date": "2022.11.18", "body": "闭户街邻静，\n封村鸟雀愁。\n熟人皆不见，\n是去或当留。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1264", "title": "减字木兰花·晨望", "genre": "减字木兰花", "date": "2022.11.19", "body": "漫天晓雾，鸟雀醒来迷所处。\n南北东西，不见星光车马稀。\n疫中遥望，门户冷清思绪荡。\n期待天晴，万里云霄风色明。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1265", "title": "七绝·悲", "genre": "七绝", "date": "2022.11.20", "body": "团圆本是一家亲，\n羁旅他乡恋旧根。\n相伴为轻孤岛苦，\n如今独自断愁魂。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "1266", "title": "七绝·望石门", "genre": "七绝", "date": "2022.11.21", "body": "匆忙上路又回头，\n筹划欠周难自由。\n度势方能千里远，\n审时而动水长流。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1267", "title": "蝶恋花·时令吟", "genre": "蝶恋花", "date": "2022.11.22", "body": "小雪节来冰未冻，\n万户千家，\n闻疫心怀重。\n真假传言屏幕弄，\n犹如落叶随风动。\n封放两难谁与共。\n独自无言，\n遥望亲人痛。\n老少易伤催恶梦，\n偏偏几处爷孙控。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1268", "title": "朝中措·冬日痛望", "genre": "朝中措", "date": "2022.11.23", "body": "中原大火烈而凶。\n财物命皆空。\n平日粗心侥幸，\n终身遗恨无穷。\n千家遭难，\n万民悲痛。\n云暗苍穹。\n莫忘平安至上，\n做行最忌盲从。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "1269", "title": "七绝·致敬白衣", "genre": "七绝", "date": "2022.11.24", "body": "雾笼晓空摧败叶，\n鸦啼枝杪恋寒家。\n可怜医护贪黑起，\n入户核酸又是她。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1271", "title": "长相思·抗原入户", "genre": "长相思", "date": "2022.11.25", "body": "左一惊，右一惊。\n鼻孔酸酸泪欲零。\n忧心两道红。\n检瘟虫，灭瘟虫。\n妙计高招筹划中。\n只为争取赢。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1272", "title": "七律·冬夜吟", "genre": "七律", "date": "2022.11.26", "body": "五人四地困楼中，\n千里相思去不成。\n古冶廉州隔老俩，\n京城迪化裂家庭。\n夫妻难见心头恨，\n父女常温梦里情。\n幸有银屏可遥望，\n欣闻童稚唤爷声。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1273", "title": "五绝·无奈", "genre": "五绝", "date": "2022.11.27", "body": "几案青青韭，\n迎人阵阵香。\n禁足家少菜，\n悲却入餐汤。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1274", "title": "五绝·偶赏", "genre": "五绝", "date": "2022.11.28", "body": "芳翠去无踪，\n海棠遗果红。\n行人抬眼望，\n脚步自然轻。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1275", "title": "沁园春·归休有寄", "genre": "沁园春", "date": "2022.11.29", "body": "花甲凡人，从此身轻，往后心闲。\n恰肩头卸载，腰舒背挺，胸中减负，怀阔膺宽。\n虑渐行消，情投所好，浮利虚名抛九天。\n绪思转，乐尊前院后，水畔山边。\n今生多少余年。应自在、行藏花草间。\n顾儿孙俗愿，鬓华妻子，乡邻琐事，颜老椿萱。\n清晓凭栏，黄昏望月，信手拈来诗百篇。\n咏歌赋，仿前朝李杜，篱下陶潜。", "image_files": ["01.jpg"]}, {"poem_id": "1276", "title": "十六字令·三首", "genre": "十六字令", "date": "2022.11.30", "body": "风，\n彻夜猖狂冷月横。\n天将裂，\n山海缀银冰。\n风，\n吹走尘霾晓色晴。\n伸双手，\n依旧刺心疼。\n风，\n残叶横飞枝杪空。\n孤鸦苦，\n谁与共寒冬。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1277", "title": "踏莎行·星空相会", "genre": "踏莎行", "date": "2022.12.01", "body": "地面同堂，\n天宫合室。\n神舟先后蹁跹至。\n呼星唤月傲长空，\n扬眉挥手多豪气。\n饮恨当年，\n舒怀今日。\n辛酸多少情难寄。\n素娥青鸟欲争来，\n趣谈今古千般事。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "1278", "title": "七绝·望梅", "genre": "七绝", "date": "2022.12.02", "body": "雪花亲吻冷梅枝，\n玉蕊惺忪回味迟。\n晴霁飞霞辉弄影，\n馨香疏淡惹人期。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1279", "title": "梅花引·和维真", "genre": "梅花引", "date": "2022.12.03", "body": "传玉碗，赐金盏。\n后手无留意非浅。\n寒衣娃，仗义侠。\n尚武拜师，来此皆一家。\n风霜论剑闻鸡舞，\n雨雪摩拳擂鼙鼓。\n敬前贤，越前贤。\n绝技超人，盖世笑河山。\n维真原玉：\n玲珑碗，金醇盏，\n道骨仙魂龙泉浅。\n昆仑娃，武当侠，\n四海归宗，天下成一家。\n冬来踏雪笑云舞，\n夏至临风吼天鼓。\n继先贤，破先贤，\n夺世神功，挥剑指华山。", "image_files": ["01.jpg"]}, {"poem_id": "1280", "title": "五绝·冬晓", "genre": "五绝", "date": "2022.12.04", "body": "夜暗近黎明，\n招牌闪彩虹。\n行人呼所好，\n小店暖相迎。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1281", "title": "踏莎行·贺神舟返回", "genre": "踏莎行", "date": "2022.12.05", "body": "大漠风寒，\n神兵天降。\n无边月夜星辉旷。\n雄鹰载誉远归来，\n自豪难表欢情漾。\n半载飞天，\n三英合唱。\n九州妙韵催波浪。\n佳音阵阵漫苍穹，\n连绵入耳心怀壮。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg", "04.jpg"]}, {"poem_id": "1282", "title": "五绝·冬日闲吟", "genre": "五绝", "date": "2022.12.06", "body": "人生多所期，\n无奈费光时。\n白日难如愿，\n犹来梦里痴。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1283", "title": "浣溪沙·节序吟", "genre": "浣溪沙", "date": "2022.12.07", "body": "大雪时辰晓日明，\n寂寥村口尽开封。\n四周依旧少人行。\n对面阴阳难断定，\n相逢苦笑怎为情。\n冠虫诡秘悄无踪。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1284", "title": "五绝·梦", "genre": "五绝", "date": "2022.12.08", "body": "远家常有梦，\n多是在归途。\n历尽千难险，\n抬头望却无。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1285", "title": "七绝·痛", "genre": "七绝", "date": "2022.12.09", "body": "天寒夜半体发烧，\n或许无端中了招。\n还好细屏一道杠，\n惟期明日似今朝。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1286", "title": "七绝·无奈", "genre": "七绝", "date": "2022.12.10", "body": "屏面依稀两道红，\n心期躲过已成空。\n隔离自己宅楼上，\n莫害家邻父老翁。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1287", "title": "长相思·坚持", "genre": "长相思", "date": "2022.12.11", "body": "上一横，下一横。\n红线成双病已行。\n楼头苦自撑。\n忍头疼，恨头疼。\n缕缕丝丝来不停。\n几能消此情？ ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1288", "title": "踏莎行·酬亲友", "genre": "踏莎行", "date": "2022.12.12", "body": "多少关怀，\n万千惦念。\n屏前身后温情漫。\n家亲周到送餐汤，\n友朋馨语频连线。\n四面春风，\n一方心坎。\n教谁能不千般暖。\n惟期疫过喜相逢，\n为君斟把醇香盏。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1289", "title": "七绝·苦", "genre": "七绝", "date": "2022.12.13", "body": "密控周防难躲过，\n一人得中阖家祸。\n可怜老少语无详，\n苦态愁容心忐忑。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1290", "title": "七绝·望", "genre": "七绝", "date": "2022.12.14", "body": "无灾无病小神仙，\n何惧夏温冬日寒。\n清晓凭栏心不迫，\n夜来兴起赋诗笺。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1291", "title": "七绝·道", "genre": "七绝", "date": "2022.12.15", "body": "尘世阴阳万物间，\n此消彼长两重天。\n乾坤翻转无穷尽，\n日月晴缺去复还。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1292", "title": "七律·赠友归休", "genre": "七律", "date": "2022.12.16", "body": "人生山海景非同，\n南北风光异样情。\n莫恋曾经桃李路，\n且观今日岭坡枫。\n锦颜无悔高歌唱，\n霜鬓还应雅趣浓。\n树下逢棋心自语，\n窗前咏赋鸟来听。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1293", "title": "蝶恋花·观图有寄", "genre": "蝶恋花", "date": "2022.12.17", "body": "冷暖由天情在己。\n莫使心愁，\n觅趣随天意。\n桃李争春芳满地，\n红枫黄叶霞千里。\n夏院临风闲对弈。\n踏雪寻梅，\n冷处清香溢。\n月下垂竿池水碧，\n围炉博古茶烟细。\n注：月曼清游图\n图中12月，每月\n别有趣。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1294", "title": "七绝·叹", "genre": "七绝", "date": "2022.12.18", "body": "路阔灯红少气息，\n并非风冷夜深时。\n从前寂静缘封控，\n今日多因体不支。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1295", "title": "长相思·望", "genre": "长相思", "date": "2022.12.19", "body": "山亦寒，水亦寒。\n闻遍阳声雁未还。\n悲情染泪笺。\n思春妍，盼春妍。\n地暖花开舒肺肝。\n疫消人自安。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1296", "title": "长相思·闲吟", "genre": "长相思", "date": "2022.12.20", "body": "你也阳，我也阳。\n邻里亲朋各卧床。\n悬壶店铺忙。\n左一张，右一张。\n退热安神皆妙方。\n药行人不慌。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1297", "title": "蝶恋花·孙女两周", "genre": "蝶恋花", "date": "2022.12.21", "body": "生日今朝千里远。\n遥望边疆，\n多少相思念。\n拂晓闻烧心里乱，\n天公何意招人怨。\n惟盼风轻霜雪淡。\n尽早阳康，\n更若花枝灿。\n祈祝精灵神气现，\n此劫过后京城见。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1298", "title": "点绛唇·祈望孙女安康", "genre": "点绛唇", "date": "2022.12.22", "body": "冬至天寒，娇娃冷热予心碎。\n嗜床昏睡，巧嘴无滋味。\n千里之遥，难替儿孙罪。\n夜无寐。祈孙烧退，开口舒肠胃。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1299", "title": "浣溪沙·戏赠维真", "genre": "浣溪沙", "date": "2022.12.23", "body": "智者归休愿景多，\n激扬文字爱生活。\n思如天马过山车。\n心想旅行人未动，\n喉出音调不成歌。\n理财苦少玉金坨。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1300", "title": "七绝·岁晚抒怀", "genre": "七绝", "date": "2022.12.24", "body": "少年豪气梦趋同，\n惊醒多成半老翁。\n世路崎岖车马乱，\n几人好运入关中！ ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1301", "title": "七绝·回暖", "genre": "七绝", "date": "2022.12.25", "body": "街头烟火渐趋浓，\n远处依稀叫卖声。\n鸟雀来回低首看，\n从前老友几时逢？ ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1302", "title": "踏莎行·缅怀主席", "genre": "踏莎行", "date": "2022.12.26", "body": "百姓回眸，\n伟人诞日。\n满怀敬仰情难抑。\n先贤挖井水甘甜，\n润泽华夏民长记。\n没有当初，\n何来今世。\n高楼万丈凭基起。\n倚栏远眺俏川原，\n韶山冲里云空丽。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "1303", "title": "长相思·吟怀", "genre": "长相思", "date": "2022.12.27", "body": "烧已停，痛已停。\n阳过身疲静养中。\n魂归气脉通。\n忆亲情，念亲情。\n暖意丝丝心底生。\n爱能溶化冰。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1304", "title": "阮郎归·岁暮吟", "genre": "阮郎归", "date": "2022.12.28", "body": "疫情反复已三年，\n放开羊满川。\n东西南北起风烟，\n茫然一瞬间。\n霜雪后，是春妍。\n金鱼白浪翻。\n桃花杏雨碧云天，\n蝶莺舞陌阡。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1305", "title": "满庭芳·新年顾望", "genre": "满庭芳", "date": "2022.12.29", "body": "鸡晓钟昏，天寒岁暮，时光流逝无踪。\n举头回望，日月亦匆匆。\n先是携孙迪化，清明后、古冶京城。\n廉州路，来回几度，南北似征鸿。\n五人居四地，春秋相念，寒暑为情。\n更二老，音容总在心中。\n千里几头难顾，恨冠疫、年底疯行。\n东风劲，阴霾吹散，待旭日高升。", "image_files": ["01.jpg"]}, {"poem_id": "1306", "title": "五绝·晓吟", "genre": "五绝", "date": "2022.12.30", "body": "腊日年年过，\n今朝味不同。\n冠虫还肆虐，\n阵阵乱心情。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1307", "title": "西江月·岁暮闲吟", "genre": "西江月", "date": "2022.12.31", "body": "今日夕阳辞岁，\n明朝晓月迎年。\n鬓边霜雪漫趋前，\n闲看风轻云淡。\n侍老弄孙家乐，\n咏诗挥墨心欢。\n远离尘世少忧烦，\n窗下开怀把盏。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1308", "title": "阮郎归·元旦吟", "genre": "阮郎归", "date": "2023.01.01", "body": "终于岁杪喜相逢，\n祖孙别样情。\n依约同日到京城，\n冀边万里晴。\n阳康后，自由行，\n筹谋皆可能。\n三年羁绊尽随风，\n迎春畅想中。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "1309", "title": "浣溪沙·新年吟望", "genre": "浣溪沙", "date": "2023.01.02", "body": "三载猖狂疫渐消，\n出行随愿乐滔滔。\n京城元旦涌人潮。\n旧岁回头多少事，\n新年昂首路千条。\n人生斑鬓任逍遥。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1310", "title": "浣溪沙·孙女归来", "genre": "浣溪沙", "date": "2023.01.03", "body": "万里回家喜又惊，\n东瞧西看语随行。\n眉扬手舞表心情。\n玩具平铺挨个数，\n儿书翻遍点图形。\n可怜别久再相逢。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1311", "title": "七绝·冬夜吟", "genre": "七绝", "date": "2023.01.04", "body": "一轮明月数颗星，\n寒夜清辉漫九空。\n阳后身心多有变，\n群楼庭院少人行。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1312", "title": "浣溪沙·小孙女", "genre": "浣溪沙", "date": "2023.01.05", "body": "别久重逢长进多，\n童言稚语似长河。\n拼图认字欲飞车。\n懂话察颜观脸色，\n会思善记爱听歌。\n朱唇笑靥眼婆娑。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1313", "title": "七绝·闲问", "genre": "七绝", "date": "2023.01.06", "body": "一冬未见雪花飘，\n满目街头草木凋。\n难道天公今亦老，\n忘规逾矩使昏招？ ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1314", "title": "七绝·腊十五夜吟", "genre": "七绝", "date": "2023.01.07", "body": "天上月圆人未圆，\n明朝团聚晚餐前。\n一家五口京城会，\n短暂相逢怎个欢！ ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1315", "title": "七绝·十六夜吟", "genre": "七绝", "date": "2023.01.08", "body": "京城古冶往来还，\n千里晨辉晚照间。\n接上夫人孙女悦，\n迎门巧嘴惹心甜。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1316", "title": "七绝·腊夜吟", "genre": "七绝", "date": "2023.01.09", "body": "五口团圆只一天，\n爷爷奶奶伴窗前。\n宝妈公干边陲去，\n幼女思亲怪可怜。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1317", "title": "七绝·吟望", "genre": "七绝", "date": "2023.01.10", "body": "尘霾散落九霄明，\n妖雾摧开玉宇清。\n更起祥云千万里，\n神州大地欲春风。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1318", "title": "小重山·晨练感杯", "genre": "小重山", "date": "2023.01.11", "body": "晓月偏西依旧明。出门寒气甚、冷清清。从前晨练影重重。刀枪剑、歌漫舞红缨。\n阳过梦难成。凭空添恐惧、病无情。人多调养待春生。花开后、庭院喜盈盈。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1319", "title": "蝶恋花·赠维真", "genre": "蝶恋花", "date": "2023.01.12", "body": "夜饮归来人不寐。\n欲闹青啤，\n往事还回味。\n无奈途中朋隐退，\n寒灯独自仍无睡。\n提笔抒怀心里累。\n转眼浮生，\n叶落窗前醉。\n漫卷西风飘又坠，\n别来何日能相会。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1320", "title": "七绝·吟望", "genre": "七绝", "date": "2023.01.13", "body": "几片雪花飘九空，\n降临京洛霎无踪。\n天公也弄稀松事，\n难怪人间有懒虫。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1321", "title": "望海潮·小年感怀", "genre": "望海潮", "date": "2023.01.14", "body": "冠虫三载，横行岁暮，肆侵万户千家。\n欺叟害童，滋男扰女，攻城掠地无涯。\n神药亦浮夸。价高争付款，疯抢连花。\n布洛芬无，悲医护困累交加。\n中招筋骨酸麻。更头疼欲裂，嗓痛音沙。\n咳嗽难消，低烧不退，可怜耆老娇娃。\n愁苦厌餐茶。辗转宵无寐，期盼朝霞。\n阳过神疲体弱，何日竞芳华。", "image_files": ["01.jpg"]}, {"poem_id": "1322", "title": "七绝·闲问", "genre": "七绝", "date": "2023.01.15", "body": "小年南北不同天，\n自古传来必有缘。\n谁解个中多少趣，\n与人分享乐屏前。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1323", "title": "七绝·吟望", "genre": "七绝", "date": "2023.01.16", "body": "朔风翻卷刀割面，\n败叶枯枝送虎年。\n一点寒梅迎卯兔，\n思乡顾望不成欢。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1324", "title": "采桑子·寄友", "genre": "采桑子", "date": "2023.01.17", "body": "石门别久京都聚。\n廿载重逢，\n未变音容。\n岁月无痕情意浓。\n疫虫阻挡难相见。\n几欲成行，\n终是无功。\n今日开怀酒色红。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1325", "title": "鹧鸪天·吟望抒怀", "genre": "鹧鸪天", "date": "2023.01.18", "body": "临近年关灯火红，\n通宵庭院树窗明。\n鹊鸦惊眼啼华影，\n枝叶舒怀舞瑞风。\n人阳过，愿趋同。\n南亲北友尽相逢。\n共迎卯兔新春日，\n畅叙三秋梦里情。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1326", "title": "七绝·晓行", "genre": "七绝", "date": "2023.01.20", "body": "戴月披星返故乡，\n驱车独自沐霞光。\n阳康来往心无忌，\n陪伴爹娘梦里香。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1327", "title": "太常引·除夕", "genre": "太常引", "date": "2023.01.21", "body": "久违鞭炮漫长空。\n户户挂红灯。\n福字映门厅。\n煮煎炒、新年味浓。\n返乡游子，\n居家老少，\n欢笑聚堂中。\n守岁望花红。\n团圆夜、深深意情。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1328", "title": "七绝·元日", "genre": "七绝", "date": "2023.01.22", "body": "红灯倚树喜冲天，\n鞭炮争鸣过大年。\n玉兔飞临辞虎岁，\n人间春始物华妍。\n祝大家新年吉祥！ ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1329", "title": "七律·春晚", "genre": "七律", "date": "2023.01.23", "body": "昔日九州年夜餐，\n大江南北庆团圆。\n相声捧逗舒心乐，\n魔术虚实眼欲穿。\n妙语撩人人不寐，\n明星搞笑笑翻天。\n而今却似白开水，\n寡味偏凉惹胃寒。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1330", "title": "五律·初二待亲", "genre": "五律", "date": "2023.01.24", "body": "三年愁未聚，今日喜相逢。\n心语无穷尽，芳樽满莫停。\n酒香情更切，胆壮脸微红。\n频怪醇醪浅，骄嗔地不平。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1331", "title": "七绝·闻讯吟", "genre": "七绝", "date": "2023.01.25", "body": "养儿防老古来言，\n真到用时能向前？\n多是又忙孙辈事，\n费心上下两为难。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1332", "title": "卜算子·初五", "genre": "卜算子", "date": "2023.01.26", "body": "鞭炮映长空，\n门敞财神到。\n玉兔飞临带瑞风，\n山水人欢笑。\n三载疫猖狂，\n今个真奇妙。\n虎过瘟虫影迹无，\n剩有梅花悄。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1333", "title": "卜算子·乡情", "genre": "卜算子", "date": "2023.01.27", "body": "弯月笑红灯，\n夜色辉相映。\n回到家乡过大年，\n斑鬓春心动。\n发小恁多情，\n交盏欢言盛。\n畅饮醇香醉不知，\n挽手欹窗并。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1334", "title": "蝶恋花·开年", "genre": "蝶恋花", "date": "2023.01.28", "body": "破五纳财迎六顺。\n转眼新春，万众情怀奋。\n抖擞身心浑是劲，\n今朝阔步朝前奔。\n人涌车流锣鼓震，\n店铺开张，筹划周思甚。\n紫气东来春水近，\n人间岁月交鸿运。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1335", "title": "七绝·闲吟", "genre": "七绝", "date": "2023.01.29", "body": "尘絮漫天凭借风，\n添柴方使火通红。\n人推神助功名就，\n不懈精心事可成。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1336", "title": "喜团圆·过年", "genre": "喜团圆", "date": "2023.01.30", "body": "回家守岁，荧屏舞动，厅案飘香。\n楼窗映衬烟花炫，虎归兔繁忙。\n尊贤祭祖，迎亲待友，一派和祥。\n匆匆假日，离亲欲返，略感心伤。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1337", "title": "柳含烟·春瑞", "genre": "柳含烟", "date": "2023.01.31", "body": "迎仙兔，庆新春。\n破五祈求六顺。\n响鞭花炮映朱门，\n纳财神。\n紫气东来祥瑞降，\n树杪莺鸣燕唱。\n熏风袅袅吻家人，\n喜双亲。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1338", "title": "七绝·新春吟", "genre": "七绝", "date": "2023.02.01", "body": "午后高阳檐下暖，\n阶前闲坐身心懒。\n过年惬意好风光，\n无奈将行京邑远。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1339", "title": "七绝·惜春", "genre": "七绝", "date": "2023.02.02", "body": "光阴总是牵君手，\n日月多情催我走。\n短暂人生更恋春，\n谁如天地恒长久。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1340", "title": "五律·别有思", "genre": "五律", "date": "2023.02.03", "body": "入夜乡村静，\n时闻犬吠声。\n花墙移月影，\n街角闪红灯。\n回首新年过，\n抬头望斗星。\n寒家穷不舍，\n最念是亲情。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1341", "title": "喜团圆·祖孙乐", "genre": "喜团圆", "date": "2023.02.04", "body": "驱车半晌，京都相见，日暖人欢。\n乖孙手舞双眉悄，笑音绕堂前。\n别离半月，虎踪隐没，玉兔翩翩。\n娇灵幼女，身心俱进，动静嫣然。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1342", "title": "采桑子·上元吟", "genre": "采桑子", "date": "2023.02.05", "body": "春风初起元宵闹。\n聚散京城，\n别样心情。\n戴月披星古冶行。\n爷来奶又今朝去。\n无奈匆匆，\n何日相逢。\n别却娇孙晓梦中。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1343", "title": "七律·元夕寄妻", "genre": "七律", "date": "2023.02.06", "body": "京城古冶两云天，\n银发贤淑不住闲。\n侍奉老娘迷昼夜，\n管陪孙女制衣餐。\n元宵昏晓人来去，\n远处家亲心苦酸。\n明月清辉同举望，\n寄情千里共婵娟。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1344", "title": "七绝·遥望闲吟", "genre": "七绝", "date": "2023.02.07", "body": "气球飘落惹舆情，\n美相神州梦未成。\n真假终究多少事，\n何方拆解细说清。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1345", "title": "七绝·新春晓吟", "genre": "七绝", "date": "2023.02.08", "body": "残月西悬拂晓明，\n上元已过少花灯。\n风吹寂寞空庭院，\n晨练天寒独自行。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1346", "title": "踏莎行·新春别", "genre": "踏莎行", "date": "2023.02.09", "body": "奶奶离开，\n妈妈远去。\n娇孙日暮添思绪。\n与爷玩耍亦分神，\n欲眠伤感呢喃语。\n冬雪消融，\n春风和煦。\n路边小草依稀绿。\n莺欢燕舞柳芽新，\n一家何日能相聚。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1347", "title": "七绝·正月飞花", "genre": "七绝", "date": "2023.02.10", "body": "早春初雪兆丰年，\n点缀梅枝鸟雀欢。\n树草迓迎童稚喜，\n滋生万物竞新颜。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1348", "title": "七绝·闻事吟", "genre": "七绝", "date": "2023.02.11", "body": "名英之后招人骂，\n多是偏离祖辈心。\n头顶光环谋小利，\n定然污色染金身 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1349", "title": "采桑子·悦游", "genre": "采桑子", "date": "2023.02.12", "body": "乖孙向望芳园里。\n嘴上黄鸭，\n梦里黄鸭。\n昨日三番把弄它。\n稚童堂聚心怀旷。\n娇影如花，\n笑靥如花。\n各处流连忘却家。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "1350", "title": "五绝·晓吟", "genre": "五绝", "date": "2023.02.13", "body": "春雪驱尘尽，\n银辉映九空。\n霁晴霞色漫，\n万物复萌生。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1351", "title": "七绝·网事吟", "genre": "七绝", "date": "2023.02.14", "body": "何来无事作一休，\n笑料频添己不愁。\n顶上光环风掠去，\n花冠跌落老秃头。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1352", "title": "七绝·春日闲吟", "genre": "七绝", "date": "2023.02.15", "body": "口力疯行网络间，\n各方角色诉心言。\n偷风盗雨争名利，\n搅乱云空昼夜天。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1353", "title": "七绝·春望", "genre": "七绝", "date": "2023.02.16", "body": "残雪消融临雨水，\n余寒渐退柳芽生。\n人间烟火迎春旺，\n庭院梅梢啭鹊莺。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1354", "title": "五绝·春晓", "genre": "五绝", "date": "2023.02.17", "body": "起闻莺鹊语，\n旭日耀东方。\n庭院清新气，\n微风袅瑞祥。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1355", "title": "临江仙·何苦", "genre": "临江仙", "date": "2023.02.18", "body": "两弹一星功已定，\n痴和于敏齐名。\n英雄逝去怎知声。\n奈何民不应，\n神鬼道非同。\n倚老狂言愚蠢事，\n先前人设残崩。\n模糊老底被拎清。\n耆年当本分，\n闲淡度余生。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1356", "title": "七绝·时令吟", "genre": "七绝", "date": "2023.02.19", "body": "喜逢雨水物华新，\n垂柳摇风惹翠禽。\n睡草惊光尖乍绿，\n慵人晓起自精神。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1357", "title": "七绝·二把刀", "genre": "七绝", "date": "2023.02.20", "body": "爷爷水饺乖孙爱，\n奶奶遥闻饭菜香。\n老少欢玩心魄定，\n半拉厨艺不亏肠。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1358", "title": "七绝·二月二", "genre": "七绝", "date": "2023.02.21", "body": "龙抬头日望山川，\n春意欣盈九陌妍。\n如水车流驰远近，\n离枝燕鹊舞蹁跹。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1359", "title": "七绝·吟望", "genre": "七绝", "date": "2023.02.22", "body": "飞龙昂首冲云汉，\n回瞰山河遍处春。\n南北风光虽迥异，\n鲜花青睐早行人。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1360", "title": "五绝·晨吟", "genre": "五绝", "date": "2023.02.23", "body": "故人托梦来，\n往事绕心怀。\n晓敬尘封酒，\n举杯云雾开。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1361", "title": "七绝·闻事吟", "genre": "七绝", "date": "2023.02.24", "body": "为师不正道将偏，\n莫怪登台赤子言。\n常羡他人堂上论，\n作回自己讲尊严。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1362", "title": "七绝·春晓吟", "genre": "七绝", "date": "2023.02.25", "body": "清晨五谷磨成浆，\n滋养心田暖胃肠。\n日月精华盈宇宙，\n人生智慧脑中藏。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1363", "title": "南乡子·娇孙趣事", "genre": "南乡子", "date": "2023.02.26", "body": "假日乐无边，\n餐饭疏思忘睡眠。\n宵昼耍疯难住手。\n何缘，\n妈爸今朝有空闲。\n童稚性天然，\n父母身旁任是欢。\n过后岂知爷奶苦。\n难言，\n诱导多时到以前。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1364", "title": "七绝·湖畔早春", "genre": "七绝", "date": "2023.02.27", "body": "轻柔杨柳映残冰，\n倒影横斜泮水中。\n乍暖还寒郊野处，\n云空万里日辉红。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1365", "title": "七绝·见有思", "genre": "七绝", "date": "2023.02.28", "body": "贪黑起早上学堂，\n父母劳神里外忙。\n恨不分出灵巧手，\n随身儿女著文章。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1366", "title": "玉楼春·798艺术区", "genre": "玉楼春", "date": "2023.03.01", "body": "站在火车头上望，\n孙女扬眉心底旷。\n昔时荒废一工房，\n今日涂装翻有样。\n思路转弯行走畅，\n杨柳春风新气象。\n商家游客两相宜，\n掘土为金烟火旺。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg", "04.jpg"]}, {"poem_id": "1367", "title": "七绝·观展有寄", "genre": "七绝", "date": "2023.03.02", "body": "解脱双脚四轮行，\n海角天涯任纵横。\n以电代油风势劲，\n烟霾消散宇寰清。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg", "04.jpg", "05.jpg", "06.jpg"]}, {"poem_id": "1368", "title": "蝶恋花·晓望", "genre": "蝶恋花", "date": "2023.03.03", "body": "寒褪阳升风色暖。\n雨水初临，\n草木新芽短。\n放眼江河冰欲泮，\n游人郊野寻春面。\n两会将开翘首盼。\n又聚群英，\n争把筹谋献。\n疫过民生千百唤，\n心期国策金光灿。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1369", "title": "五绝·动车有感", "genre": "五绝", "date": "2023.03.04", "body": "窗外晓云飞，\n予心似箭归。\n扬眉千里路，\n一日几来回。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1370", "title": "七绝·雷锋", "genre": "七绝", "date": "2023.03.05", "body": "为民旗帜航标塔，\n六秩春风火焰红。\n照亮世间山海路，\n神州百姓一心灯。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1371", "title": "七绝·节令吟", "genre": "七绝", "date": "2023.03.06", "body": "未响惊雷虫自醒，\n回眸栖草已然青。\n抬头天际风云丽，\n抖擞泥身快乐行。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1372", "title": "如梦令·仲春", "genre": "如梦令", "date": "2023.03.07", "body": "庭院细风吹荡，\n杨柳新芽漫放。\n远处起雷声，\n地下虫惊争上。\n张望，张望。\n睡眼惺忪相向。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1373", "title": "七绝·三八有寄", "genre": "七绝", "date": "2023.03.08", "body": "春风浩荡百花妍，\n细水柔条舞陌阡。\n蝶色莺声云欲醉，\n朝霞红透半边天。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1374", "title": "七绝·新官秀", "genre": "七绝", "date": "2023.03.09", "body": "倾心妙语论当前，\n身段绵柔底气传。\n袖里藏刀山海去，\n随时防备野狼缠。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1375", "title": "采桑子·春日抒怀", "genre": "采桑子", "date": "2023.03.10", "body": "神州两会环球望。\n要事连番，\n花絮蹁跹。\n各路媒喉喊破天。\n东风强劲云空阔。\n鸦闹莺欢，\n细韵粗弦。\n合唱吾朝卯兔年。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1376", "title": "采桑子·骤降", "genre": "采桑子", "date": "2023.03.12", "body": "仲春又遇寒潮甚。\n日月无情，\n草木皆惊。\n老少添衣避冷风。\n谁人能管天公事！\n南北西东，\n莫不愁容。\n嫩蕾新芽晓泪盈。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1377", "title": "七绝·祖孙古冶行", "genre": "七绝", "date": "2023.03.13", "body": "离京寻奶到唐山，\n身境新奇俏语连。\n西望东瞧闲不住，\n扬眉抖腕舞蹁跹。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "1378", "title": "七绝·三月春", "genre": "七绝", "date": "2023.03.14", "body": "一夜风来满眼花，\n芳菲染酷万千家。\n沟红岭翠黄莺啭，\n漫舞蜂蝶暖水鸭。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1379", "title": "七绝·春日闲吟", "genre": "七绝", "date": "2023.03.16", "body": "漫漫人生世路宽，\n直通不畅走坡弯。\n历经坎坷心怀壮，\n斑鬓深情语少年。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1380", "title": "七绝·晨吟", "genre": "七绝", "date": "2023.03.20", "body": "晓风细雨却尘埃，\n红日爬升霞色开。\n缓步迎来春暖意，\n梅香莺语入心怀。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1381", "title": "七绝·春分", "genre": "七绝", "date": "2023.03.21", "body": "昼夜均开早晚寒，\n午时微汗透轻衫。\n繁花各色眸前亮，\n翠鸟清音向远天。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1382", "title": "七绝·沙尘暴", "genre": "七绝", "date": "2023.03.22", "body": "飞沙蔽日漫春庭，\n晓色昏黄柳荡风。\n偶有乌鸦头顶过，\n斜身抖落土一层。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1383", "title": "七绝·春日闲吟", "genre": "七绝", "date": "2023.03.23", "body": "邻居走近有人愁，\n歪嘴酸言苦上头。\n灯塔无光虚摆设，\n仰凭北斗宇寰游。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1384", "title": "七绝·春思", "genre": "七绝", "date": "2023.03.24", "body": "昼夜短长交替行，\n世间不变是亲情。\n儿今斑鬓娘犹念，\n二老频来我梦中。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1385", "title": "七绝·悼友", "genre": "七绝", "date": "2023.03.25", "body": "噩耗如雷晓色昏，\n悲闻昨夜逝文斌。\n中天家业轰然变，\n难掩双颊泪水痕。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1386", "title": "蝶恋花·芳香", "genre": "蝶恋花", "date": "2023.03.26", "body": "孙女两周留玉照。\n窈窕身姿，\n浅靥朱唇俏。\n秀发明眸娇若鸟，\n扬眉回首频微笑。\n紫色花衣香袅袅。\n光彩宜人，\n映衬春来早。\n似是瑶台花正好，\n闲来把看千般巧。\n​ ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg", "04.jpg", "05.jpg", "06.jpg"]}, {"poem_id": "1387", "title": "太常引·蝶变", "genre": "太常引", "date": "2023.03.27", "body": "春来闲逛首钢园。\n翠柳映蓝天。\n不见旧尘烟。\n老楼塔，容光焕然。\n时逢假日，车流如水，\n游客悦桃源。\n鸟雀啭声欢。\n明湖畔，风吹画船。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg", "04.jpg"]}, {"poem_id": "1388", "title": "五绝·日暮吟", "genre": "五绝", "date": "2023.03.28", "body": "花草有兴衰，\n雪融春又来。\n暗香浮动处，\n不似旧心怀。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1389", "title": "浪淘沙·闻事吟", "genre": "浪淘沙", "date": "2023.03.29", "body": "马氏访家乡，\n祭祖匆忙。\n中山陵处尽春光。\n漫步东西多少事，\n情暖中肠。\n两岸久离殇，\n独子猖狂。\n言行卑鄙洗心房。\n唯有交流知远近，\n血脉悠长。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1390", "title": "浪淘沙·春日吟", "genre": "浪淘沙", "date": "2023.03.30", "body": "风暖百花开，\n景色新裁。\n缤纷五彩荡心怀。\n百子湾园闲度步，\n绕柳环台。\n玩稚乐无猜，\n未染尘埃。\n个中或有栋梁才。\n奋起腾飞翔宇宙，\n期待将来。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1391", "title": "浪淘沙·闻事寄怀", "genre": "浪淘沙", "date": "2023.03.31", "body": "蔡女美洲行，\n欲借西风。\n跳梁贼子怕天明。\n被作刀枪难自主，\n掌上悲鸣。\n两岸壑沟横，\n不久将平。\n污涛浊浪势难成。\n雨过长空霞色丽，\n海阔天晴。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1392", "title": "浪淘沙·春晓寄怀", "genre": "浪淘沙", "date": "2023.04.01", "body": "转眼又清明，\n草木含情。\n纸烟漫卷笼悲声。\n祭祖抒怀思往事，\n泪染哀容。\n乡梦寄春风，\n万里飞鸿。\n将归故里意尤浓。\n南望廉州心里念，\n父老安宁。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1393", "title": "七绝·闻事吟", "genre": "七绝", "date": "2023.04.02", "body": "认贼作父有私心，\n图霸家山梦岂真。\n风雨将来天地暗，\n摇枝落叶卷独根。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1394", "title": "七绝·和霜雁飞", "genre": "七绝", "date": "2023.04.03", "body": "人间四月漫飞花，\n袅袅清香入万家。\n更有梨园千树雪，\n翩翩起舞吻篱笆。\n诗友原玉：\n七绝           白梅\n霜雁飞\n满身玉洁压梨花，\n独自盛开山野家。\n春染枝头关不住，\n暗香一缕过篱笆。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1395", "title": "醉花阴·春晓吟望", "genre": "醉花阴", "date": "2023.04.04", "body": "每近清明天堕雨，\n和泪浇愁绪。\n烟火袅云空，\n灰烬犹悲，\n痛向膺田聚。\n挚情最是儿男女，\n长跪坟前语。\n岁月刻心痕，\n久久相思，\n音貌难将去。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1396", "title": "太常引·清明寄怀", "genre": "太常引", "date": "2023.04.05", "body": "神州春祭慰英灵，\n天雨洗长空。\n山水柳青青。\n遍华夏，\n红旗五星。\n万千先烈，\n长眠地下，\n方使有今生。\n门户可安宁。\n龙腾跃，\n江明宇清。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1397", "title": "天净沙·清明", "genre": "天净沙", "date": "2023.04.06", "body": "不期病扰娇孙，\n返乡之愿难真。\n彻夜愁思染鬓。\n晓来前问，\n稚声驱散烟云。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1398", "title": "采桑子·遥望有思", "genre": "采桑子", "date": "2023.04.07", "body": "又闻两岸雷声起。\n风雨飘摇，\n浪里舟桥。\n独岛狼烟待水浇。\n蒋家后代人犹在。\n朽木难雕，\n绿寇成妖。\n玩火终将被火烧。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1399", "title": "七绝·春日闲吟", "genre": "七绝", "date": "2023.04.08", "body": "笑对风霜雪染头，\n老来岁月少忧愁。\n与孙为伴光阴逝，\n弯背躬身无所求。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "1400", "title": "七绝·咏怀", "genre": "七绝", "date": "2023.04.09", "body": "逆旅征途已下车，\n回乡俯首报恩德。\n趋前二老殷勤伴，\n往事聊成岁月歌。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1401", "title": "醉花阴·千里探母", "genre": "醉花阴", "date": "2023.04.11", "body": "拜过双亲魂魄稳，\n一见超千问。\n庭院草花香，\n门户无忧，\n多有乡邻进。\n鬓苍少虑时常困，\n醒后牌消闷。\n妹妹往来频，\n念想周全，\n二老衣餐顺。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1402", "title": "五绝·春晓", "genre": "五绝", "date": "2023.04.12", "body": "小院对红开，\n鸣檐鸟雀来。\n凭栏飞意绪，\n青翠悦胸怀。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1403", "title": "七绝·春趣", "genre": "七绝", "date": "2023.04.13", "body": "蔷薇红晕染枝头，\n翠叶摇风映远楼。\n童稚相邀花树下，\n逐香嘻闹逮蜗牛。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1404", "title": "七绝·春夜吟", "genre": "七绝", "date": "2023.04.14", "body": "昔日青丝染雪颜，\n今朝无悔少时年。\n人生自古终将老，\n斑鬓闲身好梦眠。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1405", "title": "七绝·牡丹", "genre": "七绝", "date": "2023.04.15", "body": "花色斑斓香满园，\n粉红带露恁娇鲜。\n芳姿摇拽蜂蝶醉，\n胜过瑶台万朵仙。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1406", "title": "七绝·和诗友", "genre": "七绝", "date": "2023.04.16", "body": "相逢不易散时难，\n酒热衷肠心底寒。\n此去东西千里梦，\n低眉挽袖泪轻弹。\n诗友原玉：\n七绝           离梦\n霜雁飞\n踯躅村头一别难，\n离魂羁旅雪天寒。\n他乡游子沧桑梦，\n总把幽思借瑟弹。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1407", "title": "七绝·观事有吟", "genre": "七绝", "date": "2023.04.17", "body": "凡人难抵四周拳，\n且看神龙跃九天。\n巡望八方云海阔，\n瑶台闲坐会游仙。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1408", "title": "七绝·春日有感", "genre": "七绝", "date": "2023.04.18", "body": "红花绿叶巧为邻，\n相处无争最可亲。\n漫溢芳香赢赞誉，\n独留青翠亦精神。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1409", "title": "七绝·咏荷", "genre": "七绝", "date": "2023.04.20", "body": "芙蕖曼妙玉洁身，\n浊水淤泥不染尘。\n高雅赢得千古颂，\n百花丛里最倾心。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1410", "title": "七绝·赠银川兄", "genre": "七绝", "date": "2023.04.21", "body": "诗词诱惑理工男，\n花甲躬身李杜前。\n平仄谱出千百韵，\n老来岁月有新天。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1411", "title": "七绝·闻事吟", "genre": "七绝", "date": "2023.04.22", "body": "狗随人性雨随风，\n暴劣温良与主同。\n常近朱砂沾赤色，\n身临缁墨脸乌青。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1412", "title": "七绝·春夜吟", "genre": "七绝", "date": "2023.04.23", "body": "修来缘分且珍惜，\n携手把樽能几时。\n旦使相逢宜畅饮，\n管他春夏与东西。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1413", "title": "七绝·春日抒怀", "genre": "七绝", "date": "2023.04.24", "body": "人生谁不老白头，\n昔日芳华任去留。\n无悔苍颜心体健，\n开怀胜过少年愁。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1414", "title": "踏莎行·郊游", "genre": "踏莎行", "date": "2023.04.27", "body": "古塔春园，\n垂杨翠柳。\n躲开假日携孙走。\n湖边曲径少人行，\n煦风暖照亭台秀。\n碧水朱栏，\n童声玉手。\n香甜食物充鱼口。\n鸭鹅争叫戏青蛙，\n开心老少频回首。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1415", "title": "蝶恋花·遥望", "genre": "蝶恋花", "date": "2023.04.29", "body": "父母携儿京洛起，\n此去天津，\n尽把深情寄。\n玩雪春天长久意，\n今朝了却心头事。\n笑靥明眸谁似你，\n玉面纤姿，\n清雅盈香气。\n两岁娇孙心底记，\n归来回味皆欢喜。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "1416", "title": "太常引·大洋彼岸", "genre": "太常引", "date": "2023.04.30", "body": "奈何相似画中身。\n日者已飞魂，\n韩子步前尘。\n赤毯上，犹如主人。\n仆从夫妇，\n旁边侧立，\n呆板眼无神。\n心底乱纷纷。\n脸堆笑，眉愁万分。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1417", "title": "七绝·五一寄怀", "genre": "七绝", "date": "2023.05.01", "body": "茶酒飘香祝友朋，\n置身节日万花丛。\n开怀畅享春光暖，\n烦恼随风散九空。\n五一快乐！[握手][咖啡] ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1418", "title": "七绝·五一致敬", "genre": "七绝", "date": "2023.05.02", "body": "劳者节来犹未休，\n挥浆砌瓦筑高楼。\n除尘净道披星月，\n俯首无言解众忧。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1419", "title": "七绝·叹望", "genre": "七绝", "date": "2023.05.03", "body": "出门看景被围观，\n未见物华愁望天。\n抬脚未曾挪半步，\n有心放下已然难。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1420", "title": "七绝·吟望", "genre": "七绝", "date": "2023.05.04", "body": "淄博烧烤爆出圈，\n千里奔驰解嘴馋。\n遍处飘香情似火，\n主家周到客流连。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1421", "title": "江城子·吟望抒怀", "genre": "江城子", "date": "2023.05.05", "body": "昔时五四意飞扬。\n入华堂，佩勋章。\n热血盈怀，\n胆壮志如钢。\n绶带红花频闪烁，\n高台上，恁风光。\n今朝华发绪思长。\n鬓如霜，梦犹香。\n老少于心，\n几处远奔忙。\n俯首灶台炉火旺，\n亲情暖，醉栏窗。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1422", "title": "五绝·立夏", "genre": "五绝", "date": "2023.05.07", "body": "风开夏日门，\n菡萏影缤纷。\n神韵纤姿妙，\n魂失过路人。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1423", "title": "七绝·吟怀", "genre": "七绝", "date": "2023.05.08", "body": "花甲年来病染身，\n腿疼目眩费心神。\n八方询问投医处，\n妙手何时馈我春。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1424", "title": "采桑子·初夏晓院", "genre": "采桑子", "date": "2023.05.10", "body": "春归花谢晨风暖。\n庭院清幽，\n漫步神游。\n微汗盈身散虑愁。\n柳条垂荡莺飞啭。\n无欲无求，\n怡悦难休。\n寥廓云空竞自由。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1425", "title": "七绝·真与假", "genre": "七绝", "date": "2023.05.11", "body": "颦仿西施惹众嘲，\n虚情得意使一招。\n常年棒打鸳鸯散，\n今日撮合恨未消。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1426", "title": "七绝·寄儿生日", "genre": "七绝", "date": "2023.05.12", "body": "三十六载育身心，\n沐雨经风始作人。\n京邑扎根松柏壮，\n争当梁栋报家亲。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1427", "title": "七绝·孤芳人恋", "genre": "七绝", "date": "2023.05.13", "body": "寥廓尘间百色花，\n春秋冬夏竞相发。\n眼前一朵云空向，\n过客天涯把视她。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1428", "title": "如梦令·遥念母亲", "genre": "如梦令", "date": "2023.05.14", "body": "近日娘亲健忘。\n常问儿孙时况，\n转眼不知情，\n又复先前声嗓。\n凄怆，凄怆。\n为子心头惆怅。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1429", "title": "七绝·童趣", "genre": "七绝", "date": "2023.05.15", "body": "常玩楼院两无猜，\n哥妹花前去又来。\n携手滑梯同上下，\n秋千并坐乐开怀。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1430", "title": "七绝·闲吟", "genre": "七绝", "date": "2023.05.16", "body": "别去新冠卷土来，\n复阳音讯渐传开。\n先期未中多人倒，\n口罩随身或免灾。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1431", "title": "破阵子·笑果酸臭", "genre": "破阵子", "date": "2023.05.18", "body": "小丑一声嘶叫，\n裹含恶语伤人。\n暗箭一支星准点，\n正对神州海陆军。\n损阴煞费神。\n鬼怪难逃干系，\n犹期尘世还魂。\n万众齐呼孙大圣，\n携手钟馗斩魅根。\n风行朗朗坤。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1432", "title": "七绝·戏赠子玉", "genre": "七绝", "date": "2023.05.19", "body": "已惯操劳难作休，\n门前排队欲相求。\n冠阳无奈悠闲日，\n坐卧无聊暗自愁。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1433", "title": "七绝·童趣", "genre": "七绝", "date": "2023.05.20", "body": "傍妹倚栏哥喂水，\n楼前玩伴似家亲。\n纤眉嫩脸心相映，\n笑靥明眸稚子真。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1434", "title": "破阵子·小满有寄", "genre": "破阵子", "date": "2023.05.21", "body": "正是风清云淡，\n禾田籽粒盈浆。\n饱纳天光凭日月，\n此后丰收充廪仓。\n农勤岁月长。\n世路不辞劳苦，\n惠人利己兴邦。\n初获无骄心不躁，\n遇事虚怀底气藏。\n家和国业昌。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1435", "title": "西江月·夏趣", "genre": "西江月", "date": "2023.05.23", "body": "童稚花前围坐，\n妪翁树下旁观。\n绿荫花影趣无边，\n书在怀中虚看。\n多是心神飞荡，\n并非眉眼伤残。\n周遭景致扰膺田，\n犬吠鸟鸣惊伴。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "1436", "title": "西江月·祖孙乐", "genre": "西江月", "date": "2023.05.24", "body": "左摆右拼如画，\n运眸动手凭心。\n散图零乱费童神，\n时有娇声发问。\n楼外天光烦热，\n案周家境清新。\n祖孙老少笑声频，\n夏日无忧情奋。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1437", "title": "七绝·玩趣", "genre": "七绝", "date": "2023.05.25", "body": "年龄虽小久相逢，\n只差三天姐弟称。\n并立鹿前争比个，\n楼厅蹦跳笑声盈。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1438", "title": "七律·玩童趣读", "genre": "七律", "date": "2023.05.26", "body": "耍闹间歇看画书，\n彩图精妙眼神足。\n翻开当页长鬃马，\n转过来篇短尾猪。\n姐弟专心旁者聚，\n诵听依脑外音除。\n树梢鸟雀低头望，\n池上花枝底气无。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1439", "title": "七律·稚子夏趣", "genre": "七律", "date": "2023.05.27", "body": "初夏土桃青又小，\n枝头翠叶笑相迎。\n幼儿结伴清荫下，\n纤手争高兴趣浓。\n圆果脱毛眉目痒，\n微风拂面脸皮红。\n你牵我扯时光快，\n晌午将临未尽情。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1440", "title": "西江月·吟望", "genre": "西江月", "date": "2023.05.28", "body": "岁月如书深厚，\n人生似画斑斓。\n烟涛水浪卷云天，\n梅雪芳香莺啭。\n天地春秋往复，\n昼宵苦乐轮番。\n多情挚爱是人间，\n风月草花相伴。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1441", "title": "天净沙·农家乐", "genre": "天净沙", "date": "2023.05.29", "body": "连绵细雨肥秧，\n绕杆爬上争阳。\n翠影阶前日广。\n欣荣景象。\n鸟儿欢老人康。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1442", "title": "踏莎行·有感C919", "genre": "踏莎行", "date": "2023.05.30", "body": "无限遐思，\n几多期待。\n饱含多少情和爱。\n今朝昂首刺长空，\n眸盈热泪心头快！\n曾几何时，\n千般无奈。\n低眉窝气求人卖。\n此情一去恨随风，\n大鹏展翅云霄外。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "1443", "title": "长相思·教授飞天", "genre": "长相思", "date": "2023.05.31", "body": "桂海潮，弄海潮。\n留驻天宫赤子骄。\n多能誉望高。\n有奇招，用奇招。\n荷载专家巡九霄。\n探求星际桥。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1444", "title": "七律·六一感吟", "genre": "七律", "date": "2023.06.01", "body": "独自半年爷与孙，\n京城春夏共童真。\n楼前有伴花间乐，\n灯下无忧梦里亲。\n携手天坛观日落，\n倚栏湖畔戏鱼群。\n平衡车上娇声笑，\n单杠凌空老我身。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1445", "title": "长相思·小健将", "genre": "长相思", "date": "2023.06.02", "body": "左脚前，右脚前。\n开步如弓摆动肩，\n来回玉臂牵。\n喜逐颜，乐逐颜。\n笑靥娇唇眉俏弯，\n稚童欢不闲。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "1446", "title": "天净沙·童乐", "genre": "天净沙", "date": "2023.06.03", "body": "琮琮领跑煊煊，\n夏初京洛游园。\n并倚桥栏远看。\n彩舟花岸。\n鸟翔鱼跃云天。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "1447", "title": "七绝·夏日行", "genre": "七绝", "date": "2023.06.04", "body": "白云之上向西行，\n放眼四周霄汉明。\n回望京都千里远，\n天山日暮到疆城。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg", "04.jpg", "05.jpg", "06.jpg"]}, {"poem_id": "1448", "title": "七绝·夏日行", "genre": "七绝", "date": "2023.06.04", "body": "白云之上向西行，\n放眼四周霄汉明。\n回望京都千里远，\n天山日暮到疆城。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg", "04.jpg", "05.jpg", "06.jpg"]}, {"poem_id": "1449", "title": "七绝·童心", "genre": "七绝", "date": "2023.06.05", "body": "回到新疆不陌生，\n家中玩具亦多情。\n幼儿虽小心头记，\n逐个抚摸娇有声。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "1450", "title": "七律·芒种有寄", "genre": "七律", "date": "2023.06.06", "body": "身居闹市闻收麦，\n忆起少时三夏忙。\n人醒长空星未散，\n镰挥大地鸟惊慌。\n马驮车载烟尘去，\n机打风吹芒絮扬。\n今日多为全自动，\n众前说笑籽归仓。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1451", "title": "七绝·吟怀", "genre": "七绝", "date": "2023.06.07", "body": "当年学子已成爷，\n尘世浮生后半截。\n昔遇龙门拼尽力，\n儿孙今日上台阶。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1452", "title": "七绝·执着", "genre": "七绝", "date": "2023.06.08", "body": "五十六载人生路，\n二秩又七成考神。\n商海遨游能上岸，\n不及范进怎甘心。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1453", "title": "七绝·迪化夏日", "genre": "七绝", "date": "2023.06.09", "body": "京邑边城万里间，\n昔时景色两重天。\n如今草树街头似，\n两岁娇孙几往还。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1454", "title": "七绝·吟望", "genre": "七绝", "date": "2023.06.10", "body": "​天府街头情越位，\n神州屏上火出圈。\n一时酸爽无穷恨，\n懊悔难追把手牵。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1455", "title": "七绝·吟望", "genre": "七绝", "date": "2023.06.11", "body": "心虚气壮眼神间，\n不论高低莫怨天。\n国力支撑腰杆硬，\n扬眉昂首越关山。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1456", "title": "鹧鸪天·变色龙", "genre": "鹧鸪天", "date": "2023.06.13", "body": "独与娇孙乖可人，\n爸妈相伴乱心魂。\n卧床深夜还嘻闹，\n吃饭多时未染唇。\n情激动，喊声频。\n一天难耐是晨昏。\n寻常最怕逢周末，\n哭笑无由扰四邻。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1457", "title": "五绝·感吟", "genre": "五绝", "date": "2023.06.14", "body": "为人多礼让，\n福报自来回。\n遇事心无我，\n出行好运随。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1458", "title": "七绝·夏夜思", "genre": "七绝", "date": "2023.06.15", "body": "云静空明未染尘，\n老来远事作闲人。\n通宵无虑开轩卧，\n眠梦何忧鬼上门。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1459", "title": "鹧鸪天·边城童乐", "genre": "鹧鸪天", "date": "2023.06.16", "body": "重到疆城半月间，\n日游庭院两三番。\n滑梯顶上开怀笑，\n喷水池旁粉靥妍。\n新伙伴，旧楼前。\n童真无忌尽情欢。\n与人分享心头物，\n呼鸟闻香细语言。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg", "04.jpg", "05.jpg", "06.jpg"]}, {"poem_id": "1460", "title": "七绝·闲吟", "genre": "七绝", "date": "2023.06.17", "body": "心静无尘日月明，\n乐山戏水度余生。\n闲来远事亲朋近，\n乡韵诗情染鬓容。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1461", "title": "七绝·闻事吟", "genre": "七绝", "date": "2023.06.18", "body": "鼠鸭搅动万人心，\n啮齿指为脖颈根。\n欲效赵高说鹿马，\n引得烈火燎贼身。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1462", "title": "七绝·看图有感", "genre": "七绝", "date": "2023.06.19", "body": "晴空无恙人心异，\n眼望神州别样情。\n酸涩难言阴损盛，\n鬼魂魅影怕天明。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1463", "title": "临江仙·仲夏游园", "genre": "临江仙", "date": "2023.06.20", "body": "酷热炎光何处爽，\n红山树下清香。\n前人栽种我乘凉。\n野风摇鬓影，\n翠叶啭莺藏。\n牵手娇孙闲迈步，\n寻阶漫享时光。\n幼童嘴眼两相忙。\n半腰骑木马，\n登顶俏眉扬。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg", "04.jpg"]}, {"poem_id": "1464", "title": "五绝·夏至", "genre": "五绝", "date": "2023.06.21", "body": "天山映我窗，\n夏至晓风凉。\n不似关门内，\n晨昏汗浸裳。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1465", "title": "临江仙·端午寄怀", "genre": "临江仙", "date": "2023.06.22", "body": "边地端阳思念远，\n抬头遥望双亲。\n粽香应是满庭门。\n眼花兼耳背，\n同念远行人。\n老少别离情几处，\n疆城京冀分神。\n自来骨肉总连心。\n梦中牵一发，\n惊动遍周身。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1466", "title": "临江仙·端阳游", "genre": "临江仙", "date": "2023.06.23", "body": "水磨沟中端午日，\n摩肩游客从容。\n曼歌妙舞恁深情。\n岸前垂钓叟，\n草畔睡酣童。\n戏水白云来又去，\n金鱼潜跃欢逢。\n芳枝翠叶望无穷。\n柳荫遮酷日，\n暑气尽随风。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "1467", "title": "七律·石人沟", "genre": "七律", "date": "2023.06.24", "body": "遥望景光别样新，\n天棚地铺就青茵。\n游人结伴云间卧，\n辞客独行风色亲。\n山顶凌空观落日，\n农家月下肉香熏。\n繁星笑我归来醉，\n旁者岂能知我心。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg", "04.jpg"]}, {"poem_id": "1468", "title": "七绝·庙儿沟逢雨", "genre": "七绝", "date": "2023.06.25", "body": "攀上南山天不留，\n突来风雨使人愁。\n气温骤降十多度，\n酷夏瞬间如晚秋。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1469", "title": "七绝·寄友朋", "genre": "七绝", "date": "2023.06.26", "body": "浮云千里天天见，\n流水东西有浪声。\n不赖飞鸿传语信，\n微屏日日寄深情。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1470", "title": "七绝·吟望", "genre": "七绝", "date": "2023.06.27", "body": "人以群分各自欢，\n诗歌棋画不相干。\n朝天大路腾云上，\n快马奋蹄何用鞭。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1471", "title": "七绝·敬拜", "genre": "七绝", "date": "2023.06.28", "body": "佛在家中莫远求，\n何来四处乱磕头。\n高堂白发心端住，\n尘世穿行岂用愁。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1472", "title": "七绝·夏游红光山", "genre": "七绝", "date": "2023.06.29", "body": "对面天山雪未消，\n眼前熏烤树弯腰。\n谁人能借凉风至，\n携带雪花头上飘。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1473", "title": "七绝·疆城夏日", "genre": "七绝", "date": "2023.06.30", "body": "半宵风雨似深秋，\n晨晓层云隐日头。\n长裤夹衫犹耳冷，\n阴凉双手复相揉。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1474", "title": "清平乐·七一吟颂", "genre": "清平乐", "date": "2023.07.01", "body": "又逢华诞，\n举世群英赞。\n百载辉煌星璀璨，\n自始初心未变。\n神州地覆天翻，\n国人背挺颜欢。\n日夜舟行碧落，\n蛟龙海底翩跹。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1475", "title": "青玉案·古尔邦节", "genre": "青玉案", "date": "2023.07.04", "body": "大巴扎里人潮涌。\n鼓乐奏，声云动。\n曼舞轻歌同尽兴。\n肉馕香溢，彩旗横纵。\n笑靥凌波影。\n维乡老少齐欢庆。\n邻里亲朋酒樽弄。\n回汉前来情亦重。\n疆城和睦，神州安定。\n山水遥相映。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg", "04.jpg"]}, {"poem_id": "1476", "title": "青玉案·西白杨沟", "genre": "青玉案", "date": "2023.07.05", "body": "连天瀑布飞流下。\n响山谷，银绡挂。\n落玉飞珠妍似画。\n南山一景，清凉三夏。\n远客来休假。\n草坪溪水争相耍。\n放眼舒怀见牛马。\n风雨袭来浑不怕。\n白云漫卷，兴情难罢。\n最是欢无价。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg", "04.jpg"]}, {"poem_id": "1477", "title": "七绝·夏日闲吟", "genre": "七绝", "date": "2023.07.06", "body": "世间遍处有高楼，\n莫羡他人己不愁。\n便是身居蓬草地，\n老来无虑更何求。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1478", "title": "七绝·时令吟", "genre": "七绝", "date": "2023.07.07", "body": "小暑恰逢七月七，\n神州警报响东西。\n国仇民愤心头怨，\n旧未消除新又积。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1479", "title": "七绝·夏日闲吟", "genre": "七绝", "date": "2023.07.08", "body": "闻道家乡热浪翻，\n边城小暑夜风寒。\n卧床不敢开窗牗，\n惟恐眠深醒却难。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1480", "title": "采桑子·闻事吟", "genre": "采桑子", "date": "2023.07.09", "body": "平时台上风光劲。\n不道心灵，\n苦念如丛。\n思绪无常乱死生。\n鲜花正艳狂飚落。\n无奈凋零，\n怎不悲情。\n红堕泥香鸟叹声。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1481", "title": "唐多令·夏日吟", "genre": "唐多令", "date": "2023.07.11", "body": "伏暑入边城，晓来风色清。\n内地时、粘汗难停。\n早晚微凉心里盼。\n多数是、梦成空。\n今日雨三更，舒心晨练中。\n望天山、岭雪川冰。\n或许阴凉源自此。\n千百载、老还生。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1482", "title": "唐多令·夏日怅吟", "genre": "唐多令", "date": "2023.07.12", "body": "五口巧团圆，疆城夏日天。\n欲空闲、游览南山。\n岂料娇孙餐后吐。\n过夜后、漫周边。\n先与爸妈传，又分爷奶间。\n次第来、尽数轮番。\n好在每人愁两日。\n这心绪、怎能言。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1483", "title": "唐多令·遥望", "genre": "唐多令", "date": "2023.07.13", "body": "落魄眼神传，\n孤形魅影寒。\n绝望情、鬓际眉间。\n心冷眸酸圈子外，\n他人乐，己难欢。\n昔日恁光鲜，\n风头盖过天。\n乱招摇、鼓暴旗翻。\n国破民亡妻子笑，\n跳梁者，岂能闲？ ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1484", "title": "七绝·夏日暮吟", "genre": "七绝", "date": "2023.07.14", "body": "黄昏庭院水池暝，\n夕照霞辉映晚风。\n携手娇孙闲漫步，\n清凉树色隐蝉鸣。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1485", "title": "五绝·童趣", "genre": "五绝", "date": "2023.07.15", "body": "小手巧拼图，\n暑天心气足。\n不觉窗外热，\n半晌未出屋。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1486", "title": "七律·再探水磨沟", "genre": "七律", "date": "2023.07.16", "body": "伏后重来水磨沟，\n家妻结伴算初游。\n山光树色还依旧，\n鼓点人声格外稠。\n席地阴凉消溽暑，\n漫天云朵散忧愁。\n清风拂面心怀爽，\n翥鸟争鸣绕我头。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg", "04.jpg"]}, {"poem_id": "1487", "title": "七律·重游庙儿沟", "genre": "七律", "date": "2023.07.17", "body": "前朝遇雨未登山，\n今日白云翠岭间。\n妻子缓行芳草处，\n娇孙急步荡秋千。\n连天瀑布青龙舞，\n落水珍珠响九环。\n远客闲来消暑夏，\n八方炎气作风烟。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg", "04.jpg"]}, {"poem_id": "1488", "title": "七律·日暮抒怀", "genre": "七律", "date": "2023.07.18", "body": "老来安分自逍遥，\n醉眼闲心看四遭。\n雨落风吹天有道，\n虫鸣犬吠事难消。\n枝条长短抬头见，\n人品高低随处瞧。\n莫为周边情所累，\n抛开物欲度昏朝。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1489", "title": "眼儿媚·馆池戏水", "genre": "眼儿媚", "date": "2023.07.19", "body": "穹顶清池水中闲。\n孙女自成欢。\n旋梯滑下，浪花飞溅，\n形态娇妍。\n龙头喷洒琼珠散。\n落地自清圆。\n透心凉爽，眉峰带露，\n浅靥欢颜。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "1490", "title": "眼儿媚·欢乐城堡", "genre": "眼儿媚", "date": "2023.07.21", "body": "湖畔高楼任童欢。\n酷耍乐翻天。\n先骑木马，\n蹦床飞跳，\n又荡秋千。\n琳琅玩具无穷数。\n商户笑迎前。\n时非假日，\n孩童偏少，\n多是清闲。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg", "04.jpg", "05.jpg", "06.jpg"]}, {"poem_id": "1491", "title": "七绝·贺妻61周岁", "genre": "七绝", "date": "2023.07.23", "body": "恰逢生日在疆城，\n西域糕点情更浓。\n一碗丝滑长寿面，\n牵来孙女祝福声。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1492", "title": "七绝·时令吟", "genre": "七绝", "date": "2023.07.24", "body": "时逢大暑宿天山，\n清晓盈眸翠色妍。\n眺望四周神气爽，\n凉风惬意不思还。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "1493", "title": "沁园春·江布拉克", "genre": "沁园春", "date": "2023.07.25", "body": "古郡奇台，百里方圆，万顷山川。\n眺松林雪岭，霄连地漫，花涛麦浪，绿绣红妍。\n峡谷清幽，白云舒卷，牛马成群映草原。\n风凉夏，纵晴明无雨，入夜微寒。\n穿行犹似云端。花海子，展眸不到边。\n遇怪坡上下，有违物理，星空宵昼，别具风烟。\n溪水轻流，雄鹰高翥，醉卧毡篷好梦眠。\n宜避暑，度消魂日月，不慕神仙。", "image_files": ["01.jpg", "02.jpg", "03.jpg", "04.jpg", "05.jpg", "06.jpg", "07.jpg", "08.jpg"]}, {"poem_id": "1494", "title": "七绝·天山怪坡", "genre": "七绝", "date": "2023.07.26", "body": "斜路上坡车自行，\n转弯向下脚须蹬。\n一头雾水凭心问，\n谁解个中别样情。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "1495", "title": "减字木兰花·奇台消夏", "genre": "减字木兰花", "date": "2023.07.27", "body": "深情母女，俏揽夕阳凭笑语。\n悠荡秋千，芳靥明眸对雪山。\n刀条岭上，花海无边连麦浪。\n峡谷云天，溪水鸣莺树色寒。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg", "04.jpg", "05.jpg", "06.jpg"]}, {"poem_id": "1496", "title": "七绝·刀郎曲", "genre": "七绝", "date": "2023.07.28", "body": "十年一剑闪寒光，\n驱散怨怀留韵腔。\n不为人知多少事，\n琴弦慢捻细声张。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1497", "title": "七绝·难得", "genre": "七绝", "date": "2023.07.31", "body": "为忙老少聚来难，\n徒想山川草地边。\n今日芳茵溪水处，\n夫妻闲坐望云天。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1498", "title": "渔家傲·八一颂", "genre": "渔家傲", "date": "2023.08.01", "body": "血染军旗红劲展。\n边陲飘舞山川漫。\n映照长空华夏灿。\n天可见，\n救灾抢险从无怨。\n临夜警眠头枕剑。\n狼来定是咽喉断。\n疆土无忧凭火箭。\n迎挑战，\n赤心威猛铮铮汉。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1499", "title": "御街行·夏日吟望", "genre": "御街行", "date": "2023.08.02", "body": "漫天暴雨倾盆下。\n浊浪冲河坝。\n云烟滚滚卷长空，\n遥望心惊魂怕。\n轿车翻转，\n随涛起落，\n逢树斜腰挂。\n山洪犹似无缰马。\n街路禾田垮。\n池塘四溢毁城乡，\n怎奈今朝仲夏。\n寰球气候，\n酿成灾祸，\n此害何时罢！ ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "1500", "title": "五律·孙女两岁半", "genre": "五律", "date": "2023.08.03", "body": "前期开口晚，近日语频频。\n远上寒山去，朝辞白帝云。\n随风潜入夜，铜雀锁春深。\n诗句连成串，言词巧劝人。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1501", "title": "七绝·学游泳", "genre": "七绝", "date": "2023.08.05", "body": "老来池里仿青蛙，\n蹬腿埋头两臂划。\n水溅四空人未走，\n为防沉底紧挠抓。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1502", "title": "御街行·重游石人沟", "genre": "御街行", "date": "2023.08.06", "body": "新添景色千般样。\n稻草描形状。\n恐龙兔狗貌清新，\n海盗神形俱旷。\n农夫劳作，躬耕弯背，\n亦有抬头望。\n绣球花海翻波浪。\n眸展情怀畅。\n云随歌舞韵轻扬，\n日暮光流彩放。\n重来意奋，爽心悦目，\n入夜魂飞荡。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg", "04.jpg", "05.jpg", "06.jpg", "07.jpg", "08.jpg", "09.jpg"]}, {"poem_id": "1503", "title": "七律·闻事有感", "genre": "七律", "date": "2023.08.07", "body": "域广物博常事多，\n天灾地害扰生活。\n水淹京冀愁将去，\n震毁山东泪似河。\n冬夏山川迎雨雪，\n春秋江海起风波。\n八方援手合一处，\n灶破家离饭不隔。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "1504", "title": "七绝·立秋吟望", "genre": "七绝", "date": "2023.08.08", "body": "风吹迪化秋来早，\n便是晴天夜晚凉。\n闻道家乡似蒸煮，\n我于此处怕开窗。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1505", "title": "七律·趣闻", "genre": "七律", "date": "2023.08.09", "body": "昏暮孩童摆地摊，\n滑梯近处幼儿观。\n稚言讯问相中物，\n嫩语声明多少元。\n从小双方学买卖，\n大来独自闯商关。\n无心练就终身技，\n日后平生好赚钱。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "1506", "title": "七绝·夏趣", "genre": "七绝", "date": "2023.08.11", "body": "娇娃铜马两相宜，\n昂首天山各有思。\n何处飞来小仙女，\n华骝不动任由骑。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1507", "title": "七绝·夏日抒怀", "genre": "七绝", "date": "2023.08.12", "body": "​身似青蛙水里游，\n金鱼摆尾不需愁。\n平生一念随人愿，\n老戏碧池无所求。\n​ ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1508", "title": "七绝·西安吟望", "genre": "七绝", "date": "2023.08.13", "body": "三个男孩一场戏，\n粉丝狂热使人愁。\n不惜百万谋张票，\n多少家亲泪水流。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1509", "title": "七律·转折", "genre": "七律", "date": "2023.08.14", "body": "娇孙喜入幼儿堂，\n座落楼前草树旁。\n平日飘窗明眼看，\n今朝教室细眉扬。\n预期熟识新朋友，\n渴望同欢话短长。\n涉世人生初拐点，\n阖家老少睡难香。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "1510", "title": "七绝·吟望娇孙", "genre": "七绝", "date": "2023.08.15", "body": "头天吃睡幼儿园，\n日暮归来恁是欢。\n能否今朝还照旧，\n风轻云淡自心宽。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "1511", "title": "清平乐·贺早梅香诗刊二百", "genre": "清平乐", "date": "2023.08.17", "body": "早梅香韵，朵朵皆温润。\n燕舞蝶飞骚客问，妙语盈心情奋。\n诗苑四季生花，欣欣映照天涯。\n多少辞家回首，樽前细品争夸。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1512", "title": "七绝·无奈", "genre": "七绝", "date": "2023.08.19", "body": "风云不测事难期，\n故里回还枉费思。\n苦是双亲遥望眼，\n欲穿更待到何时。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1513", "title": "七绝·颂早梅香诗刊", "genre": "七绝", "date": "2023.08.20", "body": "梅香雪藻映诗坛，\n四季芬芳漫世间。\n惬意灯前闲细品，\n胜如琼露醉心田。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1514", "title": "鹊桥仙·七夕感怀", "genre": "鹊桥仙", "date": "2023.08.22", "body": "银河阻断，鹊桥为盼。\n苦等一年夕见。\n牛郎织女泪花流，\n化作雨、云空飘漫。\n传言千古，相思一愿。\n天上人间呼唤。\n有情若是伴昏朝，\n到老后、如初何怨。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1515", "title": "五律·处暑", "genre": "五律", "date": "2023.08.23", "body": "溽暑遇秋归，\n清凉暮色回。\n西风吹落叶，\n花影爽心扉。\n雁翥云天外，\n蝉鸣日月催。\n夏秋能往复，\n白发有谁黑。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1516", "title": "七绝·闻讯有感", "genre": "七绝", "date": "2023.08.25", "body": "害人核水无穷尽，\n可恨东洋肆意为。\n若马脱缰游荡处，\n天知到了重伤谁。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1517", "title": "七绝·秋日吟", "genre": "七绝", "date": "2023.08.27", "body": "夏去无声叶落秋，\n初来风色亦轻柔。\n寻常日月悠悠过，\n两鬓人生痕迹留。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1518", "title": "七绝·木化石", "genre": "七绝", "date": "2023.08.28", "body": "树经万载还坚挺，\n纹理清晰质不同。\n卧睡泥中抬腿立，\n林边湖畔笑相迎。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1519", "title": "七绝·吟望", "genre": "七绝", "date": "2023.08.29", "body": "秋果盈盈景色新，\n鸣蝉飞鸟喜为临。\n可怜桔柿千疮孔，\n谁慰茅棚泣血心。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1520", "title": "七绝·闻讯吟", "genre": "七绝", "date": "2023.08.31", "body": "雷蒙多怨华为猛，\n爆款银屏耀眼星。\n向死而生今挺立，\n无情打脸不知疼！ ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1521", "title": "采桑子·天山天池", "genre": "采桑子", "date": "2023.09.01", "body": "万年岭雪冰融化。\n川水溪流，\n涛浪无忧。\n汇入瑶池王母游。\n蟠桃会上从仙乐。\n无欲何求，\n无怨何愁。\n唤鸟携云日月悠。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg", "04.jpg", "05.jpg", "06.jpg", "07.jpg", "08.jpg", "09.jpg"]}, {"poem_id": "1522", "title": "五律·九三寄怀", "genre": "五律", "date": "2023.09.03", "body": "当年倭寇败，\n今日不甘心。\n还做嚣张梦，\n犹来弄鬼神。\n奈何华夏盛，\n早已九州春。\n草木山河翠，\n巨龙腾碧云。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "1523", "title": "七绝·秋日吟", "genre": "七绝", "date": "2023.09.04", "body": "老来惬意品闲茶，\n回味当年向晚霞。\n舒卷浮云终远去，\n任由鬓发染霜华。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1524", "title": "踏莎行·寇与民", "genre": "踏莎行", "date": "2023.09.05", "body": "五味沉浮，\n一腔无奈。\n曾经多少阴招坏。\n扣人断货打华为，\n抱团围困图她败。\n任有提防，\n海思澎湃。\n深蹲飞脚高墙踹。\n纵横腾跃志凌空，\n回头已在云天外。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1525", "title": "七绝·秋日暮吟", "genre": "七绝", "date": "2023.09.06", "body": "夕阳金水河边俏，\n岸草微黄掩落晖。\n飒爽秋风今又是，\n云天人字雁南飞。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1526", "title": "七绝·秋日闲吟", "genre": "七绝", "date": "2023.09.07", "body": "笑敞胸怀体魄康，\n闲心且赏碧云光。\n低头坎坷终需过，\n昂首前行岁月长。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1527", "title": "七绝·白露吟", "genre": "七绝", "date": "2023.09.08", "body": "草木秋来七色光，\n人生五味百年尝。\n心头喜怒千般过，\n便是祸福无可慌。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1528", "title": "清平乐·缅怀主席", "genre": "清平乐", "date": "2023.09.09", "body": "人民没忘，\n日久情怀涨。\n一个声音华夏荡，\n功盖九州无上。\n九月九日同悲，\n天丝心泪纷飞。\n黄叶伤神飘落，\n凉风寒意频催。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1529", "title": "满江红·谢师恩同窗聚", "genre": "满江红", "date": "2023.09.10", "body": "京邑山河，风光秀，秋辉万里。\n重聚首，千思百感，共宵同日。\n塞北江南情不尽，相逢携手还兄弟。\n校园内，老树鸟欢鸣，云鹰喜。\n青春季，星辰起。\n楼馆内，师生事。\n更青丝白发，图强酬志。\n今返东楼回首望，汗流泪洒神州地。\n四十载，无憾为同窗，长相忆。\n踏莎行    喜重逢\n四秩春秋，\n万千昼夜。\n重逢母校情怀切。\n天南塞北鸟飞还，\n清东农苑欢声烈。\n别日青丝，\n见时霜雪。\n秦腔豫调心头悦。\n同窗聚首话今昔，\n晚霞飞渡关山越。", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "1530", "title": "七绝·边城吟望", "genre": "七绝", "date": "2023.09.12", "body": "秋香遍野色缤纷，\n云卷蝉鸣草木深。\n闲日无心观景物，\n惟思故土念双亲。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1531", "title": "七绝·吟所见", "genre": "七绝", "date": "2023.09.13", "body": "青铜器里捡刀枪，\n磨洗唬人翻自伤。\n相遇阵前多硬货，\n身无钢铁莫呈强。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1532", "title": "喝火令·天山大峡谷", "genre": "喝火令", "date": "2023.09.14", "body": "谷底溪流漫，青龙翠嶂间。半山腰处有湖泉。牛马草滩群逛，鹰雁自悠闲。\n雪岭遥相见，冰川亿万年。醉人风色染天山。夏日云飞，夏日雨丝绵，夏日客游舟渡，笑浪卷长天。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg", "04.jpg", "05.jpg", "06.jpg", "07.jpg", "08.jpg", "09.jpg"]}, {"poem_id": "1533", "title": "苏幕遮·天山大峡谷", "genre": "苏幕遮", "date": "2023.09.15", "body": "谷深长，云阵远。\n溪水奔流，翠嶂峰崖暖。\n照壁山头松子漫。\n湖上天鹅，相对情舒展。\n夏风凉，丝雨浅。\n朋侣穿行，嘻笑无人管。\n闹市憋声心底乱。\n来到此间，极目忧愁散。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "1534", "title": "七绝·吟图寄怀", "genre": "七绝", "date": "2023.09.17", "body": "民心所向比天高，\n无视岂能涛浪消。\n三座大山难自去，\n伟人挥手换今朝。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1535", "title": "破阵子·918咏怀", "genre": "破阵子", "date": "2023.09.18", "body": "又望卢沟晓月，\n叠加旧恨新仇。\n日寇洋中排秽水，\n浊浪污涛肆虐流。\n八方物态忧。\n只为东瀛私利，\n反来祸害寰球。\n人损心歪遭唾骂，\n无耻之徒不道羞。\n倭邦无可留。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1536", "title": "七绝·吟望", "genre": "七绝", "date": "2023.09.19", "body": "秋日街头百果香，\n斜晖买卖两相忙。\n手提心悦回家品，\n去载车轻喜色扬。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1537", "title": "七绝·秋日暮吟", "genre": "七绝", "date": "2023.09.20", "body": "红霞万里裹金辉，\n洒向尘间鸟欲归。\n天地无边浑一色，\n飞来绕去总难回。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1538", "title": "临江仙·秋日抒怀", "genre": "临江仙", "date": "2023.09.21", "body": "霜鬓闲身心未老，\n时而轻点银屏。\n横瞥南北与西东。\n古今天下事，\n渐次入怀中。\n贤圣英豪流誉后，\n奸臣贼子污名。\n千秋万代映长空。\n是非成与败，\n岂可尽随风。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1539", "title": "七绝·秋夜吟", "genre": "七绝", "date": "2023.09.24", "body": "秋分之日祖孙别，\n幼女回京喜见爹。\n转日老夫回故土，\n彊城挥手暂心歇。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1540", "title": "西江月·回乡吟", "genre": "西江月", "date": "2023.09.24", "body": "数尽边城夏日，\n归来故里秋风。\n云空万里绪无穷。\n入户心头方定。\n拜见堂前父母，\n闻听树杪鹂莺。\n炊烟袅袅绕榴红。\n犬吠鸡鸣相映。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1541", "title": "西江月·吟望寄怀", "genre": "西江月", "date": "2023.09.25", "body": "昂首华为吐气，\n挺胸九夏扬眉。\n奋蹄快马任凭追。\n卷起风烟无悔。\n路上牛羊忌妒，\n枝头鸦雀胡吹。\n犬狼使绊亦徒悲。\n一骑绝尘无畏。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1542", "title": "七绝·农家秋喜", "genre": "七绝", "date": "2023.09.26", "body": "耋耄家翁未肯闲，\n冬瓜上架院门前。\n根苗不负辛勤手，\n三尺皮瓤巧为餐。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1543", "title": "采桑子·亚运会", "genre": "采桑子", "date": "2023.09.27", "body": "断桥垂柳西湖畔。\n今日杭州，\n星耀寰球。\n七色缤纷异彩流。\n健儿奔跑神情奋。\n夺冠图谋，\n呐喊无休。\n握举金杯向仲秋。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1544", "title": "采桑子·回家寄怀", "genre": "采桑子", "date": "2023.09.28", "body": "中秋临近归思切。\n万里还乡，\n侍候爹娘。\n陪伴三餐焐暖床。\n闻听无遍家常事。\n东短西长，\n磨破心房。\n只为双亲眉上扬。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1545", "title": "清平乐·中秋夜", "genre": "清平乐", "date": "2023.09.29", "body": "月明天外，\n游子还家拜。\n心向高堂情自在，\n两袖清风无怪。\n丹桂摇拽飘香，\n嫦娥浅靥眉扬。\n遥望银辉玉兔，\n九州挥洒康祥。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1546", "title": "清平乐·930寄怀", "genre": "清平乐", "date": "2023.09.30", "body": "英雄远逝，\n亿万人当记。\n血洒神州山海地，\n方有今朝盛世。\n十五明月清圆，\n阖家欢聚堂前\n静好来之不易，\n缅怀先烈英贤。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "1547", "title": "五绝·游子吟", "genre": "五绝", "date": "2023.09.30", "body": "正乡思不住，\n恰月色多情。\n拂晓心难待，\n孤身赶夜程。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1548", "title": "采桑子·十一颂", "genre": "采桑子", "date": "2023.10.01", "body": "花篮锦簇门楼丽。\n万象更新，\n四季缤纷。\n华夏山河久似春。\n人逢国庆心欢喜。\n行亦思君，\n坐亦思君。\n领袖当年留下根。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg", "04.jpg", "05.jpg", "06.jpg"]}, {"poem_id": "1549", "title": "七绝·仲秋闲吟", "genre": "七绝", "date": "2023.10.02", "body": "酒不在多情意真，\n城南一味聚乡邻。\n把樽漫品廉州菜，\n风色宜人几醉心。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1550", "title": "唐多令·假日吟望", "genre": "唐多令", "date": "2023.10.03", "body": "国庆并中秋，园区客不流。踵相连，左右摇头。本是欢心观景致。如今却，满怀愁。\n昏暮困山沟，风呼月挽留。望星空，思绪难收。悔不当初回故里。门庭静，日无忧。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1551", "title": "渔家傲·假日吟望", "genre": "渔家傲", "date": "2023.10.04", "body": "节日仲秋黄叶乱，\n远行心堵车流慢。\n无奈道旁支灶碗。\n烧午饭，\n斜晖星月人难散。\n长假无情将过半，\n阻途还未家亲见。\n父老依门愁望眼。\n苦相盼，\n先前已订团圆宴。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1552", "title": "醉太平·小院中秋", "genre": "醉太平", "date": "2023.10.05", "body": "明空月远，\n清辉露浅。\n瓦墙门户桂香软。\n角梧黄叶卷。\n和家团聚心头暖。\n闲唠嗑，亲情满。\n取悦爹娘有谁懒。\n竞端茶怕晚。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1553", "title": "破阵子·家印翻车", "genre": "破阵子", "date": "2023.10.06", "body": "欲与天长地久，\n妄图五岳三山。\n白纸阴阳翻作画，\n跑马东西把地圈。\n耍狂傲世间。\n不道星高海阔，\n言行离谱无边。\n明处光鲜凭造势，\n背后贪婪洗巨钱。\n为囚臭万年。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1554", "title": "七绝·心聚", "genre": "七绝", "date": "2023.10.07", "body": "假末欢逢饮五粮，\n情深意暖透中肠。\n倾樽一霎心头醉，\n盘盏多情恋故乡。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1555", "title": "七绝·时令吟", "genre": "七绝", "date": "2023.10.08", "body": "露水清莹晓色寒，\n西风黄叶晚秋天。\n菊香漫起东篱下，\n鸡犬埋头向日边。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1556", "title": "五绝·吟望", "genre": "五绝", "date": "2023.10.09", "body": "碧水红枫衬，\n黄花漫自开。\n云空孤雁去，\n霜鬓晚秋来。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "1557", "title": "鹧鸪天·秋思", "genre": "鹧鸪天", "date": "2023.10.10", "body": "晓色朦胧独自行，\n残星隐去冷西风。\n寒鸦未醒枝头卧，\n旭日将升远处明。\n沿树径，躲车灯。\n身躯微汗绪难宁。\n归来故里无多日，\n孙女呼爷去北京。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1558", "title": "折桂令·秋思", "genre": "折桂令", "date": "2023.10.11", "body": "胸中父母孙娃。心向京都，难舍贫家。左右为难，寻思日夜，苦闷无他。\n犹似深根嫩芽，壮枝方有娇花。开谢天然，春夏轮回，久历繁华。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1559", "title": "踏莎行·秋日寄怀", "genre": "踏莎行", "date": "2023.10.12", "body": "娘老痴呆，\n爹聋勤快。\n朝依暮伴无嗔怪。\n为儿不孝走东西，\n几头老少皆吾爱。\n无术分身，\n全心祈拜。\n廉州宫面京唐菜。\n多情明月寄边城，\n且将孙女嫦娥带。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1560", "title": "踏莎行·悼明生君", "genre": "踏莎行", "date": "2023.10.13", "body": "别去一年，\n聚来无盼。\n阴阳两界空留怨。\n人逢花甲事悲秋，\n归休未稳魂飞散。\n共事情深，\n同窗意满。\n曾邀山水闲来转。\n奈君早逝愿随风，\n金樽久等鸿音断。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1561", "title": "七绝·秋日闲吟", "genre": "七绝", "date": "2023.10.14", "body": "人生好似一杯茶，\n叶展香浮卷浪花。\n水净烟消闲望月，\n于无声处是咱家。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1562", "title": "七绝·秋别", "genre": "七绝", "date": "2023.10.15", "body": "泪语爹娘多保重，\n为儿今日向京城。\n娇孙召唤将身去，\n满带浓浓二老情。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1563", "title": "七绝·秋喜", "genre": "七绝", "date": "2023.10.16", "body": "半月再逢秋意浓，\n孙娃清秀态初成。\n与爷相见情无禁，\n俏语娇言悦老翁。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "1564", "title": "七绝·本性难移", "genre": "七绝", "date": "2023.10.17", "body": "狗脸阴阳快过天，\n家亲不认咬眉间，\n口鼻血注悲声切，\n悔不当初把手牵。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1565", "title": "七绝·秋夜吟", "genre": "七绝", "date": "2023.10.22", "body": "乌云压顶终将去，\n大厦欲倾梁栋支。\n自古人生多坎坷，\n清风明月不相欺。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1566", "title": "七绝·秋夜寄妻", "genre": "七绝", "date": "2023.10.23", "body": "姐妹三人未敢眠，\n西风卷叶不知寒。\n娘亲无助心头苦，\n泪眼湿襟痛胆肝。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1567", "title": "七绝·暮秋吟", "genre": "七绝", "date": "2023.10.24", "body": "重阳心乱未登高，\n霜降来临万木凋。\n花谢逢春开又艳，\n人生逆旅似烟消。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1568", "title": "七绝·秋日吟望", "genre": "七绝", "date": "2023.10.25", "body": "妻愁古冶娘亲事，\n吾在京城为幼忙。\n寄望有人能替代，\n凌空插翅到君旁。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1569", "title": "七绝·暮秋吟", "genre": "七绝", "date": "2023.10.26", "body": "寒风卷叶命由天，\n人事消磨难两全。\n遥望云空穷碧落，\n霞晖飞渡万重山。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1570", "title": "七绝·吟怀", "genre": "七绝", "date": "2023.10.27", "body": "人生尽处己无知，\n怎奈亲朋泪眼痴。\n自古养儿防病老，\n今朝孝女榻前栖。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1571", "title": "七绝·归如箭", "genre": "七绝", "date": "2023.10.28", "body": "京城古冶快车行，\n秋景难留断雁鸣。\n黄叶悲催寒意切，\n西风撩乱老梧桐。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1572", "title": "七绝·暮秋吟", "genre": "七绝", "date": "2023.10.29", "body": "黄叶飘零亿万千，\n随风落处自心安。\n久依枝干多牵挂，\n此去断离尘世缘。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1573", "title": "七绝·秋日吟", "genre": "七绝", "date": "2023.10.30", "body": "雾笼飘窗暗晓天，\n予心沉闷守床边。\n曾闻岳母逐宵瘦，\n仍被形容骇胆肝。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1574", "title": "天净沙·秋窗寄怀", "genre": "天净沙", "date": "2023.11.01", "body": "轻阴薄雾尘天。\n细风黄叶飞烟。\n眺望难寻断雁。\n床头忍见。\n骨尖神滞衰颜。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1575", "title": "西江月·暮秋吟", "genre": "西江月", "date": "2023.11.02", "body": "黄叶秋冬漫落，\n青条春夏欣丰。\n此番情景若人生。\n万物命由天定。\n想象因人而异，\n忧愁自古相同。\n名财功利害无穷。\n世事沉浮如梦。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1576", "title": "五律·痛悼岳母", "genre": "五律", "date": "2023.11.07", "body": "雨送先人去，\n风悲孝女心。\n八十七载路，\n一世善为人。\n家婿眸含泪，\n外孙怀感恩。\n目亲乘鹤远，\n仙界万年春。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1577", "title": "鹧鸪天·立冬寄怀", "genre": "鹧鸪天", "date": "2023.11.08", "body": "亲去床空夜色沉，\n临窗星月意情真。\n蟾光缕缕频相顾，\n桐叶悄悄探旧邻。\n容不在，静无音。\n冷香寒蜡袅烟尘。\n飞霜滴露千般痛，\n悲不堪言泪染襟。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1578", "title": "七律·代妻吟", "genre": "七律", "date": "2023.11.09", "body": "老娘仙逝女白头，\n胸底堆积无限愁。\n谁可解开思念扣，\n何人能闭泪泉流。\n寒风吹荡悲情切，\n落叶飞飘痛苦尤。\n更恨当初病来迅，\n家亲心愿未曾留。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1579", "title": "七绝·初冬吟", "genre": "七绝", "date": "2023.11.10", "body": "人生长卷写春秋，\n字里云烟染喜忧。\n书过今朝成往事，\n章残笔落子孙留。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1580", "title": "虞美人·初冬夜吟", "genre": "虞美人", "date": "2023.11.11", "body": "秋冬转换心怀冷，\n叶落风难定。\n床头不见旧音容，\n往日灯光彻夜、映苍穹。\n星空万里悲情递，\n百念凭风寄。\n愿亲乘鹤去无忧，\n碧落云霄俱事、不须愁。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1581", "title": "五律·先人居", "genre": "五律", "date": "2023.11.13", "body": "黄泉三尺土，\n十万雪花银。\n逝者安眠地，\n来生富贵身。\n出行龙马伴，\n坐卧使佣人。\n玉女金童俏，\n山桃水鸟亲。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1582", "title": "临江仙·初冬寄怀", "genre": "临江仙", "date": "2023.11.17", "body": "窗外寒风黄叶落，\n阳台暖意融融。\n绿萝抖擞满怀情。\n吊兰依角立，\n妻子理芳丛。\n前日悲伤思绪甚，\n无心青翠娇红。\n任由架倒瓦盆横。\n今朝精打扮，\n旧貌换新容。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1583", "title": "踏莎行·吟望", "genre": "踏莎行", "date": "2023.11.18", "body": "侧脸无情，\n横眉冷对。\n不知下句谁遭罪。\n为防失态恁揪心，\n有谁能晓今番累。\n人老言迟，\n枝残花坠。\n寒蛩秋暮嘶声废。\n奈何统领却贪权，\n案前议事常昏睡。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1584", "title": "渔家傲·闻事吟", "genre": "渔家傲", "date": "2023.11.20", "body": "果敢明家应早料，\n横行犯法终遭报。\n子女风光挥镣铐。\n天地笑，\n枝头莺雀频欢叫。\n在外出行须看道，\n遵规守矩休胡闹。\n肥己害人逃不掉。\n天地妙，\n人间善恶皆知晓。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1585", "title": "七绝·童智", "genre": "七绝", "date": "2023.11.21", "body": "父女离京古冶来，\n觅爷恋奶乐开怀。\n半年已过家犹记，\n抬手推门不用猜。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "1586", "title": "浣溪沙·玩童", "genre": "浣溪沙", "date": "2023.11.22", "body": "三岁将临小若煊。\n弯眉纤手靥辉圆，\n朱唇乌发笑声连。\n蹦跳轻盈如玉兔，\n歌吟婉转似银蝉。\n明眸灵动舞风前。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1587", "title": "七绝·冬日闲吟", "genre": "七绝", "date": "2023.11.24", "body": "寒流无意刻窗花，\n黄叶多情恋晓鸦。\n不忍别离含泪去，\n飘零何处可安家。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1588", "title": "鹧鸪天·小保洁", "genre": "鹧鸪天", "date": "2023.11.25", "body": "个比拖杆矮一截，\n埋头擦地影痕斜。\n腰身转动眉飞舞，\n腿脚开合体欲跌。\n人瘦小，手无歇。\n厅堂卧室渐光洁。\n女童欢乐阖家喜，\n最是开心还数爷。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "1589", "title": "浣溪沙·冬日吟望", "genre": "浣溪沙", "date": "2023.11.26", "body": "小雪时来冷不休，\n霜花摇拽挂枝头。\n丹枫红叶胜深秋。\n一抹青辉霄汉阔，\n无边绿色覆阡畴。\n农闲望麦少烦忧。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1590", "title": "七绝·杂趣", "genre": "七绝", "date": "2023.11.28", "body": "锅中螃蟹不甘心，\n乱舞尖钳向我孙。\n幼女围观忽近远，\n既欢又怕耍童真。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1591", "title": "七绝·家趣", "genre": "七绝", "date": "2023.11.30", "body": "小手纤纤挑绿豆，\n追随奶奶看生芽。\n每天睡眼轻声问，\n终见银针这大啦。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1592", "title": "踏莎行·图趣", "genre": "踏莎行", "date": "2023.12.01", "body": "蓝色梯形，\n桔红三角\n多边方块拼图妙。\n荷花莲叶趣成辉，\n齿轮转过时光好。\n动静结合，\n神魂颠倒。\n祖孙同乐终昏晓。\n协调手脑利身心，\n幼童健长爷难老。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg", "04.jpg", "05.jpg", "06.jpg"]}, {"poem_id": "1593", "title": "蝶恋花·吟望", "genre": "蝶恋花", "date": "2023.12.03", "body": "苦难人生衰老易。\n青发朱颜，\n还有谁能记。\n日暮青灯冬夜里，\n打窗风雪寒声递。\n慕富嫌贫今古世。\n打破头皮，\n踮脚争名利。\n穷困爹娘徒有子，\n门前寥落悲无计。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1594", "title": "七绝·冬日闲吟", "genre": "七绝", "date": "2023.12.04", "body": "淡定乡翁岁月悠，\n老心宁静少烦愁。\n漫行所处皆风景，\n何惧寒霜雪染头。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1595", "title": "七绝·吟望", "genre": "七绝", "date": "2023.12.06", "body": "任风由雨稳如山，\n自信人生二百年。\n气势高低崖谷处，\n雄鹰飞过鸟回还。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1596", "title": "七绝·时令吟", "genre": "七绝", "date": "2023.12.07", "body": "大雪时光无雪花，\n金黄漫地映寒鸦。\n北风刺骨枝摇拽，\n杂病猖狂百姓家。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1597", "title": "踏莎行·痛", "genre": "踏莎行", "date": "2023.12.16", "body": "戴月迎风，\n出门赶路。\n为孙排队求医护。\n连天咳嗽恁愁爷，\n高烧不退情无助。\n人满厅堂，\n瓶盈梁柱。\n孩童哭闹声飞度。\n雪花吻地透心凉，\n更添等盼煎熬苦。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1598", "title": "七绝·苦吟", "genre": "七绝", "date": "2023.12.18", "body": "三岁娇娃吊小瓶，\n老翁陪伴恁心疼。\n病毒肆虐人无措，\n祈祷将身替稚童。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1599", "title": "七绝·吟娇孙", "genre": "七绝", "date": "2023.12.19", "body": "纤细银针血脉连，\n晶莹玉液体循环。\n可怜幼女皮薄嫩，\n不闹赢夸五六天。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1600", "title": "踏莎行·冬夜吟望", "genre": "踏莎行", "date": "2023.12.20", "body": "冷月当空，\n银辉染地。\n枯枝残雪寒鸦泣。\n北风凛冽刺行人，\n急归脚下冰无计。\n紧扯衣裳，\n轻舒腹气。\n驱前缓慢时停立。\n家中有事火攻心，\n进门病倒无人替。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1601", "title": "踏莎行·孙女生日", "genre": "踏莎行", "date": "2023.12.22", "body": "昨日煊煊三岁喜。\n玩偶萦身，\n手舞眉飞立。\n金鼠欢腾逢盛世，\n厅堂回荡精灵气。\n精美蛋糕凝厚意。\n寿面丝滑，\n缕缕长相忆。\n父母开心情不已，\n舒怀爷奶神魂奕。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg", "04.jpg", "05.jpg", "06.jpg", "07.jpg", "08.jpg", "09.jpg"]}, {"poem_id": "1602", "title": "鹧鸪天·祝娘高寿", "genre": "鹧鸪天", "date": "2023.12.23", "body": "尝罢孙娃生日餐，\n驱车千里拜娘前。\n寒风难阻归家路，\n残雪漫扬轮毂间。\n合兄妹，把杯盘。\n鸡丝鱼片敬椿萱。\n福如东海南山寿，\n情似苍崖不老天。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "1603", "title": "西江月·冬日冷暖", "genre": "西江月", "date": "2023.12.24", "body": "大雪多年少见，\n低温近日常闻。\n夜行刺脸冻双唇，\n脚下歪斜难稳。\n路上黄衣挥汗，\n街头白絮移身。\n晓来出外喜行人，\n回望点头询问。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "1604", "title": "七绝·冬趣", "genre": "七绝", "date": "2023.12.25", "body": "九九消寒梅尽染，\n雪飞腊月喜迎春。\n古人雅趣闲挥墨，\n妙手丹青赋韵文。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1605", "title": "沁园春·缅怀主席", "genre": "沁园春", "date": "2023.12.26", "body": "……伟人诞辰130周年寄怀\n坦荡无私，独爱神州，沥血为民。\n纵离妻失子，初心不改，穷山险水，壮志凌云。\n坎坷一生，豪情万丈，唤醒工农翻了身。\n轻挥手，便情迷百姓，号令三军。\n神魂历久弥新。到今日，遍华夏念君。\n望韶山冲里，人潮涌动，延安塔下，鼓点同频。\n日月齐欢，江河共唱，劲舞高歌情意真。\n永不忘，恰东方红日，暖耀国人。", "image_files": ["01.jpg", "02.jpg", "03.jpg", "04.jpg", "05.jpg", "06.jpg"]}, {"poem_id": "1606", "title": "清平乐·敬缅主席", "genre": "清平乐", "date": "2023.12.27", "body": "东方红日，\n偶被乌云蔽。\n雾散霾除明万里，\n无限光芒永世。\n寒冬温暖人间，\n春秋花果欣妍。\n夏季驱阴消雨，\n神州岁月悠然。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1607", "title": "七绝·坚守", "genre": "七绝", "date": "2023.12.28", "body": "铁塔凌空银线舞，\n翻江越岭送光明。\n为得百姓寒冬暖，\n无惧山头饮朔风。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg", "04.jpg"]}, {"poem_id": "1608", "title": "七绝·晓吟", "genre": "七绝", "date": "2023.12.29", "body": "轻阴薄雾笼寒冬，\n残叶栖鸦冷瑟中。\n晨练乡邻争上杠，\n腾身转体暖融融。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1609", "title": "七律·岁暮吟", "genre": "七律", "date": "2023.12.30", "body": "坚守变通人世间，\n红花绿叶景光妍。\n缩头龟可千年寿，\n昂首猪来一岁难。\n猴子化身无数个，\n唐僧执念向西天。\n悠悠日月轮回动，\n恒是东升缺或圆。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1610", "title": "长相思·岁杪寄怀", "genre": "长相思", "date": "2023.12.31", "body": "送一年，又一年。\n来往劳神两鬓残。\n匆忙岁月天。\n苦三番，乐三番。\n几度春秋风雨间。\n老来心坦然。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1611", "title": "十六字令·元旦", "genre": "十六字令", "date": "2024.01.01", "body": "年。\n似水光阴漫向前。\n无穷尽，\n日月度关山。\n年。\n市井乡邻多笑颜。\n频招手，\n得空闹樽前。\n年。\n温暖如春微信间。\n临屏问，\n万里若厅前。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1612", "title": "五绝·童欢", "genre": "五绝", "date": "2024.01.02", "body": "新年童稚乐，\n礼物可心怀。\n浅靥腮边俏，\n眉梢向上开。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1613", "title": "朝中措·寒冬慢行", "genre": "朝中措", "date": "2024.01.03", "body": "一宵薄雾晓来晴，\n霾散赖东风。\n残雪街头连片，\n路人躲闪前行。\n今冬别样，\n异常寒冷，\n冰处难溶。\n出外留心防范，\n切毋坏了心情。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1614", "title": "七绝·岁暮寄怀", "genre": "七绝", "date": "2024.01.04", "body": "兔将离任龙张望，\n人欲归休茶水凉。\n尘世人间同岁月，\n且行且卧莫心伤。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "1615", "title": "蝶恋花·二九吟望", "genre": "蝶恋花", "date": "2024.01.05", "body": "酷冷严冬铺雪地，\n多在厅堂，\n谨慎门前立。\n近日回温天转丽，\n纷纷出外寻情趣。\n残雪消溶冰水溢。\n清澈潺潺，\n轻浪欢歌去。\n抒展胸怀深纳气，\n周身寒透赢心意。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "1616", "title": "七绝·节令吟", "genre": "七绝", "date": "2024.01.06", "body": "昨天雪水夜成冰，\n今日小寒君慢行。\n三九将来温色降，\n晓枝鸦雀梦魂惊。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1617", "title": "五绝·闲吟", "genre": "五绝", "date": "2024.01.07", "body": "家是故乡亲，\n金樽敬旧人。\n无关深与浅，\n把盏最欢心。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1618", "title": "七绝·咏叹", "genre": "七绝", "date": "2024.01.08", "body": "夜围炉火话当年，\n转眼稚童霜鬓颜。\n岁月公平留印迹，\n额头纹络共樽前。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1619", "title": "七绝·吟望", "genre": "七绝", "date": "2024.01.10", "body": "高知入米落街头，\n堕水浮萍任浪流。\n丢尽馨香清雅气，\n风寒无奈惹人愁？ ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1620", "title": "五绝·难", "genre": "五绝", "date": "2024.01.11", "body": "冬至老人难，\n躲风难躲寒。\n爹娘多病痛，\n愁子不堪言。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1621", "title": "七绝·军威", "genre": "七绝", "date": "2024.01.12", "body": "南昌舰艇斗波涛，\n掌舵娇颜气势豪。\n左转右旋龙欲跃，\n海空万里任逍遥。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg", "04.jpg"]}, {"poem_id": "1622", "title": "行香子·冬日咏怀", "genre": "行香子", "date": "2024.01.13", "body": "风雨人生，霜鬓从容。陪老人携手孙童。游玩水榭，闲眺云空。戏棋中马，水中蟹，草中虫。\n不觉寒暑，钟情燕雀。悦厅堂稚语耆声。时光飞逝，岁月安宁。更心无憾，身无债，梦无惊。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1623", "title": "蝶恋花·欣闻有感", "genre": "蝶恋花", "date": "2024.01.14", "body": "…贺引力一号发射\n海上巨龙喷火焰。\n万里长空，\n一道辉光灿。\n移动礁盘来备战，\n远洋深处谁寻见。\n巧妙伪装容貌变。\n暗里无声，\n瞄准人间怨。\n一霎烟消乌兽散，\n可平尘世千般乱。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg", "04.jpg"]}, {"poem_id": "1624", "title": "五绝·赠友", "genre": "五绝", "date": "2024.01.15", "body": "负任入京城，\n不图功与名。\n老来心益壮，\n策马志无穷。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1625", "title": "七绝·吟望", "genre": "七绝", "date": "2024.01.16", "body": "一张纸片惹烟尘，\n霾雾遮天日色阴。\n只待清风扫寰宇，\n隆冬虽冷净无云！ ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1626", "title": "蝶恋花·吟望寄怀", "genre": "蝶恋花", "date": "2024.01.17", "body": "黑手岂能遮日月。\n山陡枝高，\n难挡飞天雪。\n滴水成河淹蚁阙，\n波涛推浪残渣泄。\n老笔纵横和泪写。\n百姓呼声，\n阵阵通天界。\n定有霞辉驱暗夜，\n晴空万里苍生悦。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1627", "title": "西江月·腊八", "genre": "西江月", "date": "2024.01.18", "body": "前夜精心挑米，\n清晨温火熬粥。\n厅堂香味渐浓稠。\n大小碗排前后。\n奶奶轻端慢品，\n娇孙紧把无休。\n风寒腊日更何求。\n惬意心怀暖透。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1628", "title": "采桑子·闻事有感", "genre": "采桑子", "date": "2024.01.19", "body": "天平不稳随风晃。\n砝码轻摇，\n称重虚飘。\n百姓心头虑不消。\n古今打铁身须硬。\n锻造钉销，\n莫差分毫。\n斧钺钩叉气自高。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1629", "title": "七绝·时令吟", "genre": "七绝", "date": "2024.01.20", "body": "日过大寒临近年，\n冰溶雪化露真颜。\n梅花竞秀迎春到，\n京客思乡尽望南。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1630", "title": "七绝·四九晓吟", "genre": "七绝", "date": "2024.01.21", "body": "寒潮骤降晓风急，\n红日遥升暖色迟。\n赶早出行人罩面，\n枝头惊梦鸟声凄。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1631", "title": "七律·吟望寄友", "genre": "七律", "date": "2024.01.22", "body": "裹带京城霜雪意，\n来寻宝岛俏风情。\n裘衣褪却心怀爽，\n波浪徘徊鸥鹭萌。\n兄弟追云欢戏水，\n夫妻揽月弄涛声。\n天涯海角同窗聚，\n斑鬓年光兴趣浓。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg", "04.jpg"]}, {"poem_id": "1632", "title": "鹧鸪天·年声", "genre": "鹧鸪天", "date": "2024.01.24", "body": "天地风寒难掩情，\n灯笼高挂味趋浓。\n龙年脚步声声近，\n庭院枝头点点红。\n兴集市，蟹虾丰。\n乡邻照面喜盈盈。\n竹篮布袋回身满，\n笑脸弯腰语不停。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1633", "title": "七绝·闻事吟", "genre": "七绝", "date": "2024.01.25", "body": "与人为善路平宽，\n孝敬双亲日夜安。\n和睦夫妻香火旺，\n持家创业两周全。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1634", "title": "清平乐·岁杪吟望", "genre": "清平乐", "date": "2024.01.28", "body": "车流似水，\n年近心头醉。\n来往东西辞旧岁，\n南北穿梭回味。\n同窗把盏言欢，\n老乡玉液频干。\n战友豪情益壮，\n白红见底轮番。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1635", "title": "七绝·冬日吟", "genre": "七绝", "date": "2024.01.29", "body": "功名远去病加身，\n几案书香陶冶心。\n耆老莫求青壮事，\n与孙为乐共童真。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1636", "title": "七绝·闻事吟", "genre": "七绝", "date": "2024.01.30", "body": "沾花君子斗蛐臣，\n时代不同别样人。\n雨雪从来天际落，\n身心生就本无尘。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1637", "title": "七律·遥望寄怀", "genre": "七律", "date": "2024.01.31", "body": "节前天际雪花多，\n年后河塘漾碧波。\n四海飘游华夏子，\n一心搭乘故乡车。\n泥尘无惧双亲拜，\n情义深沉老少和。\n守岁秉烛先祖祭，\n阳春再奏凯旋歌。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1638", "title": "踏莎行·龙年大礼", "genre": "踏莎行", "date": "2024.02.01", "body": "意料之中，\n闻听尤奋。\n手屏夜半传佳讯。\n白刘魏害罪应得，\n折身依法香烛烬。\n天网恢恢，\n国威震震。\n神州号令中华盾。\n名高气壮映八方，\n环球瞩目今番信。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1639", "title": "七绝·灶前吟", "genre": "七绝", "date": "2024.02.02", "body": "转眼时光到小年，\n灶王言事上青天。\n临行询问人间愿，\n嘱与帝君约束仙。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1640", "title": "七律·岁杪吟望", "genre": "七律", "date": "2024.02.03", "body": "预期雪影未曾来，\n许是天公释善怀。\n知晓人间节日到，\n遣将琼粉饰瑶台。\n众仙协奏阳春曲，\n百姓合赢盛世牌。\n南北红灯分外艳，\n东西锣鼓震八垓。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1641", "title": "七律·立春有寄", "genre": "七律", "date": "2024.02.04", "body": "新年未到已逢春，\n不日花红柳色深。\n岁至甲辰龙劲舞，\n时当盛世故乡亲。\n归家游子心头热，\n把盏香醪敬旧邻。\n转眼除夕鞭炮响，\n桃符更换喜盈门。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1642", "title": "卜算子·岁暮吟", "genre": "卜算子", "date": "2024.02.05", "body": "昨日已春归，\n岁月悄然过。\n一寸光阴不欠谁，\n别怪天公错。\n世路百千条，\n莫作无心客。\n右侧言明有玉山，\n你却偏行左。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1643", "title": "七绝·春来闲吟", "genre": "七绝", "date": "2024.02.06", "body": "为人感悟与时增，\n处世修行理渐通。\n怎奈时光染霜鬓，\n春归更羡草重生。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1644", "title": "卜算子·吟望", "genre": "卜算子", "date": "2024.02.07", "body": "绿影冷森森，\n远望凉风透。\n多少国人夜未眠，\n无奈街头遛。\n投入去无回，\n运气千般臭。\n已近年关苦不言，\n假笑娘前凑。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1645", "title": "五绝·岁杪", "genre": "五绝", "date": "2024.02.08", "body": "清晓街头静，\n寻常忙者闲。\n除夕明日至，\n好梦过年关。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1646", "title": "满庭芳·过大年", "genre": "满庭芳", "date": "2024.02.10", "body": "鞭炮轰鸣，烟花璀璨，昔时年味回还。\n红灯高挂，福字映阶前。\n万户千家同庆，点香火、祭祖堂前。\n净庭院，风尘不染，晴日对春联。\n望枝头喜鹊，飞身跳跃，羽艳声欢。\n守岁夜，阖家老少团圆。\n手把金樽畅饮，钟声响、龙兔交班。\n新年到，东方红日，耀万里河山。", "image_files": ["01.jpg"]}, {"poem_id": "1647", "title": "七绝·省亲", "genre": "七绝", "date": "2024.02.11", "body": "大年初二走娘家，\n车载手牵夫与娃。\n梦里几番呼父母，\n今朝相见靥如花。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1648", "title": "七绝·新春闲吟", "genre": "七绝", "date": "2024.02.12", "body": "初三晓静路无人，\n昨日重逢醉了心。\n亲友同欢托好梦，\n春宵熟睡养精神。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1649", "title": "踏莎行·吟望咏怀", "genre": "踏莎行", "date": "2024.02.13", "body": "内地祥和，\n边疆毅勇。\n山川将士眸光炯。\n踏冰卧雪保家园，\n赢得华夏黎民颂。\n节日思亲，\n闲时想静。\n赖凭门户无人动。\n若非国盛壮三军，\n便当酷暑心头冷。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "1650", "title": "七绝·初五有寄", "genre": "七绝", "date": "2024.02.14", "body": "凌晨鞭炮响连天，\n破五财神喜迓还。\n数载声消烟火断，\n今朝遍处爆花妍。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1651", "title": "七律·过年", "genre": "七律", "date": "2024.02.15", "body": "春晚欢鲜滋味淡，\n闷头酣睡几多年。\n幸得鞭炮回宵夜，\n助兴亲朋宴案前。\n龙兔交班华夏悦，\n弟兄守岁醉心田。\n东风吹荡烟花雨，\n万里金星璀璨天。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1652", "title": "七绝·年趣", "genre": "七绝", "date": "2024.02.16", "body": "竹雨堂中叙旧情，\n金樽玉液鬓霜浓。\n光阴飞逝三十载，\n再话初逢感慨生。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1653", "title": "七律·快乐时光", "genre": "七律", "date": "2024.02.17", "body": "过年最乐属孩童，\n压岁红包染稚容。\n花炮飞鸣纤手舞，\n糖人传递故乡情。\n走家串户逢亲拜，\n姑舅叔伯祝愿声。\n日日开心宵不寐，\n时时笑靥映长空。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg", "04.jpg", "05.jpg", "06.jpg"]}, {"poem_id": "1655", "title": "七绝·得失", "genre": "七绝", "date": "2024.02.18", "body": "最长节假把人闲，\n初九上工情不甘。\n却是荣休心静好，\n寻常日月总如年。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1656", "title": "七绝·时令吟", "genre": "七绝", "date": "2024.02.19", "body": "雨水时节雪探头，\n寒潮复降惹人愁。\n新春本欲花初绽，\n此弄枝芽不自由。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1657", "title": "蝶恋花·初春晓吟", "genre": "蝶恋花", "date": "2024.02.20", "body": "春雪夜来寒又至。\n丝雨加杂，\n混入泥尘地。\n晓色阴沉云蔽日，\n新春喜庆浑无计。\n苦了行人谁可替。\n赶点开工，\n惆怅心憋气。\n惟盼长空霄汉霁，\n东风吹荡城乡丽。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1658", "title": "七绝·倒春寒", "genre": "七绝", "date": "2024.02.21", "body": "时逢雨水雪纷纷，\n天地茫茫少见人。\n便是舟车风里卧，\n树鸦凄瑟断肠魂。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1659", "title": "七绝·初春赠友", "genre": "七绝", "date": "2024.02.22", "body": "天女散花风漫舞，\n黄梅香溢沁心魂。\n十方院里虔诚客，\n金阙宫中辞旧身。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1660", "title": "七律·元宵节", "genre": "七律", "date": "2024.02.24", "body": "一口汤圆软糯甜，\n观灯品味甲辰年。\n龙腾鱼跃金猴奋，\n马踏羊牵玉兔欢。\n情侣街头明月照，\n宾朋庭院望花天。\n银光火树星空夜，\n鼓乐笙箫谁个眠。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1661", "title": "西江月·新春北上", "genre": "西江月", "date": "2024.02.26", "body": "正月廉州别却，\n孤身京邑前行。\n两头牵挂一腔情，\n老少盈怀搅动。\n守岁椿萱同乐，\n赏灯孙女期空。\n今朝能去意千重，\n心在旅途难定。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1662", "title": "七绝·心愿", "genre": "七绝", "date": "2024.02.28", "body": "春来又到入园时，\n三岁娇娃有所期。\n询问爷爷能去否，\n闻声稚脸喜滋滋。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1663", "title": "七律·春会吟望", "genre": "七律", "date": "2024.03.03", "body": "建言国是聚京城，\n汇纳神州百姓声。\n田野禾苗应更壮，\n庙堂财物怎尤丰。\n山河无恙凭谁守，\n道路微坑几日平，\n广厦栋梁堪重任，\n经霜沐雨抗西风。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1664", "title": "七绝·春日闲吟", "genre": "七绝", "date": "2024.03.04", "body": "有缘早晚能相遇，\n少爱夫妻亦闹翻。\n朋侣推心天地久，\n弟兄计较苦无边。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1665", "title": "七绝·惊蛰有寄", "genre": "七绝", "date": "2024.03.05", "body": "地温渐暖搅虫眠，\n睡眼惺忪杂草间。\n不道朔风吹雪日，\n自鸣所见数他全。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1666", "title": "七律·新春代孙吟", "genre": "七律", "date": "2024.03.07", "body": "梦里入园今日成，\n明眸浅靥放歌声。\n爸妈别我辛劳作，\n爷奶驱车快乐行。\n门口随师挥手去，\n厅堂与伴笑眉平。\n童真难掩心头悦，\n蹦跳欢言游戏中。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "1667", "title": "踏莎行·贺三八", "genre": "踏莎行", "date": "2024.03.08", "body": "笑靥红妆，\n穿针引线。\n育儿养老千斤担。\n贤妻良母古来今，\n弓身巧手丰盈饭。\n职场玫瑰，\n征途花旦。\n英姿飒爽情无限。\n扬鞭策马傲须眉，\n齐驱并驾山峰见。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1668", "title": "朝中措·新春乐园", "genre": "朝中措", "date": "2024.03.10", "body": "一群三岁俏孩童，\n鲜有泣哭声。\n稚语招人引笑，\n明眸闪动多情。\n扬眉起舞，\n随师咏唱，\n悦嗓欢容。\n迎面春风陶醉，\n归来浅靥盈盈。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "1669", "title": "七绝·二月二", "genre": "七绝", "date": "2024.03.11", "body": "飞龙昂首傲八方，\n旭日霞辉万里扬。\n又抖精神重远去，\n行囊珠满再还乡。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1670", "title": "七律·植树寄怀", "genre": "七律", "date": "2024.03.12", "body": "今栽小院一棵苗，\n期许遮阴风水调。\n酷暑炎光能蔽日，\n严霜寒地赏花娇。\n长年喜鹊枝头卧，\n后世佳丁才气高。\n岁月无忧潇洒过，\n乘凉树下自逍遥。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1671", "title": "七绝·咏春", "genre": "七绝", "date": "2024.03.13", "body": "日影星辉万象新，\n物华景秀水宜人。\n花妍鸟啭山峰丽，\n翠色青云撩老身。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1672", "title": "七绝·春晓", "genre": "七绝", "date": "2024.03.14", "body": "人多未起太阳升，\n东海泛波霄汉红。\n紫气蒸腾笼华夏，\n神州草树沐春风。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1673", "title": "七绝·春分", "genre": "七绝", "date": "2024.03.20", "body": "天均昼夜软风吹，\n陌上花妍翠柳垂。\n旭日初升人早起，\n谋生晨练不须催。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1674", "title": "七绝·幼儿迎春", "genre": "七绝", "date": "2024.03.20", "body": "春分彩蛋立桌台，\n稚脸明眸笑靥开。\n幼小心灵叹奇妙，\n师生携手乐膺怀。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "1675", "title": "鹧鸪天·幼儿踏青", "genre": "鹧鸪天", "date": "2024.03.21", "body": "童稚寻芳百子湾，\n湖堤缓步手相牵。\n闻听翠鸟高歌唱，\n观看金鱼戏水边。\n争询问，抢声言。\n如何花艳是春天。\n谁人能解黄莺语，\n宛转清音为那般？ ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "1676", "title": "七绝·春日吟", "genre": "七绝", "date": "2024.03.22", "body": "抬头忽见柳条青，\n万物更新赖雨风。\n滋润根苗辞旧貌，\n凭得紫气绽芳容。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1677", "title": "七绝·敬王校长", "genre": "七绝", "date": "2024.03.23", "body": "赞誉漫传人去后，\n定因诚意换民心。\n坐行磊落繁霜鬓，\n传道黉门幸此君。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "1678", "title": "七律·花蕾初绽", "genre": "七律", "date": "2024.03.24", "body": "风吹杨柳万千条，\n翠色京城别样娇。\n多彩幼儿初试镜，\n真情稚脸把人招。\n对答流畅心无怯，\n手眼翩跹气亦高。\n三岁乖孙赢赞誉，\n染霜爷奶乐逍遥。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg", "04.jpg", "05.jpg", "06.jpg"]}, {"poem_id": "1679", "title": "五绝·三月春", "genre": "五绝", "date": "2024.03.25", "body": "翠色暖风来，\n木棉花盛开。\n温馨红火意，\n摇曳入心怀。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1680", "title": "踏莎行·春思", "genre": "踏莎行", "date": "2024.03.26", "body": "晓色微明，\n晨曦初照。\n百花娇艳惊栖鸟。\n风摇细柳绿飘垂，\n阳春三月人行早。\n追赶时光，\n争淘珠宝。\n一心只为门庭好。\n阖家老幼眼睁睁，\n可怜青壮闲思少。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1681", "title": "踏莎行·童春悦行", "genre": "踏莎行", "date": "2024.03.27", "body": "一早乘车，\n半天游览。\n幼儿满座欢声伴。\n巡观义利面包房，\n师生仿制赢称赞。\n缕缕飘香，\n丝丝扣愿。\n装兜提袋将家返。\n童言稚语笑翻天，\n枝头花朵争相看。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg", "04.jpg", "05.jpg", "06.jpg"]}, {"poem_id": "1682", "title": "七绝·闲吟", "genre": "七绝", "date": "2024.03.28", "body": "街店冷清医处忙，\n熬时漫等起心慌。\n原来伤痛还无看，\n怎奈新忧断我肠。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1683", "title": "七律·隔屏赠友", "genre": "七律", "date": "2024.03.29", "body": "多年未见酒相迎，\n伊力陈醪色味浓。\n迪化风情催客醉，\n楼兰美馔伴君行。\n昔时杨柳殷勤问，\n边地花枝慰远朋。\n战友欢谈军旅事，\n同窗笑忆校园声。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "1684", "title": "七绝·春趣", "genre": "七绝", "date": "2024.03.30", "body": "湖苑枝头别样花，\n朱唇浅靥绽芳华。\n飞来莺鹊长凝视，\n怎个先前未见她。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "1685", "title": "行香子·踏青", "genre": "行香子", "date": "2024.03.31", "body": "春日乘风，父女前行。染霜爷奶喜陪同。京城郊外，暖丽云空。望陌头翠，枝头彩，渡头明。\n温榆河畔，人来车往。耳旁盈荡趣欢声。沙滩闲坐，远眺雄鹰。自心生悦，脑生念，目生情。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg", "04.jpg", "05.jpg", "06.jpg"]}, {"poem_id": "1686", "title": "鹧鸪天·重游万牲园", "genre": "鹧鸪天", "date": "2024.04.01", "body": "假日前来狮虎山，\n娇孙添岁任由欢。\n金丝猴处开心舞，\n大象身旁露俏颜。\n熊猫秀，企鹅安。\n喜逢鹦鹉语声连。\n去年斑马今还在，\n嘶叫犹如唤若煊。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg", "04.jpg", "05.jpg", "06.jpg"]}, {"poem_id": "1687", "title": "七绝·童趣有感", "genre": "七绝", "date": "2024.04.02", "body": "鼠兔本该行陌阡，\n纵横黄土近云烟。\n如今身陷籓笼里，\n看似无忧不自然。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "1688", "title": "踏莎行·观展寄怀", "genre": "踏莎行", "date": "2024.04.03", "body": "一个星球，\n万千生物。\n自来演变谁停步。\n惟当人类立潮头，\n乘风踏浪旗独树。\n活在今朝，\n晓知远古。\n暗生感慨无穷数。\n珍惜眼下每一天，\n光阴逝去无从复。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg", "04.jpg", "05.jpg", "06.jpg"]}, {"poem_id": "1689", "title": "七绝·清明", "genre": "七绝", "date": "2024.04.04", "body": "山川草木色清新，\n堕泪天公祭逝魂。\n悲痛家亲肠欲断，\n纸烟缭绕万千坟。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1690", "title": "七绝·仲春吟望", "genre": "七绝", "date": "2024.04.07", "body": "尘世春回昼渐长，\n百花争艳漫清香。\n巡天日月情无怠，\n熠煜山川草木芳。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1691", "title": "七律·将老抒怀", "genre": "七律", "date": "2024.04.08", "body": "心静方能明事理，\n人闲才可与孙欢。\n怱忙于世遗烦恼，\n急躁攻身伤胆肝。\n枯木逢春花竞艳，\n状元去势度残年。\n白云无所空中乐，\n翠鸟高巢风后难。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1692", "title": "踏莎行·春日欣讯", "genre": "踏莎行", "date": "2024.04.10", "body": "瞩目迁西，\n关心贵富。\n历经仨月清门户。\n春宵夜半落锤音，\n翻山跨海云飞度。\n声震乌鸦，\n魂惊老虎。\n黎民闻讯欢无数。\n为官切莫乱言行，\n越池逾矩名如鼠。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1693", "title": "七绝·回头吟", "genre": "七绝", "date": "2024.04.11", "body": "风雨由天人自主，\n体勤心奋争寒暑。\n壮时尝胆闯东西，\n耆老年光难受苦。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1694", "title": "浪淘沙·西北吟望", "genre": "浪淘沙", "date": "2024.04.12", "body": "大漠望无边，\n远上云端。\n微茫人马玉沙间。\n行走千年浑未变，\n今古同天。\n往事自悠然，\n际阔心闲。\n置身此处忘忧烦。\n一任黄风来又去，\n不改初颜。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "1695", "title": "鹧鸪天·别样春游", "genre": "鹧鸪天", "date": "2024.04.13", "body": "……赠马英九\n人老情疏念故乡，\n乘风跨海鬓毛扬。\n寻根俯首黄陵拜，\n追梦思贤著华章。\n秦俑叹，泪山冈。\n几回掩泣绪飘茫。\n中山墓畔伤残胆，\n东大厅中悔旧肠。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1696", "title": "七绝·闻事吟", "genre": "七绝", "date": "2024.04.14", "body": "善友同行世路宽，\n无情风雨共承担。\n征途坎坷勤携手，\n对视抬头望远天。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1697", "title": "唐多令·贺马逍新婚", "genre": "唐多令", "date": "2024.04.15", "body": "春雨贵如油，\n花枝彩染头。\n宴会厅、灯丽光流。\n友子成婚宾客喜，\n尊盏满、贺无休。\n父母乐悠悠，\n新人笑语稠。\n自今朝、爱甚情周。\n共枕同眠寻好梦，\n携玉手、任欢游。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1698", "title": "清平乐·吟趣", "genre": "清平乐", "date": "2024.04.16", "body": "借凭婚宴，\n幸会同窗面。\n别久各忙鲜有见，\n今日归休多半。\n左右斑鬓霜丝，\n容光不似当时。\n谈笑不曾相认，\n说来名姓深知。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1699", "title": "七律·廉州一绝", "genre": "七律", "date": "2024.04.17", "body": "华夏宫灯自藁城，\n屯头工匠远闻名。\n一村千户心灵巧，\n十巷九条庭院红。\n王谢堂前飘丽影，\n天安门上映长空。\n神州内外赢声誉，\n寰宇楼台舞彩缨。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg", "04.jpg", "05.jpg", "06.jpg"]}, {"poem_id": "1700", "title": "朝中措·贺爹高寿", "genre": "朝中措", "date": "2024.04.18", "body": "八十有二寿辰来，\n三月百花开。\n初九天晴柳翠，\n风摇香絮袭怀。\n孙男孝女，\n争前拜祝，\n玉馔盈台。\n樽盏染红苍鬓，\n燕莺高啭徘徊。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1701", "title": "菩萨蛮·吟望", "genre": "菩萨蛮", "date": "2024.04.19", "body": "时逢谷雨春将暮，\n落红飞絮飘无数。\n不必惹伤愁，\n天择适者留。\n芳郊苗木壮，\n逐日蒸蒸上。\n四野绿成荫，\n凝眸景色新。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1702", "title": "七绝·闻事吟", "genre": "七绝", "date": "2024.04.20", "body": "年少谁知父母心，\n几多白眼对家亲。\n秋来悔恨光如箭，\n不待回头雪染身。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1703", "title": "七绝·暮春吟望", "genre": "七绝", "date": "2024.04.21", "body": "无欲青云闲自在，\n欢腾溪水向东流。\n知足心底宽明亮，\n寡淡得失少苦愁。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1704", "title": "七绝·中文美", "genre": "七绝", "date": "2024.04.22", "body": "撇捺钩横笺上描，\n龙翔凤翥墨香飘。\n翠微碧落扶摇韵，\n漫卷尘寰气自豪。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1705", "title": "七律·鹤翔庄有感", "genre": "七律", "date": "2024.04.23", "body": "奇经妙络脉相连，\n百会中通到涌泉。\n气走任督周复始，\n意行天地远回还。\n青蜓点水盈精血，\n白鹤凌空疏胆肝。\n日夜无形除病灶，\n春秋永志养容颜。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1706", "title": "七绝·春暮吟", "genre": "七绝", "date": "2024.04.25", "body": "时光牵手风拂面，\n日月悠悠尘世间。\n回首人生花甲过，\n且凭诗酒度余年。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1707", "title": "七律·贺发射成功", "genre": "七律", "date": "2024.04.26", "body": "神舟似箭入苍穹，\n裹带黄河不老风。\n映衬牡丹花更艳，\n启熏笑脸韵无穷。\n一十八次飞天地，\n亿万千回欢舞声。\n探月逐星今古事，\n嫦娥颙望断悲情。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "1708", "title": "鹧鸪天·暮春寄友", "genre": "鹧鸪天", "date": "2024.04.27", "body": "细雨轻雷电闪鸣，\n城南一味友相逢。\n廉州地主诚心待，\n京邑宾朋笑脸红。\n樽醪满，馔香萦。\n趣谈妙语蕴深情。\n不觉窗外云霄霁，\n挽手呼车送一程。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1709", "title": "七绝·暮春吟望", "genre": "七绝", "date": "2024.04.28", "body": "品茗春涧观峰翠，\n听鸟闻香人自醉。\n云骤风急雨洗茶，\n古亭依旧山崖媚。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1710", "title": "七绝·隔岸吟望", "genre": "七绝", "date": "2024.04.29", "body": "虚讲自由愚弄人，\n言行切莫背其心。\n曾夸风景今相遇，\n触动神经乱了魂。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1711", "title": "七绝·节前吟", "genre": "七绝", "date": "2024.04.30", "body": "人逢节假有忙闲，\n日月轮回昼夜间。\n花落花开方为世，\n任他苦乐扣心弦。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1712", "title": "七律·假日吟望", "genre": "七律", "date": "2024.05.01", "body": "五一节日艳阳欢，\n柳翠空明花色妍。\n洒水车来街道净，\n游人影过笑声连。\n飞天侠客云边落，\n入海艨艟浪里潜。\n华夏山川旗劲舞，\n城乡锣鼓响尘寰。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "1713", "title": "七绝·观图有寄", "genre": "七绝", "date": "2024.05.02", "body": "晓来屏上望乳山，\n忽起情思绪万千。\n三载未曾闻牡蛎，\n预期今岁可尝鲜。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "1714", "title": "七绝·题图", "genre": "七绝", "date": "2024.05.03", "body": "一挺一弯一瞬间，\n此情胜似万千言。\n料他遗臭三生世，\n羞愧子孙八百年。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1715", "title": "采桑子·五四寄怀", "genre": "采桑子", "date": "2024.05.04", "body": "青春不负当年事。\n岁月多情，\n回味无穷。\n镜里飞霜染鬓容。\n周边柳翠鲜花艳。\n盛世峥嵘，\n探海巡空。\n昨见嫦娥舞月宫。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1716", "title": "卜算子·时令吟", "genre": "卜算子", "date": "2024.05.05", "body": "晓雨送春归，\n夏日悠然到。\n水碧花红气色新，\n树杪鸣莺闹。\n节假剩一天，\n本欲东行了。\n二老牵心动魄魂，\n续把恩情报。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1717", "title": "七绝·福祸", "genre": "七绝", "date": "2024.05.07", "body": "真假李逵千百年，\n唬人弄鬼不周全。\n本尊虚拟同屏语，\n便是亲朋认亦难。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1718", "title": "七绝·悲", "genre": "七绝", "date": "2024.05.08", "body": "井底之蛙望斗天，\n不知四外阔无边。\n虫前狂语何如我，\n忽落砖头小命完。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1719", "title": "七绝·悲", "genre": "七绝", "date": "2024.05.08", "body": "岛底之蛙望斗天，\n不知四外阔无边。\n虫前狂语何如我，\n忽落砖头小命完。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1720", "title": "鹧鸪天·吟望寄怀", "genre": "鹧鸪天", "date": "2024.05.10", "body": "杨柳摇风乱絮飞，\n行人无奈苦伤悲。\n呛喉咳嗽声难断，\n迷眼喷酸泪不归。\n花已落，雨频催。\n暮春愁色鬓边堆。\n何当天际空明净，\n昂首凭栏展骏眉。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1721", "title": "鹧鸪天·母亲快乐并祝儿生日", "genre": "鹧鸪天", "date": "2024.05.12", "body": "耆老娘亲白发稀，情思受限语多迟。\n闲聊常问孙何处，兴起频言岁几时。\n行缓慢，坐斜依。粗粮饭菜最当吃。\n缺牙少味浑呑咽，和蔼苍颜事不期。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1722", "title": "一剪梅·吟痛", "genre": "一剪梅", "date": "2024.05.14", "body": "初夏当空絮扰人，\n迷眼分神，睁眼无神。\n红斑漫起痒周身，\n坐亦烦心，卧亦烦心。\n吃药难舒又吊针，\n举目无亲，招手无亲。\n昼宵独自苦相侵，\n无奈呻吟，谁解呻吟。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1723", "title": "七绝·世间吟望", "genre": "七绝", "date": "2024.05.16", "body": "近邻交往有人嫌，\n搅棍投石语恶言。\n惟恐比肩同挽手，\n掀翻独霸换新天。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1724", "title": "踏莎行·夏日吟望", "genre": "踏莎行", "date": "2024.05.17", "body": "袅袅青烟，\n欣欣绿浪。\n无垠阡陌风光靓。\n灌浆麦粒喜垂头，\n迎风摇曳心怀壮。\n昭示丰收，\n加深盼望。\n农家盘算豪情涨。\n秋来置业盖新屋，\n孩儿嫁娶追时尚。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1725", "title": "七绝·夏日闲吟", "genre": "七绝", "date": "2024.05.19", "body": "小满将临籽灌浆，\n尚须滋育待时光。\n人生最忌功初就，\n唤雨呼风声调扬。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1726", "title": "七绝·记事吟", "genre": "七绝", "date": "2024.05.20", "body": "十天滴液日如年，\n小满来临体魄还。\n尚有残斑留印迹，\n遇人相问俏开言。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1727", "title": "踏莎行·尘寰吟望", "genre": "踏莎行", "date": "2024.05.21", "body": "国际风云，\n江湖涛浪。\n奈何四处狼烟漾。\n多家首脑死伤悲，\n天知幕后真情况。\n纵是阴谋，\n切毋狂妄。\n言行无耻双簧唱。\n画皮内外渐分明，\n终将白骨灰埋葬。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1728", "title": "七绝·凭栏吟望", "genre": "七绝", "date": "2024.05.22", "body": "小楼对面起高层，\n昔日垄田回忆中。\n麦浪摇风香不再，\n喧嚣趋甚乱心情。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1729", "title": "七绝·致敬任总", "genre": "七绝", "date": "2024.05.23", "body": "不因域外喜伤悲，\n自主图强血汗挥。\n雪耻莫言头拱地，\n堪为华夏树丰碑。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1730", "title": "鹧鸪天·六一吟望", "genre": "鹧鸪天", "date": "2024.05.24", "body": "节日将临童稚欢，\n多姿溢彩幼儿园。\n朱唇浅靥招人笑，\n纤手明眸舞院前。\n钢琴秀，彩旗妍。\n歌声飘荡入云天。\n枝头小鸟频频顾，\n几欲同台一起玩。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "1731", "title": "七绝·夏日闲吟", "genre": "七绝", "date": "2024.05.25", "body": "花开叶落赖天公，\n昂首垂头气自胸。\n心态充盈难亦乐，\n神情懈怠苦无穷。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1732", "title": "踏莎行·小聚咏怀", "genre": "踏莎行", "date": "2024.05.26", "body": "故友情深，\n乳鸽香溢。\n芳醪玉液怀思寄。\n曾经幕幕眼前来，\n回头三秩光阴逝。\n邀聚新朋，\n拜商愁事。\n姐孩托付吾兄弟。\n时常教悔用真心，\n赢得日后终生记。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1733", "title": "太常引·寄语独蛙", "genre": "太常引", "date": "2024.05.27", "body": "两天围岛练兵枪。看似不心慌。\n肚里苦回肠。弹丸地、如何躲藏。\n水天无际，云梯不稳，胆颤嘴呈强。\n只怕闪雷光。声响处、鱼虾死伤。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1734", "title": "蝶恋花·叙旧咏怀", "genre": "蝶恋花", "date": "2024.05.28", "body": "酒过三巡频握手。\n挚友深情，言语心肝透。\n斑鬓霜丝追往旧，\n曾经岁月欢回首。\n奉献芳华人已瘦。\n各自归休，且与孙娃逗。\n最是开心今聚后，\n人情家事聊无够。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1735", "title": "七律·小店深情", "genre": "七律", "date": "2024.05.29", "body": "寻常酒馆聚珍朋，\n丽日青云映暖空。\n玉液穿肠温旧事，\n清茶入口话闲情。\n香醪满盏心怀醉，\n细语同频意趣浓。\n厅里大多人已去，\n惟余我处火还红。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1736", "title": "七绝·五月吟所见", "genre": "七绝", "date": "2024.05.30", "body": "甜杏黄红摆路边，\n诱人色味入心田。\n下班急过歇歇脚，\n老少回家解解馋。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "1737", "title": "清平乐·六一寄怀", "genre": "清平乐", "date": "2024.05.31", "body": "隔空遥望，\n万里娇孙想。\n辜有音姿屏幕上，\n慰我心怀情畅。\n节前月末今朝，\n闻知亲子逍遥。\n母女同台竞技，\n幼儿园里妖娆。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1738", "title": "踏莎行·六一咏怀", "genre": "踏莎行", "date": "2024.06.01", "body": "节日来临，\n稚童欢乐。\n青云翠鸟来相贺。\n幼儿园里舞蹁跹，\n绿茵场上歌声彻。\n旗子飘飘，\n花儿朵朵。\n园丁浇灌枝条阔。\n个中多少栋梁才，\n必成立厦擎天客。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg", "04.jpg", "05.jpg", "06.jpg"]}, {"poem_id": "1739", "title": "太常引·六一有感", "genre": "太常引", "date": "2024.06.02", "body": "光阴无奈指间流，\n稚子已白头。\n花甲更何求。\n望晚辈、行端品优。\n人和家睦，征途策马，\n世路少闲愁。\n远去有川丘，\n莫气馁、心恒志酬。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1740", "title": "太常引·仲夏晓吟", "genre": "太常引", "date": "2024.06.03", "body": "一轮初日耀东方。\n漫步享清凉。\n树杪闪金光。\n翠鸟醒、佳音远扬。\n晴空无际，心怀愉悦，\n思绪万千长。\n人海有闲忙。\n霜染鬓、心安梦香。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1741", "title": "七绝·闲闻有寄", "genre": "七绝", "date": "2024.06.04", "body": "一世人生多巧合，\n奇逢妙遇任凭说。\n有缘屡次途中会，\n阳错阴差同趟车。​ ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1742", "title": "七律·芒种有寄", "genre": "七律", "date": "2024.06.05", "body": "今闻节令想当年，\n梦眼惺忪手把镰。\n随父低头挥汗雨，\n只身捆麦叹云烟。\n可怜手掌多磨泡，\n无奈腰椎难打弯。\n高考随心京邑去，\n忧愁少却六七番。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1743", "title": "七绝·吟望寄怀", "genre": "七绝", "date": "2024.06.07", "body": "当年高考无人问，\n学子今朝万目追。\n俱盼挥毫高榜中，\n满门荣耀映金辉。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1744", "title": "七绝·晓来吟", "genre": "七绝", "date": "2024.06.08", "body": "端午将临人远去，\n边陲迎夏看娇孙。\n幸得二老今无恙，\n才可辞乡落下心。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1745", "title": "七律·节前出行", "genre": "七律", "date": "2024.06.09", "body": "赛里木湖端午游，\n西疆晓色映窗流。\n岭山远近连天外，\n草树高低卧土丘。\n车上祖孙情俱悦，\n云边思绪阔无忧。\n阖家五口分头去，\n博乐相逢始自由。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "1746", "title": "太常引·出游宿博州", "genre": "太常引", "date": "2024.06.10", "body": "依河夜宿似江南。\n桥树草花妍。\n清晓碧云天。\n恰端午、风和粽甜。\n早餐用罢，行程继续，\n近午到湖边。\n休整木亭间。\n蓄精气、为图畅玩。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "1747", "title": "太常引·游赛里木湖", "genre": "太常引", "date": "2024.06.11", "body": "雪山环抱水青蓝。\n玉帝泪珠圆。\n净海美名传。\n五百里、湖含远天。\n帆舟竞渡，天鹅奋舞，\n风过漾波澜。\n游客聚流连。\n人接踵、车龙往还。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg", "04.jpg", "05.jpg", "06.jpg"]}, {"poem_id": "1748", "title": "七绝·旅途闲吟", "genre": "七绝", "date": "2024.06.12", "body": "览景偷闲亦健身，\n纤姿有样看娇孙。\n近朱染赤天然色，\n来去无忧若片云。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1749", "title": "太常引·夏游特克斯", "genre": "太常引", "date": "2024.06.14", "body": "乾坤八卦布街城。\n踏入似迷宫。\n南北或西东。\n放眼望、龙吟虎鸣。\n八方四面，神同貌似，\n烟火映长空。\n天地物相通。\n风水转、人和域宁。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "1750", "title": "鹧鸪天·游喀拉峻", "genre": "鹧鸪天", "date": "2024.06.15", "body": "车到山门近日昏，\n微茫烟雨笼疲身。\n无穷青翠连天际，\n几处霓虹染草茵。\n鹰远翥，马狂奔。\n牛羊闲漫景温馨。\n凭栏望眼胸怀阔，\n塞外江南夏胜春。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg", "04.jpg", "05.jpg", "06.jpg"]}, {"poem_id": "1751", "title": "踏莎行·老父亲", "genre": "踏莎行", "date": "2024.06.16", "body": "手巧心灵，\n腰疼耳背。\n萦身脉络昏昏睡。\n平生良善事殷勤，\n务农实在终疲惫。\n萱草将衰，\n椿庭无悔。\n同迎风雨闻虫吠。\n朱檐青瓦共朝霞，\n悠悠岁月夕阳美。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1752", "title": "七律·伊犁见闻", "genre": "七律", "date": "2024.06.17", "body": "熏衣草处紫云烟，\n公主解忧西域间。\n香气宜人赢赞誉，\n花魂除晦保平安。\n和亲不惧乌孙远，\n白发方得汉室还。\n千载悠悠情不尽，\n天山南北美名传。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg", "04.jpg", "05.jpg", "06.jpg"]}, {"poem_id": "1753", "title": "七绝·时令吟", "genre": "七绝", "date": "2024.06.21", "body": "夏至边疆月影凉，\n避寒未敢夜开窗。\n晓来风色犹春日，\n漫步街头念故乡。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1754", "title": "蝶恋花·稚子情欢", "genre": "蝶恋花", "date": "2024.06.22", "body": "生日同天三女靓。\n一派祥和，\n俱是娇模样。\n糕点溢香烛火旺，\n幼童欢乐花儿唱。\n头戴皇冠人最棒。\n伫立台前，\n闪闪金光放。\n拇指齐伸均向上，\n文欢园里苗茁壮。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1755", "title": "蝶恋花·彩淡情深", "genre": "蝶恋花", "date": "2024.06.23", "body": "纤手轻轻描画笔。\n彩染白猫，\n眉眼层层丽。\n黑墨点睛神几许，\n红黄蓝配添情趣。\n孙女舒怀心更喜。\n不舍难离，\n把握时时举。\n夜置床头埋被里，\n醒来紧抱亲无比。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg", "04.jpg", "05.jpg", "06.jpg"]}, {"poem_id": "1756", "title": "太常引·游哈熊沟", "genre": "太常引", "date": "2024.06.24", "body": "蜿蜒百里岭沟间。\n屡过碎石滩。\n水少草无欢。\n踏黄土、扬灰起烟。\n游人骑马，风尘漫卷，\n遮断碧云天。\n旁者莫能安。\n今朝至、身心不堪。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg", "04.jpg", "05.jpg", "06.jpg"]}, {"poem_id": "1757", "title": "七绝·祥瑞凌空", "genre": "七绝", "date": "2024.06.25", "body": "暮云漫卷似龙腾，\n寥廓神州瑞色兴。\n昂首舒怀心底畅，\n惟期天际万年青。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1758", "title": "采桑子·迪化夏日", "genre": "采桑子", "date": "2024.06.28", "body": "微风日暮神情爽。\n翠叶青枝，\n绿院红梯。\n老少悠闲景适宜。\n妪翁树下舒心坐。\n童稚追嘻，\n各自无欺。\n维汉祥和看此时。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "1759", "title": "采桑子·花枝初绽", "genre": "采桑子", "date": "2024.06.29", "body": "课余舞蹈心头爱。\n乖巧娇孙，\n尽显童真。\n紧体香衣裹瘦身。\n一周两次修仨月。\n犹木逢春，\n花蕾宜人。\n韵味芬芳日日欣。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1760", "title": "五律·领悟", "genre": "五律", "date": "2024.06.30", "body": "室外风光热，\n书屋案卷香。\n桌旁一母女，\n手里几篇章。\n慈母轻声念，\n娇儿细嗓扬。\n温馨人羡慕，\n惬意韵悠长。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "1761", "title": "清平乐·庆七一", "genre": "清平乐", "date": "2024.07.01", "body": "童心向党，\n朵朵花儿放。\n枝叶欣繁争向上，\n自是根苗茁壮。\n文欢沃土丰田，\n园丁耕作少言。\n向日葵香四溢，\n含情仪态芳妍。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg", "04.jpg", "05.jpg", "06.jpg"]}, {"poem_id": "1762", "title": "清平乐·健身有寄", "genre": "清平乐", "date": "2024.07.02", "body": "老来缓动。\n游泳随人性，\n器械架前谁与共。\n莫要争强好胜。\n练家相互切磋，\n闲来独自琢磨。\n疑惑咨询私教，\n涓涓细水成河。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg", "04.jpg", "05.jpg", "06.jpg"]}, {"poem_id": "1763", "title": "鹧鸪天·夏日喜雨", "genre": "鹧鸪天", "date": "2024.07.03", "body": "夜霁银空晓色凉，\n驱除炎热泛清香。\n天边旭日云层破，\n树上污尘水洗光。\n青叶秀，细风扬。\n行人吐纳气丝长。\n胸怀饱满舒心去，\n一昼能当两昼忙。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1764", "title": "七律·贺深中直通", "genre": "七律", "date": "2024.07.04", "body": "昔人文氏叹伶仃，\n今日穿洋走地宫。\n举世闻听惊转赞，\n神州笑傲更从容。\n飞天潜海寻常事，\n探月捉鳖乐不穷。\n水陆桥涵通内外，\n舟车驰越岭川行。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg", "04.jpg", "05.jpg", "06.jpg"]}, {"poem_id": "1765", "title": "七律·夏日别趣", "genre": "七律", "date": "2024.07.07", "body": "化作青蛙仰望天，\n景观不似在人间。\n透光荷叶他番趣，\n映日莲花别样妍。\n菡萏高枝纤挺立，\n青云碎影水中含。\n大千世界多奇妙，\n便是圣才难认全。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "1766", "title": "七绝·闲来吟望", "genre": "七绝", "date": "2024.07.10", "body": "贼子心虚乱咬人，\n妄言白昼是黄昏。\n损招不断徒得意，\n到了翻伤自个身。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "1767", "title": "五绝·淀中乐", "genre": "五绝", "date": "2024.07.11", "body": "老者荡轻舟，\n鱼虾为所求。\n把樽餐美味，\n兜鼓眼神牛。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1768", "title": "五律·吟东南", "genre": "五律", "date": "2024.07.12", "body": "​蛙岛人关注，\n舰机巡不停。\n鸟虫闻讯闹，\n草木遇风惊。\n独子胡言语，\n家亲掷地声。\n离乡时已远，\n莫待苦无穷。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "1769", "title": "七律·新世缘", "genre": "七律", "date": "2024.07.13", "body": "俩童本是北京人，\n奇遇边疆真个神。\n同在小区前后住，\n共居园里铺相临。\n课余携手滑梯上，\n檐下齐眉歌舞群。\n三五春秋能再见，\n帝都或许一师门。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1770", "title": "七律·数伏有寄", "genre": "七律", "date": "2024.07.15", "body": "又入神州最热天，\n疆城干爽不湿粘。\n太阳底下光难耐，\n绿树荫中风自闲。\n早晚出行人惬意，\n柳枝鸣唱醉高蝉。\n遥思故里三伏日，\n汗水盈身夜未眠。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1771", "title": "鹧鸪天·游独山子", "genre": "鹧鸪天", "date": "2024.07.16", "body": "鹿角湾中起野餐，\n娇孙笑靥映云寰。\n大峡谷里婆媳舞，\n独库路头风景妍。\n博物馆，忆从前。\n工兵将士战天山。\n百多英烈长眠此，\n南北疆通利万年。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg", "04.jpg", "05.jpg", "06.jpg", "07.jpg", "08.jpg", "09.jpg"]}, {"poem_id": "1772", "title": "鹧鸪天·峡谷吟", "genre": "鹧鸪天", "date": "2024.07.17", "body": "神斧轻划地裂开，\n石崖玉壁眼前排。\n俯身探看深无底，\n吊胆移挪惊满怀。\n峡谷事，客思猜。\n终无谁可道明白。\n人间风物尤如此，\n多少情形空叹哀。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "1773", "title": "七律·独库英雄赞", "genre": "七律", "date": "2024.07.18", "body": "天山横亘东西向，\n阻断九霄南北风。\n便是雄鹰悲且叹，\n奈何骏马冷无情。\n凿石筑路一声令，\n挥镐推车十万兵。\n卧雪战冰餐血汗，\n畅通疆域慰英灵。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "1774", "title": "蝶恋花·大美新疆", "genre": "蝶恋花", "date": "2024.07.20", "body": "夏日冰川风色美。\n四面八方，\n游客心陶醉。\n如镜天池凝碧水，\n惊魂峡谷叠青翠。\n独库车流南或北。\n四季同天，\n雨雪时交会。\n遍览草原花点缀，\n大巴扎里还回味。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg", "04.jpg", "05.jpg", "06.jpg"]}, {"poem_id": "1775", "title": "七绝·边城夏吟", "genre": "七绝", "date": "2024.07.22", "body": "大暑多云树色深，\n炎光隐去晓宜人。\n轻身晨练微出汗，\n犹似故乡逢暮春。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1776", "title": "七绝·夏日闲吟", "genre": "七绝", "date": "2024.07.23", "body": "长空堆荡彩云山，\n七色交织恁壮观。\n华夏今朝逢盛世，\n霞辉染遍九州天。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "1777", "title": "七绝·夏日暮吟", "genre": "七绝", "date": "2024.07.24", "body": "余辉闲照意悠然，\n自在爷孙楼树间。\n水榭高台风漫过，\n不觉暑气只闻蝉。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "1778", "title": "采桑子·闻事有寄", "genre": "采桑子", "date": "2024.07.25", "body": "散沙风卷飘无处。\n粘聚如钢，\n抵挡刀枪。\n阻水遮光耐雪霜。\n世间万物真奇妙。\n骤短忽长，\n乍热还凉。\n把握时机弱转强。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1779", "title": "五绝·夏愁", "genre": "五绝", "date": "2024.07.26", "body": "千般防不住，\n一霎醒来疼。\n肿胀孩童闹，\n阖家夜未宁。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1780", "title": "踏莎行·巴黎吟望", "genre": "踏莎行", "date": "2024.07.27", "body": "一水行舟，\n五星耀眼。\n中华儿女骄姿艳。\n红旗摇荡满怀情，\n凝神铆劲金牌献。\n奥运搭台，\n宾朋会面。\n俯身竞技争长短。\n更高更快妙无穷，\n探珠何惧龙宫远。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "1781", "title": "采桑子·登雅山有寄", "genre": "采桑子", "date": "2024.07.28", "body": "群楼怎抵山峰秀。\n四望无边，\n抬手及天。\n近日沾辉云里闲。\n谋生眺远登高处。\n敞阔心田，\n多是良言。\n稳妥餐行避祸端。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "1782", "title": "鹧鸪天·夏日闲吟", "genre": "鹧鸪天", "date": "2024.07.29", "body": "漫步闲思发会呆，\n挥毫随写老心怀。\n见闻化作诗词句，\n善恶说来任剪裁。\n君莫笑，子宜猜。\n世间万事悟中开。\n盲人摸象非全貌，\n瞎子点灯鬼不来。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1783", "title": "蝶恋花·升班典礼赞", "genre": "蝶恋花", "date": "2024.07.31", "body": "一.\n文苑鲜花初绽放，\n喜看枝头，\n幼鸟齐声唱。\n最是园丁当赞赏，\n春秋寒暑苗儿壮。\n童稚一年多变样。\n认字学歌，\n礼貌成时尚。\n戴帽穿衣纤手上，\n乐得家长心花放。\n二.\n一早驱车孙女笑。\n剧场登台，\n敬庆八一到。\n音乐飞扬银幕闹，\n文欢此刻星光耀。\n玉女金童争汇报。\n独奏群歌，\n舞蹈情兼貌。\n花朵缤纷空里俏，\n童心向党春晖照。", "image_files": ["01.jpg", "02.jpg", "03.jpg", "04.jpg", "05.jpg", "06.jpg"]}, {"poem_id": "1784", "title": "采桑子·庆八一", "genre": "采桑子", "date": "2024.08.01", "body": "军旗擎举边防稳。\n疆固民安，\n功盖长天。\n寥廓神州山水妍。\n枕戈将士餐风雪。\n行坐优先，\n牢记心田。\n风气将成转自然。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1785", "title": "蝶恋花·贺潘展乐", "genre": "蝶恋花", "date": "2024.08.02", "body": "碧水池中催浪起。\n鬼愕神惊，\n华夏添新喜。\n打破白人争霸事，\n神州骄子宣绝技。\n闻讯今朝情不自。\n提笔抒怀，\n发泄窝囊气。\n尿检不公由美帝，\n转身夺冠名于世！ ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "1786", "title": "蝶恋花·贺邓雅文", "genre": "蝶恋花", "date": "2024.08.03", "body": "驱动小轮成大事。\n跨界前来，\n首秀赢佳绩。\n汗水无言千万次，\n一朝夺冠名天际。\n凭借青春留印迹。\n妙写春秋，\n光耀三生世。\n莫道付出犹水逝，\n逐涛击浪风云丽。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "1787", "title": "江城子·贺郑钦文", "genre": "江城子", "date": "2024.08.04", "body": "网单女冠谱新篇。\n几十年，梦儿圆。\n笑傲巴黎，\n旗展五星妍。\n奥运神州多靓丽。\n龙腾跃，映长天。\n钦文汗水洗娇颜。\n屡夺关，苦翻甜。\n一路挥拍，\n纵马跃山巅。\n含泪回眸一霎那。\n思华夏，意缠绵。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "1788", "title": "鹧鸪天·重游江布拉克", "genre": "鹧鸪天", "date": "2024.08.05", "body": "景色依稀入眼亲，峰峦叠翠映白云。\n随风麦浪金光闪，拔地云杉落绿荫。\n逃暑热，趁清欣。房车游客各成群。\n帐篷遍地闲人卧，鹰鸟当空闻水音。\n附：去年七月二十五日游记\n沁园春      江布拉克\n古郡奇台，百里方圆，万顷山川。\n眺松林雪岭，霄连地漫，花涛麦浪，绿绣红妍。\n峡谷清幽，白云舒卷，牛马成群映草原。\n风凉夏，纵晴明无雨，入夜微寒。\n穿行犹似云端。花海子，展眸不到边。\n遇怪坡上下，有违物理，星空宵昼，别具风烟。\n溪水轻流，雄鹰高翥，醉卧毡篷好梦眠。\n宜避暑，度消魂日月，不慕神仙。", "image_files": ["01.jpg", "02.jpg", "03.jpg", "04.jpg", "05.jpg", "06.jpg", "07.jpg", "08.jpg", "09.jpg"]}, {"poem_id": "1789", "title": "鹧鸪天·游江布拉克有寄", "genre": "鹧鸪天", "date": "2024.08.06", "body": "茂密云杉隐木屋，恰逢大暑昼宵舒。\n祖孙山坳蘑菇采，松鼠枝头精气足。\n山野静，好读书。忧烦杂念瞬时除。\n若得逢夏长居此，不道人间还数伏。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "1790", "title": "七绝·立秋吟", "genre": "七绝", "date": "2024.08.07", "body": "一夜西风晓转凉，\n抬头偶见叶微黄。\n人情天道寻常理，\n瞅准时机行与藏。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1791", "title": "七绝·赞潘展乐", "genre": "七绝", "date": "2024.08.08", "body": "骄龙一跃挽狂澜，\n俯首神游后变前。\n涌起银涛连碧浪，\n打翻四秩霸王冠。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1792", "title": "七绝·夏日吟", "genre": "七绝", "date": "2024.08.09", "body": "举世遥听龙啸音，\n银屏奥运胜亲临。\n神州圆梦千般事，\n夺冠之骄多子衿。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1793", "title": "七绝·夏日吟望", "genre": "七绝", "date": "2024.08.11", "body": "昨宵网上咏七夕，\n梦醒巴黎又第一。\n华夏健儿神与气，\n风头正劲卷东西。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1794", "title": "太常引·赞奥运健儿", "genre": "太常引", "date": "2024.08.12", "body": "金牌榜上竞豪雄。\n华夏宇寰名。\n游泳世间惊。\n网球女、挥拍爆红。\n无忧跳水，\n乒乓如愿，\n举重立新功。\n掉杠意难平。\n四年后，冲高跃层。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1795", "title": "蝶恋花·消夏闲吟", "genre": "蝶恋花", "date": "2024.08.16", "body": "水磨沟中消暑气。\n牵手娇孙，\n观赏鱼鸭戏。\n争闹觅食情有趣，\n岸边投喂合心意。\n树下欣闻歌舞艺。\n鸟雀同欢，\n老少无忧虑。\n最爱边城逢夏季，\n总能寻到清凉地。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg", "04.jpg", "05.jpg", "06.jpg"]}, {"poem_id": "1796", "title": "七绝·边城闲吟", "genre": "七绝", "date": "2024.08.19", "body": "迪化初秋夜雨寒，\n风吹梧叶断声蝉。\n可怜一夏吱吱叫，\n不道黄花雪染天。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1797", "title": "五律·童如愿", "genre": "五律", "date": "2024.08.21", "body": "娇孙大板台，\n落座眼光开。\n张口心中问，\n抬头图上猜。\n京新家两处，\n手指几徘徊。\n母解孩儿惑，\n舒眉释闷怀。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1798", "title": "蝶恋花·娇孙学艺", "genre": "蝶恋花", "date": "2024.08.24", "body": "偶见轮滑心里痒。\n缠闹家人，\n只道千般想。\n三岁娇娃终入场，\n行头全套新模样。\n撞撞跌跌身踉跄。\n摔倒无哭，\n爬起驱前上。\n梦里喃喃还不忘，\n三天独自悠闲逛。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg", "04.jpg", "05.jpg", "06.jpg"]}, {"poem_id": "1799", "title": "渔家傲·疆城晚照", "genre": "渔家傲", "date": "2024.08.25", "body": "日暮南湖歌舞劲，\n飞霞飘影人心奋。\n倦鸟归来神又振，\n添美韵。\n点头摇翅频相问。\n老少舒怀消晚闷，\n呼星唤月风拂鬓。\n域外谣言诚可恨，\n人神愤。\n欣闻此刻谁还信。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg", "04.jpg", "05.jpg", "06.jpg"]}, {"poem_id": "1800", "title": "七绝·出游阿勒泰", "genre": "七绝", "date": "2024.08.27", "body": "驱车向北少人烟，\n千里黄沙映远天。\n窗外起伏风卷浪，\n到得福海草花妍。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg", "04.jpg", "05.jpg", "06.jpg"]}, {"poem_id": "1801", "title": "踏莎行·游乌伦古湖", "genre": "踏莎行", "date": "2024.08.28", "body": "沙漠明珠，\n人间福海。\n女娲遗玉多姿彩。\n无边碧水漾波澜，\n渔舟快艇皆为爱。\n魔鬼城惊，\n野狼形骇。\n雅丹地貌心澎湃。\n八方远客叹神奇，\n争相点赞情于外。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg", "04.jpg", "05.jpg", "06.jpg"]}, {"poem_id": "1802", "title": "采桑子·游宿布尔津", "genre": "采桑子", "date": "2024.08.29", "body": "中苏交往风情在。\n集市留痕，\n桥路留痕。\n河水滔滔唤故人。\n星辉夜色灯光璨。\n烟火迎君，\n花月迎君。\n远道而来似旧亲。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg", "04.jpg", "05.jpg", "06.jpg", "07.jpg", "08.jpg", "09.jpg"]}, {"poem_id": "1803", "title": "踏莎行·游宿禾木", "genre": "踏莎行", "date": "2024.09.02", "body": "四处环山，\n一河流水。\n木屋成片云空缀。\n夏秋风色鸟舒怀，\n冬春雪景人陶醉。\n篝火欢歌，\n繁星笑对。\n清风明月来相会。\n远飘美味悦姮娥，\n吴刚神荡宵难寐。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg", "04.jpg", "05.jpg", "06.jpg"]}, {"poem_id": "1804", "title": "七律·游宿喀纳斯", "genre": "七律", "date": "2024.09.03", "body": "遥闻水怪客前来，\n日暮廉纤雨撞怀。\n犹到湖边争远眺，\n奈何雾里乱疑猜。\n木屋深夜人无寐，\n山顶清晨眼尽开。\n只见白云闲起落，\n难寻涛浪怪徘徊。\n清平乐    喀纳斯\n观鱼台上，\n远客争相望。\n湖怪无形山水旷，\n伫立心怡神畅。\n飞云峰岭悠闲，\n俯身极目三湾。\n白浪欢歌而下，\n青天碧水遥连。\n注：湖下游为河，\n有卧龙湾、月亮\n湾、神仙湾。", "image_files": ["01.jpg", "02.jpg", "03.jpg", "04.jpg", "05.jpg", "06.jpg"]}, {"poem_id": "1805", "title": "七绝·过路游", "genre": "七绝", "date": "2024.09.04", "body": "疆域闻名五彩滩，\n胡杨碧水映长天。\n雅丹朝暮非同色，\n玉落凡尘亿万年。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg", "04.jpg", "05.jpg", "06.jpg"]}, {"poem_id": "1806", "title": "鹧鸪天·过乌尔禾", "genre": "鹧鸪天", "date": "2024.09.05", "body": "超大雅丹魔鬼城，\n驱车游逛自心惊。\n楼亭百丈凌空立，\n剑客千年跨马行。\n凭想象、画图生。\n狂奔狮虎卧神龙。\n置身此处由衷叹，\n俗子休贪天地功。\n​\n​注：多部影视剧\n​拍摄地。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg", "04.jpg", "05.jpg", "06.jpg"]}, {"poem_id": "1807", "title": "渔家傲·游宿克拉玛依", "genre": "渔家傲", "date": "2024.09.06", "body": "近望楼前一号井，\n凭生城市人烟盛。\n闻道芳郊奇异景，\n游客竞。\n黑油山上油花蹦。\n昔日青年留倩影，\n忠心赤胆人称颂。\n戈壁滩涂钻探洞，\n终得胜。\n绿洲葱郁边陲映。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg", "04.jpg", "05.jpg", "06.jpg"]}, {"poem_id": "1808", "title": "太常引·过石河子", "genre": "太常引", "date": "2024.09.07", "body": "…敬览博物馆\n军人兼作务农工。\n戈壁起春风。\n红绿染云空。\n筑楼处、经年为城。\n种瓜点豆，\n繁荣集市，\n西域日安宁。\n盛世念英雄。\n传后代、千秋太平。", "image_files": ["01.jpg", "02.jpg", "03.jpg", "04.jpg", "05.jpg", "06.jpg"]}, {"poem_id": "1809", "title": "清平乐·敬缅主席", "genre": "清平乐", "date": "2024.09.09", "body": "四十八载，\n笑貌深情在。\n温暖黎民无替代，\n千古人间大爱。\n沤心打下根基，\n后生立柱堆石。\n大厦东方高耸，\n五洲举目称奇。", "image_files": ["01.jpg"]}, {"poem_id": "1810", "title": "南乡子·赠幼儿教师", "genre": "南乡子", "date": "2024.09.10", "body": "每日语童真，\n情意丝滑暖稚心。\n群幼不知丁点事，\n陶熏。\n春雨清风分外亲。\n苗木与时新，\n仰仗园丁灌溉勤。\n喜见映天松柏树，\n情深。\n翠叶高枝笑望君。", "image_files": ["01.jpg"]}, {"poem_id": "1811", "title": "蝶恋花·吟望", "genre": "蝶恋花", "date": "2024.09.11", "body": "妄想天堂偏入狱。\n何似息神，\n闭目由他去。\n一觉醒来常谓己，\n欺人亏理平生忌。\n世路宽平天盖地。\n行走凝眸，\n远躲南墙壁。\n霜降风吹何所惧，\n赤身光脚迎狂雨。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1812", "title": "蝶恋花·游宿吐鲁番", "genre": "蝶恋花", "date": "2024.09.12", "body": "……观叹坝儿井\n竖井间隔十几米，\n深浅随坡，\n底下连通壁。\n雪水天山来漫地，\n暗渠遍布堪奇迹。\n敬佩先人勤努力，\n聪慧躬行，\n驱害得天利。\n改善民生名被记，\n千年不朽功于世。", "image_files": ["01.jpg", "02.jpg", "03.jpg", "04.jpg", "05.jpg", "06.jpg"]}, {"poem_id": "1813", "title": "鹧鸪天·游宿吐鲁番", "genre": "鹧鸪天", "date": "2024.09.13", "body": "……悦览葡萄沟\n火焰山旁碧水流，\n葡萄遍地色盈沟。\n无核白玉迎人笑，\n含籽红珠隐客愁。\n篇章美，语文牛。\n少年学子背从头。\n今番亲历书中事，\n犹似春宵梦里游。#绿水青山就是金山银山##国内旅游# ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg", "04.jpg", "05.jpg", "06.jpg", "07.jpg", "08.jpg", "09.jpg"]}, {"poem_id": "1814", "title": "鹧鸪天·游宿吐鲁番", "genre": "鹧鸪天", "date": "2024.09.14", "body": "……近观火焰山\n少小即闻火焰山，\n老来有幸站跟前。\n西游记里僧途事，\n尘世餐中作笑谈。\n芭蕉扇，力无边。\n把之灭火蔽云天。\n今朝旁立留身影，\n祈盼凭她避祸端。", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "1815", "title": "踏莎行·文欢歌宴", "genre": "踏莎行", "date": "2024.09.15", "body": "时欲中秋，\n天将满月。\n梧桐枝杪飘黄叶。\n幼儿园里舞还歌，\n笑颜师长情真切。\n台上国风，\n树稍莺鹊。\n溢香家宴楼前列。\n珍馐美馔色盈眸，\n朵颐老少心怀惬。#幼儿园##汉服[超话]# ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg", "04.jpg", "05.jpg", "06.jpg"]}, {"poem_id": "1816", "title": "踏莎行·吟望", "genre": "踏莎行", "date": "2024.09.16", "body": "明日中秋，\n今宵西域。\n乡关遥望八千里。\n爹娘幸甚妹相亲，\n为儿愧对难由己。\n晚辈争前，\n老夫助力。\n边城数月陪孙聚。\n待得十月转回家，\n椿萱庭院身心寄。#﻿记录生活##晚安心语# ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1817", "title": "踏莎行·中秋抒怀", "genre": "踏莎行", "date": "2024.09.17", "body": "白鹭一行，\n清风两盏。\n月儿今夜将圆满。\n阖家企盼共抬头，\n奈何独子须行远。\n中午欢谈，\n黄昏别散。\n京新两地深宵看。\n银辉皓月耀长空，\n婵娟颙望同心愿。#中秋快乐##﻿记录生活##晚安心语# ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1818", "title": "七律·铭耻备战", "genre": "七律", "date": "2024.09.18", "body": "当年倭寇兽行狂，\n华夏山河遭祸殃。\n十四春秋齐抗战，\n万千儿女赴国殇。\n英雄气概弥寰宇，\n悲壮情怀感上苍。\n今日东瀛妖又舞，\n愤呼大圣换刀枪。#十四年情怀##抗战十四年# ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1819", "title": "五绝·秋夜寄友", "genre": "五绝", "date": "2024.09.20", "body": "冀新同望月，\n兄弟共相思。\n待到还乡日，\n交杯话此时。", "image_files": ["01.jpg"]}, {"poem_id": "1820", "title": "采桑子·秋日吟", "genre": "采桑子", "date": "2024.09.21", "body": "援疆母女期将到。\n近日回京，\n爷奶随行。\n往复三年别有情。\n边城迪化蒸蒸上。\n街院繁荣，\n歌舞欢声。\n鹰雁争翔啭碧空。#采桑子##边城# ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1821", "title": "七绝·时令吟", "genre": "七绝", "date": "2024.09.22", "body": "秋来昼夜暂均分，\n此后阳衰渐感阴。\n尘世风云凭日月，\n江湖善恶透人心。#昼夜均分,快乐共享# ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "1822", "title": "七绝·吟趣", "genre": "七绝", "date": "2024.09.24", "body": "远看老生俯首读，\n专心注目手轻扶。\n近前不道人何处，\n只见青石哪有书。#七绝# ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1823", "title": "七绝·归来吟", "genre": "七绝", "date": "2024.09.27", "body": "别时西域叶飘黄，\n早晚出门着厚裳。\n来至京城枝杪翠，\n行人短袖不觉凉。#生活手记##日常[超话]# ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1824", "title": "虞美人·十一颂", "genre": "虞美人", "date": "2024.10.01", "body": "七十五载江山丽，\n华夏新天地。\n九州百姓暖心怀，\n国庆金秋歌舞靓亭台。\n晴空万里辉芒映，\n草木今朝盛。\n岭川妍秀染云空，\n鸟语花香尘世漫清风。#记录美好生活# ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg", "04.jpg", "05.jpg", "06.jpg", "07.jpg", "08.jpg", "09.jpg"]}, {"poem_id": "1825", "title": "七律·吟长假", "genre": "七律", "date": "2024.10.07", "body": "金风送爽喜间愁，\n众欲出行挤破头。\n路上人车云下卧，\n景区花草梦中游。\n山门虽近忧停步，\n湖岸徒长苦觅舟。\n身困天峰争宿厕，\n腰包涨鼓水难求。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg", "04.jpg", "05.jpg", "06.jpg"]}, {"poem_id": "1826", "title": "七律·节后晓吟", "genre": "七律", "date": "2024.10.08", "body": "寒露今朝日色扬，\n匆忙童子上学堂。\n临街店铺勤迎客，\n赶路职员着靓妆。\n十月金秋盈喜气，\n万家红火娶新娘。\n神州南北欢天地，\n山海东西硕果香。#二十四节气# ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1827", "title": "蝶恋花·老父亲", "genre": "蝶恋花", "date": "2024.10.09", "body": "霜鬓居家闲不住。\n种菜浇花，\n庭院枝藤舞。\n手巧人勤无惧苦，\n清香日月盈门户。\n喜获冬瓜一米五。\n欲与肩高，\n尽可蒸烧煮。\n入味丝滑频下肚，\n洗肠瘦体天然补。#我家院子里的风景##生活诗意##乡味##蝶恋花##家的味道# ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1828", "title": "蝶恋花·节前吟寄", "genre": "蝶恋花", "date": "2024.10.10", "body": "天欲重阳人念旧。\n思绪飞扬，\n举目频搔首。\n往事依稀心左右，\n遂邀故友樽前凑。\n昔日华颜今老叟。\n弯背塌腰，\n笑把杯中酒。\n见面不多情意厚，\n开怀同醉扶墙走。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1829", "title": "五律·重阳寄怀", "genre": "五律", "date": "2024.10.11", "body": "九九登高日，\n银空万仞晴。\n云游归故里，\n神绪荡苍穹。\n人道俦朋逝，\n予心悲痛浓。\n茱萸无觅处，\n思念几时穷。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1830", "title": "五律·秋夜小聚", "genre": "五律", "date": "2024.10.13", "body": "经久未曾逢，\n樽前意趣浓。\n欢谈同辈事，\n笑语子孙情。\n涮肉穿肠过，\n香醪落口中。\n不觉时已晚，\n半月映长空。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1831", "title": "五律·友相聚", "genre": "五律", "date": "2024.10.14", "body": "秋叶任风摇，\n清蟾隐夜霄。\n故朋灯下聚，\n新客觯前聊。\n香酒十人醉，\n欢言举案飘。\n曾经同苦难，\n退后各逍遥。#五律# ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1832", "title": "五律·同窗聚", "genre": "五律", "date": "2024.10.17", "body": "石门秋正浓，\n黄叶弄寒声。\n兴起安家聚，\n悦谈兄弟情。\n香醪争入口，\n罩饼暖心宫。\n往日今朝事，\n飞霜染鬓丛。#尽兴生活每一天# ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1833", "title": "五律·秋思", "genre": "五律", "date": "2024.10.19", "body": "长夜廉纤雨，\n暮秋心底寒。\n孤灯难入睡，\n百念绕床前。\n五口京津冀，\n四方星月天。\n晓阶黄叶覆，\n思绪更缠绵。#手机随手拍##五律##生活诗意##乡味# ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1834", "title": "七绝·街景", "genre": "七绝", "date": "2024.10.29", "body": "草木叶黄秋已深，\n栖鸦飞燕冷心魂。\n闲余老者阶前聚，\n畅浴阳光话古今。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1835", "title": "清平乐·闻讯抒怀", "genre": "清平乐", "date": "2024.10.30", "body": "神舟十九，\n秋日晨昂首。\n喜见三人挥巨手，\n飞向天宫会友。\n半年守望苍穹，\n巡回俯瞰山溟。\n逐日携星揽月，\n为得寰宇安宁。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "1836", "title": "朝中措·吟望怀", "genre": "朝中措", "date": "2024.10.31", "body": "太空舱内喜相逢，\n携手舞天宫。\n华夏英雄儿女，\n穿梭日月云星。\n神舟利剑，\n从无到有，\n自主奇功。\n举世今朝仰望，\n交织羡忌杂情。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1837", "title": "采桑子·老来乐", "genre": "采桑子", "date": "2024.11.01", "body": "小轮转动躯前展。\n腰臂拉伸，\n上下抻筋。\n鼻脸无忧与地亲。\n半年渐进终成就。\n不负余心，\n炼罢舒身。\n腹背凹凸欲作真。", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "1838", "title": "朝中措·唐山宴", "genre": "朝中措", "date": "2024.11.02", "body": "小山世界往昔情，\n旧物忆峥嵘。\n店铺当街叫卖，\n匾牌旗帜飞红。\n境迁时过，\n仿修原貌，\n韵味犹浓。\n招引京邻远客，\n品游美乐食空。", "image_files": ["01.jpg", "02.jpg", "03.jpg", "04.jpg", "05.jpg", "06.jpg", "07.jpg", "08.jpg", "09.jpg"]}, {"poem_id": "1839", "title": "七律·岳母周年祭", "genre": "七律", "date": "2024.11.04", "body": "车灯穿雾向陵园，\n逝者仙归整一年。\n平日家人常忆事，\n今朝亲友伫坟前。\n陡河水气萦碑墓，\n秋叶寒声痛胆肝。\n贡品丰盈悲更甚，\n后生思念寄青烟。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1840", "title": "七律·闻西马有寄", "genre": "七律", "date": "2024.11.05", "body": "跨步长安别样天，\n时空穿越两千年。\n永宁门处人昂首，\n长庆宫前鸟悦颜。\n大雁塔头铃忆事，\n华清池畔水传言。\n古今多少风流过，\n血染都城脚下砖。\n注：西安马拉松\n起点永宁门。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1841", "title": "破阵子·吟望寄怀", "genre": "破阵子", "date": "2024.11.16", "body": "珠海航空展演，\n今非昔日神州。\n撩眼无人新武器，\n不断惊闻喜上头。\n开怀情自流。\n最是邻朋远客，\n徘徊询问详由。\n触目彩虹凝白帝，\n难禁心欢舞亮眸。\n携来雪耻仇。\n注：彩虹无人机\n白帝空天战机", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "1842", "title": "七绝·冬日闲吟", "genre": "七绝", "date": "2024.11.17", "body": "尘世相逢人不易，\n寻常交往且珍惜。\n心诚念少天长久，\n遇事无争情自怡。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1843", "title": "七律·故友小聚", "genre": "七律", "date": "2024.11.19", "body": "多年未见喜相逢，\n窗外风寒情意浓。\n酒满金樽香入口，\n锅频涮肉味萦空。\n朋俦高语交心腹，\n妻子欢言热眼瞳。\n午后冬阳斜照暖，\n微醺霜鬓踏归程。#记录美好生活# ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1844", "title": "七绝·初冬吟望", "genre": "七绝", "date": "2024.11.21", "body": "朝霞东起月沉西，\n日夜轮回诚可期。\n莫谓长阴晴色少，\n苍天公道古来知。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1845", "title": "七绝·冬日晨吟", "genre": "七绝", "date": "2024.11.23", "body": "小雪时来晓色寒，\n出门戴月展双拳。\n微风拂面周身热，\n鸦雀噪枝人向前。#身边的风景# ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1847", "title": "鹧鸪天·冬日吟望", "genre": "鹧鸪天", "date": "2024.11.27", "body": "风卷尘飞叶满天，\n枝鸦瑟瑟草花寒。\n交加雨雪冰初就，\n次第晨昏人不安。\n温骤降，苦缠绵。\n出行无奈冷心田。\n可怜老少居家处，\n期待阳升日色妍。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1848", "title": "五律·冬日闲吟", "genre": "五律", "date": "2024.12.01", "body": "无风寒意减，\n晨炼汗加身。\n几日出门怕，\n今朝爽入心。\n苍天威力重，\n大地热情深。\n便是冰叠雪，\n终归万里春。", "image_files": ["01.jpg"]}, {"poem_id": "1849", "title": "七绝·闻事感怀", "genre": "七绝", "date": "2024.12.03", "body": "南北观山景不同，\n众说人影短长声。\n言出异口寻常事，\n认作云泥自有情。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1850", "title": "七律·冬日闲吟", "genre": "七律", "date": "2024.12.04", "body": "转眼寒天大雪来，\n一年光景自徘徊。\n春花香漫千山过，\n夏雨风悠万树裁。\n秋日飞霜甘果盛，\n冬时落叶腊梅开。\n阴阳交替无穷尽，\n悲乐轮回撞我怀。#身边的风景# ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1851", "title": "踏莎行·大势所趋", "genre": "踏莎行", "date": "2024.12.05", "body": "……吟陆生访台\n华夏东南，\n中国台北。\n出言响亮蝇营碎。\n一声激起浪滔天，\n谋独小丑云空坠。\n面目狰狞，\n心神交瘁。\n呲牙舞爪情徒费。\n挡车螳臂若烟尘，\n飞轮滚滚归龙队。", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "1852", "title": "七绝·时令吟", "genre": "七绝", "date": "2024.12.06", "body": "大雪时来又近春，\n两寒过后物华新。\n忍得短暂冰霜苦，\n翠紫芳红迎抱君。", "image_files": ["01.jpg"]}, {"poem_id": "1853", "title": "七绝·冬晓吟望", "genre": "七绝", "date": "2024.12.09", "body": "风云漫卷中东乱，\n虎豹争食草木哀。\n百姓安居华夏暖，\n当空晴日待春来。", "image_files": ["01.jpg"]}, {"poem_id": "1854", "title": "七律·冬至", "genre": "七律", "date": "2024.12.21", "body": "晓月当空趋向西，\n北风枯叶劲摇枝。\n老夫早起人稀少，\n宿狗突惊吠叫急。\n宁静街头声乍破，\n高低杠上跃翁姿。\n周身渐暖心怀阔，\n数九从今日日期。", "image_files": ["01.jpg"]}, {"poem_id": "1855", "title": "七律·孙女生日", "genre": "七律", "date": "2024.12.22", "body": "冬至煊煊整四周，\n家亲宠爱更何求。\n爹娘短暂千般趣，\n爷奶无穷万事由。\n四季一心情灌注，\n三餐多味饭稀稠。\n身高已在同龄上，\n体智乘风崭露头。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1856", "title": "踏莎行·缅怀主席", "genre": "踏莎行", "date": "2024.12.26", "body": "圣诞东方，\n福临华夏。\n移山填海开新画。\n贫穷百姓喜翻身，\n挥拳砸碎南天霸。\n射弹飞星，\n营渠造坝。\n三分世界赢天下。\n呕心国是筑根基，\n得来今日凌云厦。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1857", "title": "七绝·吟望", "genre": "七绝", "date": "2024.12.27", "body": "伟人诞日艳阳天，\n华夏双飞秀技颜。\n神秘空中南北客，\n举头仰望赤心甜。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "1858", "title": "七绝·故友三家聚", "genre": "七绝", "date": "2024.12.30", "body": "京邑东西各自忙，\n难得抽空享时光。\n娇孙都已学园去，\n落座潇湘几案香。", "image_files": ["01.jpg"]}, {"poem_id": "1859", "title": "鹤冲天·元旦抒怀", "genre": "鹤冲天", "date": "2025.01.01", "body": "年初岁暮，九汉争鹰鹭。\n晴日秀芳姿，翩跹舞。\n四海人皆望，惊叫赞声无数。\n欢心催泪目。\n元旦来临，览喜事刷屏幕。\n追星赶月，华夏辉煌今古。\n北斗引鸣镝，神雕翥。\n俯瞰疆川域岭，巡湖海，盯礁渚。\n神州精把护。\n百姓安闲，岂惧豹豺狼虎。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1860", "title": "七绝·岭上花", "genre": "七绝", "date": "2025.01.02", "body": "生在悬崖人不知，\n无声开落应天时。\n经年未染尘间秽，\n笑与清风两念思。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1861", "title": "七律·健身寄怀", "genre": "七律", "date": "2025.01.03", "body": "室外寒风刺骨吹，\n楼中健体暖心扉。\n哑铃弯举匀吸气，\n单杠平伸血脉催。\n器械夹胸双臂胀，\n游池蹬腿老身飞。\n一年四季膺怀悦，\n霜发春秋任手挥。", "image_files": ["01.jpg", "02.jpg", "03.jpg", "04.jpg", "05.jpg", "06.jpg"]}, {"poem_id": "1862", "title": "七绝·时令吟", "genre": "七绝", "date": "2025.01.05", "body": "大雪时节雪未飘，\n深冬交往气温高。\n小寒今又晴空丽，\n期待早春花色娇。", "image_files": ["01.jpg"]}, {"poem_id": "1863", "title": "七绝·冬日晓吟", "genre": "七绝", "date": "2025.01.07", "body": "寒星隐隐腊八来，\n晓色朔风迎我怀。\n庭院冷光描树影，\n粥香缕缕溢窗台。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1864", "title": "玉楼春·吟望寄怀", "genre": "玉楼春", "date": "2025.01.12", "body": "山火无情人有恨，\n多少公知心里闷。\n昔时眉眼向西歪，\n此刻缩头遭众愤。\n信口雌黄浑不论，\n崇外诬中曾起劲。\n而今世道换新天，\n水荡风流华夏润。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "1865", "title": "朝中措·童稚迎春", "genre": "朝中措", "date": "2025.01.16", "body": "幼儿画笔诉心声。\n蛇舞彩云空。\n泼墨辞别旧岁，\n挥毫妆点新容。\n胸中美景，\n飘然纸上，\n韵味无穷。\n今日朦胧童愿，\n将来或许都成。", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "1866", "title": "七绝·岁暮抒怀", "genre": "七绝", "date": "2025.01.18", "body": "日月难穷人易老，\n山河无恙换新妆。\n愚公代代齐天志，\n江海同心感上苍。", "image_files": ["01.jpg"]}, {"poem_id": "1867", "title": "五律·岁暮吟", "genre": "五律", "date": "2025.01.20", "body": "大寒冬欲尽，\n不日又迎春。\n别却西风冷，\n思归故里亲。\n进门尊父母，\n卧榻定心魂。\n长久飘乡外，\n得闲邀旧人。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1868", "title": "七绝·小年", "genre": "七绝", "date": "2025.01.22", "body": "京城晓色静无风，\n残月西南卧远空。\n路上人车已偏少，\n任谁不起故乡情。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1869", "title": "七绝·岁杪吟望", "genre": "七绝", "date": "2025.01.26", "body": "千呼万唤雪毛来，\n落下无形隐老宅。\n吻润云空亲故土，\n待风吹绽百花开。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1870", "title": "七律·乙巳年吟怀", "genre": "七律", "date": "2025.02.02", "body": "鞭炮回归年味浓，\n九州街巷染灯红。\n走亲访友频来往，\n串店刷屏尽笑容。\n春晚新添神秘客，\n舞台依旧漫真情。\n今逢初五嘣穷日，\n一早冲天震耳鸣。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1871", "title": "蝶恋花·立春抒怀", "genre": "蝶恋花", "date": "2025.02.03", "body": "四季轮回春又到。\n万里无云，\n山海晴阳照。\n乙巳年来闻响炮，\n灵蛇献瑞人欢笑。\n寒冷将行花欲俏。\n喜看门庭，\n雀鸟枝头叫。\n暖坐阶前闲老少，\n家长里短开心唠。", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "1872", "title": "五律·吟怀", "genre": "五律", "date": "2025.02.04", "body": "不觉年已过，\n岁月自悠然。\n老者霜丝甚，\n少儿心底甜。\n连餐鱼蟹肉，\n满手百十元。\n梦里偷偷笑，\n醒来无个闲。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1873", "title": "七绝·初十吟寄", "genre": "七绝", "date": "2025.02.07", "body": "十全十美人心愿，\n岁首扬眉共向前。\n春至百花皆欲放，\n莺鸣柳翠众芳妍。\n​​​", "image_files": ["01.jpg"]}, {"poem_id": "1874", "title": "采桑子·吟望寄怀", "genre": "采桑子", "date": "2025.02.08", "body": "狗粮暗供催其吠。\n挑逗星辰，\n搅动风云。\n主子无形它咬人。\n而今暴露魔头面。\n大快民心，\n恶犬失魂。\n寰宇空明气色新。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "1875", "title": "七律·春日吟望", "genre": "七律", "date": "2025.02.09", "body": "正月心闲日子红，\n炉台烟火袅云空。\n舒眉漫享团圆趣，\n落坐畅聊南北情。\n迈步街头逢故友，\n举觞家里笑今生。\n无忧自在枝檐鸟，\n恰似门阶霜鬓翁。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1876", "title": "七绝·春怨", "genre": "七绝", "date": "2025.02.10", "body": "时逢乙巳倒春寒，\n冷甚严冬三九天。\n连日北风狂肆虐，\n吹枝卷地扰新年。", "image_files": ["01.jpg"]}, {"poem_id": "1877", "title": "七绝·吟怀", "genre": "七绝", "date": "2025.02.11", "body": "新春膺悦赋闲篇，\n思绪飞扬眉宇间。\n屏上文交天下友，\n才情神韵尽诗仙。", "image_files": ["01.jpg"]}, {"poem_id": "1878", "title": "七绝·乙巳元宵节", "genre": "七绝", "date": "2025.02.12", "body": "花灯破晓闹新春，\n五色汤圆万户亲。\n一缕阳光初耀眼，\n微风和煦暖人心。", "image_files": ["01.jpg"]}, {"poem_id": "1879", "title": "七律·悼黄老院士", "genre": "七律", "date": "2025.02.12", "body": "卅载埋名未见亲，\n凝眸铸剑赤儿心。\n日思夜继寻遥梦，\n笔算纸承图念真。\n入水蛟龙声远震，\n冲天神火散阴魂。\n老来霜鬓惊乡土，\n驾鹤西归众染襟。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "1880", "title": "五律·乙巳元夕", "genre": "五律", "date": "2025.02.13", "body": "新年初满月，\n辉影弄花灯。\n笑靥随蛇舞，\n俏眸追火龙。\n彩烛争璀璨，\n玉树闪金星。\n都市宵无寐，\n乡村连炮声。", "image_files": ["01.jpg"]}, {"poem_id": "1881", "title": "七绝·春日寄人", "genre": "七绝", "date": "2025.02.15", "body": "过桥莫忘回头看，\n或许他时往复行。\n雁去衡阳春亦返，\n螺旋进取是人生。", "image_files": ["01.jpg"]}, {"poem_id": "1882", "title": "七绝·岁初吟望", "genre": "七绝", "date": "2025.02.16", "body": "彼岸一番操弄后，\n崇洋媚客却无言。\n昔时鼓噪乌鸦嘴，\n近日缩头怪可怜。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1883", "title": "五律·春意", "genre": "五律", "date": "2025.02.19", "body": "东风吹古柳，\n雨水润新芽。\n老者欣欣意，\n童儿朵朵花。\n城乡生璀璨，\n山海染辉霞。\n放眼晴空阔，\n街头气色佳。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1884", "title": "七律·引体人生", "genre": "七律", "date": "2025.02.20", "body": "手拉躯体头超杠，\n上下垂直往复行。\n臂背核心齐用力，\n腰身经脉悄然通。\n二十余载从无断，\n数万来回别有情。\n花甲时光多自主，\n双修早晚意方平。", "image_files": ["01.jpg"]}, {"poem_id": "1885", "title": "七律·乙巳吟望", "genre": "七律", "date": "2025.02.21", "body": "新年哪吒火出圈，\n影院爆棚宵不眠。\n角色闪辉情喻世，\n言谈含蓄隐尘烟。\n票房史上名前列，\n人气今朝冲破天。\n华夏春风吹正甚，\n此花芳苑或夺冠。", "image_files": ["01.jpg"]}, {"poem_id": "1886", "title": "五绝·郊外吟", "genre": "五绝", "date": "2025.02.22", "body": "细柳扶人背，\n携春望水流。\n扬眉青鸟舞，\n惬意更何求。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1887", "title": "鹧鸪天·春日闲吟", "genre": "鹧鸪天", "date": "2025.02.25", "body": "冬晓林园雾色浓，\n初春草木映天明。\n昔时小径人稀少，\n今日高枝众鸟鸣。\n年过后，友相逢。\n送完学子倍轻松。\n畅谈哪吒银屏事，\n沐浴温阳神自宁。", "image_files": ["01.jpg"]}, {"poem_id": "1888", "title": "七绝·龙之声", "genre": "七绝", "date": "2025.02.27", "body": "无论东西南北风，\n立根华夏若苍松。\n阴晴雨雪皆无谓，\n躯干雄拔叶自青。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1889", "title": "七绝·二月二", "genre": "七绝", "date": "2025.03.01", "body": "新春正月时光逝，\n转眼今朝龙首昂。\n细柳发芽人跃步，\n且凭鸿运走八方。", "image_files": ["01.jpg"]}, {"poem_id": "1890", "title": "采桑子·悼汪院长", "genre": "采桑子", "date": "2025.03.04", "body": "惊闻讣告追思远。\n学苑当年，\n笑貌悠然。\n如画蹁跹又眼前。\n寻常语缓情深厚。\n授课余闲，\n问暖嘘寒。\n君去温存心底间。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1891", "title": "七绝·惊蛰有寄", "genre": "七绝", "date": "2025.03.05", "body": "春华渐入芬芳境，\n虫草扬眉气色新。\n人世百年迎巨变，\n大洋两岸竞晴阴。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1892", "title": "五绝·吟望", "genre": "五绝", "date": "2025.03.06", "body": "开年春为首，\n又见风吹柳。\n摇曳恁多情，\n悄然思故旧。#随手拍春天##诗歌[超话]# ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1893", "title": "采桑子·入群吟贺", "genre": "采桑子", "date": "2025.03.07", "body": "乡情凝聚八方客。\n南北知音，\n老少相亲。\n只为廉州一脉根。\n书香漫溢人陶醉。\n犹木逢春，\n历久成林。\n故土芬芳天地新。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1894", "title": "朝中措·三八吟寄", "genre": "朝中措", "date": "2025.03.08", "body": "九州女子半边天。\n家事缀心田。\n料里还须忙外，\n公差勇往争先。\n春秋寒暑，\n操劳日夜，\n灶上屏前。\n居内心倾老少，\n加班无悔鲜言。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1895", "title": "七律·藁城吟颂", "genre": "七律", "date": "2025.03.09", "body": "廉州自古远名扬，\n华夏肥国属汉邦。\n宫酒飘香皇室醉，\n宫灯闪耀伴君王。\n台西铁钺商周事，\n岗上黑猪御宴汤。\n名将梅花村灭寇，\n子麟故里尚书庄。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1896", "title": "五绝·吟望", "genre": "五绝", "date": "2025.03.10", "body": "已被当枪使，\n今应亦自知。\n人前堆苦笑，\n夜里悔无时。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1897", "title": "七律·植树节吟望", "genre": "七律", "date": "2025.03.12", "body": "霞日春辉百子湾，\n园丁影衬草花妍。\n挖坑浇水根茁壮，\n培土修枝绿染天。\n今种幼苗心念驻，\n终将老木入云端。\n前人栽下摇钱树，\n实惠后生千万年。", "image_files": ["01.jpg"]}, {"poem_id": "1898", "title": "七律·孙女春趣", "genre": "七律", "date": "2025.03.13", "body": "学稚归来百子湾，\n斜阳沐浴嫩娇颜。\n彩虹跑道嘻声闹，\n浅绿草坪悄语酣。\n滑板追逐摔倒乐，\n跳绳碰撞躺平欢。\n眼前花朵争先放，\n爷奶近旁心里甜。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "1899", "title": "七绝·春日吟怀", "genre": "七绝", "date": "2025.03.14", "body": "别人逐利我求闲，\n得空躬身二老前。\n兼顾儿孙多少事，\n任谁埋怨莫搭言。", "image_files": ["01.jpg"]}, {"poem_id": "1900", "title": "小重山·冷暖抒怀", "genre": "小重山", "date": "2025.03.15", "body": "乙巳春光少女情。\n娇颜难料定、暗忽明。\n柳眉扬起喜鸣莺。\n欢一刻、转脸恼丛生。\n暖日映苍穹。\n隔天云密布、起寒风。\n可怜老少路难行。\n凭生愿、惟岁月长晴。", "image_files": ["01.jpg"]}, {"poem_id": "1901", "title": "太常引·315有感", "genre": "太常引", "date": "2025.03.16", "body": "奸商黑店昧良心。\n假货乱充真。\n修物骗人金。\n肉掺水、坑钱害民。\n日常监管，\n君臣不到，\n奏报少回音。\n每岁只逢今。\n凭晚会、难能断根。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1902", "title": "七律·仲春闲吟", "genre": "七律", "date": "2025.03.17", "body": "阳光普照心头暖，\n连日阴霾逝九天。\n研墨读章皆快事，\n抒怀醒脑自悠然。\n诗学李杜从新韵，\n词咏苏辛爱旧篇。\n更有廉州骚客友，\n书香群里共言欢。", "image_files": ["01.jpg"]}, {"poem_id": "1903", "title": "采桑子·孙女学拳", "genre": "采桑子", "date": "2025.03.19", "body": "娇童初练跆拳道。\n意兴欣然。\n眼亮声尖。\n手腿劈蹬侧转翻。\n强身利脑坚其志。\n不畏炎寒。\n玉立人前。\n柔软腰姿好少年。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg", "04.jpg", "05.jpg", "06.jpg"]}, {"poem_id": "1904", "title": "七律·春分有寄", "genre": "七律", "date": "2025.03.20", "body": "乙巳今朝昼夜均，\n神州花草水清欣。\n东来紫气蒸蒸上，\n西落斜辉漫漫沉。\n日月轮回天不老，\n阴阳交替景宜人。\n一年四季风光好，\n骚客诗章偏爱春。", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "1905", "title": "清平乐·乙巳闲吟", "genre": "清平乐", "date": "2025.03.22", "body": "归休烦少，\n多半陪煊宝。\n四载娇孙哭更笑，\n日子喜添调料。\n任凭苦辣酸咸，\n片云难掩晴天。\n屡屡微风拂过，\n悠悠我自清欢。#随手拍美景# ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1906", "title": "西江月·春日闲吟", "genre": "西江月", "date": "2025.03.23", "body": "转眼时来周末，\n回头日过七天。\n光阴飞逝鬓霜间。\n精气充盈早晚。\n拂晓舒筋花苑，\n清晨送幼学园。\n得闲撸铁泳池边。\n星夜苏辛书伴。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1907", "title": "西江月·览群寄杯", "genre": "西江月", "date": "2025.03.24", "body": "屏上诗词书画，\n心中淡静闲安。\n凝神细赏赋拙篇。\n邀友粗读评鉴。\n故里藏龙卧虎，\n大家吐气盈天。\n不才何日拜真颜，\n了却一桩心愿。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1908", "title": "七绝·春日晓吟", "genre": "七绝", "date": "2025.03.25", "body": "抬头翠色染新枝，\n满目鲜花竞艳姿。\n便是大风心不冷，\n春光远胜暖冬时。", "image_files": ["01.jpg"]}, {"poem_id": "1909", "title": "七律·春园有寄", "genre": "七律", "date": "2025.03.26", "body": "早晚经行百子湾，\n爷孙最爱是春天。\n林花竞秀迎童去，\n翠鸟争呜送稚还。\n老者舒心闲散步，\n幼儿脱手漫撒欢。\n夕阳斜照东风暖，\n惬意归来放纸鸢。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1910", "title": "七律·藁城咏望", "genre": "七律", "date": "2025.03.27", "body": "滹沱河水润良田，\n自与廉州结妙缘。\n两岸稻粱金谷盛，\n万家炉火袅青烟。\n宫灯闪耀楼台宇，\n宫面飘香日月年。\n风土乡情民意厚，\n酿来御酒醉神仙。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1911", "title": "踏莎行·乙巳感怀", "genre": "踏莎行", "date": "2025.03.28", "body": "世态炎凉，\n人心恶善。\n江湖风雨寻常见。\n老来静处一杯茶，\n闲听鸟语家妻伴。\n忘却忧愁，\n倾情餐饭。\n神舒食饱身常练。\n养精蓄力不求人，\n九旬笑饮峰溪畔。", "image_files": ["01.jpg"]}, {"poem_id": "1912", "title": "七绝·乙巳风云", "genre": "七绝", "date": "2025.03.29", "body": "不意春寒闹玉京，\n花伤雀躁乱西风。\n应天大势谁能改，\n紫气还来日更红。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1913", "title": "七绝·吟望东南", "genre": "七绝", "date": "2025.03.30", "body": "被人霸领已多年，\n几次招回起事端。\n今欲亲情呼认祖，\n奈何逆子坏心肝。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1914", "title": "七律·台岛吟望", "genre": "七律", "date": "2025.03.31", "body": "银鹰怒目向东南，\n铁甲奔流草木喧。\n浊水蟹虾犹乱舞，\n晴空日月照魔顽。\n岛中小丑形孤兽，\n岸上雄师名宇寰。\n猎狗擒狼华夏稳，\n神州一统九龙旋。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1915", "title": "七绝·近清明有感", "genre": "七绝", "date": "2025.04.01", "body": "忽觉空里漫浮灰，\n烧纸家亲解念悲。\n万户今朝红火日，\n尽凭冥币了心扉。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1916", "title": "西江月·望故乡", "genre": "西江月", "date": "2025.04.02", "body": "上树摘桃年少，\n爬墙掏鸟时迁。\n每当忆起暖膺田。\n远去风光难现。\n昔日青丝浅靥，\n今朝霜鬓苍颜。\n街头相遇不曾言，\n人道同窗玩伴。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1917", "title": "七绝·乙巳春吟望", "genre": "七绝", "date": "2025.04.03", "body": "春风普惠世间花，\n粉紫红黄染万家。\n更有窗前枝杪翠，\n盎然生气映朝霞。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1918", "title": "七绝·清明见闻", "genre": "七绝", "date": "2025.04.04", "body": "便道划圈堆纸烧，\n悲思飘过故乡桥。\n远途难到坟前祭，\n想必先人理不挑。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1919", "title": "蝶恋花·清明吟望", "genre": "蝶恋花", "date": "2025.04.05", "body": "百里山蹊徒步走。\n学子三千，\n顶日迎星斗。\n昼夜兼程无意柳。\n只缘烈士心中有。\n祭拜英灵齐叩首。\n卅载坚持，\n感地惊天久。\n如此育人真善守。\n神州万代山河秀。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1920", "title": "蝶恋花·贺父寿八十三", "genre": "蝶恋花", "date": "2025.04.06", "body": "三月风光初九日。\n椿寿萱亲，四代人欢喜。\n袅袅炊烟香漫溢，\n农家小院辉盈壁。\n慈父居堂心满意。\n儿女孙娃，把盏福音寄。\n不老南山松久立，\n亲如日月同天地。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1921", "title": "七绝·风云吟望", "genre": "七绝", "date": "2025.04.07", "body": "花开必有落花时，\n人至巅峰贵自知。\n留路下山频顾望，\n当归莫恋鸟鸣啼。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1922", "title": "七绝·闲人吟望", "genre": "七绝", "date": "2025.04.08", "body": "吾儿三口到成都，\n临去乖孙咏杜书。\n今日草堂门处站，\n少陵绝律应声出。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1923", "title": "江城子·读友买车记吟怀", "genre": "江城子", "date": "2025.04.09", "body": "四驱越野任驰翔。\n过河床，跨峰梁。\n华夏东西、南北细端详。\n五岳群山寻探后，\n观四海，望三江。\n余生惬意好风光。\n景无常，绪飞扬。\n神魄云游，妙手著华章。\n屡有诗词平仄句，\n情无限，韵悠长。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1924", "title": "七绝·题照", "genre": "七绝", "date": "2025.04.10", "body": "昔气充盈眼放光，\n满怀自信笑声长。\n而今黯寂失魂魄，\n贪草老牛愁断肠。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1925", "title": "朝中措·十二级狂风欲闹", "genre": "朝中措", "date": "2025.04.11", "body": "极端预警为黎民。风力恁惊人。\n百载廉州未见，闻听骇魄飞魂。\n由来西北，尘沙南下，地暗天昏。\n学校行将停课，拜托转告乡邻。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1926", "title": "蝶恋花·春宵难寐", "genre": "蝶恋花", "date": "2025.04.12", "body": "彻夜狂风声怒吼。\n房瓦叮当，\n砖块环庭走。\n牌匾心寒频颤抖，\n断枝残叶窗阶凑。\n清晓落红铺地厚。\n燕雀无形，\n只剩春梢瘦。\n一早人稀空远透，\n可怜环卫街前后。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1927", "title": "南乡子·大风后寄怀", "genre": "南乡子", "date": "2025.04.13", "body": "转日景光新。\n万里长空无片云。\n晨起清凉听鸟雀，\n惜春。\n百啭千声尽妙音。\n岁月有晴阴。\n凡事遭逢可两分。\n且莫一心钻死角，\n回身。\n世路崎岖总有人。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1928", "title": "七绝·黄毛之痛", "genre": "七绝", "date": "2025.04.14", "body": "抡起钢刀劈对方，\n不成想己亦遭枪。\n病身失血难言苦，\n暗恨爪牙无预防。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1929", "title": "七绝·中越吟望", "genre": "七绝", "date": "2025.04.15", "body": "犹似连枝两弟兄，\n围居南海几多情。\n共经风雨心怀异，\n同对豺狼合力生。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1930", "title": "七律·暮春吟望", "genre": "七律", "date": "2025.04.17", "body": "神州花绽韵无穷，\n遍处芬芳映远空。\n彼岸寒潮携墨雨，\n吾庭角落起阴风。\n东升旭日消霾雾，\n西坠斜辉裹旧红。\n岁月轮回天地换，\n飞龙盛世唱英雄。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1931", "title": "鹧鸪天·彼岸吟望", "genre": "鹧鸪天", "date": "2025.04.18", "body": "驴技将穷象亦难。\n丛林套路岂遮天。\n高悬大棒收无奈，\n频耍花腔少信言。\n灯塔暗，月光残。\n出行路上渐成单。\n世人今日趋清醒，\n失道之徒夏也寒。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1932", "title": "定风波·蛙泳有感", "genre": "定风波", "date": "2025.04.19", "body": "池里学蛙双腿蹬。\n埋头呼气臂伸平。\n划手胸前夹抱水。\n挺背。\n畅怀吸纳自充盈。\n如此循环沉又起。\n惬意。\n浪花朵朵玉晶莹。\n霜鬓妪翁勤锻炼。\n常见。\n天南地北话无穷。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1933", "title": "蝶恋花·谷雨抒怀", "genre": "蝶恋花", "date": "2025.04.20", "body": "谷雨之前甘露降。\n润物除尘，\n今日晴空旷。\n放眼高楼心底畅\n葱葱郁郁千层浪。\n草木感恩花竞放。\n山海多情，\n莺鹊欢声唱。\n最是黎民天不忘，\n秋收祭拜添佳酿。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1934", "title": "西江月·周末小姐妹", "genre": "西江月", "date": "2025.04.21", "body": "团子来家做客，\n若煊出户迎宾。\n入门牵手笑声频。\n缓步厅堂答问。\n玩具并肩摆弄，\n读书异口同音。\n蜜般滋味润童心。\n一晌欢情未尽。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1935", "title": "七律·京城半马赛", "genre": "七律", "date": "2025.04.22", "body": "常闻人跑马拉松，\n突现机奔亮眼睛。\n手脚协同神气在，\n腰身摆动意从容。\n路边观者皆欢舞，\n业界来宾亦震惊。\n一霎创新传四宇，\n万千网友赞无穷。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "1936", "title": "踏莎行·今非昔比", "genre": "踏莎行", "date": "2025.04.23", "body": "……贺海军生日\n向海图强，\n凝心聚力。\n七十六载风和雨。\n辛酸挥泪更高歌，\n缺船少舰成回忆。\n航母巡游，\n大驱轮替。\n无踪潜艇开天地。\n五洲任我自由行，\n大西洋里频来去。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "1937", "title": "蝶恋花·书香藁城", "genre": "蝶恋花", "date": "2025.04.24", "body": "缕缕书香飘四海。\n熏暖廉州，\n受众多豪迈。\n字画俗规皆所爱，\n诗词文赋情慷慨。\n提振膺怀人不怠。\n政要黎民，\n尽展新风采。\n敬业持家和内外，\n并肩逐梦初心在。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1938", "title": "菩萨蛮·贺神舟20发射成功", "genre": "菩萨蛮", "date": "2025.04.25", "body": "五十五载同一处。\n箭辉更亮星如故。\n兴起忆当年，东方红漫天。\n举国歌并舞，齐庆敲锣鼓。\n今日驻天宫，嫦娥笑靥浓。\n注：神舟20与第一颗人造\n卫星同天同地点发射。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1939", "title": "朝中措·暮春有思", "genre": "朝中措", "date": "2025.04.26", "body": "娇娃学课老夫闲。\n隔壁稚声喧。\n恰是晚春天暮，\n抬头青翠无边。\n风摇秀景，\n群楼耸立，\n霞色盈天。\n花草春秋往复，\n谁能许我童年。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1940", "title": "五律·春日吟", "genre": "五律", "date": "2025.04.27", "body": "暮春天渐暖，\n晨练喜添人。\n舞炫歌声远，\n拳飞脚带魂。\n老夫翻卷杠，\n翠鸟啭清音。\n庭院温馨景，\n神州遍处闻。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1941", "title": "七绝·寰宇吟望", "genre": "七绝", "date": "2025.04.28", "body": "教皇葬礼却偷闲，\n规避他人聊会天。\n肢体语言瞒不住，\n无声画面世间传。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1942", "title": "十六字令·三首", "genre": "十六字令", "date": "2025.04.29", "body": "风。\n落叶秋来卷过冬。\n冰融化，\n春草百花生。\n风。\n吹散阴霾万里晴。\n山川丽，\n春水泛光明。\n风。\n扫灭西方塔上灯。\n天边亮，\n春日旭由东。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1943", "title": "清平乐·劳动节吟赞", "genre": "清平乐", "date": "2025.05.01", "body": "无声打脸。\n董姐浑身胆。\n格力腰直行路远。\n任汝说长道短。\n海龟或有间谍。\n用人业主谋决。\n不鸟周边犬吠。\n挺胸再上台阶。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1944", "title": "减字木兰花·青年节吟望", "genre": "减字木兰花", "date": "2025.05.04", "body": "今逢五四，昔日青春成记忆。\n过往辉煌，回荡心头日月长。\n苍颜斑鬓，喜望山河情亦奋。\n地覆天翻，遍处青葱草木妍。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1945", "title": "五律·立夏吟", "genre": "五律", "date": "2025.05.05", "body": "夜雨迎初夏，\n晓风拂老身。\n民心河畔景，\n单杠柱边人。\n踢腿弯腰乐，\n牵绳遛狗亲。\n凌空鸣鸟翥，\n鱼跃响清音。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1946", "title": "七律·临屏吟望", "genre": "七律", "date": "2025.05.08", "body": "印巴交火起东风，\n吹落阿三铁鸟篷。\n败阵军心生恐惧，\n闻情政客更发蒙。\n当年惹事愁肠断，\n今日抽疯苦胆疼。\n狂妄无知天下笑，\n劝君切莫耍聪明。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "1947", "title": "七绝·乙巳夏初", "genre": "七绝", "date": "2025.05.09", "body": "纤丝细雨已连天，\n雷电未闻风亦闲。\n喜纳玉珠苗木壮，\n人逢甘露润心田。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1948", "title": "江城子·乙巳还乡", "genre": "江城子", "date": "2025.05.10", "body": "祖孙五口故乡还。\n旧堂前，拜椿萱。\n四载时光，\n二老念煊煊。\n半岁当时曾见过。\n今目秀，更心欢。\n满门四代俱平安。\n老一言，少一言。\n笑语盈盈，\n喜气胜新年。\n兄妹三家人俱到，\n连环乐，闹翻天。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1949", "title": "七绝·母亲节有寄", "genre": "七绝", "date": "2025.05.12", "body": "一.\n贤妻良母一家亲，\n琴瑟和鸣漫妙音。\n常有身边儿女伴，\n风霜寒暑总如春。\n二.\n逢儿生日母亲节，\n孙女忙前不肯歇。\n俏语欢歌传四处，\n偷闲左右找爷爷。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "1950", "title": "七绝·神龙吟望", "genre": "七绝", "date": "2025.05.13", "body": "印巴交手子扬名，\n举世方知有巨龙。\n平日鲜闻潜水下，\n一朝腾起露真容。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1951", "title": "七绝·愁望", "genre": "七绝", "date": "2025.05.14", "body": "五月冰雹降夜空，\n大如鸡蛋使人惊。\n可怜花木失魂魄，\n毁损麦田愁老农。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1952", "title": "五律·夏园有寄", "genre": "五律", "date": "2025.05.15", "body": "翠鸟树争鸣，\n繁花粉映红。\n青云闲自度，\n湖水静无声。\n健体人心悦，\n浇园苦壮丁。\n阳光同照耀，\n草木各西东。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1953", "title": "蝶恋花·风云吟望", "genre": "蝶恋花", "date": "2025.05.16", "body": "川普无端兴税浪。\n多地人惊，\n跪倒埋头向。\n胆颤心寒神不壮，\n总觉刀片迎眸晃。\n华夏硬刚惟榜样。\n对岸无着，\n货断人声呛。\n无奈几番期造访，\n终得瑞士东方亮。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1954", "title": "蝶恋花·闻趣有寄", "genre": "蝶恋花", "date": "2025.05.17", "body": "交火双方皆庆祝。\n真假迷人，\n惟阵风清楚。\n巴放录音谁苦诉，\n阿三铁鸟生无助。\n一战歼十成大户。\n举世惊魂，\n仰望神龙翥。\n霄汉翱翔凭自主，\n神州何日开疆土？ ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1955", "title": "七绝·夜悦吟", "genre": "七绝", "date": "2025.05.18", "body": "夏初昼热晚风凉，\n忙罢娇孙享夜光。\n楼院舒心闲散步，\n吟思词句凑篇章。", "image_files": ["01.jpg"]}, {"poem_id": "1956", "title": "五律·乙巳初夏", "genre": "五律", "date": "2025.05.19", "body": "春归夜雨频，\n晓霁少飞云。\n高树枝梢翠，\n长空气色新。\n恋花欢鸟雀，\n行路不愁人。\n醉爱天公意，\n红黄染绿荫。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1957", "title": "七绝·乙巳闲吟", "genre": "七绝", "date": "2025.05.20", "body": "柴米油盐日复年，\n春秋寒暑苦还甜。\n子孙依次攀登上，\n白首老夫心自甘。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1958", "title": "蝶恋花·小满有寄", "genre": "蝶恋花", "date": "2025.05.21", "body": "喜看麦田秸粒壮。\n风起青萍，\n绿海翻波浪。\n无数农家齐盼望，\n天公助力台阶上。\n人物相通君莫忘。\n地利天时，\n得遇人和畅。\n便有先机休恣妄，\n功名小满宜谦让。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1959", "title": "七律·琴音悦耳", "genre": "七律", "date": "2025.05.23", "body": "课外学琴家里弹，\n孙娃四岁不偷闲。\n书中五线音符密，\n键上一双童手纤。\n入耳飞声人自乐，\n扬眉埋首韵您然。\n黑白舞动和弦妙，\n旋律充盈玉指间 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1960", "title": "浣溪沙·乙巳初夏", "genre": "浣溪沙", "date": "2025.05.24", "body": "夜雨洗尘明霁空，\n恰逢周末好心情。\n孙随父母悦闲翁。\n眺远凭高杨柳翠，\n飞声入耳鹊莺鸣。\n倚栏独望趣无穷。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1961", "title": "五律·幼女骑车", "genre": "五律", "date": "2025.05.26", "body": "不觉孙已大，\n首次试骑行。\n目举前方看，\n耳倾边侧听。\n小轮能助稳，\n纤手把平衡。\n眉眼神情秀，\n腰直腿脚蹬。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1962", "title": "七律·孙女咏趣", "genre": "七律", "date": "2025.05.27", "body": "一天背过沁园春，\n玩乐之余巧聚神。\n汉武秦皇随口问，\n唐宗宋祖引童真。\n言词反复知其意，\n平仄融合有妙音。\n稚子心灵潜力巨，\n莫凭杂念误儿身。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1963", "title": "七绝·夏园晓色", "genre": "七绝", "date": "2025.05.28", "body": "笛子悠扬声悦耳，\n芳园葱郁养心神。\n抬头满眼皆青翠，\n晨晓温凉最喜人。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1964", "title": "虞美人·爷孙参访北大", "genre": "虞美人", "date": "2025.05.29", "body": "妈妈深造燕园里，\n钩起娇娃趣。\n爷孙相伴兴前来，\n游览未名湖畔、尽心怀。\n百贤古院书香甚，\n幼女频相问。\n将来能否此读书，\n博雅塔边傍晚、看鸭浮？ ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg", "04.jpg", "05.jpg", "06.jpg"]}, {"poem_id": "1965", "title": "朝中措·祖国花朵", "genre": "朝中措", "date": "2025.05.30", "body": "时临六一幼儿欢，\n早晚尽开颜。\n长辈叠加礼物，\n老师语润心田。\n居家可爱，\n园中勇跃，\n遇事争先。\n今日娇柔花朵，\n将来梁栋盈天。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "1966", "title": "蝶恋花·乙巳端午", "genre": "蝶恋花", "date": "2025.05.31", "body": "又品粽香华夏味。\n千载传承，\n恰似东流水。\n青叶米团红枣配，\n甘甜入口心陶醉。\n多少龙舟宵不寐。\n只为今朝，\n竞渡江头会。\n锣鼓喧天驱鬼魅，\n旌旗翻卷灵均泪。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1967", "title": "鹧鸪天·儿童节有寄", "genre": "鹧鸪天", "date": "2025.06.01", "body": "端午六一前后天，\n幼儿欢乐若新年。\n粽香漫溢神州地，\n花朵芬芳华夏园。\n新衣俏，浅妆妍。\n开怀嘻闹不思还。\n才骑木马滑梯悦，\n又喂鱼鸭戏水滩。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1968", "title": "蝶恋花·闻讯有寄", "genre": "蝶恋花", "date": "2025.06.03", "body": "香会开成媒体秀。\n米帝新官，\n作派还依旧。\n嘴大不知天地厚，\n自嗨人恨名声臭。\n且看龙哥眉眼透。\n刚毅坚强，\n谁敢和他斗。\n半岛昔时驱恶狗，\n今朝寰宇频昂首。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1969", "title": "七绝·闻事吟", "genre": "七绝", "date": "2025.06.04", "body": "登高莫忘来时路，\n振臂发声休背心。\n痕迹已留难抹去，\n盗铃掩耳妄欺人。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1970", "title": "七律·乙巳芒种吟", "genre": "七律", "date": "2025.06.05", "body": "京城今日忆当年，\n随父麦收学舞镰。\n三点起床天未亮，\n五更挥手汗珠连。\n弯腰埋首心头苦，\n入夜屈身梦里甜。\n睡醒指根多水泡，\n脖疼臂肿后背酸。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "1971", "title": "踏莎行·吟学子", "genre": "踏莎行", "date": "2025.06.07", "body": "高考来临，\n寒门期待。\n十年心血贫能改。\n爹娘无靠自殷勤，\n征途不想人前败。\n宛若独桥，\n几多无奈。\n埋头挥墨心胸快。\n换得慧眼巧识珠，\n黄金榜下情豪迈。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1972", "title": "蝶恋花·京城大吉巷", "genre": "蝶恋花", "date": "2025.06.08", "body": "菜市口旁新去处。\n地上悠闲，\n地下光盈目。\n店面琳琅赢客驻，\n吃喝玩乐光阴度。\n百姓欢游朝与暮。\n情侣双双，\n夜晚难移步。\n谁道旧时骡马路，\n而今万众争相顾。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg", "04.jpg", "05.jpg", "06.jpg"]}, {"poem_id": "1973", "title": "太常引·寄语学子", "genre": "太常引", "date": "2025.06.09", "body": "今朝考罢路东西。\n各自有心期。\n何必抢高枝。\n尽情唱，终为所知。\n莺啼树上，\n鸡鸣窗下，\n庭院显生机。\n两者莫缺一。\n如日月，风光晓夕。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1974", "title": "浣溪沙·夏晓吟寄", "genre": "浣溪沙", "date": "2025.06.10", "body": "送罢娇孙入早园。\n穿行石径百花间。\n鸟声盈耳悦心田。\n闲望浮云来又去，\n欣闻歌舞起回旋。\n老翁神态胜青年。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1975", "title": "七绝·天怒人怨", "genre": "七绝", "date": "2025.06.11", "body": "往时风景到身边，\n不见妖婆嘻笑颜。\n米帝当年拿手戏，\n今朝屡屡馈她前。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1976", "title": "七律·颂少校张伟", "genre": "七律", "date": "2025.06.12", "body": "和平卫士气如山，\n无愧英雄天地间。\n跪拜含情别母去，\n转身入水使人还。\n连番五次拼竭力，\n不怕一生止眼前。\n解放军中兵与将，\n世逢危难总当先。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1977", "title": "七绝·仲夏晓吟", "genre": "七绝", "date": "2025.06.13", "body": "三年夏日在新疆，\n夜里从来未敞窗。\n京邑今朝刚欲热，\n醒神已是汗浇床。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1978", "title": "五绝·夏雨人欢", "genre": "五绝", "date": "2025.06.14", "body": "老天怜百姓，\n周末雨浇城。\n退却烦人热，\n依栏别有情。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1979", "title": "踏莎行·节日敬父", "genre": "踏莎行", "date": "2025.06.15", "body": "父爱如山，\n亲情似海。\n椿庭敞亮春长在。\n仰天远阔悦儿心，\n阖家受益多豪迈。\n银发稀疏，\n柔怀未改。\n重孙相见心澎湃。\n八十三岁挺腰身，\n迎风矗立犹松柏。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1980", "title": "蝶恋花·北京绿心森林", "genre": "蝶恋花", "date": "2025.06.17", "body": "废厂焕新盈草木。\n引水成渠，\n桥上游人驻。\n云戏碧波蛙劲鼓，\n绿荫树下环行路。\n周末祖孙携手度。\n望远抒怀，\n心悦莺鸣舞。\n为赏风光勤脚步，\n宜人景色频回顾。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "1981", "title": "采桑子·日暮吟雨", "genre": "采桑子", "date": "2025.06.18", "body": "娇孙上课吾听雨。\n打叶敲窗，\n祛热添凉。\n青翠枝条气色扬。\n甘霖骤降人心喜。\n清爽盈腔，\n意绪飞翔。\n稚嫩书声韵味长。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1982", "title": "七绝·中东吟望", "genre": "七绝", "date": "2025.06.20", "body": "心浮杂念苦苍生，\n火弹银花乱夜空。\n百姓不知何处是，\n躲藏无奈梦魂惊。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1983", "title": "踏莎行·乙巳夏至", "genre": "踏莎行", "date": "2025.06.21", "body": "时遇周休，\n年逢夏至。\n最长白昼弥炎气。\n从今往后暑难熬，\n汗流面背身如洗。\n梦里求风，\n醒来祈雨。\n坐行专捡阴凉地。\n手摇蒲扇眼惺忪，\n蝉鸣树杪添烦意。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1984", "title": "蝶恋花·夏日闲思", "genre": "蝶恋花", "date": "2025.06.23", "body": "网上言谈天与地。\n真假难分，\n闻罢由他去。\n碧落风云凭玉帝，\n物情对错人心里。\n路走东西终靠己。\n切莫随风，\n摇摆墙头立。\n欲到长城依脚力，\n八达岭上辉光异。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1985", "title": "蝶恋花·吟中东", "genre": "蝶恋花", "date": "2025.06.24", "body": "曾望加沙心坏笑。\n不想今时，\n家破楼倾倒。\n天道轮回终有报，\n眉凝肠断闻哭闹。\n狂妄言行常跑调。\n撕毁章程，\n上下东西跳。\n以为没谁能管了，\n不成想会钟馗到。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "1986", "title": "朝中措·夏日有感", "genre": "朝中措", "date": "2025.06.26", "body": "蝴蝶飞舞百花丛。\n自奋且凭风。\n无虑闲舒心态，\n绕枝起落身轻。\n引予观看，\n触发感想，\n激荡神情。\n人世何当如此，\n悠哉潇洒平生。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1987", "title": "踏莎行·琴声激荡", "genre": "踏莎行", "date": "2025.06.28", "body": "期待十天，\n欢弹一刻。\n钢琴学练初收获。\n今朝检试展人前，\n低头行礼回身坐。\n双手轻舒，\n两眸闪烁。\n音符跳动童心彻。\n和弦妙韵谢师恩，\n娇孙添技爷相贺。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1988", "title": "踏莎行·童趣", "genre": "踏莎行", "date": "2025.06.30", "body": "园里同班，\n小区邻住。\n三天姐弟长相顾。\n时逢周末早前约，\n两家郊外光阴度。\n画笔合描，\n转轮同步。\n吟诗对句无穷数。\n青云来去影相随，\n黄莺飞过心头妒。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "1989", "title": "踏莎行·七一抒怀", "genre": "踏莎行", "date": "2025.07.01", "body": "昔日红船，\n今朝航母。\n历经百载千难苦。\n神州日月换新天，\n大洋彼岸愁川普。\n你控晶芯，\n我封稀土。\n可怜洛马神无主。\n银鹰六代刺云空，\n长巡碧落谁为伍！\n注：洛马为米国\n最大军火商。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1990", "title": "南乡子·乙巳夏吟", "genre": "南乡子", "date": "2025.07.03", "body": "闷热胜昔年。\n还未头伏汗水连。\n白昼少风愁鸟雀。\n人烦。\n深夜翻腾总不眠。\n湿度日高攀。\n雾气蒙蒙蔽远天。\n便是彻阴无烈日。\n身黏。\n苦状揪心不可言。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1991", "title": "清平乐·酬友赠句", "genre": "清平乐", "date": "2025.07.04", "body": "欣闻佳韵，\n溽暑心怀润。\n妙笔生辉传美讯，\n骤减炎光一寸。\n若风入户穿梁，\n提神醒脑添香。\n回味飘来字句，\n长思细品华章。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1992", "title": "踏莎行·孙女舞蹈", "genre": "踏莎行", "date": "2025.07.06", "body": "背挺眉舒，\n腰柔眼亮。\n合生汇处心怀向。\n每周相聚舞娇姿，\n园丁浇灌禾苗壮。\n师长倾心，\n幼儿渴望。\n今朝展演争前上。\n婀娜身手引人眸，\n鲜花朵朵迎风靓。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "1993", "title": "采桑子·铭记国耻", "genre": "采桑子", "date": "2025.07.07", "body": "七七事变八八载。\n战火风烟，\n地覆天翻。\n日寇狼心存世间。\n倭贼近日频频动。\n窥伺周边，\n怪论奇谈。\n吾辈钢枪顶上肩。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1994", "title": "五律·夏日吟", "genre": "五律", "date": "2025.07.10", "body": "雨浇天未凉，\n暑气透纱窗。\n平卧身难耐，\n烦听心愈慌。\n蝉鸣人躁虑，\n叶落树悲伤。\n如此三伏近，\n到时愁更长。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1995", "title": "朝中措·出京避暑", "genre": "朝中措", "date": "2025.07.20", "body": "帝都一路向山东。\n窗外郁葱葱。\n车内祖孙三口，\n沿途喜乐融融。\n淄博夜宿，\n闲游街市，\n烧烤香浓。\n张店吴家就坐，\n人说远近闻名。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "1996", "title": "朝中措·到乳山银滩", "genre": "朝中措", "date": "2025.07.21", "body": "淄博晓起再东行。\n过午海滨停。\n左转海都花苑。\n卧闻千里涛声。\n娇孙期待，\n金辉拇指，\n广场多情。\n日暮星光璀璨，\n银滩歌舞欢腾。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg", "04.jpg", "05.jpg", "06.jpg"]}, {"poem_id": "1997", "title": "七律·大暑有寄", "genre": "七律", "date": "2025.07.23", "body": "院临堤岸夜风凉，\n酣卧纱帘半掩窗。\n电扇不开身倍爽。\n空调未挂梦犹香。\n清晨鸟语催人起，\n傍晚蝉声伴绪扬。\n暑日时光潇洒过，\n银滩谁道是他乡。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "1998", "title": "蝶恋花·银滩海洋园", "genre": "蝶恋花", "date": "2025.07.24", "body": "夜场游园光烂漫。\n人少心愉，\n爷俩精玩遍。\n海盗船头摇眺瞰，\n欢骑木马千般转。\n漫步太空身欲探。\n碰碰车中，\n娇女肝肠颤。\n旋转双飞风洗面，\n摩天轮上银滩灿。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg", "04.jpg", "05.jpg", "06.jpg"]}, {"poem_id": "1999", "title": "七律·银滩戏水", "genre": "七律", "date": "2025.07.26", "body": "长江路上海洋园，\n华夏八方客涌前。\n京邑祖孙初试水，\n银滩波浪掩鸣蝉。\n学爷划手双蹬腿，\n望伴漂流两眼馋。\n飞下滑梯白玉碎，\n碧涛洗面笑欢言。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg", "04.jpg", "05.jpg", "06.jpg"]}, {"poem_id": "2000", "title": "蝶恋花·盛夏童欢", "genre": "蝶恋花", "date": "2025.07.28", "body": "​南北京城兄妹趣。\n祖辈同窗，\n约在银滩聚。\n相见若亲双手递，\n好玩食物凭心取。\n形影不离消夏季。\n戏水挖沙，\n合荡秋千去。\n同坐滑梯生惬意，\n摩天轮上长欢叙。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg", "04.jpg", "05.jpg", "06.jpg", "07.jpg", "08.jpg", "09.jpg"]}, {"poem_id": "2001", "title": "七绝·闻事吟", "genre": "七绝", "date": "2025.07.30", "body": "佛门净地亦藏污，\n一夜风来浊气除。\n期望禅房香愈甚，\n诵经打坐破尘俗。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "2002", "title": "蝶恋花·银滩之夜", "genre": "蝶恋花", "date": "2025.07.31", "body": "傍晚海风消暑气。\n乡客出门，\n堤岸舒心意。\n闲望烟云别有趣，\n银滩暮色风光丽。\n歌舞盈眸锣鼓密。\n娱乐抒怀，\n老少皆参与。\n模特走来香满地，\n闻听竹板勾回忆。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg", "04.jpg", "05.jpg", "06.jpg"]}, {"poem_id": "2003", "title": "踏莎行·八一颂", "genre": "踏莎行", "date": "2025.08.01", "body": "将勇兵强，\n矛长盾固。\n三军昼夜江山护。\n神州岁月稳平安，\n黎民无虑时光度。\n偶起风云，\n紧盯门户。\n钢枪时刻瞄狼虎。\n挺胸高举舞旌旗，\n八一闪耀夺人目。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "2004", "title": "采桑子·伏天乐学", "genre": "采桑子", "date": "2025.08.03", "body": "海滨松树林中坐。\n风色宜人，\n暑日消魂。\n简易书桌乐我孙。\n打开斑马思维课。\n数字诗文，\n图画声音。\n雀鸟飞来几探身。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "2005", "title": "水调歌头·山东银滩寄怀", "genre": "水调歌头", "date": "2025.08.05", "body": "暑季银滩飒，早晚有凉风。江南塞北，闲客于此好心情。拂晓沿堤散步，前晌寻街探市，日落踏歌声。三五成群伴，满脸尽欢容。\n品海鲜，吸富氧，乐无穷。短休长住，涛浪云月俱相迎。新痛转天或好，久病日长亦去，时日更轻松。翁媪无忧虑，碧水对青空。", "image_files": ["01.jpg", "02.jpg", "03.jpg", "04.jpg", "05.jpg", "06.jpg"]}, {"poem_id": "2006", "title": "五绝·时令吟", "genre": "五绝", "date": "2025.08.07", "body": "立秋如往常，\n未感更风凉。\n隔日三伏到，\n后才枝叶黄。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "2007", "title": "蝶恋花·银滩踏海", "genre": "蝶恋花", "date": "2025.08.08", "body": "海里娇孙初戏水。\n笑靥如花，\n臂展心陶醉。\n双手急划频踹腿，\n波涛卷舞纤肩背。\n浪里众游声鼎沸。\n老少同欢，\n不道身怀累。\n暮色苍茫星欲坠，\n归来满口腥咸味。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "2008", "title": "七律·青岛海底世界", "genre": "七律", "date": "2025.08.10", "body": "生物繁多乱眼球，\n斑斓色彩水中流。\n鲨鳍涛里凭心舞，\n鲸骨人前不自由。\n玳瑁企鹅行缓慢，\n金鱼海豹竞驰游。\n珊瑚摇动孙兴奋，\n水母如花脚步留。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg", "04.jpg", "05.jpg", "06.jpg"]}, {"poem_id": "2009", "title": "踏莎行·濒海灯光秀", "genre": "踏莎行", "date": "2025.08.12", "body": "彩挂楼阁，\n光铺水岸。\n海滨夜色丰姿幻。\n妙图美乐酷无穷，\n眼迷耳胀心撩乱。\n鸟啭激扬，\n人山翻卷。\n繁星摇曳风情漫。\n银花火树映霄空，\n初秋青岛凭君恋。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg", "04.jpg", "05.jpg", "06.jpg"]}, {"poem_id": "2010", "title": "七律·青岛八大关", "genre": "七律", "date": "2025.08.13", "body": "古时关隘作街名，\n三纵七横车马行。\n别墅于间格调异，\n瓦砖置上色偏红。\n蓝天映照烟花盛，\n碧海合围草木荣。\n游者摩肩声鼎沸，\n摆拍朋侣恁多情。\n注：起初八个关名\n八条路，后扩两关\n两路。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg", "04.jpg", "05.jpg", "06.jpg"]}, {"poem_id": "2011", "title": "清平乐·和友见赠", "genre": "清平乐", "date": "2025.08.14", "body": "云青气润，\n堤岸飘秋韵。\n碧海无边思不尽，\n眺望征鸿飞阵。\n沙滩松软滑柔，\n回头翠叶盈眸。\n暮色凉风好梦，\n神游枕上如舟。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "2012", "title": "五律·寄日寇", "genre": "五律", "date": "2025.08.15", "body": "战败八十载，\n罪行无反思。\n书中长掩盖，\n嘴上久相欺。\n政客图私欲，\n国民事莫知。\n瞒天天不应，\n尘世共喷之。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "2013", "title": "蝶恋花·夏日吟望", "genre": "蝶恋花", "date": "2025.08.16", "body": "举世遥期双普会。\n就在今朝，\n予盾强相对。\n必是往来烟火味，\n不知高下人心惴。\n最是欧乌难醒寐。\n命运由他，\n空落膺怀累。\n玉案虽宽无己位，\n菜单被点凭开胃。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "2014", "title": "清平乐·赠普京", "genre": "清平乐", "date": "2025.08.16", "body": "单刀赴会，\n昂首心无愧。\n便是虎穴徒手对，\n君为国何所谓。\n战机掠过从容，\n一车双普同行。\n交手言谈得体，\n临别拜谒英雄。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "2015", "title": "蝶恋花·孙女玩杠", "genre": "蝶恋花", "date": "2025.08.17", "body": "一岁多时初吊杠。\n三载光阴，\n屡次爷扶上。\n口数三十当日状，\n今朝百二娇模样。\n每有同龄腰腿壮。\n欲试高低，\n总比她先晃。\n羸弱香肩堪小将，\n争先意愿心怀荡。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "2016", "title": "浣溪沙·初秋有寄", "genre": "浣溪沙", "date": "2025.08.18", "body": "送罢娇孙返乳山，\n难得老俩自悠闲。\n初秋漫赏逛银滩。\n树果飘香街市旺，\n海鱼入味灶盘鲜。\n凭风望海度流年。 ​​​", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "2017", "title": "浣溪沙·幼儿喜相逢", "genre": "浣溪沙", "date": "2025.08.19", "body": "遥望娇孙返幼园。\n中班开课第一天。\n重逢姐弟笑开颜。\n放假出游时过月，\n入学落座趣无边。\n琮琮招手唤煊煊。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "2018", "title": "七绝·秋日闲吟", "genre": "七绝", "date": "2025.08.20", "body": "出伏暑气未全消，\n秋虎袭来无处逃。\n漫待风吹桐叶落，\n天清云爽任逍遥。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "2019", "title": "踏莎行·彼岸吟望", "genre": "踏莎行", "date": "2025.08.21", "body": "别样风情，\n空前宴会。\n丛林老虎独高位。\n豺狼狗兔不甘心，\n奈何势弱徒含泪。\n欲上餐桌，\n实得杂碎。\n尝来不是曾经味。\n无知今日异昔时，\n守残抱旧堪愚昧。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "2020", "title": "七绝·秋日吟", "genre": "七绝", "date": "2025.08.22", "body": "秋香漫溢染银滩，\n瓜果鱼虾映碧天。\n风色人情留远客，\n八方相聚又一年。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "2021", "title": "七律·金秋盛宴", "genre": "七律", "date": "2025.09.02", "body": "上合峰会聚八方，\n星耀海河龙凤祥。\n四面风来秋更飒，\n五湖鱼跃米尤香。\n神州待客发诚意，\n津水载舟思远航。\n携手宾朋盈笑靥，\n共谋欧亚再图强。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "2022", "title": "清平乐·观阅兵有感", "genre": "清平乐", "date": "2025.09.03", "body": "高朋满座，\n争看三军愕。\n铁甲银鹰呼啸过，\n徒步官兵炯烁。\n空中水下神惊，\n无敌陆上群英。\n华夏今朝底气，\n东风助力和平。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "2023", "title": "朝中措·谁与争锋", "genre": "朝中措", "date": "2025.09.04", "body": "……九三寄怀\n东风浩荡卷尘沙。\n利剑扫天涯。\n且凭高能锐器，\n宇寰所向开花。\n三军抖擞，\n银鹰舞动，\n铁甲穿插。\n将士横刀立马，\n把来盗寇击杀。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg", "04.jpg", "05.jpg", "06.jpg"]}, {"poem_id": "2024", "title": "朝中措·九三之后", "genre": "朝中措", "date": "2025.09.05", "body": "东风闪过宇寰新。\n四海少杂音。\n西霸眼花心悸，\n猢狲留去难分。\n沉浮渐定，\n光阴照旧，\n翻转乾坤。\n华夏复兴非梦，\n神州万里迎春。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "2025", "title": "清平乐·缅怀主席", "genre": "清平乐", "date": "2025.09.09", "body": "那年今日，\n山裂江河滞。\n泪水长流华夏地，\n四十九载常忆。\n像前将士昂头，\n赤心瞩目城楼。\n敬慰先驱领袖，\n红旗沃土无忧。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "2026", "title": "采桑子·国耻铭心", "genre": "采桑子", "date": "2025.09.18", "body": "……九一八抒怀\n九十四载谁能忘。\n倭寇猖狂，\n掳掠爹娘。\n践踏山河华夏殇。\n英雄儿女齐心力。\n意志坚强，\n奋舞刀枪。\n消灭豺狼迎暑光。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "2027", "title": "七绝·乙巳秋分", "genre": "七绝", "date": "2025.09.23", "body": "中秋将近昼宵均，\n木叶趋黄细雨勤。\n今岁天凉较往早，\n阴晴无定更愁人。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "2028", "title": "满江红·十一寄怀", "genre": "满江红", "date": "2025.10.01", "body": "…迎国庆七十六周年\n云淡天高，秋风劲、空明国庆。\n亿民悦、五星旗赤，山河辉映。\n江海飞舟腾碧浪，边陲跃马欢歌竞。\n忆前贤、叹地覆天翻，今朝盛。\n航母飒，华为硬。军民奋，惊贼梦。\n华夏展宏图，遍如仙境。\n亚太融合峰岭秀，宇寰协振星辰共。\n且扬眉、昂首再挥鞭，神州胜。", "image_files": ["01.jpg"]}, {"poem_id": "2029", "title": "七绝·霜后有寄", "genre": "七绝", "date": "2025.10.24", "body": "近日诗词友未闻，\n念吾思绪几萦心。\n寒宵来电情怀暖，\n睡起余温笼老身。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "2030", "title": "采桑子·闻讯寄怀", "genre": "采桑子", "date": "2025.10.25", "body": "台湾光复八十秩。\n日月轮回，\n浪子无归。\n政客贪权百姓悲。\n家亲思念频呼唤。\n情迫声催，\n大势难违。\n聚力神州共起飞。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "2031", "title": "鹧鸪天·重九寄怀", "genre": "鹧鸪天", "date": "2025.10.29", "body": "昔日重阳敬老人，\n而今霜鬓染吾身。\n无穷岁月悠悠去，\n短暂霞辉漫漫沉。\n花间客，岭头云。\n犹蓬飘过少留痕。\n凡尘世物皆如此，\n度尽秋冬总是春。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "2032", "title": "七绝·秋日吟望", "genre": "七绝", "date": "2025.11.02", "body": "寒风落叶冷深秋，\n鸟雀无声草木忧。\n偶有阳光人世暖，\n倚墙翁妪少闲愁。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "2033", "title": "采桑子·宝岛吟望", "genre": "采桑子", "date": "2025.11.05", "body": "百年烂党新魁首。\n念想牵魂，\n声势夺人。\n或聚蓝营散漫心！\n绿白两阵偷瞭望。\n各自思寻，\n细找伤痕。\n能胜英姿俏丽文？ ​​​", "image_files": ["01.jpg"]}, {"poem_id": "2034", "title": "七绝·立冬有寄", "genre": "七绝", "date": "2025.11.07", "body": "杂忙无意岁临冬，\n细雨缠绵日冷清。\n更有尘间多少事，\n寒风吹过透心胸。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "2035", "title": "渔家傲·福建航母赞", "genre": "渔家傲", "date": "2025.11.08", "body": "航母成三华夏奋，\n劈波斩浪风头劲。\n迈向深蓝携利刃，\n威名震。\n大洋阔海凭出进。\n昔日有心缺后盾，\n岛礁遥望徒生恨。\n强盗横行得尺寸，\n膺怀闷。\n今朝吞气眉峰顺。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "2036", "title": "踏莎行·初冬吟望", "genre": "踏莎行", "date": "2025.11.13", "body": "落叶铺金，\n玩童拾趣。\n稚声鼎沸连天地。\n林园韵味恁宜人，\n手忙心醉情难抑。\n树鸟凝神，\n园丁会意。\n景音融洽腾欢气。\n栋梁缘自幼苗根，\n他年大厦凌云立。 ​​​", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "2038", "title": "鹧鸪天·纪念主席诞辰132年", "genre": "鹧鸪天", "date": "2025.12.26", "body": "圣诞中华国运来，\n百年磨难聚英排。\n三山推倒翻天地，\n万马奔腾画卷开。\n身虽去，念徘徊。\n每逢今日忆贤才。\n若无盖世君擎臂，\n巨厦倾斜遍地埃。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "2039", "title": "满江红·贺宁忠岩冰上速滑夺冠", "genre": "满江红", "date": "2026.02.22", "body": "赤子神风，寒光里、龙飞旗跃。惊玉道、一金破阵，百年冰裂。赤县久缺霜刃锐，亚洲今有锋芒烨。丙午春、挥手向长天，情怀悦。\n征衣烈，心似铁；男儿奋，魂如血。任高寒彻骨，志冲云阙。不负艰辛夺胜绩，犹得奥运开新页。待明朝、华夏展雄姿，群英列。", "image_files": ["01.jpg"]}, {"poem_id": "2040", "title": "七律·丙午春寄怀", "genre": "七律", "date": "2026.02.23", "body": "五人三地度新春，\n古冶廉州劳燕分。\n京邑鸟儿飞上海，\n浦江城堡戏青云。\n夫妻各自陪亲老，\n子幼合欢逛景林。\n元日连屏遥问好，\n团圆难称万家心。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "2041", "title": "一剪梅·丙午春开工有寄", "genre": "一剪梅", "date": "2026.02.24", "body": "九昼春休意未央，山魄徜徉，水趣徜徉。\n归程各趁好时光，亲敬高堂，友聚华堂。\n今赴新程向远疆，眉宇轩昂，志意轩昂。\n马年风运正腾骧，业比春长，福与天长。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "2042", "title": "沁园春·娇孙舞元日", "genre": "沁园春", "date": "2026.02.25", "body": "红漫云台，福耀星空，光影纷缭。恰爆竹声里，岁华新换；屠苏盏外，暖意初调。五岁煊儿，两年才艺，今挽红灯态更娇。朱唇俏，唱桃符焕彩，万户妖娆。\n霓裳诗韵飞飘。融稚气、翩跹上碧霄。俱身轻目秀，眸深靥浅；群声振玉，笑卷春潮。卡酷屏中，童姿音律，细把春阳景色描。华堂里，众家亲聚望，喜染眉梢。\n注释：正月初四，北京卫视卡酷少儿频道播出了全国少儿新春大联欢，小孙女参加了一个舞蹈节目，以王安石的诗词《元日》为主题。", "image_files": ["01.jpg", "02.jpg", "03.jpg"]}, {"poem_id": "2043", "title": "临江仙·马年初雨有寄", "genre": "临江仙", "date": "2026.02.26", "body": "窗外雨丝牵晓色，\n更添春意融融。\n直教残冻化空濛。\n水云垂似幕，\n轻洗旧尘蓬。\n出户尚余清寒在，\n忽惊芽甲微萌。\n遥知生气满郊东。\n一襟新爽意，\n天地待葱茏。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "2044", "title": "七律·初十有感", "genre": "七律", "date": "2026.02.26", "body": "福字花枝映户明，\n红灯啼鸟动春情。\n十全难觅心常泰，\n百事须争意自盈。\n但以晴光开倦眼，\n莫因缺憾锁欢行。\n人生美在知足乐，\n不负耕耘天地公。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "2045", "title": "七律·AI贺春", "genre": "七律", "date": "2026.02.28", "body": "智浪催潮卷岁阳，\n神州骐骥竞呈祥。\n豆包情寄春宵宴，\n千问心怀市井香。\n元宝冲天红雨落，\n东风惠世万家昌。\n银河宇树新程启，\n魔法松延溢彩光。\n国内人工智能软件豆包、千问、元宝，春节期间采用红包、免单等惠民措施，吸引众人注意，并大力推广应用。也让百姓体会到了生活的便捷，效率的提高。\n宇树科技、魔法原子、银河通用、松延动力四家机器人也在春节期间大放光彩。", "image_files": ["01.jpg"]}, {"poem_id": "2046", "title": "江城子·健身有感", "genre": "江城子", "date": "2026.03.01", "body": "二十五载志如钢。\n沐晨光，饮风霜。\n寒暑春秋、汗透\n薄衣裳。\n杠上飞身轻似燕，\n膺怀悦，气轩昂。\n老来还恋健身房。\n铁声锵，泳花扬。\n推举深蹲、倒立\n若鹰翔。\n纵使过年珍馔盛，\n人未怠，体犹康。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "2047", "title": "五律·马年春望", "genre": "五律", "date": "2026.03.02", "body": "夜雪映窗明，\n推门晓色青。\n枝头冰蕾俏，\n檐角舞寒英。\n飞雀啄霜碎，\n玩童踏玉轻。\n东风知我意，\n梅笑瑞香凝。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "2048", "title": "七律·AI贺春", "genre": "七律", "date": "2026.02.28", "body": "智浪催潮卷岁阳，\n神州骐骥竞呈祥。\n豆包情寄春宵宴，\n千问心怀市井香。\n元宝冲天红雨落，\n东风惠世万家昌。\n银河宇树新程启，\n魔法松延溢彩光。\n国内人工智能软件豆包、千问、元宝，春节期间采用红包、免单等惠民措施，吸引众人注意，并大力推广应用。也让百姓体会到了生活的便捷，效率的提高。\n宇树科技、魔法原子、银河通用、松延动力四家机器人也在春节期间大放光彩。", "image_files": ["01.jpg", "02.jpg"]}, {"poem_id": "2049", "title": "江城子·健身有感", "genre": "江城子", "date": "2026.03.01", "body": "二十五载志如钢。\n沐晨光，饮风霜。\n寒暑春秋、汗透\n薄衣裳。\n杠上飞身轻似燕，\n膺怀悦，气轩昂。\n老来还恋健身房。\n铁声锵，泳花扬。\n推举深蹲、倒立\n若鹰翔。\n纵使过年珍馔盛，\n人未怠，体犹康。 ​​​", "image_files": ["01.jpg"]}, {"poem_id": "2050", "title": "五律·马年春望", "genre": "五律", "date": "2026.03.02", "body": "夜雪映窗明，\n推门晓色青。\n枝头冰蕾俏，\n檐角舞寒英。\n飞雀啄霜碎，\n玩童踏玉轻。\n东风知我意，\n梅笑瑞香凝。 ​​​", "image_files": ["01.jpg"]}];